window.WPS = window.WPS || {};
WPS.TB_PAGES = WPS.TB_PAGES || {};
(function (P) { for (var k in P) WPS.TB_PAGES[k] = P[k]; })({"t_gr": {"title": "古代ギリシア史", "span": "前3000年ごろ〜前30年", "year": -480, "lead": "エーゲ海の青銅器文明から始まり、ポリスという小さな都市国家の中で市民による民主政が育ちました。ペルシア戦争の勝利で頂点に立ったポリス世界は、内部抗争で衰え、マケドニアとアレクサンドロス大王の帝国を経てヘレニズム世界へと広がっていきます。", "flow": ["前2000年ごろ クレタ文明が栄える(クノッソス宮殿)→海洋的で開放的な文明", "前16世紀ごろ ミケーネ文明が栄える(線文字B)→前1200年ごろ崩壊し暗黒時代へ", "前8世紀ごろ 集住(シノイキスモス)でポリスが成立→地中海・黒海沿岸へ植民", "前6世紀 ソロンの改革(前594年)・ペイシストラトスの僭主政→クレイステネスの改革で民主政の基礎", "前500〜前449年ごろ ペルシア戦争(マラトン前490年・サラミス前480年)→アテネが台頭", "前478年ごろ デロス同盟結成→ペリクレス時代にアテネ民主政が完成", "前431〜前404年 ペロポネソス戦争→アテネ敗北、ポリス社会が動揺", "前338年 カイロネイアの戦い→マケドニアがギリシアを支配(コリントス同盟)", "前334年 アレクサンドロス大王の東方遠征開始→前330年アケメネス朝滅亡", "前323年 大王死去→ディアドコイ戦争、イプソスの戦い(前301年)で三王国に分立", "前30年 プトレマイオス朝がローマに滅ぼされヘレニズム時代が終わる"], "sync": [], "secs": [{"t": "エーゲ文明 ― ギリシア世界の始まり", "p": ["ギリシアの歴史の出発点は、エーゲ海周辺で栄えた青銅器文明である【エーゲ文明】です。前2000年ごろから栄えたのが、クレタ島を中心とする【クレタ文明(ミノア文明)】でした。中心となった【クノッソス】の宮殿は城壁をもたず、壁画にはイルカや草花など明るい題材が描かれています。このことから、クレタ文明は海上交易で富を得た、開放的で平和的な性格の文明だったと考えられています。宮殿は20世紀初めにイギリスの【エヴァンズ】によって発掘されました。文字としては【線文字A】が使われましたが、まだ解読されていません。", "前16世紀ごろになると、ギリシア本土に南下してきたギリシア人(アカイア人とされる)が【ミケーネ文明】を築きます。ミケーネやティリンスの城塞は巨石を積み上げた堅固なもので、クレタとは対照的に戦闘的な性格の文明でした。ミケーネ人はやがてクレタ島にも進出し、クレタの文化を取り入れます。ミケーネ文明の遺跡は、ホメロスの叙事詩に登場する【トロイア】の実在を信じた【シュリーマン】が発掘したことで知られています。ミケーネ文明で使われた【線文字B】は、イギリスの【ヴェントリス】によって解読され、ギリシア語を表していたことがわかりました。", "しかし前1200年ごろ、ミケーネ文明は急速に崩壊します。原因については、外部からの「海の民」の侵入や気候変動、内部の混乱などさまざまな説があり、はっきりとはわかっていません。この後、文字も失われる約400年間を【暗黒時代】と呼びます。ただし、この時代に鉄器が普及し、【ドーリア人】や【イオニア人】などのギリシア人が各地に定住していったことが、次のポリス社会の土台になりました。"]}, {"t": "ポリスの成立と植民活動", "p": ["前8世紀ごろになると、各地の有力者(貴族)のもとに人々が集まって住む【集住(シノイキスモス)】が進み、都市国家【ポリス】が生まれました。ポリスの中心には、守護神をまつる神殿が置かれた丘【アクロポリス】と、市場や集会の場である広場【アゴラ】がありました。ポリスの周囲には農地が広がり、市民の多くは自ら土地を耕す農民でもありました。ギリシアは山が多く平野が狭いため、ひとつの大きな国家にまとまらず、数百もの小さなポリスが並び立つ形になったのです。", "ポリスどうしは政治的には独立していましたが、ギリシア人は同じ言葉を話し、同じ神々を信仰するという仲間意識をもっていました。彼らは自らを【ヘレネス】と呼び、異民族を【バルバロイ】と呼んで区別しました。共通の神【ゼウス】をまつる【オリンピアの祭典】や、【デルフォイ】のアポロン神殿の神託は、ポリスの枠をこえたギリシア人の一体感を支えました。", "人口が増えて土地が足りなくなると、ギリシア人は前8世紀ごろから地中海や黒海の沿岸に盛んに植民市を建設しました。南フランスの【マッサリア】(現在のマルセイユ)、南イタリアの【ネアポリス】(現在のナポリ)、黒海の入り口の【ビザンティオン】(のちのコンスタンティノープル、現在のイスタンブル)などがその代表です。植民活動によって交易が盛んになり、貨幣が普及すると、商工業で富を得た平民が現れ、ポリスの政治のあり方を大きく変えていくことになります。"]}, {"t": "アテネとスパルタ ― 民主政への歩みと軍国主義", "p": ["ポリスの初期には、馬や武具をそろえられる貴族が戦争の主役となり、政治を独占していました。ところが、交易で豊かになった平民が武具を自分で買えるようになると、【重装歩兵】として密集隊形【ファランクス】を組み、戦争の主力となります。国を守る役割を果たす平民は、当然、政治への参加も求めるようになりました。これがアテネで民主政が発展していく根本的な理由です。", "アテネでは、前7世紀に【ドラコン】が慣習法を成文化し、貴族による恣意的な裁判を抑えようとしました。前594年には【ソロン】が改革を行い、借金のかたに市民が奴隷にされる【債務奴隷】を禁止し、財産額に応じて市民の参政権を定める【財産政治】を導入しました。しかし貴族と平民の対立はおさまらず、前6世紀半ばには、平民の支持を得て非合法に権力を握る【僭主】の【ペイシストラトス】が現れます。彼は中小農民を保護する政策をとりましたが、その子の代に僭主政は倒されました。", "前508年ごろに改革を行った【クレイステネス】は、血縁にもとづく4部族を廃止して、地縁にもとづく10部族制を設け、貴族の勢力基盤を崩しました。また、僭主の出現を防ぐため、危険人物の名を陶片に書いて投票し国外に追放する【陶片追放(オストラキスモス)】を始めたとされます。こうしてアテネ民主政の基礎が固まりました。", "一方、ドーリア人のポリスである【スパルタ】は、まったく異なる道を歩みました。スパルタでは少数の市民が、多数の隷属農民【ヘイロータイ(ヘロット)】と、商工業に従事する半自由民【ペリオイコイ】を支配していました。反乱を防ぐため、市民は幼いころから厳しい軍事訓練を受け、貴金属貨幣の使用や外国との交流も制限されました。この体制は伝説的な立法者【リュクルゴス】によって定められたと伝えられています。スパルタは強力な陸軍を誇り、【ペロポネソス同盟】の盟主となりました。"]}, {"t": "ペルシア戦争とアテネ民主政の完成", "p": ["前6世紀後半、オリエントを統一した【アケメネス朝】ペルシアは、小アジアのギリシア人ポリスを支配下に置いていました。前500年、【ミレトス】を中心とする【イオニアの反乱】が起こり、アテネがこれを支援したことから、ペルシアはギリシア本土に遠征します。これが【ペルシア戦争】です。", "前490年の【マラトンの戦い】では、アテネの重装歩兵がペルシア軍を破りました。前480年にはペルシア王【クセルクセス1世】が大軍を率いて再び侵攻し、スパルタ軍は【テルモピレーの戦い】で全滅しますが、同じ年の【サラミスの海戦】で【テミストクレス】の率いるアテネ海軍がペルシア艦隊を撃破しました。翌前479年の【プラタイアの戦い】でギリシア連合軍が勝利し、ペルシアの侵攻は退けられました。", "サラミスの海戦の勝利は、アテネの政治に大きな影響を与えました。軍船の漕ぎ手として活躍したのは、武具を買えない【無産市民】だったからです。彼らの発言力が高まったことで、民主政はさらに徹底されていきます。前478年ごろ、ペルシアの再来に備えて【デロス同盟】が結成されると、アテネはその盟主として同盟の資金を自国のために使うなど、他のポリスを支配する「帝国」のようにふるまうようになりました。", "前5世紀半ばの【ペリクレス】の時代、アテネ民主政は完成します。成年男性市民全員が参加する【民会】が最高議決機関となり、役人の多くは抽選で選ばれ、【民衆裁判所】の陪審員も市民から抽選されました。ただし、軍事に関わる【将軍(ストラテゴス)】は専門性が必要なため選挙で選ばれ、ペリクレスもこの将軍職に連続して選ばれることで指導力を発揮しました。これは市民が直接政治に参加する【直接民主政】でしたが、参政権は成年男性市民に限られ、【女性・奴隷・在留外人】は政治から排除されていた点に注意が必要です。"]}, {"t": "ペロポネソス戦争とポリス社会の動揺", "p": ["アテネの勢力拡大に対し、スパルタを中心とするペロポネソス同盟は強く警戒しました。こうして前431年、デロス同盟とペロポネソス同盟の間で【ペロポネソス戦争】が始まります。アテネは籠城策をとりましたが、城内で【疫病】が流行し、ペリクレス自身もこれで亡くなりました。指導者を失ったアテネでは、巧みな弁舌で民衆をあおる【デマゴーゴス(扇動政治家)】が政治を動かすようになり、無謀な遠征などで国力を消耗しました。一方のスパルタはペルシアから資金援助を受け、前404年にアテネは降伏しました。この戦争の経過は、歴史家【トゥキディデス】が記録しています。", "戦後、スパルタがギリシアの覇権を握りましたが長続きせず、前4世紀前半には【テーベ】が名将【エパメイノンダス】のもとでスパルタを破り、一時覇権を握りました。しかし、どのポリスも全ギリシアをまとめる力はなく、ポリス間の争いが続きました。", "長い戦争は、ポリス社会そのものを内側から変えていきました。戦争で土地を失った市民が没落し、市民が自ら武器をとって国を守るという原則が崩れて、金で雇われる傭兵が広く使われるようになります。市民の共同体としてのポリスの結束は弱まり、ギリシア世界は外からの力に対抗する力を失っていきました。"]}, {"t": "マケドニアの台頭とアレクサンドロス大王", "p": ["ギリシアの北方にあった【マケドニア】は、ギリシア人からは辺境の国と見られていましたが、前4世紀に王【フィリッポス2世】のもとで急速に強大化しました。彼は軍制を改革し、前338年の【カイロネイアの戦い】でアテネ・テーベの連合軍を破ります。その後、スパルタを除くギリシアのポリスを【コリントス同盟(ヘラス同盟)】にまとめ、その盟主となりました。こうしてポリスの独立の時代は終わりました。", "フィリッポス2世が暗殺されると、その子【アレクサンドロス大王】が王位を継ぎ、前334年に東方遠征を開始しました。前333年の【イッソスの戦い】でペルシア王ダレイオス3世を破り、エジプトを征服して【アレクサンドリア】を建設しました。さらに前331年のアルベラの戦いでも勝利し、前330年にアケメネス朝は滅亡します。大王はインダス川流域にまで進みましたが、兵士たちの反対もあって引き返し、前323年にバビロンで病死しました。", "アレクサンドロスは、ペルシアの統治制度を受け継ぎ、ペルシア人を官僚に登用し、マケドニア人とペルシア人の結婚を奨励するなど、東西の融合を図ったとされます。各地に建設されたアレクサンドリアという名の都市には、ギリシア人が移り住み、ギリシア文化をオリエントに広める拠点となりました。"]}, {"t": "ヘレニズム世界とギリシア文化の広がり", "p": ["大王の死後、帝国は後継者たち【ディアドコイ】の争いによって分裂しました。前301年の【イプソスの戦い】を経て、マケドニアの【アンティゴノス朝】、西アジアの【セレウコス朝】、エジプトの【プトレマイオス朝】の三国が並び立つ形となります。大王の東方遠征から、最後に残ったプトレマイオス朝がローマに滅ぼされる前30年までの約300年間を【ヘレニズム時代】と呼びます。この時代、ギリシア語が共通語【コイネー】として広く使われ、ギリシア文化とオリエント文化が融合した【ヘレニズム文化】が栄えました。", "ヘレニズム文化の中心はエジプトのアレクサンドリアで、王立研究所【ムセイオン】では自然科学が発達しました。平面幾何学を大成した【エウクレイデス】、浮力の原理で知られる【アルキメデス】、地球の周囲の長さを測定した【エラトステネス】、太陽中心説を唱えた【アリスタルコス】などが活躍しました。ポリスという枠が失われたことで、人々はポリスの市民としてではなく、一人の人間としてどう生きるかを問うようになり、【世界市民主義(コスモポリタニズム)】や、心の平安を求める【ストア派】・【エピクロス派】の哲学が生まれました。美術では【ミロのヴィーナス】や【ラオコーン】、【サモトラケのニケ】などが知られています。", "さかのぼると、ポリスの時代には、市民の自由な議論の中から豊かな古典文化が生まれていました。文学では【ホメロス】の『【イリアス】』『オデュッセイア』、【ヘシオドス】、女性詩人【サッフォー】が有名です。哲学では、万物の根源を探究した【イオニア自然哲学】の【タレス】、【ピタゴラス】、【ヘラクレイトス】、【デモクリトス】が現れ、やがて【プロタゴラス】ら【ソフィスト】の相対主義に対して【ソクラテス】が普遍的な真理を求め、【プラトン】(『国家』、【アカデメイア】)、【アリストテレス】(【リュケイオン】)へと受け継がれました。悲劇の【アイスキュロス】【ソフォクレス】【エウリピデス】、喜劇の【アリストファネス】、歴史の【ヘロドトス】と【トゥキディデス】、医学の【ヒッポクラテス】、建築ではドーリア式の【パルテノン神殿】と彫刻家【フェイディアス】も重要です。", "ヘレニズム時代に広がったギリシア文化は、その後ローマに受け継がれ、さらにビザンツ帝国やイスラーム世界を経て、中世ヨーロッパのルネサンスへとつながっていきます。また、ガンダーラ美術のように、東方の仏教美術にも影響を与えたとされます。古代ギリシアは、政治・思想・科学・芸術のあらゆる面で、のちの世界に大きな遺産を残したのです。"]}], "points": ["クレタ文明(エヴァンズ・線文字A未解読)とミケーネ文明(シュリーマン・線文字Bをヴェントリスが解読)の対比", "アテネ民主政の段階:ドラコン→ソロン(財産政治・債務奴隷禁止)→ペイシストラトス(僭主)→クレイステネス(10部族制・陶片追放)→ペリクレス", "重装歩兵(平民)と三段櫂船の漕ぎ手(無産市民)の活躍が参政権拡大につながった因果関係", "アテネ民主政は直接民主政だが、女性・奴隷・在留外人は参政権をもたない", "スパルタの支配構造(市民・ペリオイコイ・ヘイロータイ)とリュクルゴスの制", "ペルシア戦争の戦い(マラトン・テルモピレー・サラミス・プラタイア)の順序と結果", "ヘレニズム三国(アンティゴノス朝・セレウコス朝・プトレマイオス朝)と前30年の終わり", "ヘレニズムの自然科学者(エウクレイデス・アルキメデス・エラトステネス・アリスタルコス)とムセイオン"], "check": [["クノッソス宮殿を発掘したイギリス人は誰か", "エヴァンズ"], ["線文字Bを解読した人物は誰か", "ヴェントリス"], ["財産額に応じて参政権を定めた前594年の改革者は誰か", "ソロン"], ["10部族制と陶片追放を導入したとされる改革者は誰か", "クレイステネス"], ["前480年、テミストクレスの指揮でアテネ海軍がペルシア艦隊を破った戦いは何か", "サラミスの海戦"], ["ペルシアの再来に備えて結成され、アテネが盟主となった同盟は何か", "デロス同盟"], ["前431年に始まったアテネとスパルタの戦争は何か", "ペロポネソス戦争"], ["前338年、マケドニアがアテネ・テーベ連合軍を破った戦いは何か", "カイロネイアの戦い"], ["アレクサンドロス大王の後継者たちを何と呼ぶか", "ディアドコイ"], ["アレクサンドリアに置かれた王立研究所は何か", "ムセイオン"]], "related": ["y_bc30", "y_bc10", "y_bc6", "y_bc4", "y_bc2", "t_ori", "t_ir", "t_ro", "t_byz", "t_bal", "t_in"], "n": 5007, "videos": [{"title": "【世界史】 ギリシア世界１ エーゲ文明 （１８分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=8Vks-mjABOw", "note": "エーゲ文明を扱い、古代ギリシア史の出発点を確認できます。"}]}, "t_ro": {"title": "ローマ史", "span": "前8世紀ごろ〜476年", "year": 117, "lead": "イタリア半島の小さな都市国家ローマは、貴族と平民の身分闘争を経て共和政を整え、地中海全域を支配する大国になりました。征服による社会の変化が内乱を生み、帝政へと移行したローマは「ローマの平和」を実現しますが、3世紀の危機を経て専制君主政となり、東西に分裂して西ローマ帝国は476年に滅びます。", "flow": ["前509年ごろ エトルリア人の王を追放し共和政が成立→貴族(パトリキ)が支配", "前5〜前3世紀 身分闘争(護民官・十二表法・リキニウス・セクスティウス法・ホルテンシウス法)→平民の権利拡大", "前272年 イタリア半島を統一→分割統治", "前264〜前146年 ポエニ戦争でカルタゴに勝利→地中海の覇者に、属州とラティフンディアが拡大", "前133年〜 グラックス兄弟の改革失敗→「内乱の1世紀」", "前60年 第1回三頭政治→カエサルの独裁と暗殺(前44年)", "前31年 アクティウムの海戦→前27年オクタウィアヌスがアウグストゥスとなり元首政開始", "96〜180年 五賢帝時代→トラヤヌス帝の時代に最大版図", "235〜284年 軍人皇帝時代→ディオクレティアヌスの専制君主政", "313年 ミラノ勅令でキリスト教公認→330年コンスタンティノープル遷都", "395年 テオドシウス帝の死後、帝国が東西に分裂", "476年 オドアケルが西ローマ皇帝を廃位→西ローマ帝国滅亡"], "sync": [], "secs": [{"t": "都市国家ローマの成立と共和政", "p": ["ローマは、イタリア半島中部のティベル川のほとりに【ラテン人】が建設した都市国家です。伝説では前753年に建国されたとされます。初期のローマは、半島北部で高度な文明をもっていた【エトルリア人】の王に支配されていましたが、前509年ごろに王を追放し、【共和政】を始めたと伝えられています。王政に戻ることを嫌ったローマ人は、一人の人物に権力が集中しない仕組みを工夫しました。", "共和政ローマでは、任期1年で2名が選ばれる最高官職【コンスル(執政官)】が行政と軍事を担い、貴族の終身議員からなる【元老院】が実質的な最高機関として国政を指導しました。非常時には、半年の任期で全権を握る【独裁官(ディクタトル)】が置かれました。これらの官職は、はじめは貴族である【パトリキ】が独占しており、平民である【プレブス】は政治から排除されていました。"]}, {"t": "身分闘争とイタリア半島の統一", "p": ["ギリシアと同じように、ローマでも平民が【重装歩兵】として国防の中心を担うようになると、政治的な権利を求める声が高まりました。平民は、ローマ市から集団で退去するという手段で貴族に圧力をかけ、前5世紀前半には平民を守る役職として【護民官】と、平民だけの議会である【平民会】が設けられました。護民官は、元老院やコンスルの決定に拒否権をもっていました。", "前450年ごろには、それまで貴族が独占していた慣習法が【十二表法】として成文化され、貴族による勝手な法の運用が抑えられました。前367年の【リキニウス・セクスティウス法】では、【コンスルの1人を平民から選ぶ】ことが定められ、公有地の占有も制限されました。さらに前287年の【ホルテンシウス法】によって、平民会の決議が元老院の承認なしに国法となることが認められ、貴族と平民の法的な平等が実現しました。ただし、実際には有力な平民が貴族と結びついて新しい支配層(ノビレス)を形成し、元老院が政治を指導する体制は続きました。", "こうして国内の結束を固めたローマは周辺へ勢力を広げ、前272年には南イタリアのギリシア人植民市【タレントゥム】を征服してイタリア半島を統一しました。ローマは征服した都市に異なる権利を与えて互いに団結させない【分割統治】を行い、反乱を防ぎました。"]}, {"t": "ポエニ戦争と地中海支配がもたらした変化", "p": ["イタリア半島を統一したローマは、西地中海の覇権をめぐって、フェニキア人の植民市【カルタゴ】と衝突しました。これが前264年から前146年にかけて3回にわたって戦われた【ポエニ戦争】です。第1回の戦争でローマは【シチリア島】を獲得し、ここを最初の【属州】としました。第2回の戦争では、カルタゴの名将【ハンニバル】がアルプスを越えてイタリアに侵入し、前216年の【カンネーの戦い】でローマ軍を壊滅させましたが、ローマの【スキピオ(大スキピオ)】がアフリカに逆上陸し、前202年の【ザマの戦い】でハンニバルを破りました。そして【前146年】、ローマはカルタゴを滅ぼし、同じ年にギリシアのコリントスも破壊して、地中海世界の覇者となりました。", "しかし、この大成功はローマ社会に深刻なひずみを生みました。長い従軍で農地を荒らされた中小農民は没落し、属州から安い穀物が流れ込んだことも打撃となりました。一方、元老院議員などの有力者は、没落農民の土地や公有地を集め、戦争捕虜の奴隷を使って大規模な農場【ラティフンディア】を経営しました。属州の徴税請負などで富を得た【騎士(エクイテス)】という新興階層も現れました。土地を失った農民は都市ローマに流れ込み、無産市民となりました。重装歩兵として国を支えた中小農民の没落は、ローマ軍の弱体化を意味していました。"]}, {"t": "内乱の1世紀と共和政の崩壊", "p": ["この危機に立ち向かったのが【グラックス兄弟】です。前133年に護民官となった兄ティベリウスは、大土地所有を制限し、土地を無産市民に分配して自作農を再建しようとしましたが、元老院の反発を受けて殺害され、弟ガイウスも改革の途中で死に追い込まれました。これ以後、ローマは約100年にわたる「内乱の1世紀」に入ります。", "政界は、元老院の伝統的な権威を守ろうとする【閥族派】と、民会を基盤に民衆の支持を集める【平民派】に分かれて争いました。平民派の【マリウス】は、無産市民を志願兵として採用する兵制改革を行いましたが、その結果、兵士は国家よりも給料や土地を与えてくれる将軍個人に忠誠を誓う私兵のような存在になっていきます。閥族派の【スラ】とマリウスは軍事力で争い、ローマ市民権を求めたイタリアの同盟市が反乱を起こす【同盟市戦争】や、剣闘士【スパルタクス】の率いる奴隷反乱も起こりました。", "前60年、ポンペイウス・クラッスス・【カエサル】の3人が【第1回三頭政治】を結びます。カエサルはガリア遠征で名声と軍事力を得ると、ポンペイウスを倒して独裁官となり、ユリウス暦の採用などの改革を進めました。しかし、共和政の伝統を守ろうとする【ブルートゥス】らによって前44年に暗殺されます。その後、カエサルの養子オクタウィアヌス・アントニウス・レピドゥスが【第2回三頭政治】を結びましたが、やがて対立し、前31年の【アクティウムの海戦】でオクタウィアヌスがアントニウスとエジプトのクレオパトラの連合軍を破りました。これによりプトレマイオス朝は滅び、地中海世界はローマのもとに統一されました。"]}, {"t": "帝政の始まりと「ローマの平和」", "p": ["前27年、オクタウィアヌスは元老院から【アウグストゥス】(尊厳者)の称号を受けました。彼は共和政の形式を尊重し、自らを「市民の中の第一人者」を意味する【プリンケプス】と称しましたが、実際には軍事・政治の権限を一手に握っていました。この体制を【元首政(プリンキパトゥス)】と呼び、事実上の帝政の始まりとされます。カエサルが露骨な独裁で暗殺されたことを教訓に、元老院との協調の形をとった点がポイントです。", "アウグストゥスから約200年間、ローマ帝国は【パクス=ロマーナ(ローマの平和)】と呼ばれる繁栄の時代を迎えます。途中にはキリスト教徒を迫害した【ネロ】のような暴君も現れましたが、96年から180年までの【五賢帝】時代には安定した政治が続きました。【ネルウァ】に始まり、【トラヤヌス】の時代には帝国の領土が最大となり、【ハドリアヌス】は国境の防衛に力を注ぎ、ストア派の哲学者でもあった【マルクス=アウレリウス=アントニヌス】で五賢帝時代は終わります。", "この時代、帝国の各地には都市がつくられ、【アッピア街道】などの道路網が整備され、地中海交易が盛んになりました。【コロッセウム】や【パンテオン】、【ガール水道橋】などの建造物は、ローマ人の実用的な技術力を示しています。また、212年には【カラカラ帝】が帝国内の全自由人にローマ市民権を与えました。もともとローマ市民のための法だったローマ法は、多様な民族に適用される【万民法】へと発展していきました。"]}, {"t": "3世紀の危機と専制君主政", "p": ["五賢帝時代が終わると、帝国は動揺し始めます。3世紀には、各地の軍隊が自分たちの司令官を皇帝に擁立して争う【軍人皇帝時代】(235〜284年)となり、約50年の間に多くの皇帝が交代しました。北方からはゲルマン人、東方からはササン朝ペルシアが国境を脅かし、軍事費の増大のために重税が課され、都市の商工業は衰えました。", "こうした中で、農業経営の形も変わりました。奴隷の供給が減ったため、ラティフンディアにかわって、土地を借りて耕す小作人【コロヌス】を使う【コロナトゥス】が広がります。コロヌスはやがて土地に縛られて移動の自由を失い、中世ヨーロッパの農奴の先駆けとなりました。", "284年に即位した【ディオクレティアヌス】は、帝国を立て直すため、皇帝を神のように崇めさせる【専制君主政(ドミナトゥス)】を始めました。広大な帝国を一人で治めるのは難しいと考えた彼は、帝国を東西に分け、それぞれに正帝と副帝を置く【四帝分治制(テトラルキア)】を採用しました。また、皇帝崇拝を拒むキリスト教徒を大規模に迫害しました。"]}, {"t": "キリスト教の発展と帝国の分裂", "p": ["1世紀初め、ローマ支配下のパレスチナで【イエス】が神の愛と隣人愛を説きました。イエスが処刑された後、弟子たちは彼を救世主(キリスト)と信じ、【ペテロ】や【パウロ】の伝道によって、その教えは帝国各地の都市に広まりました。イエスの言行や使徒の手紙は『【新約聖書】』にまとめられます。皇帝崇拝を拒んだキリスト教徒はたびたび迫害を受け、地下墓所【カタコンベ】で礼拝を行ったと伝えられます。", "それでも信者は増え続け、帝国の統一を保つためにはキリスト教を味方につけるほうがよいと考えた【コンスタンティヌス帝】は、313年のミラノ勅令でキリスト教を公認しました。325年には【ニケーア公会議】を開き、キリストを神と同一視する【アタナシウス】派を正統とし、キリストの神性を否定する【アリウス】派を異端としました。アタナシウス派の考えはのちに【三位一体説】として確立します。コンスタンティヌス帝は、【ソリドゥス金貨】を発行して経済を安定させ、コロヌスの移動を禁じ、330年には都をビザンティオンに移して【コンスタンティノープル】と改称しました。その後、【ユリアヌス(背教者)】が古来の神々の信仰を復活させようとしましたが、失敗に終わりました。", "4世紀後半、アジア系の【フン人の侵入】に押された【西ゴート人】が帝国領内に移動し、378年の【アドリアノープルの戦い】でローマ軍を破りました。これをきっかけにゲルマン人の大移動が本格化します。【テオドシウス帝】はキリスト教を国教とし、他の宗教を禁止しましたが、【395年】に彼が亡くなると、帝国は2人の息子によって東西に分割されました。", "西ローマ帝国はゲルマン人の侵入に耐えきれず、476年、ゲルマン人傭兵隊長【オドアケル】によって皇帝が廃位され、滅亡しました。一方、東ローマ帝国(ビザンツ帝国)は、その後も約1000年にわたって存続します。ローマが残したローマ法・ラテン語・キリスト教会は、中世ヨーロッパ世界の土台となりました。", "ローマの文化は、ギリシア文化を受け継ぎつつ、法律や建築などの実用面で独自の成果をあげました。ラテン文学では『アエネイス』の【ウェルギリウス】、散文の【キケロ】、ストア派哲学者の【セネカ】、歴史家の【リウィウス】や『ゲルマニア』の【タキトゥス】が活躍し、ギリシア人の【プルタルコス】・【ポリビオス】・【ストラボン】・【プトレマイオス】もローマ時代の学者です。教父【エウセビオス】や【アウグスティヌス】は、キリスト教の教義の確立に貢献しました。"]}], "points": ["身分闘争の4段階:護民官・平民会→十二表法→リキニウス・セクスティウス法(前367年)→ホルテンシウス法(前287年)", "ポエニ戦争(カンネー・ザマ・前146年)と、その結果としての中小農民の没落・ラティフンディアの拡大", "グラックス兄弟の改革失敗→閥族派と平民派の抗争→三頭政治という内乱の流れ", "元首政(アウグストゥス、プリンケプス)と専制君主政(ディオクレティアヌス、ドミナトゥス)の違い", "コロナトゥス(コロヌス)は中世の農奴制の先駆け", "ミラノ勅令(313年)・ニケーア公会議(325年)・国教化(テオドシウス帝)の区別", "395年東西分裂、476年オドアケルによる西ローマ帝国滅亡", "212年カラカラ帝の全自由人への市民権付与と万民法の発展"], "check": [["前287年、平民会の決議が国法となることを定めた法は何か", "ホルテンシウス法"], ["前216年、ハンニバルがローマ軍を破った戦いは何か", "カンネーの戦い"], ["奴隷を使った大土地所有制を何と呼ぶか", "ラティフンディア"], ["大土地所有を制限して自作農の再建を図った兄弟は誰か", "グラックス兄弟"], ["前31年、オクタウィアヌスがアントニウスらを破った戦いは何か", "アクティウムの海戦"], ["アウグストゥスが始めた政治体制を何と呼ぶか", "元首政(プリンキパトゥス)"], ["帝国を4分して統治する四帝分治制を始めた皇帝は誰か", "ディオクレティアヌス"], ["325年のニケーア公会議で正統とされた派は何か", "アタナシウス派"], ["378年、西ゴート人がローマ軍を破った戦いは何か", "アドリアノープルの戦い"], ["476年に西ローマ皇帝を廃位したゲルマン人傭兵隊長は誰か", "オドアケル"]], "related": ["y_bc6", "y_bc4", "y_bc2", "y_1", "y_2", "y_3", "y_4", "y_5", "t_gr", "t_byz", "t_it", "t_fr", "t_ps", "t_ir"], "n": 4279, "videos": [{"title": "【世界史】 ローマ世界１ 共和政の確立 （２０分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=q-P5HeHb7fI", "note": "ローマ共和政の成立を学べ、2026年度第4問で問われたローマの「帝国」理解の土台になります。"}]}, "t_byz": {"title": "ビザンツ帝国史", "span": "330年〜1453年", "year": 555, "lead": "ビザンツ帝国は、ローマ帝国の東半分が受け継がれた国家で、コンスタンティノープルを都に約1000年続きました。皇帝が教会も支配する体制のもと、ギリシア正教とギリシア古典文化を守り、スラヴ人の世界に大きな影響を与えましたが、イスラーム勢力や十字軍の圧迫を受けて縮小し、1453年にオスマン帝国に滅ぼされました。", "flow": ["330年 コンスタンティヌス帝がコンスタンティノープルに遷都→東方の新しい中心", "395年 ローマ帝国が東西に分裂→東ローマ(ビザンツ)帝国として存続", "6世紀 ユスティニアヌス帝がヴァンダル王国・東ゴート王国を滅ぼし地中海をほぼ回復→ローマ法大全・ハギア=ソフィア聖堂", "7世紀 イスラーム勢力にシリア・エジプトを奪われる→軍管区制(テマ制)・屯田兵制で防衛、公用語がギリシア語に", "726年 レオン3世の聖像禁止令→ローマ教会との対立が深まる", "9〜10世紀 キュリロス兄弟の布教などでスラヴ人へ正教が広まる→キリル文字", "1054年 東西教会が相互に破門→ギリシア正教会とローマ=カトリック教会に分裂", "1071年 セルジューク朝に敗北→アレクシオス1世が教皇に救援を要請し十字軍へ", "1204年 第4回十字軍がコンスタンティノープルを占領→ラテン帝国(1261年に帝国回復)", "1453年 メフメト2世のオスマン軍により滅亡→イスタンブルとしてオスマン帝国の都に"], "sync": [], "secs": [{"t": "東ローマ帝国としての出発", "p": ["ビザンツ帝国の起点は、330年に【コンスタンティヌス帝】が、ギリシア人の植民市ビザンティオンに都を移し、【コンスタンティノープル】と名づけたことにあります。この都市は、ヨーロッパとアジアを結ぶボスフォラス海峡に面し、黒海と地中海を結ぶ交易路も押さえる要地でした。三方を海に囲まれ、陸側には堅固な城壁が築かれたため、外敵の攻撃に強い都市でもありました。帝国の名前は、旧名ビザンティオンにちなんで後世につけられたもので、住民たち自身は最後まで自らを「ローマ人」と考えていました。", "395年にローマ帝国が東西に分裂すると、東半分は東ローマ帝国となりました。西ローマ帝国がゲルマン人の大移動の中で476年に滅亡したのに対し、東ローマ帝国が生き残ったのはなぜでしょうか。東方は古くから都市と商工業が発達した豊かな地域で、税収が安定していたこと、ゲルマン人の主な移動の方向が西方に向かったこと、そして難攻不落のコンスタンティノープルがあったことなどが理由として挙げられます。こうしてビザンツ帝国は、ローマ帝国の正統な後継者として存続することになりました。", "ビザンツ帝国の政治の特徴は、皇帝が政治の支配者であると同時に、教会に対しても大きな権限をもっていたことです。コンスタンティノープル総主教は皇帝の強い影響下に置かれました。西ヨーロッパでは教皇と皇帝・国王が別々の権威として並び立ち、ときに争ったのとは対照的です。また、ビザンツ帝国では官僚制が整い、【ソリドゥス金貨】(ノミスマ)は長く国際通貨として信用されました。"]}, {"t": "ユスティニアヌス帝と地中海帝国の復活", "p": ["6世紀の【ユスティニアヌス帝】(在位527〜565年)は、かつてのローマ帝国の領土を回復することを目指しました。彼は北アフリカの【ヴァンダル王国】を滅ぼし、さらに長い戦いのすえ、イタリアの【東ゴート王国】も滅ぼして、地中海をほぼ取り囲む領土を回復しました。また、イベリア半島南部の一部も奪いました。", "内政面では、法学者【トリボニアヌス】らに命じて、ローマ時代の法律と学説を集大成した『【ローマ法大全】』を編纂させました。これはのちに西ヨーロッパでも研究され、近代ヨーロッパの法体系に大きな影響を与えました。また、都に【ハギア=ソフィア聖堂】を再建しました。巨大なドームとモザイク壁画を特徴とするこの聖堂は、【ビザンツ様式】の代表作です。さらに、中国から蚕の卵がもたらされたことで、帝国内で【養蚕(絹織物業)】が始まったと伝えられます。", "しかし、ユスティニアヌス帝の大規模な征服戦争と建設事業は、帝国の財政を苦しめ、重税への不満を招きました。東方ではササン朝ペルシアとの戦いも続いていました。彼の死後まもなく、イタリアの大半はゲルマン系の【ランゴバルド人】に奪われ、地中海帝国の復活は長続きしませんでした。"]}, {"t": "イスラームの圧迫と国家の再編", "p": ["7世紀に入ると、帝国はさらに大きな危機に直面します。アラビア半島で興ったイスラーム勢力が急速に拡大し、帝国はシリアやエジプトといった豊かな地域を失いました。コンスタンティノープルもたびたびイスラーム軍に包囲されましたが、城壁と「ギリシアの火」と呼ばれる火炎兵器などによって守り抜きました。北方からはスラヴ人や遊牧民のブルガール人が侵入し、バルカン半島の支配も揺らぎました。", "この危機を乗り切るため、帝国は国家の仕組みを大きく変えました。帝国の領土をいくつかの軍管区に分け、その司令官に軍事と行政の両方の権限を与える【軍管区制(テマ制)】が整えられました。また、農民に土地を与えるかわりに兵役を義務づける【屯田兵制】を実施し、自由な農民兵士が国防を支える体制をつくりました。7世紀には公用語もラテン語から【ギリシア語】に変わり、帝国は「ギリシア人のキリスト教国家」としての性格を強めていきます。この時期以降を、本来の意味でのビザンツ帝国と呼ぶこともあります。"]}, {"t": "聖像禁止令と東西教会の分裂", "p": ["726年、皇帝レオン3世は【聖像禁止令】を出し、キリストや聖人を描いた【イコン】(聖像画)の崇拝を禁止しました。偶像崇拝を厳しく否定するイスラーム教徒との対抗上の理由などがあったとされます。しかし、ゲルマン人への布教に聖像を利用していたローマ教会はこれに強く反発しました。", "ローマ教皇は、ビザンツ皇帝に頼らずに自らを守ってくれる新しい保護者を求め、フランク王国に接近します。756年の【ピピンの寄進】や、800年の教皇【レオ3世】による【カール大帝】の戴冠は、こうした流れの中で起こりました。西ヨーロッパに、ビザンツ皇帝とは別のもう一人の「ローマ皇帝」が現れたことになります。聖像崇拝はのちに帝国内でも復活しますが、東西の教会の溝は深まり続け、1054年には互いに相手を破門して、東の【ギリシア正教会】と西の【ローマ=カトリック教会】に分裂しました。"]}, {"t": "スラヴ世界への影響", "p": ["ビザンツ帝国は、東ヨーロッパのスラヴ人の世界に宗教・文化の面で大きな影響を与えました。9世紀には、宣教師キュリロスとメトディオスの兄弟がスラヴ人への布教を行い、スラヴ語を書き表すための文字を考案しました。これをもとに生まれたのが【キリル文字】で、現在もロシア語やブルガリア語、セルビア語などで使われています。", "バルカン半島では、トルコ系のブルガール人がスラヴ人と同化して【ブルガリア帝国(第1次ブルガリア帝国)】を建て、ビザンツ帝国と激しく争いましたが、ギリシア正教を受け入れました。11世紀初めには、ビザンツ帝国がこれを併合しています。また、ロシアではキエフ公国の【ウラジーミル1世】が10世紀末にギリシア正教を受け入れ、ビザンツ文化がロシアに根づきました。", "一方で、同じスラヴ人でも、【ポーランド人】や【チェック人】、【クロアティア人】は西方からの布教を受けてカトリックを受け入れました。ギリシア正教を受け入れた【セルビア人】と、カトリックを受け入れたクロアティア人は、言葉は近いのに宗教や文字が異なることになり、このことは20世紀の【ユーゴスラヴィア】の民族問題の背景にもなりました。また、アジア系の【マジャール人】はハンガリー王国を建て、カトリックを受け入れました。どの教会を受け入れたかが、その後の東欧各地の文化の方向を決めたといえます。"]}, {"t": "ビザンツ文化の特色", "p": ["ビザンツ文化は、ギリシア古典文化・ローマの伝統・ギリシア正教の信仰が結びついて生まれた文化です。学問の世界では、古代ギリシアの哲学者や文学者の著作が写本として大切に保存され、研究され続けました。西ヨーロッパではギリシア語を読める人がほとんどいなくなった時代にも、ビザンツ帝国ではギリシア古典が生きた教養として受け継がれていたのです。こうして守られた古典は、のちにイスラーム世界や西ヨーロッパに伝わり、学問の発展を支えることになります。", "美術と建築の分野では、円形のドームとモザイク壁画を特徴とする【ビザンツ様式】が発達しました。ハギア=ソフィア聖堂のほか、イタリアのラヴェンナにある【サン=ヴィターレ聖堂】には、ユスティニアヌス帝と皇后を描いたモザイク壁画が残されており、ビザンツ帝国がイタリアを支配していた時代を物語っています。また、金地を背景に聖母子や聖人を描いた【イコン】は、正教会の信仰の中心となり、ロシアなどにも広まりました。", "ビザンツ文化は、宗教的な性格がたいへん強く、皇帝を神の代理人とする考えのもとで、宮廷の儀式も華やかに整えられました。このような皇帝のあり方は、のちにロシアのツァーリにも受け継がれていきます。ビザンツ帝国は、政治の上ではしだいに衰えていきましたが、文化の上では東ヨーロッパ全体の「先生」の役割を果たしたといえるでしょう。"]}, {"t": "衰退と十字軍", "p": ["11世紀になると、帝国の防衛を支えた屯田兵制が崩れていきます。有力な貴族が農民の土地を集めて大土地所有を進めたため、自由な農民兵士が減少したのです。そこで皇帝は、軍役と引きかえに貴族に国有地の管理と徴税を任せる【プロノイア制】を導入しました。これは西ヨーロッパの封建制に似た仕組みで、皇帝の権力が地方貴族に分散していくことを意味しました。", "1071年、小アジアに進出してきたイスラーム教国セルジューク朝に大敗し、帝国は小アジアの大部分を失いました。危機に陥った皇帝【アレクシオス1世】は、ローマ教皇に救援を求めます。教皇【ウルバヌス2世】は1095年に【クレルモン宗教会議】を開いて聖地回復を呼びかけ、こうして十字軍が始まりました。", "しかし十字軍は、ビザンツ帝国にとって必ずしも救いにはなりませんでした。商業上の利益を狙う【ヴェネツィア】の主導のもとで進められた第4回十字軍は、聖地に向かわずに1204年にコンスタンティノープルを占領し、【ラテン帝国】を建てたのです。ビザンツの貴族たちは小アジアに逃れて【ニケーア帝国】などを建て、1261年にコンスタンティノープルを奪回して帝国を再建しましたが、往時の力は戻りませんでした。この時期には、イタリア商人に帝国内の交易の利益を奪われたことも衰退の一因となりました。"]}, {"t": "コンスタンティノープルの陥落とその後", "p": ["14世紀に小アジアから興った【オスマン帝国】はバルカン半島に進出し、ビザンツ帝国はコンスタンティノープル周辺のわずかな地域を残すのみとなりました。そして1453年、オスマン帝国のスルタン【メフメト2世】が大軍と大砲でコンスタンティノープルを包囲し、最後の皇帝【コンスタンティヌス11世】は戦死して、ビザンツ帝国は滅亡しました。都はイスタンブルと呼ばれるようになり、オスマン帝国の首都となりました。ハギア=ソフィア聖堂はモスクに改められました。", "ビザンツ帝国の滅亡は、ヨーロッパに大きな影響を残しました。帝国の滅亡前後に、ギリシア古典に通じた学者たちがイタリアに移り住み、古代ギリシアの文献を伝えたことは、イタリア=ルネサンスの発展を助けたとされます。また、ロシアのモスクワ大公国では【イヴァン3世】が最後のビザンツ皇帝の姪と結婚し、ツァーリの称号を用いて、自らをビザンツの後継者と位置づけました。ギリシア正教の中心は、こうしてロシアへと受け継がれていきます。", "約1000年続いたビザンツ帝国は、ローマ法とギリシア古典文化、ギリシア正教を保存・発展させ、それを東ヨーロッパやロシアに伝えた点で、世界史上重要な役割を果たしました。西ヨーロッパの中世が農村中心で貨幣経済が後退したのに対し、ビザンツ帝国では都市と貨幣経済が維持され続けたことも、両者の大きな違いとして押さえておきましょう。"]}], "points": ["ユスティニアヌス帝の業績:ヴァンダル・東ゴート征服、ローマ法大全(トリボニアヌス)、ハギア=ソフィア聖堂、養蚕", "7世紀の危機への対応として軍管区制(テマ制)と屯田兵制、公用語のギリシア語化", "726年レオン3世の聖像禁止令→ローマ教会がフランク王国に接近→1054年東西教会分裂", "11世紀のプロノイア制は屯田兵制の崩壊を受けたもので、封建制に似た性格をもつ", "アレクシオス1世の救援要請→クレルモン宗教会議→十字軍、第4回十字軍のラテン帝国(1204年)", "スラヴ人の宗教の違い:正教(ロシア・セルビア・ブルガリア)とカトリック(ポーランド・チェック・クロアティア)", "1453年メフメト2世による滅亡、最後の皇帝コンスタンティヌス11世", "イヴァン3世がビザンツの後継者を自任しツァーリを称したこと"], "check": [["ユスティニアヌス帝が編纂させた法典は何か", "ローマ法大全"], ["ローマ法大全の編纂の中心となった法学者は誰か", "トリボニアヌス"], ["ユスティニアヌス帝が再建したビザンツ様式の代表的な聖堂は何か", "ハギア=ソフィア聖堂"], ["軍管区の司令官に軍事・行政権を与えた制度は何か", "軍管区制(テマ制)"], ["726年にレオン3世が出した法令は何か", "聖像禁止令"], ["11世紀に導入された、軍役と引きかえに貴族に国有地の管理を任せる制度は何か", "プロノイア制"], ["教皇に救援を求め、十字軍のきっかけをつくったビザンツ皇帝は誰か", "アレクシオス1世"], ["第4回十字軍が1204年に建てた国家は何か", "ラテン帝国"], ["スラヴ人への布教から生まれ、ロシア語などで使われる文字は何か", "キリル文字"], ["1453年にコンスタンティノープルを攻略したオスマン帝国のスルタンは誰か", "メフメト2世"]], "related": ["y_4", "y_5", "y_6", "y_7", "y_8", "y_11", "y_13", "y_15", "t_ro", "t_it", "t_ru", "t_bal", "t_tr", "t_ar", "t_pl"], "n": 4243, "videos": [{"title": "【世界史】 中世各国史４ ビザンツ帝国の歴史 （２１分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=9NqJubDR1eA", "note": "東ローマ帝国の千年の歴史を通しで整理できます。"}]}, "t_uk": {"title": "イギリス史", "span": "5世紀〜現在", "year": 1688, "lead": "イギリスは、王権を法と議会で縛るという伝統を中世から積み重ね、17世紀の二つの革命を経て立憲君主政と議会政治を確立しました。世界で最初に産業革命を達成して「世界の工場」となり、19世紀には広大な植民地帝国を築きましたが、二つの世界大戦を経て覇権をアメリカに譲り、福祉国家・ヨーロッパ統合との関わりの中で現代を歩んでいます。", "flow": ["5世紀 アングロ=サクソン人が移住→七王国(ヘプターキー)", "1066年 ノルマン=コンクェスト→ノルマン朝、強い王権", "1215年 ジョン王がマグナ=カルタを認める→王権を法で制限する伝統", "1295年 模範議会→14世紀に二院制へ", "1339〜1453年 百年戦争、1455〜85年バラ戦争→諸侯が没落しテューダー朝の絶対王政", "1534年 首長法でイギリス国教会成立→エリザベス1世の統一法(1559年)で確立", "1642〜49年 ピューリタン革命→共和政・クロムウェルの独裁→1660年王政復古", "1688〜89年 名誉革命と権利の章典→立憲君主政", "18世紀 責任内閣制の成立、英仏植民地戦争に勝利、産業革命開始", "1832年 第1回選挙法改正→自由主義改革、ヴィクトリア時代の繁栄", "1914〜45年 二つの世界大戦→国力の低下、植民地の独立", "1973年 EC加盟→2020年にEUから離脱"], "sync": [], "secs": [{"t": "成立 ― アングロ=サクソンからノルマン朝へ", "p": ["ブリテン島には古くからケルト人が住み、のちにローマの属州となりました。ローマが撤退した後の5世紀、ゲルマン人の【アングロ=サクソン人】が大陸から渡ってきて、いくつもの王国を建てました。これを【ヘプターキー(七王国)】と呼びます。アングロ=サクソン人はやがてキリスト教を受け入れ、学者【アルクイン】のように、のちにフランクの【カロリング=ルネサンス】で活躍する人物も出しました。", "9世紀になると、北欧のノルマン人の一派であるデーン人が侵入を繰り返しました。これに抵抗したのが【アルフレッド大王】です。しかし11世紀初めにはデンマーク王【クヌート(カヌート)】がイングランドを征服し、一時はデンマーク・ノルウェーとあわせた北海帝国を築きました。", "1066年、フランスのノルマンディー公ウィリアムが【ヘースティングズの戦い】でアングロ=サクソンの王を破り、【ウィリアム1世】として即位してノルマン朝を開きました。これが【ノルマン=コンクェスト】です。征服王として全土の土地を家臣に分け与えたウィリアム1世は、検地台帳【ドゥームズデー=ブック】を作成して全国の土地と財産を把握しました。征服によって成立したため、イギリスでは大陸諸国よりも早くから強い王権が生まれた点が重要です。"]}, {"t": "中世 ― 王権の制限と議会の誕生", "p": ["1154年、フランスのアンジュー伯が【ヘンリ2世】として即位し、プランタジネット朝を開きました。彼はフランス西半分にも広大な領地をもち、イギリス王はフランス王の家臣でありながらフランス王より大きな領地をもつ存在となります。この複雑な関係が、のちの英仏の長い対立の原因となりました。その子【リチャード1世】は第3回十字軍で活躍しましたが、国を空けることが多かった王です。", "次の【ジョン王】は、フランス王【フィリップ2世】に敗れてフランス内の領地の大半を失い、教皇【インノケンティウス3世】とも争って破門されました。さらに戦費のために重税を課したため、貴族たちが反発し、1215年、ジョン王は【マグナ=カルタ(大憲章)】を認めさせられました。これは、新たな課税には貴族や聖職者の会議の同意が必要であることなどを定めたもので、国王も法に従わなければならないという考えの出発点となりました。", "次のヘンリ3世がマグナ=カルタを無視すると、貴族【シモン=ド=モンフォール】が反乱を起こし、1265年に貴族・聖職者に加えて州と都市の代表を招いた議会を開きました。これがイギリス議会の起源とされます。さらに1295年、エドワード1世は各身分の代表を集めた【模範議会】を招集しました。14世紀には議会が【上院(貴族院)と下院(庶民院)】に分かれ、下院には地方の騎士や都市の代表が集まりました。", "14世紀には、フランス王位継承問題と毛織物産業の中心地【フランドル地方】をめぐって、【エドワード3世】がフランスとの間に【百年戦争】(1339〜1453年)を始めます。初めは【クレシーの戦い】や【エドワード黒太子】の活躍でイギリスが優勢でしたが、最終的には【カレー】を除く大陸の領土を失いました。この時期には黒死病の流行で人口が激減し、農奴の地位が向上して、独立自営農民【ヨーマン】が成長しました。重税に反発した1381年の【ワット=タイラーの乱】では、聖職者【ジョン=ボール】が「アダムが耕しイヴが紡いだとき、だれが貴族であったか」と身分制を批判したと伝えられます。宗教面では【ウィクリフ】が聖書を重視して教会を批判し、その支持者は【ロラード派】と呼ばれました。", "百年戦争の後、王位をめぐって貴族がランカスター家とヨーク家に分かれて争う【バラ戦争】(1455〜85年)が起こりました。この内乱で多くの諸侯・騎士が没落し、勝利した【ヘンリ7世】がテューダー朝を開いて、王権を強化しました。"]}, {"t": "近世 ― テューダー朝の絶対王政と宗教改革", "p": ["テューダー朝の【ヘンリ8世】は、王妃との離婚を教皇が認めなかったことをきっかけに、1534年に【首長法(国王至上法)】を出し、国王をイギリス教会の首長としてローマ=カトリック教会から離脱しました。こうして【イギリス国教会】が成立します。修道院は解散され、その土地は国王の財源となり、のちに貴族やジェントリ(地主層)に売却されて、彼らが王を支える勢力となりました。イギリスの宗教改革は、信仰の問題よりも王権の強化という政治的な動機から始まった点が特徴です。", "その後、カトリック教徒の【メアリ1世】がカトリックを復活させ新教徒を弾圧しましたが、次の【エリザベス1世】は1559年に【統一法】を出して国教会を確立しました。エリザベス1世は、毛織物工業を保護し、1588年にはスペインの無敵艦隊(アルマダ)を破り、1600年には【イギリス東インド会社】を設立して、海外進出の基礎を築きました。また、毛織物の原料となる羊毛の生産のために農地を柵で囲い込んで牧羊地にする第1次囲い込みが進み、【トマス=モア】は『ユートピア』で「羊が人間を食う」とこれを批判しました。文学では【シェークスピア】が活躍しています。"]}, {"t": "17世紀 ― 二つの革命と議会政治の確立", "p": ["エリザベス1世が亡くなると、スコットランド王が【ジェームズ1世】として即位し、ステュアート朝が始まりました。ジェームズ1世は王権神授説を唱えて議会を軽んじ、国教会を強制して【ピューリタン(清教徒)】を弾圧しました。この弾圧を逃れて北アメリカに渡ったのが、1620年の【ピルグリム=ファーザーズ】です。次の【チャールズ1世】も専制政治を続けたため、議会は1628年に【権利の請願】を提出し、議会の同意のない課税や不当な逮捕をやめるよう求めましたが、王は議会を解散してしまいました。", "スコットランドの反乱の戦費を得るために王が議会を開くと、王党派と議会派の対立は内戦へと発展し、1642年に【ピューリタン革命】が始まりました。ピューリタンの【クロムウェル】が率いる鉄騎隊を中心とする議会派が勝利し、1649年にチャールズ1世は処刑され、共和政が始まります。クロムウェルは、急進的な民主化を求める【水平派】を弾圧し、アイルランドを征服しました。1651年には、オランダの中継貿易に打撃を与えるために【航海法】を定め、これが【イギリス=オランダ(英蘭)戦争】の原因となりました。1653年には【護国卿】となって独裁を行いましたが、厳格なピューリタン的統治は国民の不満を招きました。", "クロムウェルの死後、1660年に【王政復古】が起こり、チャールズ2世が即位します。しかし彼がカトリックを復活させようとすると、議会は1673年に公職者を国教徒に限る【審査法】、1679年に不当な逮捕を禁じる【人身保護法】を定めて対抗しました。この頃、王権に寛容な【トーリ党】と、議会の権利を重視する【ホイッグ党】が生まれ、これが政党の起源となりました。", "続く【ジェームズ2世】もカトリックと専制政治を強めたため、1688年、議会はオランダから王の娘メアリとその夫ウィレムを招きました。ジェームズ2世はフランスに亡命し、血を流さずに王が交代したため、これを【名誉革命】と呼びます。【ウィリアム3世とメアリ2世】は、1689年に議会が提出した権利の宣言を受け入れ、【権利の章典】として発布しました。こうして、議会が国王に優越する立憲君主政が確立したのです。この革命を理論的に正当化したのが、抵抗権を説いた【ロック】の『統治二論』でした。一方、ピューリタン革命の混乱を経験した【ホッブズ】は『リヴァイアサン』で強力な国家権力の必要を説いています。"]}, {"t": "18世紀 ― 議会政治の発展と植民地帝国", "p": ["1707年、イングランドは【スコットランド】と合同し、大ブリテン王国となりました。1714年にステュアート朝が途絶えると、ドイツのハノーヴァー選帝侯が【ジョージ1世】として迎えられ、ハノーヴァー朝が始まります。英語を話せず政治に関心の薄かった王のもとで、ホイッグ党の【ウォルポール】が首相として政治を主導しました。彼は議会で多数の支持を失うと辞職し、内閣は議会に対して責任を負うという【責任内閣制】が成立しました。「国王は君臨すれども統治せず」という原則はこうして生まれました。", "18世紀のイギリスは、フランスと世界各地で植民地をめぐって争いました。北アメリカでは【フレンチ=インディアン戦争】、インドでは【クライヴ】の率いる東インド会社軍がフランス・ベンガル太守の連合軍を破った1757年の【プラッシーの戦い】に勝利し、1763年の【パリ条約(1763年)】でカナダやミシシッピ川以東のルイジアナなどを獲得しました。大西洋では、ヨーロッパ・アフリカ・アメリカを結ぶ【三角貿易】で奴隷貿易を行い、莫大な富を得ました。", "しかし、戦費を補うために北アメリカの13植民地に課税したことが反発を招き、1775年にアメリカ独立戦争が始まり、1783年のパリ条約でアメリカの独立を認めることになりました。植民地を失ったイギリスは、その後インドやアジア・アフリカへと関心を移していきます。"]}, {"t": "産業革命と自由主義の時代", "p": ["18世紀後半、イギリスで世界最初の【産業革命】が始まりました。その条件として、植民地と海外市場をもっていたこと、【第2次囲い込み】と【ノーフォーク農法】による農業革命で食料が増え、土地を失った農民が都市の労働力となったこと、豊富な石炭と鉄があったこと、商業で蓄えた資本があったことなどが挙げられます。", "産業革命は【綿工業】から始まりました。インド産綿布への需要を背景に、【ジョン=ケイ】の飛び杼、【ハーグリーヴズ】のジェニー紡績機、【アークライト】の水力紡績機、【クロンプトン】のミュール紡績機、【カートライト】の力織機と、紡ぐ工程と織る工程の技術革新が互いに刺激し合って進みました。【ワット】が改良した蒸気機関は動力として工場に導入され、交通では【スティーヴンソン】が蒸気機関車を実用化し、1830年には【リヴァプール・マンチェスター間】に鉄道が開通しました。綿工業の中心地【マンチェスター】は工業都市として成長し、イギリスは【「世界の工場」】と呼ばれるようになりました。", "一方で、劣悪な環境で長時間働く労働者、とくに女性や子どもの問題が深刻化しました。機械に仕事を奪われた職人は機械を打ち壊す【ラダイト運動】を起こしました。こうした中、【ロバート=オーウェン】は労働環境の改善を唱え、1833年には年少者の労働時間を制限する【工場法】が制定されました。経済学では【アダム=スミス】が『諸国民の富』で自由放任を説き、【マルサス】や【リカード】がこれを発展させました。", "19世紀前半には自由主義的な改革が次々に進みます。1828年に【審査法の廃止】、1829年に【オコンネル】の運動による【カトリック教徒解放法】が成立しました(アイルランドは1801年に併合されていました)。1832年の第1回選挙法改正では腐敗選挙区が廃止され、【産業資本家など都市の中産階級】が選挙権を得ました。しかし労働者には選挙権が与えられなかったため、労働者は男性普通選挙などを求める人民憲章を掲げて【チャーティスト運動】を展開しました。経済面では、【コブデン(とブライト)】らの運動によって1846年に穀物法が廃止され、1849年には【航海法】も廃止されて、【自由貿易】体制が確立しました。"]}, {"t": "ヴィクトリア時代と帝国主義", "p": ["【ヴィクトリア女王】の時代(1837〜1901年)、イギリスは繁栄の頂点を迎えました。1851年のロンドン万国博覧会では、鉄とガラスでつくられた【水晶宮(クリスタル=パレス)】がイギリスの工業力を示しました。政治では、保守党の【ディズレーリ】と自由党の【グラッドストン】が交互に政権を担当する二大政党制が発達しました。1867年の第2回選挙法改正では【都市の労働者】に、1884年の第3回改正では【農業労働者・鉱山労働者】に選挙権が拡大されました。グラッドストン内閣は1870年に【教育法(初等教育法)】、1871年に【労働組合法】を制定しています。", "対外的には、ディズレーリが1875年にスエズ運河会社の株を買収し、1877年にはヴィクトリア女王をインド皇帝とするインド帝国を成立させました。1878年のベルリン会議では【キプロス島】の統治権を得ています。エジプトでは【ウラービー運動】を鎮圧して事実上の保護国とし、スーダンでは【ハルツーム】をめぐってマフディー派と戦いました。南アフリカでは、ケープ植民地首相【セシル=ローズ】が進めた拡大策を受けて、植民地相【ジョゼフ=チェンバレン】のもとで【南アフリカ戦争(ブール戦争)】(1899〜1902年)が戦われました。カイロ・ケープタウン・カルカッタを結ぶ政策は【3C政策】と呼ばれます。", "国内では、アイルランドの【ジャガイモ飢饉】(1840年代)で多数の死者と移民が出て、アイルランド問題は長く政治の難題となりました。社会主義の面では、議会を通じた漸進的改革を目指す【フェビアン協会】が生まれ、1900年に結成された【労働代表委員会】が1906年に労働党となりました。ドイツの台頭を前に、イギリスは「光栄ある孤立」を捨て、1902年に日英同盟、1904年に英仏協商、1907年に英露協商を結んで三国協商を形成しました。"]}, {"t": "20世紀から現代へ", "p": ["第一次世界大戦では、イギリスは【戦車】などの新兵器を投入して戦い、戦後は戦勝国として中東に勢力を広げました。しかし、アラブ人に独立を約束した【フセイン・マクマホン協定】と、ユダヤ人にパレスチナでの民族的郷土建設を認めた【バルフォア宣言】という矛盾した約束が、のちのパレスチナ問題の原因となりました。国内では1918年に【30歳以上】の女性に選挙権が認められ、1924年には【マクドナルド】が最初の労働党内閣を組織しました。1922年に【アイルランド自由国】が成立し、1931年の【ウェストミンスター憲章】で自治領は本国と対等な地位を得て、イギリス連邦が成立しました。", "世界恐慌が起こると、マクドナルドは【挙国一致内閣】を組織し、金本位制を停止しました。さらに1932年のオタワ会議で連邦内の特恵関税を定め、【スターリング=ブロック(ポンド=ブロック)】をつくりました。ナチス=ドイツに対しては、【ネヴィル=チェンバレン】首相が宥和政策をとり、1938年のミュンヘン会談でズデーテン地方の割譲を認めましたが、ドイツの侵略は止まらず、第二次世界大戦となりました。【チャーチル】首相のもとでイギリスはドイツの空襲に耐え、連合国の勝利に貢献しました。", "戦後、アトリー労働党内閣は主要産業の国有化と社会保障制度の整備を進め、「ゆりかごから墓場まで」と呼ばれる福祉国家を目指しました。チャーチルは1946年の演説で【鉄のカーテン】という言葉を用いてソ連を批判し、冷戦の始まりを象徴しました。1947年にはインドが独立し、1956年のスエズ戦争の失敗によって中東での影響力も後退して、植民地帝国は解体していきました。経済の停滞が続く中、1973年に【ヨーロッパ共同体(EC)】に加盟し、1979年に首相となった保守党の【サッチャー】は、国営企業の民営化や規制緩和を進める新自由主義的な改革を行いました。1997年には香港を中国に返還し、その後、2016年の国民投票の結果を受けて2020年にEUから離脱しました。", "このようにイギリスの歴史は、中世以来の議会政治の伝統、世界最初の産業革命、そして世界帝国の形成と解体という三つの柱で理解すると見通しがよくなります。科学・思想の分野でも、【ニュートン】の『【プリンキピア】』、【ダーウィン】の『【種の起源】』、【ベンサム】の功利主義、【ケインズ】の経済学など、近代世界を形づくる成果を多く生み出しました。"]}], "points": ["マグナ=カルタ(1215年)→シモン=ド=モンフォールの議会(1265年)→模範議会(1295年)の流れ", "ヘンリ8世の首長法(1534年)とエリザベス1世の統一法(1559年)の区別", "権利の請願(1628年)→ピューリタン革命→審査法・人身保護法→名誉革命・権利の章典(1689年)", "ウォルポールによる責任内閣制の成立(「国王は君臨すれども統治せず」)", "綿工業の技術革新の順序(ジョン=ケイ→ハーグリーヴズ→アークライト→クロンプトン→カートライト)", "選挙法改正の対象:第1回は都市の中産階級、第2回は都市労働者、第3回は農業・鉱山労働者", "穀物法廃止(1846年)と航海法廃止(1849年)による自由貿易体制", "フセイン・マクマホン協定とバルフォア宣言の矛盾、ウェストミンスター憲章(1931年)"], "check": [["1066年にイングランドを征服しノルマン朝を開いたのは誰か", "ウィリアム1世"], ["1215年にジョン王が認めさせられた文書は何か", "マグナ=カルタ(大憲章)"], ["1295年にエドワード1世が招集した議会は何か", "模範議会"], ["1534年に国王をイギリス教会の首長とした法は何か", "首長法(国王至上法)"], ["1628年に議会がチャールズ1世に提出した文書は何か", "権利の請願"], ["1673年に公職者を国教徒に限ると定めた法は何か", "審査法"], ["名誉革命の翌年に発布された文書は何か", "権利の章典"], ["責任内閣制を成立させた首相は誰か", "ウォルポール"], ["男性普通選挙などを求めた労働者の運動は何か", "チャーティスト運動"], ["1931年、自治領に本国と対等な地位を認めた法は何か", "ウェストミンスター憲章"]], "related": ["y_5", "y_11", "y_13", "y_14", "y_16", "y_17", "y_18", "y_19", "y_20a", "y_20b", "t_fr", "t_us", "t_in", "t_oc", "t_nl", "t_ps", "t_af"], "n": 6377}, "t_fr": {"title": "フランス史", "span": "5世紀〜現在", "year": 1789, "lead": "フランスはフランク王国を起源とし、カペー朝以来しだいに王権を強め、ルイ14世の時代にヨーロッパ随一の絶対王政国家となりました。1789年のフランス革命は自由・平等の理念を世界に広め、その後のフランスは王政・共和政・帝政を何度も行き来しながら、現在の第五共和政にいたります。", "flow": ["481年 クローヴィスがメロヴィング朝を開く→アタナシウス派に改宗しローマ系住民と協調", "751年 ピピンがカロリング朝を開く→800年カール大帝の戴冠", "843年 ヴェルダン条約→西フランク王国(のちのフランス)", "987年 ユーグ=カペーがカペー朝を開く→フィリップ2世・ルイ9世・フィリップ4世が王権強化", "1339〜1453年 百年戦争→ジャンヌ=ダルクの活躍、勝利して中央集権化が進む", "1562〜98年 ユグノー戦争→アンリ4世のナントの王令", "1643〜1715年 ルイ14世の治世→絶対王政の全盛、しかし戦争で財政悪化", "1789年 フランス革命→第一共和政・ナポレオン帝政", "1815年 ウィーン体制下の復古王政→1830年七月革命、1848年二月革命", "1852年 第二帝政→1870年普仏戦争に敗れ第三共和政", "1940年 ドイツに降伏しヴィシー政府→1944年解放", "1958年 第五共和政(ド=ゴール)→ヨーロッパ統合の中心"], "sync": [], "secs": [{"t": "成立 ― フランク王国から西フランクへ", "p": ["現在のフランスにあたるガリア地方は、ローマの属州として早くからラテン文化が根づいた地域でした。5世紀、ゲルマン人の大移動の中で、【ブルグンド人】などがこの地に王国を建てましたが、最も成功したのがフランク人です。451年の【カタラウヌムの戦い】では、西ローマ軍とゲルマン人の連合軍がフン人のアッティラを退けています。481年、フランク人の【クローヴィス】がメロヴィング朝を開きました。", "多くのゲルマン人がアリウス派を信じていたのに対し、クローヴィスは正統とされた【アタナシウス派】に改宗しました。このため、カトリックを信じるローマ系住民やローマ教会の支持を得ることができ、フランク王国が発展する大きな要因となりました。やがてメロヴィング朝の王権は衰え、実権は【宮宰(マヨル=ドムス)】のカロリング家に移ります。宮宰【カール=マルテル】は、732年の【トゥール・ポワティエ間の戦い】でイベリア半島から侵入したウマイヤ朝のイスラーム軍を撃退しました。その子【ピピン(小ピピン)】は、751年に教皇の支持を得て王位につき、カロリング朝を開きました。", "ピピンの子カール大帝が西ヨーロッパの大部分を統一し、800年に皇帝として戴冠しました。しかしその死後、王国は分裂し、843年の【ヴェルダン条約】と870年の【メルセン条約】によって、西フランク・東フランク・イタリアの3つに分かれました。この西フランク王国が、のちのフランスの原型となります。9〜10世紀にはノルマン人が侵入を繰り返し、911年にはその首領ロロが西フランク王から土地を与えられて【ノルマンディー公国】を建てました。"]}, {"t": "中世 ― カペー朝の王権強化", "p": ["987年、西フランクのカロリング家が途絶えると、パリ伯【ユーグ=カペー】が王に選ばれ、【カペー朝】が始まりました。しかし当初の王権は弱く、王が直接支配できたのはパリ周辺のわずかな地域にすぎず、国内には王より強大な諸侯がいました。この時代、宗教面では910年に建てられた【クリュニー修道院】が教会改革運動の中心となり、のちには【シトー修道会】が開墾運動を進めました。", "カペー朝の王たちは、少しずつ王権を強めていきました。【フィリップ2世】はイギリスのジョン王と争ってフランス内のイギリス領の大部分を奪い、1214年の【ブーヴィーヌの戦い】でジョン王と神聖ローマ皇帝の連合軍を破りました。【ルイ9世】は南フランスの異端【カタリ派(アルビジョワ派)】を討つ十字軍を完了させて王領を南に広げ、自らも十字軍に参加しました。経済面では、【シャンパーニュ地方】の定期市が国際商業の中心として栄えました。", "【フィリップ4世】は、聖職者への課税をめぐって教皇ボニファティウス8世と対立し、1302年に聖職者・貴族・平民の代表からなる【三部会】を開いて国内の支持を固めました。そして1303年、教皇を捕らえる【アナーニ事件】を起こし、1309年には教皇庁を南フランスの【アヴィニョン】に移しました(【教皇のバビロン捕囚】)。これは、教皇権が衰え、国王の力が強まったことを象徴するできごとです。文化面では【パリ大学】で神学が栄え、【アベラール】らが活躍し、ゴシック様式の【シャルトル大聖堂】が建てられ、南フランスでは【吟遊詩人(トルバドゥール)】が騎士道恋愛を歌いました。", "1328年にカペー朝が断絶して【ヴァロワ朝】が始まると、イギリス王エドワード3世が王位継承権を主張し、【百年戦争】(1339〜1453年)が始まります。フランスは敗北を重ね、戦争中の1358年には重税と荒廃に苦しむ農民が【ジャックリーの乱】を起こしました。しかし、神のお告げを受けたと信じる農民の娘【ジャンヌ=ダルク】が現れ、1429年に包囲されていた【オルレアン】を解放すると、形勢は逆転しました。【シャルル7世】は常備軍を整えてイギリス軍を追い出し、【カレー】を除く国土を回復しました。この戦争を通じて諸侯や騎士が没落し、国王を中心とする中央集権化が大きく進みました。"]}, {"t": "近世 ― 宗教戦争から絶対王政へ", "p": ["15世紀末、【シャルル8世】がイタリアに侵入してイタリア戦争が始まり、フランスはハプスブルク家と長く争いました。16世紀には宗教改革の波がフランスにもおよび、『【キリスト教綱要】』を著した【カルヴァン】の教えを信じる新教徒は【ユグノー】と呼ばれました。新旧両派の対立は貴族の勢力争いと結びつき、1562年に【ユグノー戦争】が始まりました。1572年には、多数の新教徒が殺害される【サンバルテルミの虐殺】が起こっています。", "この内乱を終わらせたのが、ブルボン家の【アンリ4世】です。彼は1589年に即位して【ブルボン朝】を開き、自らはカトリックに改宗する一方、1598年に【ナントの王令】を出して新教徒にも信仰の自由を認めました。国の統一を宗教の対立より優先したのです。", "次のルイ13世の時代には、宰相【リシュリュー】が三部会の招集を停止し、貴族やユグノーの勢力を抑えて王権を強めました。対外的には、カトリック国でありながら新教徒の側に立って三十年戦争に介入し、ハプスブルク家の力を弱めることを優先しました。幼い【ルイ14世】が即位すると、宰相【マザラン】の集権政策に貴族が反発して【フロンドの乱】(1648〜53年)が起こりましたが、これが鎮圧されたことで貴族は王に対抗する力を失いました。", "1661年から親政を始めたルイ14世は「太陽王」と呼ばれ、王権神授説のもとで絶対王政の全盛期を築きました。財務総監【コルベール】は、王立マニュファクチュアの設立や東インド会社の再建など、輸出を増やして国を富ませる重商主義政策を進めました。壮麗な【ヴェルサイユ宮殿】では、貴族を宮廷に集めて王の権威を示しました。文化面では、古典主義の劇作家【ラシーヌ】や【モリエール】が活躍しています。しかし、ルイ14世はたび重なる侵略戦争で財政を悪化させ、1685年の【ナントの王令の廃止】によって商工業を担っていたユグノーが国外に亡命し、経済にも打撃を与えました。【スペイン継承戦争】の結果、1713年の【ユトレヒト条約】で孫のスペイン王位継承は認められましたが、フランスとスペインの合同は禁止され、イギリスに【ニューファンドランド・アカディア・ハドソン湾地方】を譲りました。"]}, {"t": "フランス革命", "p": ["18世紀には、【モンテスキュー】が『法の精神』で三権分立を、【ルソー】が『社会契約論』で人民主権を説き、【ヴォルテール】が教会や専制を批判し、ディドロらの『【百科全書】』が理性の光を広めるなど、【啓蒙思想】が盛んになりました。一方、七年戦争やアメリカ独立戦争への参戦で国家財政は破綻寸前となりました。当時のフランスは、第一身分(聖職者)と第二身分(貴族)が免税などの特権をもち、人口の大多数を占める第三身分(平民)が重い負担を負う【アンシャン=レジーム】(旧制度)の社会でした。", "財政難を解決するため、【ルイ16世】は特権身分への課税を図りましたが、貴族はこれに抵抗し、1789年5月に約170年ぶりに三部会が招集されました。【シェイエス】が『第三身分とは何か』で平民の権利を訴えると、第三身分の代表は自らを国民議会と称し、【球戯場(テニスコート)の誓い】で憲法制定まで解散しないことを誓いました。王が軍隊でこれを抑えようとすると、7月14日、パリの民衆が【バスティーユ牢獄】を襲撃し、革命が始まりました。農村でも農民が蜂起したため、国民議会は8月に【封建的特権の廃止】を決議し、続いて自由・平等・人民主権・所有権の不可侵などをうたう【人権宣言】を採択しました。10月には女性を中心とする民衆の【ヴェルサイユ行進】により、国王一家はパリに移されました。", "1791年、国王一家が国外逃亡を図って失敗した【ヴァレンヌ逃亡事件】で、国王への信頼は失われました。オーストリアとプロイセンは【ピルニッツ宣言】で革命への干渉を示唆し、1792年、穏健共和派の【ジロンド派】政府はオーストリアに宣戦しました。戦況が悪化する中で民衆が王宮を襲い、王権が停止されて、男性普通選挙による【国民公会】が成立し、王政が廃止されて第一共和政が始まりました。1793年にルイ16世が処刑されると、イギリスを中心に対仏大同盟が結成されます。", "この危機の中で、急進的なジャコバン派の【ロベスピエール】が【公安委員会】を中心に独裁を行い、反対派を次々に処刑する恐怖政治を展開しました。一方で、封建地代の無償廃止、徴兵制、【メートル法】の制定などの政策も行われました。しかし恐怖政治への反発から、1794年の【テルミドールの反動(クーデタ)】でロベスピエールは処刑され、1795年に5人の総裁による【総裁政府】が成立しましたが、政情は不安定なままでした。"]}, {"t": "ナポレオンの時代", "p": ["イタリア遠征で名をあげた軍人【ナポレオン】は、イギリスとインドの連絡を断つために【エジプト遠征】を行った後、1799年に【ブリュメール18日のクーデタ】で総裁政府を倒し、【統領政府】を樹立して第一統領となりました。彼は1801年に教皇と【宗教協約(コンコルダート)】を結んで革命以来対立していたカトリック教会と和解し、1802年にはイギリスと【アミアンの和約】を結びました。1804年には、法の前の平等や私有財産の不可侵など革命の成果を定めた【ナポレオン法典(フランス民法典)】を公布し、同じ年に国民投票で皇帝となりました(第一帝政)。", "1805年、【トラファルガーの海戦】でイギリス海軍に敗れたものの、陸上では【アウステルリッツの戦い(三帝会戦)】でオーストリア・ロシア軍を破りました。1806年には西南ドイツ諸国を【ライン同盟】にまとめて神聖ローマ帝国を消滅させ、【大陸封鎖令(ベルリン勅令)】でイギリスを経済的に孤立させようとしました。1807年の【ティルジット条約】でプロイセンを屈服させ、ナポレオンはヨーロッパ大陸の大部分を支配しました。", "しかし、ナポレオンの支配は、各地に自由・平等の理念とともに、フランスへの反発から民族意識を目覚めさせました。スペインでは民衆の抵抗が続き、大陸封鎖令を破って穀物をイギリスに輸出した【ロシア】に遠征した1812年には、厳しい冬の中で大敗しました。1813年の【ライプツィヒの戦い(諸国民戦争)】に敗れたナポレオンは退位して【エルバ島】に流されます。いったん脱出して皇帝に復位しましたが、1815年の【ワーテルローの戦い】に敗れ、南大西洋の【セントヘレナ島】に流されてその地で亡くなりました。"]}, {"t": "19世紀 ― 革命と政体の変転", "p": ["ナポレオンの没落後、ウィーン体制のもとでブルボン朝が復活しました。しかし【シャルル10世】が反動政治を強め、国民の不満をそらすために【アルジェリア】へ出兵すると、1830年に【七月革命】が起こり、銀行家などの大ブルジョワジーに支持された【ルイ=フィリップ】が王となる七月王政が始まりました。この革命を描いたのが【ドラクロワ】の『民衆を導く自由の女神』です。", "七月王政では選挙権が富裕層に限られていたため、選挙権の拡大を求める運動が高まり、1848年に【二月革命】が起こって第二共和政が成立しました。臨時政府には社会主義者【ルイ=ブラン】も加わり、失業者救済の国立作業場が設けられましたが、その閉鎖に反発した労働者の【六月蜂起】は鎮圧されました。社会主義への不安が広がる中、ナポレオンの甥【ルイ=ナポレオン】が大統領に当選し、1852年には皇帝【ナポレオン3世】となって第二帝政を始めました。", "ナポレオン3世は、農民・資本家・労働者の支持を集めながら、パリの大改造や産業の振興を進め、【レセップス】による【スエズ運河】建設も支援しました。対外的にはクリミア戦争やイタリア統一戦争などで威信を高めようとしましたが、【メキシコ出兵】に失敗し、1870年の普仏戦争では【セダンの戦い】で捕虜となって帝政は崩壊しました。臨時政府の【ティエール】はドイツと講和し、【アルザス・ロレーヌ】を失いました。これに反発したパリの民衆は1871年、世界最初の労働者による自治政府とされる【パリ=コミューン】を樹立しましたが、政府軍に鎮圧されました。", "こうして成立した【第三共和政】は、右派の【ブーランジェ事件】やユダヤ系軍人がスパイの罪を着せられた【ドレフュス事件】などの危機に見舞われました。作家【ゾラ】がドレフュスを擁護したこの事件を通じて共和派が勢いを強め、1905年には【政教分離法】が制定されました。対外的には、アルジェリアからサハラを横断してジブチ・マダガスカルを結ぶ【アフリカ横断政策】を進めてイギリスとファショダで衝突しましたが、やがてドイツに対抗するためにロシア・イギリスと結び、三国協商を形成しました。"]}, {"t": "20世紀から現代へ", "p": ["第一次世界大戦で国土の北東部が戦場となったフランスは、戦後ドイツに厳しい態度をとり、1923年には賠償金の支払い遅延を理由に【ルール占領】を行いました。世界恐慌に対しては、植民地とともに【フラン=ブロック】を形成しました。ファシズムの台頭に対抗するため、1936年には社会党のブルムを首相とする【人民戦線内閣】が成立しました。", "第二次世界大戦では、1940年にドイツ軍の侵攻を受けて降伏し、北部はドイツに占領され、南部にはペタンを首班とする親独的な【ヴィシー政府】が成立しました。これに対し、【ド=ゴール】はロンドンで自由フランス政府を組織して抵抗を呼びかけ、国内でもレジスタンスが展開されて、1944年にパリは解放されました。", "戦後の第四共和政は、インドシナ戦争や【アルジェリア】の独立戦争に苦しみ、政局は不安定でした。1958年、アルジェリア問題の危機の中でド=ゴールが復帰し、大統領の権限を強めた【第五共和政】が始まりました。ド=ゴールは1962年にアルジェリアの独立を認め、アメリカから自立した外交を進めて、核兵器を保有し、NATOの軍事機構から脱退しました。一方で、フランスは西ドイツとの和解を土台に、ヨーロッパ石炭鉄鋼共同体からEC、EUへと続くヨーロッパ統合の中心的な役割を担い続けています。", "フランスは文化の面でも、【デカルト】や【パスカル】の思想、【ヴィクトル=ユゴー】や【バルザック】の文学、【ミレー】や【モネ】、【セザンヌ】らの絵画、【キュリー夫妻】や【パストゥール】の科学、【サルトル】の実存主義など、世界に大きな影響を与え続けてきました。"]}], "points": ["クローヴィスのアタナシウス派改宗がフランク王国発展の要因になったこと", "カペー朝の王権強化:フィリップ2世(ブーヴィーヌ)→ルイ9世(アルビジョワ十字軍)→フィリップ4世(三部会・アナーニ事件・アヴィニョン)", "ユグノー戦争→アンリ4世のナントの王令(1598年)→ルイ14世の廃止(1685年)とその経済的影響", "ルイ14世期のコルベールの重商主義とスペイン継承戦争・ユトレヒト条約", "革命の流れ:国民議会→立法議会→国民公会→総裁政府→統領政府→第一帝政", "ナポレオンの業績(宗教協約・ナポレオン法典・ライン同盟・大陸封鎖令)と没落の過程", "19世紀の政体の変化:復古王政→七月王政→第二共和政→第二帝政→第三共和政", "ドレフュス事件と政教分離法(1905年)、第五共和政とド=ゴール外交"], "check": [["732年にイスラーム軍を撃退したフランク王国の宮宰は誰か", "カール=マルテル"], ["987年にカペー朝を開いたのは誰か", "ユーグ=カペー"], ["1302年にフィリップ4世が初めて開いた身分制議会は何か", "三部会"], ["1429年にオルレアンを解放した農民の娘は誰か", "ジャンヌ=ダルク"], ["1598年にアンリ4世が新教徒に信仰の自由を認めた法令は何か", "ナントの王令"], ["ルイ14世の財務総監で重商主義政策を進めたのは誰か", "コルベール"], ["1789年、第三身分の代表が憲法制定まで解散しないと誓ったできごとは何か", "球戯場(テニスコート)の誓い"], ["1799年にナポレオンが総裁政府を倒したクーデタは何か", "ブリュメール18日のクーデタ"], ["1871年にパリの民衆が樹立した自治政府は何か", "パリ=コミューン"], ["1958年にド=ゴールのもとで始まった政体は何か", "第五共和政"]], "related": ["y_5", "y_8", "y_10", "y_14", "y_16", "y_17", "y_18", "y_19", "y_20a", "y_20b", "t_uk", "t_de", "t_it", "t_es", "t_ru", "t_vn", "t_af", "t_ar"], "n": 5865, "videos": [{"title": "【世界史】 フランス革命１ 革命の勃発 （１９分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=XFCFAE4Zra4", "note": "フランス革命の勃発を学べ、2026年度第3問Ａで問われた革命の展開を理解する助けになります。"}]}, "t_de": {"title": "ドイツ史", "span": "9世紀〜現在", "year": 1871, "lead": "ドイツは東フランク王国から神聖ローマ帝国へと続きましたが、皇帝のイタリア政策や宗教改革・三十年戦争によって多数の領邦に分かれ、統一が大きく遅れました。プロイセンを中心に1871年にようやく統一を果たした後、急速な工業化で大国となりますが、二つの世界大戦に敗れて東西に分断され、1990年に再統一されました。", "flow": ["843年 ヴェルダン条約→東フランク王国(のちのドイツ)", "962年 オットー1世が皇帝に戴冠→神聖ローマ帝国、イタリア政策で国内統一が遅れる", "1077年 カノッサの屈辱→1122年ヴォルムス協約で叙任権闘争が終わる", "1356年 金印勅書→選帝侯による皇帝選挙、領邦の分立が固定化", "1517年 ルターの宗教改革→1555年アウクスブルクの和議", "1618〜48年 三十年戦争→ウェストファリア条約で領邦の主権確立、帝国は形だけに", "18世紀 プロイセンの台頭(フリードリヒ2世)とオーストリアとの対立", "1806年 ナポレオンのライン同盟結成で神聖ローマ帝国消滅→プロイセン改革", "1834年 ドイツ関税同盟→1848年三月革命・フランクフルト国民議会", "1871年 ビスマルクのもとでドイツ帝国成立→ヴィルヘルム2世の世界政策", "1919年 ヴァイマル共和国→1933年ナチス政権→第二次世界大戦で敗北", "1949年 東西ドイツ成立→1990年再統一"], "sync": [], "secs": [{"t": "成立 ― 東フランクから神聖ローマ帝国へ", "p": ["【カール大帝】は、現在のドイツを含む西ヨーロッパの大部分を支配し、都【アーヘン】を中心に、地方には【伯】を置き、【巡察使】を派遣して統治しました。しかしその死後、843年の【ヴェルダン条約】と870年の【メルセン条約】によってフランク王国は分裂し、東フランク王国が成立しました。これが現在のドイツの原型です。", "東フランクでは10世紀初めにカロリング家が途絶え、諸侯の選挙で王が選ばれるようになりました。ザクセン家の【ハインリヒ1世】に続く【オットー1世】は、955年の【レヒフェルトの戦い】でアジア系の【マジャール人】を撃退し、962年に教皇から皇帝の冠を受けました。これが【神聖ローマ帝国】の始まりとされます。", "しかし、歴代の皇帝は「ローマ皇帝」としての権威にこだわり、イタリアを支配しようとたびたびアルプスを越えて遠征しました。これを【イタリア政策】と呼びます。皇帝がイタリアに力を注いでいる間に、ドイツ国内では諸侯が自立を強め、王権による国内統一は進みませんでした。フランスやイギリスが中央集権化を進めたのとは逆の道をたどったのです。"]}, {"t": "中世 ― 叙任権闘争と領邦の分立", "p": ["皇帝は国内統治のために、聖職者を任命して教会を味方につける政策をとっていました。これに対し、教会の改革を進めた教皇【グレゴリウス7世】は、聖職者の任命権(叙任権)は教会にあると主張し、皇帝【ハインリヒ4世】と激しく対立しました。これが【叙任権闘争】です。破門されたハインリヒ4世は、ドイツ諸侯が離反する中で、1077年に雪の中で教皇に許しを請いました。この事件を【カノッサの屈辱】と呼びます。闘争は1122年の【ヴォルムス協約】で妥協が成立し、教皇が叙任権を得ることになりました。", "12世紀のシュタウフェン朝では、【フリードリヒ1世】が第3回十字軍に参加し、イタリア政策を推進しましたが、北イタリア諸都市の【ロンバルディア同盟】に敗れました。【フリードリヒ2世】はシチリアで育ち、外交交渉でイェルサレムを一時回復した皇帝として知られています。シュタウフェン朝の断絶後、事実上皇帝が不在となる【大空位時代】(1256〜73年)が続き、皇帝権は大きく衰えました。", "14世紀、ベーメン王を兼ねた皇帝【カール4世】は、1356年に【金印勅書】を発布し、7人の【選帝侯】が皇帝を選出することを定めました。これにより皇帝選挙の手続きは安定しましたが、同時に選帝侯をはじめとする諸侯の権利が認められ、ドイツが多数の【領邦】に分かれる状態が固定化しました。カール4世はプラハに【プラハ大学】を創設しています。15世紀からは、皇帝の位は事実上【ハプスブルク家】が世襲するようになりました。なお、ハプスブルク家の支配に抵抗した【スイス】は、15世紀末に事実上独立しました。", "一方、中世のドイツ人はエルベ川以東のスラヴ人の地域に進出する【東方植民】を進めました。その中で【ブランデンブルク辺境伯領】や、【ドイツ騎士団】の領地(のちのプロイセン)が生まれ、のちのプロイセン王国の基礎となりました。北ドイツでは、リューベックを盟主とする都市同盟【ハンザ同盟】が北海・バルト海の交易を支配し、皇帝から特権を得た【帝国都市(自由都市)】が自治を行いました。南ドイツでは、アウクスブルクの【フッガー家】が鉱山経営と金融で巨富を築き、皇帝や教皇にも資金を貸しました。教会では、1414年からの【コンスタンツ公会議】で【教会大分裂(大シスマ)】が終わり、ベーメンの宗教改革者【フス】が異端として処刑されています。15世紀半ばには【グーテンベルク】が活版印刷術を実用化し、これがのちの宗教改革の広がりを支えました。"]}, {"t": "宗教改革と三十年戦争", "p": ["16世紀初め、教皇【レオ10世】がサン=ピエトロ大聖堂の改築資金を集めるために【贖宥状(免罪符)】を販売させると、ドイツはとくにその標的となりました。分裂したドイツには、教会の収奪を防ぐ強い王権がなかったからです。1517年、ヴィッテンベルク大学の神学教授【ルター】は「九十五か条の論題」を発表し、人は信仰によってのみ救われると説いて贖宥状を批判しました。", "ルターは、1521年の【ヴォルムス帝国議会】で皇帝【カール5世】から自説の撤回を求められましたが、これを拒否しました。彼はザクセン選帝侯の保護を受けて聖書をドイツ語に翻訳し、その教えは印刷物を通じて急速に広まりました。1524年には、ルターの影響を受けた農民が【トマス=ミュンツァー】の指導のもとで農奴制の廃止などを求める【ドイツ農民戦争】を起こしましたが、ルターは諸侯の側に立って鎮圧を支持しました。この頃、オスマン帝国のスレイマン1世が1529年に【第1次ウィーン包囲】を行うなど、外からの脅威もあって皇帝はルター派を徹底的に抑えることができませんでした。ルター派の諸侯は【シュマルカルデン同盟】を結んで皇帝と戦い、1555年の【アウクスブルクの和議】で、諸侯はカトリックとルター派のどちらかを選べるようになりました。「【領主の宗教、その地に行われる】」という原則で、個人の信仰の自由ではなかった点、またカルヴァン派は認められなかった点に注意しましょう。", "宗教対立はその後も続き、1618年、ベーメン(ボヘミア)の新教徒がハプスブルク家のカトリック強制に反抗したことから【三十年戦争】が始まりました。デンマークやスウェーデン(国王【グスタフ=アドルフ】)が新教側で参戦し、さらにカトリック国のフランスも、ハプスブルク家を抑えるために新教側に立って介入しました。宗教戦争は国際的な権力争いへと変わり、戦場となったドイツは人口が激減するほど荒廃しました。1648年の【ウェストファリア条約】では、カルヴァン派も公認され、ドイツの諸領邦にほぼ完全な主権が認められました。スイスとオランダの独立も正式に承認されました。【神聖ローマ帝国】は名ばかりの存在となり、この条約は「帝国の死亡証書」とも呼ばれます。また、この条約は主権国家どうしが対等に並ぶ近代ヨーロッパの国際秩序の出発点とされています。"]}, {"t": "近世 ― プロイセンとオーストリアの対立", "p": ["分裂したドイツの中で台頭したのが、【ホーエンツォレルン家】が治めるブランデンブルク選帝侯国でした。これがプロイセン公国と合同し、1701年にプロイセン王国となります。「軍隊王」と呼ばれた【フリードリヒ=ヴィルヘルム1世】は軍備を増強し、官僚制を整えました。プロイセンを支えたのは、エルベ川以東で農奴を使って輸出用の穀物を生産する大農場を経営した地主貴族ユンカーでした。この農業経営の形を【農場領主制(グーツヘルシャフト)】と呼びます。", "1740年に即位した【フリードリヒ2世(大王)】は、オーストリアの【マリア=テレジア】の相続に異議を唱えてオーストリア継承戦争を起こし、資源豊かな【シュレジエン】を奪いました。1748年の【アーヘンの和約】で領有が認められます。シュレジエン奪回をめざすマリア=テレジアは、長年の宿敵だったフランスと手を結ぶ外交革命を行い、【七年戦争】(1756〜63年)を起こしましたが、プロイセンはイギリスの支援を受けて持ちこたえ、【フベルトゥスブルク条約】でシュレジエンの領有を確定させました。", "フリードリヒ2世は「君主は国家第一の僕」と述べ、啓蒙思想を取り入れて上からの近代化を進める啓蒙専制君主の代表とされます。ヴォルテールを招いた【サンスーシ宮殿】は彼の宮殿です。オーストリアでもマリア=テレジアの子【ヨーゼフ2世】が農奴解放や宗教寛容令などの改革を試みました。プロイセンとオーストリアは、ロシアとともにポーランド分割にも加わっています。この時代のドイツでは、哲学の【カント】、音楽の【バッハ】や【ハイドン】、【モーツァルト】が活躍しました。"]}, {"t": "近代 ― ナショナリズムとドイツ統一", "p": ["フランス革命とナポレオンの登場は、ドイツを大きく揺さぶりました。1806年、ナポレオンが西南ドイツ諸国を【ライン同盟】にまとめると、神聖ローマ帝国は正式に消滅しました。プロイセンもナポレオンに大敗しますが、その屈辱の中で、哲学者【フィヒテ】は講演「ドイツ国民に告ぐ」で国民意識を呼び起こし、【シュタイン(とハルデンベルク)】は農民解放や行政改革などの【プロイセン改革】を進めました。", "ウィーン会議の後、ドイツには35の君主国と4つの自由市からなる【ドイツ連邦】がつくられましたが、統一国家ではありませんでした。自由と統一を求める学生組合【ブルシェンシャフト】の運動は、オーストリアの【メッテルニヒ】に弾圧されました。しかし経済面では、経済学者【フリードリヒ=リスト】の主張などを背景に、1834年にプロイセン中心の【ドイツ関税同盟】が成立し、オーストリアを除く形での経済的な統一が先に進みました。", "1848年、フランスの二月革命の影響でウィーンとベルリンで【三月革命】が起こり、メッテルニヒは失脚しました。ドイツの統一と憲法制定を目指して【フランクフルト国民議会】が開かれ、オーストリアを除いてプロイセン中心に統一する【小ドイツ主義】が採択されましたが、プロイセン王が帝位を拒否したため、統一は失敗に終わりました。同じ年、【マルクス】とエンゲルスは『【共産党宣言】』を発表しています。", "統一を実現したのは、プロイセン王【ヴィルヘルム1世】のもとで1862年に首相となった【ビスマルク】です。彼は「現在の大問題は言論や多数決ではなく、鉄と血によって解決される」と議会で演説し(鉄血政策)、軍備拡張を強行しました。1864年の【デンマーク戦争】、1866年の【プロイセン=オーストリア(普墺)戦争】に勝利して【北ドイツ連邦】を結成し、オーストリアをドイツ統一から締め出しました(オーストリアは翌年【オーストリア=ハンガリー帝国(二重帝国)】となります)。さらに【エムス電報事件】をきっかけにフランスとの戦争(普仏戦争)に勝利し、1871年、占領下のフランスの【ヴェルサイユ宮殿】でヴィルヘルム1世がドイツ皇帝として即位し、ドイツ帝国が成立しました。ドイツの統一は、民衆の革命ではなく、プロイセンの軍事力による「上からの統一」だった点が特徴です。"]}, {"t": "ドイツ帝国 ― ビスマルク体制から世界政策へ", "p": ["帝国宰相となったビスマルクは、国内では南ドイツのカトリック勢力と対立して【文化闘争】を行い、1878年には【社会主義者鎮圧法】で社会主義運動を弾圧する一方、労働者を国家に引きつけるために世界に先駆けて【社会保険制度】を整えました。「アメとムチ」の政策と呼ばれます。対外的には、フランスを孤立させるために【三帝同盟】や三国同盟、ロシアとの【再保障条約】など複雑な同盟網をつくり、1878年の【ベルリン会議】では「誠実な仲介人」としてロシアとイギリス・オーストリアの対立を調停しました。", "1888年に即位した【ヴィルヘルム2世】は、1890年にビスマルクを辞任させ、再保障条約の更新を拒否して、海軍の拡張と海外進出をめざす「世界政策」を進めました。ベルリン・ビザンティウム(イスタンブル)・バグダードを結ぶ【3B政策】はイギリスの3C政策と対立し、ロシアはフランスと同盟を結びました。こうしてドイツはしだいに孤立していきます。国内では急速な工業化が進み、社会民主党(前身は【ドイツ社会主義労働者党】)が議会で勢力を伸ばし、党内では【ベルンシュタイン】が議会を通じた改良を唱える修正主義を主張しました。", "1914年、オーストリアの帝位継承者【フランツ=フェルディナント】が、オーストリアが1908年に併合した【ボスニア・ヘルツェゴヴィナ】の州都サライェヴォで暗殺されると、第一次世界大戦が始まりました。ドイツは【シュリーフェン=プラン】に従って、まずフランスを短期間で破ろうとしましたが失敗し、西部戦線は塹壕戦で膠着しました。東部戦線では【タンネンベルクの戦い】でロシア軍を破りましたが、1917年の【無制限潜水艦作戦】がアメリカの参戦を招きます。1918年、【ドイツ革命(キール軍港の水兵反乱)】が起こって皇帝は亡命し、ドイツは共和国となって休戦しました。"]}, {"t": "現代 ― ヴァイマル共和国・ナチス・分断と統一", "p": ["1919年、急進左派の【スパルタクス団の蜂起】が鎮圧された後、社会民主党の【エーベルト】を大統領として、男女普通選挙や社会権を定めた民主的な【ヴァイマル憲法】が制定されました。しかし、ヴェルサイユ条約による領土の喪失と巨額の賠償金は国民の不満を招き、1923年のフランスのルール占領をきっかけに激しいインフレーションが起こりました。【シュトレーゼマン】は新紙幣レンテンマルクの発行でインフレを収束させ、外相としてロカルノ条約や国際連盟加盟を実現し、国際協調を進めました。", "ところが世界恐慌によって失業者があふれると、ヒトラーの率いるナチ党(国民社会主義ドイツ労働者党)が支持を集め、1932年に第一党となりました。1933年に首相となった【ヒトラー】は、議会の立法権を政府に与える【全権委任法】を成立させて一党独裁を確立し、翌年には大統領と首相を兼ねる【総統(フューラー)】となりました。ナチスは公共事業や軍需産業で失業を減らす一方、言論を弾圧し、1935年の【ニュルンベルク法】でユダヤ人の公民権を奪いました。対外的には、国際連盟を脱退し、1935年に【ザール地方】を編入して再軍備を宣言し【徴兵制】を復活、1936年に【ラインラント】に進駐し、1938年には【オーストリア】を併合しました。1939年のポーランド侵攻で第二次世界大戦が始まり、戦争中にはユダヤ人などの大量虐殺【ホロコースト】が行われ、【アウシュヴィッツ】などの強制収容所で多くの命が奪われました。", "1945年に敗北したドイツは、米英仏ソの4か国に分割占領されました。冷戦の中で、ソ連は1948年に【ベルリン封鎖】を行い、翌1949年に西側にドイツ連邦共和国(西ドイツ、首相【アデナウアー】)、東側に【ドイツ民主共和国】(東ドイツ)が成立して、ドイツは分断されました。1961年には東ドイツがベルリンの壁を築きました。西ドイツは「経済の奇跡」と呼ばれる復興を遂げ、ヨーロッパ統合にも参加しました。1969年に首相となった社会民主党の【ブラント】は、東側諸国との関係を改善する東方外交を進め、1973年には東西ドイツがそろって【国際連合】に加盟しました。", "1989年、東欧の民主化の波の中でベルリンの壁が崩壊し、【1990年】に東ドイツが西ドイツに編入される形でドイツは再統一されました。統一後のドイツは、EUの中心国として重要な役割を果たしています。思想・文化の面では、【ヘーゲル】の哲学、【ゲーテ】の文学、【ベートーヴェン】の音楽、【ランケ】の近代歴史学、【マックス=ヴェーバー】の社会学、【アインシュタイン】の相対性理論など、ドイツ語圏は近代世界に多くの知的遺産を残しました。"]}], "points": ["オットー1世の戴冠(962年)とイタリア政策がドイツの国内統一を遅らせたこと", "カノッサの屈辱(1077年)とヴォルムス協約(1122年)の叙任権闘争", "金印勅書(1356年、カール4世)による7選帝侯と領邦分立の固定化", "アウクスブルクの和議(1555年)は諸侯の宗教選択権で、カルヴァン派は対象外", "ウェストファリア条約(1648年):領邦の主権・カルヴァン派公認・スイスとオランダの独立承認", "関税同盟(1834年)→フランクフルト国民議会(小ドイツ主義)→ビスマルクの3つの戦争→帝国成立(1871年)", "ビスマルクの「アメとムチ」(社会主義者鎮圧法と社会保険)と同盟外交、ヴィルヘルム2世の世界政策", "ヴァイマル憲法・シュトレーゼマン・全権委任法・東西分断・ブラントの東方外交・1990年統一"], "check": [["955年にマジャール人を撃退し、962年に皇帝に戴冠したのは誰か", "オットー1世"], ["1077年、皇帝ハインリヒ4世が教皇に許しを請うた事件を何と呼ぶか", "カノッサの屈辱"], ["1356年に7選帝侯による皇帝選挙を定めた文書は何か", "金印勅書"], ["1517年に九十五か条の論題を発表したのは誰か", "ルター"], ["三十年戦争を終結させた1648年の条約は何か", "ウェストファリア条約"], ["フリードリヒ2世がオーストリアから奪った地方はどこか", "シュレジエン"], ["1834年にプロイセン中心に成立した経済的な同盟は何か", "ドイツ関税同盟"], ["鉄血政策でドイツ統一を進めたプロイセン首相は誰か", "ビスマルク"], ["1933年に成立し、政府に立法権を与えた法律は何か", "全権委任法"], ["東方外交を進めた西ドイツの首相は誰か", "ブラント"]], "related": ["y_9", "y_10", "y_11", "y_14", "y_16", "y_17", "y_18", "y_19", "y_20a", "y_20b", "t_fr", "t_it", "t_pl", "t_ru", "t_uk", "t_nl", "t_nord", "t_bal"], "n": 6021, "videos": [{"title": "【世界史】 19世紀の欧米５ ドイツの統一 （２０分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=mA4plZy1seI", "note": "19世紀のドイツ統一の過程を整理できます。"}]}, "t_it": {"title": "イタリア史", "span": "476年〜現在", "year": 1861, "lead": "西ローマ帝国滅亡後のイタリアは、ゲルマン人・ビザンツ帝国・神聖ローマ皇帝・ローマ教皇などの勢力が入り乱れ、長く分裂が続きました。その一方で、東方貿易で栄えた都市が自治を行い、ルネサンスの舞台となりました。19世紀にサルデーニャ王国を中心に統一が実現し、20世紀にはファシズムを経て共和国となりました。", "flow": ["476年 西ローマ帝国滅亡→493年テオドリック大王の東ゴート王国", "6世紀 ユスティニアヌス帝が東ゴート王国を滅ぼす→568年ランゴバルド人が侵入", "756年 ピピンの寄進→教皇領の起源、800年レオ3世がカール大帝を戴冠", "10世紀〜 神聖ローマ皇帝のイタリア政策→教皇党と皇帝党の抗争", "11〜12世紀 東方貿易で北イタリア諸都市が繁栄→コムーネ・ロンバルディア同盟、南部に両シチリア王国", "1309〜77年 教皇のバビロン捕囚→教会大分裂で教皇権が衰退", "14〜16世紀 フィレンツェ(メディチ家)などでルネサンス", "1494年 シャルル8世の侵入でイタリア戦争→外国勢力の支配が続く", "1831年 マッツィーニが青年イタリアを結成→統一運動(リソルジメント)", "1861年 イタリア王国成立→1870年ローマ併合", "1922年 ムッソリーニのローマ進軍→ファシズム体制、1929年ラテラノ条約", "1946年 国民投票で共和政に→EEC原加盟国"], "sync": [], "secs": [{"t": "西ローマ帝国滅亡後のイタリア", "p": ["476年、ゲルマン人傭兵隊長【オドアケル】が西ローマ皇帝を廃位したことで、西ローマ帝国は滅亡しました。そのオドアケルを倒してイタリアを支配したのが、東ゴート人の【テオドリック大王】です。彼は493年に【東ゴート王国】を建て、ローマ人の制度や文化を尊重して統治しました。しかし、東ゴート人がアリウス派だったのに対し、ローマ系住民はカトリックであり、両者の融和は十分には進みませんでした。", "6世紀、ビザンツ帝国の【ユスティニアヌス帝】は東ゴート王国を滅ぼし、イタリアを取り戻しました。ラヴェンナの【サン=ヴィターレ聖堂】に残るユスティニアヌス帝のモザイク画は、この時代の記念碑です。しかし長い戦争でイタリアは荒廃し、568年にはゲルマン人の【ランゴバルド人】が北イタリアに侵入して王国を建てました。こうしてイタリアは、ビザンツ領、ランゴバルド王国、ローマ教皇の勢力などに分かれ、19世紀まで続く分裂の時代に入ります。", "この混乱の中で、ローマ教会は精神的な権威を高めていきました。6世紀末の教皇【グレゴリウス1世】はゲルマン人への布教に力を入れ、ローマ教会の地位を高めました。また、529年ごろには、ベネディクトゥスがモンテ=カシノに修道院を建て、「【祈り、働け】」を戒律とする【ベネディクト修道会】が生まれました。修道院は、労働を尊ぶ精神や古典の写本の保存を通じて、中世ヨーロッパの文化に大きな役割を果たしました。"]}, {"t": "中世 ― 教皇・皇帝・都市", "p": ["8世紀、ランゴバルド王国の圧迫とビザンツ皇帝の聖像禁止令に苦しんだ教皇は、フランク王国に接近しました。フランク王【ピピン(小ピピン)】は、ランゴバルド人から奪ったラヴェンナ地方を教皇に寄進しました。これが【ピピンの寄進】(756年)で、のちの【教皇領】の起源となります。その子カール大帝はランゴバルド王国を滅ぼし、800年には教皇【レオ3世】から西ローマ皇帝の冠を受けました。", "10世紀以降、神聖ローマ皇帝は「ローマ皇帝」として【イタリア政策】を進め、たびたびイタリアに遠征しました。一方、教皇【グレゴリウス7世】は教会改革を進め、聖職叙任権をめぐって皇帝と争いました(叙任権闘争)。教皇【ウルバヌス2世】は1095年に【クレルモン宗教会議】で十字軍を呼びかけ、13世紀初めの教皇【インノケンティウス3世】の時代に教皇権は絶頂に達しました。彼は「教皇は太陽、皇帝は月」と述べたとされ、1215年の【第4回ラテラノ公会議】で教会の教義と規律を整えました。この時代、ローマ教皇を頂点とする【階層制組織(ヒエラルキー)】をもつ【ローマ=カトリック教会】が西ヨーロッパ全体を精神的に支配し、清貧を重んじる托鉢修道会として【フランチェスコ修道会】も生まれました。異端に対しては【異端審問】が行われました。", "南イタリアでは、ノルマン人がビザンツ領やイスラーム勢力の支配地を奪い、1130年に【両シチリア王国】を建てました。シチリアのパレルモでは、ビザンツ・イスラーム・ラテンの文化が交わり、のちに【12世紀ルネサンス】にもつながる文化交流の場となりました。医学で知られた【サレルノ大学】は、ヨーロッパ最古の大学の一つです。", "北・中部イタリアでは、十字軍をきっかけに東方貿易(レヴァント貿易)が盛んになり、香辛料や絹織物を扱う【ヴェネツィア】やジェノヴァ、ピサ(【ピサ大聖堂】)などの港市が繁栄しました。内陸のミラノや【フィレンツェ】も毛織物業や金融業で栄えました。これらの都市は、周辺の農村も支配する自治都市【コムーネ(自治都市)】として事実上の都市国家となり、皇帝の干渉に対しては【ロンバルディア同盟】を結んで対抗しました。しかし、都市内部や都市間では、教皇を支持する【ゲルフ(教皇党)】と皇帝を支持する【ギベリン(皇帝党)】の争いが絶えず、イタリアの統一を妨げる要因となりました。", "14世紀になると、教皇権は衰退に向かいます。1303年の【アナーニ事件】でフランス王フィリップ4世に屈した後、教皇庁は南フランスのアヴィニョンに移され(【教皇のバビロン捕囚】、1309〜77年)、ローマに戻った後も、ローマとアヴィニョンに教皇が並び立つ【教会大分裂(大シスマ)】が起こりました。教皇の権威の失墜は、のちの宗教改革の伏線となりました。"]}, {"t": "ルネサンスの舞台", "p": ["14世紀から16世紀にかけて、イタリアでは古代ギリシア・ローマの文化を再生させ、人間らしい生き方を追求する【ルネサンス】が花開きました。イタリアで最初に始まった理由として、東方貿易で富を蓄えた都市があり、裕福な商人や君主が芸術家の保護者となったこと、各地に古代ローマの遺跡が残っていたこと、ビザンツ帝国から逃れてきた学者がギリシア古典を伝えたことなどが挙げられます。", "とくに中心となったのがフィレンツェで、金融業で富を築いた【メディチ家】が事実上の支配者として学者や芸術家を保護しました。文学では、【ダンテ】がラテン語ではなくトスカナ語(イタリア語)で『神曲』を著し、【ペトラルカ】が叙情詩を、【ボッカチオ】が『デカメロン』を書きました。建築では【ブルネレスキ】がフィレンツェ大聖堂の大ドームを完成させ、絵画では【ボッティチェリ】が『ヴィーナスの誕生』を描きました。", "ルネサンスの最盛期には、万能の天才【レオナルド=ダ=ヴィンチ】(『最後の晩餐』『モナ=リザ』)、『ダヴィデ像』や『最後の審判』の【ミケランジェロ】、聖母子像で知られる【ラファエロ】が活躍しました。彼らの活動の場は、フィレンツェからしだいに教皇のいるローマへと移り、【サン=ピエトロ大聖堂】の改築も進められました。メディチ家出身の教皇【レオ10世】がその資金集めのために贖宥状を販売させたことが、ドイツの宗教改革のきっかけとなります。", "政治思想では、【マキァヴェリ】が『君主論』で、宗教や道徳から切り離された政治の現実を論じ、近代政治学の祖とされます。その背景には、分裂して外国勢力に翻弄されるイタリアの現状がありました。フィレンツェでは、ドミニコ会修道士【サヴォナローラ】がメディチ家の支配と享楽的な風潮を批判して一時政治を握りましたが、のちに処刑されました。科学の分野では、ポーランド出身でイタリアに学んだ【コペルニクス】が地動説を唱え、のちに【ガリレイ(ガリレオ=ガリレイ)】が望遠鏡による観測で地動説を支持して宗教裁判にかけられ、【ジョルダーノ=ブルーノ】は火刑に処されました。"]}, {"t": "近世 ― イタリア戦争と外国支配", "p": ["1494年、フランス王【シャルル8世】がナポリ王国の継承権を主張してイタリアに侵入し、【イタリア戦争】が始まりました。この戦争は、フランスのヴァロワ家とスペイン・神聖ローマ帝国のハプスブルク家がイタリアの支配権を争う国際戦争となり、16世紀半ばまで続きました。結果として、ミラノやナポリ・シチリアはスペインの支配下に入り、イタリアは外国勢力の争奪の場となってしまいました。", "さらに大航海時代に入ると、ヨーロッパの商業の中心は地中海から大西洋沿岸へと移り(商業革命)、東方貿易で栄えたイタリア諸都市の経済は衰えていきました。宗教面では、カトリック教会が宗教改革に対抗して1545年から【トリエント公会議】を開き、教皇の至上権とカトリックの教義を再確認しました(対抗宗教改革)。18世紀にはスペイン継承戦争の結果などを経て、北イタリアではオーストリアの影響力が強まりました。一方、北西部ではサヴォイア家のサルデーニャ王国が成長し、のちに統一の中心となっていきます。"]}, {"t": "近代 ― リソルジメントとイタリア統一", "p": ["ナポレオンのイタリア遠征によって、イタリアには一時、フランスの影響下に統一的な国家がつくられ、自由と国民という考えが広まりました。しかし、ウィーン会議の後、北イタリアのロンバルディアとヴェネツィアはオーストリア領となり、イタリアは再び分裂状態に戻されました。これに対して、秘密結社【カルボナリ】が1820年代から各地で蜂起しましたが、オーストリア軍に鎮圧されました。", "1831年、【マッツィーニ】は【青年イタリア】を結成し、民衆の力による共和政の統一国家をめざしました。1848年の革命の波の中で、マッツィーニらは1849年に【ローマ共和国】を建てましたが、フランス軍の介入で倒されました。サルデーニャ王国もオーストリアと戦いましたが敗れ、民衆の蜂起による統一は失敗に終わりました。", "その後、統一運動の中心となったのが、サルデーニャ王国の国王【ヴィットーリオ=エマヌエーレ2世】と首相【カヴール】です。カヴールは国内の近代化を進め、クリミア戦争に参戦して国際的な地位を高め、フランスのナポレオン3世と【プロンビエール密約】を結びました。1859年のイタリア統一戦争でオーストリアを破ってロンバルディアを獲得し、翌1860年には、フランスに【サヴォイア・ニース】を割譲するかわりに中部イタリアを併合しました。同じ年、【ガリバルディ】は義勇兵の千人隊(赤シャツ隊)を率いて両シチリア王国を征服し、これをサルデーニャ王に献上しました。こうして【1861年】、イタリア王国が成立しました。", "その後、1866年の普墺戦争でプロイセン側について【ヴェネツィア】を併合し、1870年の普仏戦争でフランス軍が撤退した隙に教皇領の【ローマ】を占領して、翌年ローマを首都としました。しかし教皇はこれを認めず、イタリア政府と教皇庁の対立が長く続きました。また、トリエステや南チロルなどオーストリア領に残ったイタリア人居住地域は【「未回収のイタリア」】と呼ばれ、その回復が国民的な課題となりました。統一後も、工業化が進む北部と農業中心で貧しい南部との格差は大きく、多くの人々がアメリカ大陸へ移民しました。"]}, {"t": "現代 ― ファシズムから共和国へ", "p": ["イタリアは1882年にドイツ・オーストリアと三国同盟を結び、アフリカ進出をめざしましたが、1896年にはアドワの戦いで【エチオピア】に敗れました。1911〜12年にはオスマン帝国と戦ってリビアを獲得しています。第一次世界大戦が始まると、オーストリアとの「未回収のイタリア」問題を抱えていたイタリアは中立を保ち、1915年に未回収地の割譲などを約束した【ロンドン秘密条約】を連合国と結んで、協商国側で参戦しました。", "しかし、戦勝国となったにもかかわらず、アドリア海の港市【フィウメ】の獲得などの要求は認められず、国民の間には「傷ついた勝利」への不満が広がりました。戦後の経済混乱の中で労働者のストライキや工場占拠が相次ぐと、社会主義革命を恐れる資本家・地主・中産階級は、【ムッソリーニ】の率いるファシスト党を支持しました。1922年、ファシスト党は【ローマ進軍】で圧力をかけ、国王はムッソリーニを首相に任命しました。ムッソリーニは一党独裁体制をつくり、1924年にはフィウメを併合し、1929年には教皇庁と【ラテラノ条約(ラテラン協定)】を結んでヴァチカン市国の独立を認め、統一以来の対立を解消しました。", "世界恐慌後、ムッソリーニは対外進出によって国民の不満をそらそうとし、1935年に【エチオピア】に侵攻して翌年併合しました。国際連盟は経済制裁を決定しましたが効果は乏しく、イタリアはナチス=ドイツに接近してベルリン=ローマ枢軸を形成し、国際連盟を脱退しました。1940年には第二次世界大戦に参戦しますが、各地で敗北を重ね、1943年に連合軍がシチリア島に上陸するとムッソリーニは失脚しました。後継の【バドリオ】政府は無条件降伏しましたが、北部ではドイツ軍がムッソリーニを擁立して抵抗を続け、イタリア人によるレジスタンスが展開されました。", "1946年、国民投票によって王政は廃止され、イタリアは共和国となりました。戦後のイタリアは西側陣営に属し、1957年のローマ条約によるヨーロッパ経済共同体(EEC)の原加盟国となるなど、ヨーロッパ統合の推進に加わりました。音楽の【ヴェルディ】や、無線電信を発明した【マルコーニ】など、近代イタリアも多くの人材を生み出しています。"]}], "points": ["テオドリック大王の東ゴート王国(493年)とランゴバルド人の侵入(568年)", "ピピンの寄進(756年)が教皇領の起源であること", "教皇権の盛衰:グレゴリウス7世→ウルバヌス2世→インノケンティウス3世(絶頂)→アナーニ事件・バビロン捕囚・大シスマ", "北イタリア諸都市(コムーネ)の繁栄とロンバルディア同盟、教皇党と皇帝党の対立", "ルネサンスがイタリアで始まった理由とメディチ家、主要人物と作品", "イタリア戦争(1494年〜)と大航海時代による地中海商業の衰退", "統一の流れ:カルボナリ→青年イタリア(マッツィーニ)→カヴールとガリバルディ→1861年王国成立→ヴェネツィア・ローマ併合", "ロンドン秘密条約・フィウメ問題・ローマ進軍・ラテラノ条約・エチオピア侵攻"], "check": [["493年にイタリアに東ゴート王国を建てたのは誰か", "テオドリック大王"], ["「祈り、働け」を戒律とした修道会は何か", "ベネディクト修道会"], ["教皇領の起源となった756年のできごとは何か", "ピピンの寄進"], ["1130年にノルマン人が南イタリアに建てた国は何か", "両シチリア王国"], ["神聖ローマ皇帝に対抗した北イタリア諸都市の同盟は何か", "ロンバルディア同盟"], ["フィレンツェで学者や芸術家を保護した一族は何か", "メディチ家"], ["『君主論』を著したのは誰か", "マキァヴェリ"], ["1831年にマッツィーニが結成した結社は何か", "青年イタリア"], ["千人隊を率いて両シチリア王国を征服したのは誰か", "ガリバルディ"], ["1929年にムッソリーニ政権が教皇庁と結んだ条約は何か", "ラテラノ条約(ラテラン協定)"]], "related": ["y_5", "y_6", "y_8", "y_12", "y_14", "y_15", "y_16", "y_19", "y_20a", "y_20b", "t_ro", "t_byz", "t_de", "t_fr", "t_es", "t_af"], "n": 4880, "videos": [{"title": "【世界史】 19世紀の欧米４ イタリアの統一 （１９分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=gy1etmZbT_k", "note": "19世紀のイタリア統一の流れを確認できます。"}]}, "t_es": {"title": "スペイン・ポルトガル史", "span": "5世紀〜現在", "year": 1492, "lead": "イベリア半島は、西ゴート王国の後に約700年にわたってイスラーム勢力が支配し、キリスト教徒による国土回復運動(レコンキスタ)の中からスペインとポルトガルが生まれました。両国は大航海時代を切り開いて世界に植民地帝国を築き、16世紀のスペインは「太陽の沈まぬ国」となりましたが、その後は衰退し、20世紀には内戦や独裁を経て民主化しました。", "flow": ["5世紀 ゲルマン人が移動、西ゴート王国が成立", "711年 ウマイヤ朝が西ゴート王国を滅ぼす→イスラーム支配", "756年 後ウマイヤ朝(都コルドバ)→10世紀アブド=アッラフマーン3世のもとで繁栄", "11〜13世紀 レコンキスタの進展→カスティリャ・アラゴン・ポルトガル王国", "1479年 カスティリャとアラゴンが合同しスペイン王国成立", "1492年 グラナダ陥落でレコンキスタ完了→同年コロンブスが大西洋横断", "1498年 ヴァスコ=ダ=ガマがインド到達→ポルトガルのアジア貿易", "16世紀前半 コルテス・ピサロがアステカ・インカを征服→ポトシ銀山の銀", "1556年 フェリペ2世即位→レパントの海戦・ポルトガル併合で全盛", "1568年〜 オランダ独立戦争、1588年無敵艦隊敗北→スペインの衰退", "1808年 ナポレオンの支配に対しスペイン反乱→ラテンアメリカ諸国の独立", "1936〜39年 スペイン内戦→フランコ独裁、1975年以後民主化"], "sync": [], "secs": [{"t": "成立 ― 西ゴート王国とイスラームの支配", "p": ["イベリア半島は、古代にはカルタゴの勢力圏を経てローマの属州となり、ラテン語とキリスト教が深く根づきました。5世紀のゲルマン人の大移動では、【ヴァンダル人】がイベリア半島を通過して北アフリカに渡り、そのあと【西ゴート王国】が半島の大部分を支配しました。西ゴート王国は都を【トレド】に置き、やがてアリウス派からカトリックに改宗しました。", "711年、北アフリカから進出したイスラーム勢力のウマイヤ朝が西ゴート王国を滅ぼし、半島のほぼ全域を支配しました。イスラーム軍はさらにピレネー山脈をこえてフランク王国に侵入しましたが、732年の【トゥール・ポワティエ間の戦い】で退けられました。", "750年にウマイヤ朝がアッバース朝に倒されると、ウマイヤ家の一族がイベリア半島に逃れ、756年に【後ウマイヤ朝】を建てました。都【コルドバ】は、10世紀にカリフを称した【アブド=アッラフマーン3世】のもとで、人口の多い西ヨーロッパ最大級の都市として栄えました。コルドバの大モスク【メスキータ】は、この繁栄を今に伝えています。後ウマイヤ朝の滅亡後も、イベリア半島では北アフリカの王朝のもとでイスラーム文化が栄え、哲学者【イブン=ルシュド(アヴェロエス)】はアリストテレスの注釈で知られ、のちのヨーロッパのスコラ学に影響を与えました。"]}, {"t": "中世 ― レコンキスタとイスラーム文化の継承", "p": ["イスラームの支配に対し、半島北部に残ったキリスト教徒は、少しずつ南へ領土を取り戻していきました。これが【国土回復運動(レコンキスタ)】です。11世紀に後ウマイヤ朝が滅亡してイスラーム側が分裂すると、レコンキスタは本格化し、その中で【カスティリャ王国】・【アラゴン王国】が成長しました。また、12世紀にはカスティリャから【ポルトガル王国】が独立しました。レコンキスタは、十字軍と同じく、キリスト教徒による異教徒との戦いという性格をもっていました。", "1085年にカスティリャがトレドを奪回すると、トレドではアラビア語に訳されていたギリシアの哲学・科学の文献や、イスラームの学問がラテン語に翻訳されました。これがヨーロッパの学問を大きく発展させた【12世紀ルネサンス】の重要な源の一つとなりました。イベリア半島は、イスラーム文化を西ヨーロッパに伝える窓口の役割を果たしたのです。", "宗教面では、スペイン出身のドミニクスが創設した【ドミニコ修道会】が、托鉢修道会として異端の教化や学問に力を入れました。13世紀にはレコンキスタが大きく進み、半島に残ったイスラーム国家は南部の【ナスル朝】(都グラナダ)だけになりました。ナスル朝の【アルハンブラ宮殿】は、イスラーム建築の傑作として知られています。", "1469年、カスティリャ王女【イサベル】とアラゴン王子【フェルナンド】が結婚し、1479年に両国が合同して【スペイン王国】が成立しました(【イサベル・フェルナンド】の共同統治)。そして1492年、スペインはグラナダを陥落させ、レコンキスタは完了しました。同じ年、スペインはユダヤ教徒に改宗か国外退去を迫り、カトリックによる国家統一を進めています。"]}, {"t": "大航海時代 ― ポルトガルのアジア進出", "p": ["15世紀、イベリア半島の両国が大西洋に乗り出した背景には、いくつもの事情がありました。ヨーロッパでは肉料理に欠かせない香辛料の需要が高かったのに、地中海の東方貿易はイタリア商人とイスラーム商人に握られ、さらにオスマン帝国の進出で高価になっていました。そこで、アジアと直接取引する航路の開拓が求められたのです。また、レコンキスタの延長として、キリスト教の布教への熱意もありました。羅針盤の改良や航海術の発達、マルコ=ポーロの『世界の記述』などによるアジアへの関心も航海を後押ししました。", "先頭を切ったのはポルトガルです。「航海王子」と呼ばれた【エンリケ】がアフリカ西岸の探検を推進し、1488年には【バルトロメウ=ディアス】がアフリカ南端の喜望峰に到達しました。そして1498年、【ヴァスコ=ダ=ガマ】がインド西岸のカリカットに到達し、インド航路が開かれました。1500年には【カブラル】がインドに向かう途中でブラジルに漂着し、ここはポルトガル領となりました。", "ポルトガルは、インド総督【アルブケルケ】のもとで1510年にゴアを占領し、翌年にはマラッカを占領して、アジアの香辛料貿易に参入しました。さらに中国の明から【マカオ】の居住権を得て、日本とも交易を行いました。1543年ごろにはポルトガル人が種子島に漂着して鉄砲を伝えたとされ、1549年には【イエズス会】の【フランシスコ=ザビエル】が日本にキリスト教を伝えました。イエズス会は、宗教改革に対抗するカトリック改革の中で生まれた修道会で、アジアやアメリカでの布教に大きな役割を果たしました。ポルトガルの首都リスボンは、香辛料取引で一時ヨーロッパ有数の商業都市となりました。"]}, {"t": "大航海時代 ― スペインのアメリカ征服", "p": ["スペインの援助を受けたジェノヴァ出身の【コロンブス】は、地球球体説にもとづいて西回りでアジアをめざし、1492年にカリブ海のサンサルバドル島に到達しました。コロンブス自身はインドに着いたと信じていましたが、のちに【アメリゴ=ヴェスプッチ】の探検によって、そこが未知の大陸であることが知られるようになり、アメリカという名前は彼にちなんでつけられました。新しい土地をめぐってスペインとポルトガルが争ったため、1494年の【トルデシリャス条約】で、大西洋上の境界線より西をスペイン、東をポルトガルの勢力範囲と定めました。ブラジルがポルトガル領となったのはこのためです。", "1519年に出発したポルトガル人【マゼラン(マガリャンイス)】の船隊は、スペインの援助で西回りの航海に出て、マゼラン自身はフィリピンで戦死したものの、部下が1522年に帰国して世界周航を達成しました。スペインはのちにフィリピンに【マニラ】を建設し、メキシコのアカプルコとの間でガレオン船による貿易を行い、アメリカ大陸の銀をアジアにもたらしました。", "アメリカ大陸では、スペインから来た征服者(コンキスタドール)が先住民の文明を滅ぼしました。【コルテス】はメキシコのアステカ王国を、【ピサロ】はアンデスのインカ帝国を征服しました。スペインは植民者に先住民の支配と保護をゆだねる【エンコミエンダ制】を導入しましたが、実際には先住民を鉱山や農園で過酷に働かせることになり、さらにヨーロッパから持ち込まれた伝染病によって先住民の人口は激減しました。ドミニコ会士の【ラス=カサス】は、この残虐な支配を告発しました。労働力不足を補うため、アフリカから多くの黒人奴隷が運ばれました。", "1545年に発見されたボリビアの【ポトシ銀山】などから大量の銀がヨーロッパに流れ込み、物価が大きく上昇する価格革命が起こりました。また、ヨーロッパの商業の中心が地中海から大西洋沿岸に移る商業革命も進みました。"]}, {"t": "近世 ― スペインの全盛と衰退", "p": ["16世紀のスペインは、ハプスブルク家の王のもとで全盛期を迎えます。カルロス1世は神聖ローマ皇帝カール5世を兼ね、スペイン・ネーデルラント・南イタリア・アメリカ大陸に広がる大帝国を支配しました。その子【フェリペ2世】は、1571年の【レパントの海戦】でオスマン帝国の海軍を破り、1580年には王家が断絶した【ポルトガル】を併合しました。こうしてスペインはアジアからアメリカにいたる世界帝国となり、「太陽の沈まぬ国」と呼ばれました。", "しかし、熱心なカトリック教徒だったフェリペ2世は、新教徒が多く商工業の盛んな【フランドル地方】を含むネーデルラントにカトリックを強制し、重税を課しました。これに反発して1568年にオランダ独立戦争が始まります。南部10州はやがてスペインに屈しましたが、北部7州は1579年に【ユトレヒト同盟】を結び、【ウィレム(オラニエ公ウィレム)】の指導のもとで戦い続け、1581年に独立を宣言して【オランダ(ネーデルラント連邦共和国)】を建てました。それまで国際商業・金融の中心だった【アントウェルペン(アントワープ)】はスペイン軍によって打撃を受け、その地位は【アムステルダム】に移りました。さらに1588年、オランダを支援するイギリスを討とうとした無敵艦隊(アルマダ)がイギリス海軍に敗れました。", "アメリカの銀に頼ったスペインは、国内の産業を育てず、たび重なる戦争と宗教的な不寛容によって衰えていきました。1640年にはポルトガルが独立を回復しています。一方、独立したオランダは【オランダ東インド会社】を設立してアジアに進出し、ジャワの【バタヴィア】を拠点に香辛料貿易を支配し、ポルトガルの勢力を奪っていきました。この時期のスペインでは、【セルバンテス】が『ドン=キホーテ』で没落する騎士を風刺し、宮廷画家【ベラスケス】が活躍するなど、文化の黄金時代を迎えていました。", "1700年にスペインのハプスブルク家が断絶すると、ルイ14世の孫がフェリペ5世として即位し、これをめぐって【スペイン継承戦争】が起こりました。1713年のユトレヒト条約で、ブルボン家のスペイン王位継承は認められたものの、【ジブラルタル】をイギリスに譲りました。"]}, {"t": "近代 ― ナポレオン戦争と植民地の独立", "p": ["1808年、ナポレオンは兄ジョゼフをスペイン王に据えました。これに対してスペインの民衆はゲリラ戦で激しく抵抗し、イギリスの支援も受けてフランス軍を苦しめました。これが【スペイン反乱(半島戦争)】です。画家【ゴヤ】は『1808年5月3日』で、フランス軍による民衆の処刑を描きました。スペインでの苦戦は、ナポレオンの没落の一因となりました。", "本国がナポレオンに支配されたことで、ラテンアメリカの植民地では、現地生まれの白人(クリオーリョ)を中心とする独立運動が一気に進み、1810年代から1820年代にかけて多くの国が独立しました。ポルトガルの王室はナポレオン軍の侵攻を逃れてブラジルに移り、その後ブラジルは1822年に帝国として独立しました。スペインは19世紀を通じて政治的な混乱が続き、1898年の米西戦争に敗れて、キューバの独立を認め、フィリピンやプエルトリコ、グアムをアメリカに譲り、海外の植民地のほとんどを失いました。"]}, {"t": "現代 ― 内戦・独裁から民主化へ", "p": ["スペインでは1931年に王政が倒れて共和政となり、1936年の選挙で左派の人民戦線政府が成立しました。これに対し、軍人フランコが保守派・カトリック教会・地主の支持を得て反乱を起こし、【スペイン内戦】(1936〜39年)が始まりました。ドイツとイタリアはフランコ側を公然と支援し、1937年にはドイツ空軍がバスク地方の町を無差別爆撃しました。これに抗議して【ピカソ】が描いたのが『【ゲルニカ】』です。一方、イギリスとフランスは戦争の拡大を恐れて【不干渉政策】をとり、政府側を支援したのはソ連と、世界各地から集まった国際義勇軍でした。結局、1939年にフランコ側が勝利し、独裁体制が築かれました。スペイン内戦は、ファシズムと反ファシズムの対立という第二次世界大戦の前哨戦の性格をもっていました。", "フランコは第二次世界大戦では中立を保ち、戦後も独裁を続けました。1975年にフランコが死去すると、国王フアン=カルロス1世のもとで民主化が進み、立憲君主政が確立しました。ポルトガルでも、1910年に王政が倒れた後、長くサラザールの独裁が続きましたが、1974年の軍人によるクーデタ(カーネーション革命)で民主化し、翌年にはアンゴラやモザンビークなどアフリカの植民地の独立を認めました。1986年、両国はそろってヨーロッパ共同体(EC)に加盟し、ヨーロッパ統合の一員となりました。1999年にはポルトガルがマカオを中国に返還し、大航海時代以来の植民地支配の歴史に区切りがつきました。", "イベリア半島の歴史は、イスラームとキリスト教の文化が出会った中世、世界を一つに結びつけた大航海時代、そして植民地の喪失と内戦を経た近現代という流れで整理すると理解しやすくなります。とくに、両国が切り開いた航路によって、ヨーロッパ・アフリカ・アメリカ・アジアが初めて一つの交易網で結ばれた「世界の一体化」の意義は大きいといえます。"]}], "points": ["西ゴート王国(都トレド)の滅亡(711年)と後ウマイヤ朝(都コルドバ、アブド=アッラフマーン3世)", "レコンキスタの中でのカスティリャ・アラゴン・ポルトガルの成立と、1479年スペイン王国成立、1492年グラナダ陥落(ナスル朝)", "トレドの翻訳活動と12世紀ルネサンス、イブン=ルシュドの影響", "ポルトガルの航路:エンリケ→バルトロメウ=ディアス(喜望峰)→ヴァスコ=ダ=ガマ(インド)→カブラル(ブラジル)", "トルデシリャス条約(1494年)とブラジルがポルトガル領になった理由", "コルテス(アステカ)・ピサロ(インカ)・エンコミエンダ制・ラス=カサス・ポトシ銀山と価格革命", "フェリペ2世の全盛(レパントの海戦・ポルトガル併合)と、オランダ独立戦争・無敵艦隊敗北による衰退", "スペイン内戦(1936〜39年)の国際的構図(独伊の支援・英仏の不干渉政策・ゲルニカ)"], "check": [["756年にイベリア半島に建てられたイスラーム王朝は何か", "後ウマイヤ朝"], ["10世紀にカリフを称し、後ウマイヤ朝の最盛期を築いたのは誰か", "アブド=アッラフマーン3世"], ["イベリア半島最後のイスラーム王朝は何か", "ナスル朝"], ["1488年に喜望峰に到達したのは誰か", "バルトロメウ=ディアス"], ["1498年にインド西岸のカリカットに到達したのは誰か", "ヴァスコ=ダ=ガマ"], ["1494年にスペインとポルトガルの勢力範囲を定めた条約は何か", "トルデシリャス条約"], ["インカ帝国を征服したのは誰か", "ピサロ"], ["先住民への残虐な支配を告発したドミニコ会士は誰か", "ラス=カサス"], ["1571年にスペインがオスマン帝国海軍を破った戦いは何か", "レパントの海戦"], ["スペイン内戦中の無差別爆撃に抗議してピカソが描いた作品は何か", "ゲルニカ"]], "related": ["y_5", "y_8", "y_10", "y_13", "y_15", "y_16", "y_17", "y_19", "y_20a", "t_ar", "t_la", "t_nl", "t_ph", "t_in", "t_id", "t_fr", "t_uk"], "n": 4926, "videos": [{"title": "【世界史】 西欧絶対王政２ スペイン・オランダ （２０分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=noq0uI5SNKA", "note": "絶対王政期のスペインとオランダを学べ、スペイン帝国を扱った2026年度第4問Ｃの背景にもなります。"}]}, "t_nl": {"title": "オランダ・ベルギー史", "span": "9世紀〜現在", "year": 1581, "lead": "北海に面した低地地方(ネーデルラント)は、中世から毛織物業と商業で栄えた豊かな地域です。16世紀にスペインから独立した北部のオランダは、17世紀に世界の海運と金融の中心となりました。南部は19世紀にベルギーとして独立し、両国は現代のヨーロッパ統合の出発点を担っています。", "flow": ["中世 フランドル地方で毛織物業が発達→英仏の争奪の的となり百年戦争の一因に", "15〜16世紀 ブルゴーニュ公領からハプスブルク家の領地へ→カール5世・フェリペ2世の支配", "1568年 オランダ独立戦争が始まる(指導者オラニエ公ウィレム)", "1579年 北部7州がユトレヒト同盟→1581年ネーデルラント連邦共和国の独立宣言", "1602年 オランダ東インド会社設立→1619年バタヴィア建設、1623年アンボイナ事件", "1648年 ウェストファリア条約で独立が国際的に承認→17世紀はアムステルダムが世界経済の中心", "1651年 イギリスの航海法→1652年からイギリス=オランダ戦争、オランダの覇権が後退", "1815年 ウィーン議定書でオランダ王国が南部(のちのベルギー)を併合", "1830年 七月革命の影響でベルギーが独立→1839年永世中立が承認", "1830年 ジャワで強制栽培制度、1885年ベルギー王の私領コンゴ自由国", "1914年・1940年 中立国ベルギー・オランダがドイツに侵攻される", "1948年〜 ベネルクス3国が西ヨーロッパ連合条約・NATO・ECSC・EECに参加→EUの中心へ"], "sync": [], "secs": [{"t": "中世の低地地方 ― 毛織物と都市", "p": ["現在のオランダ・ベルギー・ルクセンブルクにあたる地域は、ライン川などの大河の河口に広がる低い土地で、【ネーデルラント】(低地地方)とよばれました。この地域はもともとフランク王国の一部でしたが、9世紀に王国が分裂すると、フランス王国と東フランク(のちの神聖ローマ帝国)の境目に位置することになり、多くの諸侯の領地に分かれました。", "中世の後半になると、南部の【フランドル地方】で【毛織物業】が大きく発達しました。ガン(ヘント)やブリュージュなどの都市は、イギリスから原料の羊毛を輸入して高級な毛織物をつくり、北ヨーロッパの商業の中心となりました。ブリュージュには北ドイツの【ハンザ同盟】の商館も置かれ、北海・バルト海の商業と地中海の商業が出会う場所になりました。", "フランドルは政治的にはフランス王の影響を受けながら、経済的にはイギリスの羊毛に頼っていました。そのため、この地域の支配をめぐってイギリスとフランスが対立し、それが【百年戦争】の原因の一つになりました。豊かな低地地方は、こののちも周辺の大国の争いに巻き込まれ続けることになります。", "14世紀後半から15世紀にかけて、低地地方の多くはフランス王家の分家である【ブルゴーニュ公】の領地になりました。その後、結婚を通じてブルゴーニュ公の遺領は【ハプスブルク家】に受け継がれます。こうして16世紀には、ハプスブルク家の【カール5世】(スペイン王カルロス1世)がネーデルラントを支配するようになりました。アントウェルペン(アントワープ)は16世紀前半、大航海時代の新しい商品が集まる国際商業・金融の中心として繁栄しました。"]}, {"t": "オランダ独立戦争", "p": ["16世紀のネーデルラントでは、宗教改革の影響を受けて新教徒が増え、とくに北部では【カルヴァン派】が広まりました。商工業者が多いこの地域では、勤労と蓄財を肯定するカルヴァン派の教えが受け入れられやすかったとされます。ネーデルラントの新教徒は【ゴイセン】とよばれました。", "カール5世の子でスペイン王となった【フェリペ2世】は、熱心なカトリックの立場から新教徒を厳しく弾圧し、重い税を課して都市の自治を抑えようとしました。これに反発したネーデルラントの人々は、【オラニエ公ウィレム】を指導者として、1568年に反乱を起こしました。これが【オランダ独立戦争】の始まりです。", "しかし、ネーデルラントの南部と北部では事情が違いました。カトリックの住民が多い南部10州は、スペインとの妥協に向かい、反乱から離れていきます。これに対して、新教徒の多い北部7州は1579年に【ユトレヒト同盟】を結んで団結し、1581年に【ネーデルラント連邦共和国】として独立を宣言しました。北部の中心がホラント州であったことから、この国は【オランダ】とよばれます。", "戦いはその後も長く続き、1609年にはスペインとの休戦が成立して事実上の独立を勝ち取りました。最終的に独立が国際的に認められたのは、【三十年戦争】を終わらせた1648年の【ウェストファリア条約】で、このとき【スイス】の独立も正式に承認されました。一方、南部はスペイン領として残り、この南北の違いが、のちのオランダとベルギーの分離につながっていきます。"]}, {"t": "17世紀 ― オランダの黄金時代", "p": ["独立戦争の最中から、オランダは海運と貿易で急速に力をつけました。スペインの攻撃でアントウェルペンが衰えると、多くの商人や職人が北部へ移り、【アムステルダム】が新たな国際商業・金融の中心になりました。バルト海の穀物や木材を運ぶ中継貿易を土台に、オランダの商船は世界中の海へ進出しました。", "1602年には【オランダ東インド会社】が設立されました。この会社は、条約の締結や軍隊の保有なども認められた強力な組織で、ポルトガルにかわってアジアの香辛料貿易を支配しようとしました。ジャワ島に【バタヴィア】(現在のジャカルタ)を建設して拠点とし、1623年の【アンボイナ事件】ではモルッカ諸島からイギリス勢力を追い出しました。この結果、イギリスはインド経営に力を注ぐようになります。さらにオランダは、台湾の一部を支配し、鎖国下の日本とも長崎の出島で貿易を続けました。", "オランダはアフリカ南端に【ケープ植民地】(1652年)を築き、北アメリカには【ニューアムステルダム】を建設しました。こうした海外進出を支えたのが、自由な商業活動と宗教的な寛容でした。各地で迫害された人々がオランダに逃れ、学問や芸術が花開きます。【国際法の父】とよばれる【グロティウス】は『戦争と平和の法』を著し、哲学者の【スピノザ】が活躍し、画家の【レンブラント】は市民の姿を描いた作品を残しました。", "しかし、オランダの繁栄は長くは続きませんでした。イギリスは1651年に【航海法】を定め、オランダの中継貿易を締め出そうとしました。これをきっかけに1652年から【イギリス=オランダ(英蘭)戦争】が起こり、ニューアムステルダムはイギリスに奪われてニューヨークと改められました。さらにフランスの【ルイ14世】による侵略戦争も受け、オランダは陸と海で大国と戦わざるをえなくなりました。", "このとき国を率いたオラニエ公ウィレム3世は、1688〜89年のイギリスの【名誉革命】で妻メアリとともにイギリス王に迎えられ、【ウィリアム3世】として即位しました。これによりオランダとイギリスはともにフランスと戦う関係になりましたが、18世紀になると世界貿易の主役はしだいにイギリスへ移り、オランダは金融国として存在感を保つものの、覇権国の地位を失っていきました。"]}, {"t": "フランス革命からベルギー独立へ", "p": ["18世紀末、フランス革命軍がネーデルラントに進出し、オランダには1795年にフランスの影響下の共和国が成立しました。さらにナポレオンの時代には、弟のルイ=ボナパルトがオランダ王に立てられ、のちにはフランスに併合されます。この間に、ケープ植民地やセイロン島はイギリスに占領されました。", "ナポレオン戦争後の【ウィーン会議】では、フランスを北から抑える緩衝国をつくるため、オランダが旧オーストリア領ネーデルラント(南部)をあわせて【オランダ王国】となりました。その一方で、【ケープ植民地】と【セイロン島】はイギリス領とされました。", "しかし、南部の住民はカトリックが多く、フランス語を話す人も多かったため、プロテスタントのオランダ王の支配に強い不満をもちました。1830年にフランスで【七月革命】が起こると、その影響を受けて南部が反乱を起こし、【ベルギー】として独立を宣言しました。ベルギーは立憲君主政をとり、1839年には列強によって独立と【永世中立】が承認されました。", "独立したベルギーは、石炭と鉄の資源に恵まれ、ヨーロッパ大陸でいち早く【産業革命】が進んだ国の一つになりました。一方、オランダは植民地のジャワで1830年から【強制栽培制度】を実施し、コーヒーやサトウキビ、藍などを住民に強制的に栽培させて莫大な利益をあげましたが、現地の人々は飢饉に苦しみました。"]}, {"t": "帝国主義と二つの世界大戦", "p": ["19世紀後半の帝国主義の時代、ベルギー国王【レオポルド2世】はアフリカ中央部に関心を向けました。1884〜85年のベルリン会議(ベルリン=コンゴ会議)の結果、コンゴ盆地は国王の私有地のような【コンゴ自由国】として認められました。しかし、天然ゴムの採取などのために住民への苛酷な強制労働が行われて国際的な非難を浴び、1908年にベルギー政府が管理する植民地(ベルギー領コンゴ)に移されました。", "オランダもまた、19世紀後半から20世紀初めにかけてスマトラ島のアチェなどを征服し、【オランダ領東インド】を完成させました。この植民地支配に対して、20世紀に入るとインドネシアの民族運動が高まっていきます。", "1914年、第一次世界大戦が始まると、ドイツはフランスを短期間で倒す作戦のために中立国ベルギーに侵入しました。この【ベルギーの中立侵犯】は、イギリスがドイツに宣戦する大きな理由となりました。大戦後の1923年には、ドイツの賠償金支払いの遅れを理由に、フランスとベルギーがドイツの工業地帯を占領する【ルール占領】を行いました。", "第二次世界大戦でも、1940年にドイツはオランダ・ベルギー・ルクセンブルクに侵攻して占領し、そこからフランスへ攻め込みました。オランダではユダヤ人の迫害も行われ、隠れ家での生活をつづった『アンネの日記』はその記録として知られています。"]}, {"t": "現代 ― 植民地の独立とヨーロッパ統合", "p": ["第二次世界大戦後、オランダ領東インドでは1945年に【スカルノ】らが【インドネシア】の独立を宣言しました。オランダは武力で再支配を試みましたが、国際的な圧力もあって1949年に独立を認めました。ベルギー領コンゴも1960年に独立しますが、直後に【コンゴ動乱】が起こり、旧宗主国や大国の介入を招きました。", "戦争で大国に何度も踏みにじられた経験から、ベルギー・オランダ・ルクセンブルクの3国は、小国どうしが協力する道を選びました。3国は関税同盟を結んで【ベネルクス】とよばれる協力体制をつくり、1948年にはイギリス・フランスとともに【西ヨーロッパ連合条約】(ブリュッセル条約)を結び、1949年には【北大西洋条約機構(NATO)】の原加盟国となりました。", "さらにベネルクス3国は、フランス・西ドイツ・イタリアとともに1952年の【ヨーロッパ石炭鉄鋼共同体(ECSC)】、1958年の【ヨーロッパ経済共同体(EEC)】の原加盟国となりました。ベルギーの首都【ブリュッセル】にはEUの主要機関やNATOの本部が置かれ、1992年にオランダの都市で調印された【マーストリヒト条約】によってEUが発足しました。かつて大国の争いの舞台だった低地地方は、いまではヨーロッパ統合の中心地となっています。", "なお、ベルギー国内には、北部のオランダ語系(フラマン語)の人々と南部のフランス語系(ワロン)の人々という言語の異なる集団があり、両者の対立は独立以来の課題でした。このためベルギーは20世紀後半に地域ごとの自治を拡大する改革を重ね、1993年に連邦制へ移行しました。オランダ独立戦争のときに南北が分かれた歴史と、言語や宗教の違いが、現在の国のかたちにまで影響していることがわかります。"]}], "points": ["フランドル地方の毛織物業とイギリス羊毛の関係が百年戦争の一因になったこと", "オランダ独立戦争:フェリペ2世の弾圧→1568年反乱(オラニエ公ウィレム)→1579年ユトレヒト同盟→1581年独立宣言→1648年ウェストファリア条約で承認", "南部10州はカトリックが多くスペイン支配に残った→のちのベルギー", "オランダ東インド会社(1602年)、バタヴィア、アンボイナ事件(1623年)の結果イギリスがインドへ重点を移したこと", "航海法(1651年)と英蘭戦争、ニューアムステルダム→ニューヨーク", "ウィーン議定書でケープ植民地・セイロン島がイギリス領に、ベルギーは1830年に独立し永世中立", "強制栽培制度(ジャワ)とコンゴ自由国(レオポルド2世)", "ベネルクス3国がECSC・EECの原加盟国で、マーストリヒト条約でEU発足"], "check": [["オランダ独立戦争を指導したのは誰か", "オラニエ公ウィレム"], ["1579年に北部7州が結んだ同盟は何か", "ユトレヒト同盟"], ["オランダの独立が国際的に承認された1648年の条約は何か", "ウェストファリア条約"], ["オランダ東インド会社がジャワ島に建設した拠点はどこか", "バタヴィア"], ["1623年にオランダがモルッカ諸島からイギリスを排除した事件は何か", "アンボイナ事件"], ["『戦争と平和の法』を著し国際法の父とよばれるのは誰か", "グロティウス"], ["1651年にイギリスがオランダの中継貿易に打撃を与えるため定めた法は何か", "航海法"], ["1830年の七月革命の影響で独立した国はどこか", "ベルギー"], ["ジャワで住民にコーヒーなどを強制的につくらせた制度は何か", "強制栽培制度"], ["ベルギー国王レオポルド2世の私領として認められた地域は何か", "コンゴ自由国"]], "related": ["y_14", "y_16", "y_17", "y_19", "y_20a", "y_20b", "t_es", "t_uk", "t_fr", "t_de", "t_id", "t_af", "t_us"], "n": 4151}, "t_nord": {"title": "北欧史", "span": "8世紀〜現在", "year": 1397, "lead": "デンマーク・スウェーデン・ノルウェーなどの北欧は、8〜11世紀にノルマン人(ヴァイキング)としてヨーロッパ各地に進出しました。14世紀にはカルマル同盟で一つにまとまり、17世紀にはスウェーデンがバルト海の覇権を握ります。近代以降は列強の争いの中で中立と福祉国家の道を歩みました。", "flow": ["8〜11世紀 ノルマン人(ヴァイキング)が各地へ進出→911年ノルマンディー公国、862年ノヴゴロド国", "1016年 デーン人のクヌートがイングランド王に→北海帝国", "1066年 ノルマンディー公ウィリアムがイングランド征服(ノルマン=コンクェスト)", "1397年 カルマル同盟でデンマーク・スウェーデン・ノルウェーが同君連合に", "1523年 スウェーデンがグスタフ=ヴァーサのもとで同盟から独立→ルター派を採用", "1630年 グスタフ=アドルフが三十年戦争に参戦→1648年ウェストファリア条約で領土獲得、バルト海帝国に", "1700〜21年 北方戦争でカール12世がピョートル1世に敗北→スウェーデン衰退", "1809年 フィンランドがロシア領に、1814年ノルウェーがデンマークからスウェーデンへ", "1864年 デンマーク戦争でシュレスヴィヒ・ホルシュタインを失う", "1905年 ノルウェー独立、1917年フィンランド独立", "1939年 ソ連=フィンランド戦争(冬戦争)、1940年ドイツがデンマーク・ノルウェーを占領", "戦後 NATO加盟国と中立国に分かれる→福祉国家の発展、1995年スウェーデン・フィンランドEU加盟"], "sync": [], "secs": [{"t": "ノルマン人の大移動 ― ヴァイキングの時代", "p": ["スカンディナヴィア半島とユトランド半島に住んでいたゲルマン人の一派を【ノルマン人】といいます。寒冷でやせた土地が多く人口が増えると暮らしが苦しくなったこと、すぐれた造船・航海の技術をもっていたことなどから、彼らは8世紀後半から11世紀にかけて海を越えてヨーロッパ各地へ進出しました。この人々は【ヴァイキング】ともよばれ、略奪だけでなく交易や植民も盛んに行いました。これは4世紀以降のゲルマン人の大移動に続く、【第2次民族移動】とも位置づけられます。", "ノルマン人の進出先は広い範囲にわたりました。西フランクでは首領【ロロ】が911年に【ノルマンディー公国】を建てることを認められました。南イタリアとシチリア島には12世紀に【両シチリア王国】が建てられました。東では、【スウェーデン系】のノルマン人(ルーシ)が862年に【リューリク】のもとで【ノヴゴロド国】を建て、のちに【キエフ公国】がつくられたとされ、これがロシアのはじまりとなります。さらにアイスランドやグリーンランドへ植民し、北アメリカ大陸にまで到達したとされます。", "イングランドには【デーン人】(デンマーク系ノルマン人)がたびたび侵入しました。アングロ=サクソン王国の【アルフレッド大王】はこれと戦いましたが、1016年にはデンマーク王子の【クヌート(カヌート)】がイングランドを征服して王となり、デンマーク・ノルウェーをあわせた【北海帝国】を築きました。さらに1066年には、ノルマンディー公【ウィリアム】がイングランドを征服して【ノルマン朝】を開きました(【ノルマン=コンクェスト】)。こうしてノルマン人は、イギリスやロシアなど、のちのヨーロッパの国々の形成に大きな役割を果たしたのです。", "いっぽう、故郷のスカンディナヴィアにも、10〜11世紀ごろまでに【デンマーク・スウェーデン・ノルウェー】の三つの王国が形成されました。王たちはキリスト教(ローマ=カトリック)を受け入れ、北欧はしだいに西ヨーロッパのキリスト教世界に組み込まれていきました。"]}, {"t": "カルマル同盟とスウェーデンの独立", "p": ["中世後半の北欧では、北ドイツの都市がつくる【ハンザ同盟】がバルト海の商業を握り、北欧の王たちにとって大きな脅威になっていました。こうした状況のなか、デンマークの摂政【マルグレーテ】の主導で、1397年に【カルマル同盟】が結ばれ、デンマーク・スウェーデン・ノルウェーの3国が同じ君主をいただく同君連合となりました。", "しかし同盟の実権はデンマークが握っていたため、スウェーデンの貴族や農民はこれに反発しました。1523年、【グスタフ=ヴァーサ】がスウェーデン王に選ばれて同盟から離脱し、独立を果たしました。彼は王権を強めるために教会の財産を没収し、【ルター派】を受け入れました。デンマーク・ノルウェーでもルター派が国の宗教となり、北欧は現在までルター派の地域となっています。宗教改革が、王権強化と結びついて広まった例です。", "スウェーデンが離れたあとも、デンマークとノルウェーの結びつきは続き、ノルウェーは1814年までデンマーク王の支配のもとに置かれました。そのため、近世の北欧は、デンマーク(ノルウェーを含む)とスウェーデンという二つの王国が、バルト海の出入口や沿岸の支配をめぐって争う時代となりました。この二国の対立に、のちにはロシアやポーランド、北ドイツの諸侯がからみ、バルト海は国際政治の重要な舞台となっていきます。"]}, {"t": "バルト海帝国スウェーデンの興亡", "p": ["17世紀になると、スウェーデンはバルト海の覇権をめざして急速に力をつけました。ドイツで【三十年戦争】が起こると、まずデンマーク王クリスチャン4世が新教徒側として介入しましたが、皇帝側の傭兵隊長【ヴァレンシュタイン】に敗れました。続いて1630年、スウェーデン王【グスタフ=アドルフ】が新教徒の保護とバルト海沿岸の支配をねらって参戦しました。彼は優れた軍隊を率いて勝利を重ねましたが、1632年の【リュッツェンの戦い】で戦死しました。", "1648年の【ウェストファリア条約】で、スウェーデンは西ポンメルンなどバルト海南岸の領土を獲得し、神聖ローマ帝国の議会にも加わる立場を得ました。こうしてスウェーデンはバルト海をほぼ取り囲む【バルト海帝国】となり、北ヨーロッパの大国として君臨しました。", "しかし、バルト海への出口を求めるロシアの【ピョートル1世】は、ポーランド・デンマークと結んでスウェーデンに挑みました。これが1700年に始まる【北方戦争】です。若き国王【カール12世】は1700年のナルヴァの戦いでロシア軍を破りましたが、1709年の【ポルタヴァの戦い】で大敗しました。1721年の【ニスタット条約】でスウェーデンはバルト海東岸の領土を失い、ロシアがかわってバルト海の強国となりました。ピョートル1世が建設した新首都【ペテルブルク】は、この戦争の中で生まれた都市です。", "こうしてスウェーデンは大国の地位を失いましたが、18世紀には学問が発展し、植物学者【リンネ】が生物を分類する方法を確立しました。", "北方戦争の結果は、北欧だけでなくヨーロッパ全体の勢力図を変えました。それまで東方の辺境国とみられていたロシアがバルト海に面した大国としてヨーロッパの国際政治に加わり、スウェーデンは以後、大国どうしの争いからしだいに距離をおくようになります。この経験が、のちのスウェーデンの中立政策の背景の一つになったと考えられています。"]}, {"t": "ナポレオン戦争と19世紀の再編", "p": ["ナポレオン戦争は北欧の国境を大きく塗りかえました。1809年、スウェーデンはロシアとの戦争に敗れて【フィンランド】を失い、フィンランドはロシア皇帝を君主とする【フィンランド大公国】となりました。その後スウェーデンは、ナポレオン配下の将軍であった【ベルナドット】を王位継承者に迎え、彼は対ナポレオン戦争に加わって勝者の側に立ちました。", "一方、ナポレオン側についたデンマークは敗れ、1814年の条約で【ノルウェー】をスウェーデンに譲りました。ノルウェーは独自の憲法と議会をもちながらスウェーデン王を君主とする同君連合となり、19世紀を通じて自立を求める動きが強まりました。", "19世紀半ば、デンマークは南部の【シュレスヴィヒ・ホルシュタイン】の両公国をめぐってドイツ人勢力と対立しました。1864年、ビスマルクの率いるプロイセンとオーストリアがデンマークと戦い(【デンマーク戦争】)、両公国はデンマークから奪われました。この両公国の管理をめぐる対立が、1866年の【プロイセン=オーストリア戦争】につながります。", "20世紀に入ると、1905年に【ノルウェー】がスウェーデンから平和的に分離・独立しました。また、ロシア革命の混乱のなかで1917年に【フィンランド】が独立を宣言しました。北欧の国々は、このようにして現在の姿になっていったのです。"]}, {"t": "北欧の文化と社会", "p": ["19世紀の北欧は、すぐれた文化人を多く生み出しました。ノルウェーの劇作家【イプセン】は『人形の家』で、夫に従属して生きる女性が自立していく姿を描き、女性解放の問題を投げかけました。デンマークでは童話作家の【アンデルセン】や、実存哲学の先駆者とされる思想家【キルケゴール】が活躍しました。スウェーデンの【ノーベル】はダイナマイトを発明し、その遺産で【ノーベル賞】がつくられました。", "探検の分野でも、ノルウェーの【アムンゼン】が1911年に人類で初めて【南極点】に到達しました。音楽ではノルウェーのグリーグ、フィンランドの【シベリウス】が民族的な作品を残し、とくにシベリウスの交響詩『フィンランディア』はロシア支配下のフィンランドで愛国心を高めたとされます。", "北欧の国々は19世紀後半から議会政治と社会運動が発達し、早い時期から女性参政権も実現しました。20世紀には、社会民主主義の政党が長く政権を担い、税負担は重いものの、教育・医療・年金などを国が手厚く保障する【福祉国家】が築かれました。"]}, {"t": "二つの世界大戦と現代", "p": ["第一次世界大戦では北欧の国々は中立を保ちました。しかし第二次世界大戦では状況が異なりました。1939年、独ソ不可侵条約を結んだソ連はフィンランドに領土を要求し、拒否されると攻撃を始めました(【ソ連=フィンランド戦争】、冬戦争)。この侵略を理由に、ソ連は【国際連盟から除名】されました。フィンランドは善戦しましたが、領土の一部を割譲させられ、のちの独ソ戦ではドイツ側について再びソ連と戦いました。", "1940年にはドイツが【デンマーク】と【ノルウェー】に侵攻して占領しました。ドイツにとって、スウェーデンからの鉄鉱石の輸送路や北大西洋への出口を確保することが重要だったとされます。スウェーデンは中立を保ちましたが、その立場は大国の間で難しい舵取りを迫られるものでした。", "戦後、ナチス=ドイツの侵略を受けたデンマーク・ノルウェー・アイスランドは、1949年に【北大西洋条約機構(NATO)】の原加盟国となりました。一方、スウェーデンは伝統的な中立を続け、フィンランドはソ連と友好協力相互援助条約を結んで、ソ連に配慮しながら中立を守る難しい立場をとりました。", "冷戦が終わると、北欧の国々はヨーロッパ統合にも積極的にかかわりました。デンマークは1973年に【EC】に加盟し、スウェーデンとフィンランドは1995年に【EU】に加盟しました。一方、ノルウェーは国民投票で加盟を否決しています。さらに2022年のロシアのウクライナ侵攻を受けて、長く中立を保ってきた【フィンランド】(2023年)と【スウェーデン】(2024年)もNATOに加盟し、北欧の安全保障は大きな転換点を迎えました。", "なお、北欧の国々は言語や文化の近さを生かして、戦後に北欧理事会をつくるなど地域どうしの協力を進めてきました。デンマーク領だったアイスランドも1944年に共和国として完全に独立しています。ヴァイキングの時代から続く海との深いかかわりと、大国のはざまで生き残るための知恵が、北欧の歴史をつらぬく特徴だといえるでしょう。"]}], "points": ["ノルマン人の進出先:ノルマンディー公国(911年、ロロ)、両シチリア王国、ノヴゴロド国(862年、リューリク)、イングランド(クヌート、ノルマン=コンクェスト1066年)", "カルマル同盟(1397年)はデンマーク主導の3国の同君連合で、マルグレーテが主導", "グスタフ=ヴァーサのスウェーデン独立(1523年)とルター派の採用", "三十年戦争:デンマーク(クリスチャン4世)→スウェーデン(グスタフ=アドルフ、リュッツェンで戦死)の参戦", "北方戦争(1700〜21年):カール12世がポルタヴァの戦いで敗北→ニスタット条約でロシアがバルト海の覇権", "デンマーク戦争(1864年)とシュレスヴィヒ・ホルシュタイン問題", "ソ連=フィンランド戦争(1939年)でソ連が国際連盟から除名", "イプセン『人形の家』、ノーベル、アムンゼン、キルケゴール、アンデルセンなどの文化人"], "check": [["911年にロロが建てた国は何か", "ノルマンディー公国"], ["1016年にイングランドを征服したデンマーク王子は誰か", "クヌート(カヌート)"], ["1397年にデンマーク・スウェーデン・ノルウェーが結んだ同君連合は何か", "カルマル同盟"], ["三十年戦争に参戦し1632年に戦死したスウェーデン王は誰か", "グスタフ=アドルフ"], ["北方戦争でピョートル1世と戦ったスウェーデン王は誰か", "カール12世"], ["北方戦争を終わらせた1721年の条約は何か", "ニスタット条約"], ["1864年にプロイセン・オーストリアがデンマークと戦った戦争は何か", "デンマーク戦争"], ["『人形の家』を著したノルウェーの劇作家は誰か", "イプセン"], ["1911年に初めて南極点に到達したのは誰か", "アムンゼン"], ["1939年にソ連がフィンランドに侵攻した戦争の結果、ソ連はどうなったか", "国際連盟から除名された"]], "related": ["y_9", "y_10", "y_11", "y_14", "y_16", "y_17", "y_18", "y_19", "y_20a", "y_20b", "t_uk", "t_fr", "t_de", "t_ru", "t_it", "t_pl"], "n": 4061}, "t_pl": {"title": "ポーランド・東欧史", "span": "10世紀〜現在", "year": 1795, "lead": "ポーランド・チェコ(ベーメン)・ハンガリーなどの東欧は、西スラヴ人やマジャール人がカトリックを受け入れて建てた国々の地域です。ドイツとロシアという大国にはさまれたため、ポーランドは18世紀に分割されて消滅し、20世紀にはナチス=ドイツとソ連の支配を受けました。1989年の東欧革命で自由を取り戻し、現在はEUの一員となっています。", "flow": ["10世紀ごろ ポーランド王国・ベーメン王国・ハンガリー王国が成立しカトリックを受容", "1241年 モンゴル軍がワールシュタットの戦いでドイツ・ポーランド軍を破る", "1348年 カール4世がプラハ大学を創設、1356年金印勅書", "1386年 リトアニアとポーランドが合同しヤゲウォ朝→1410年タンネンベルクでドイツ騎士団を破る", "1415年 フスが処刑される→フス戦争、1526年モハーチの戦いでハンガリーの大半がオスマン領に、1572年ヤゲウォ朝断絶→選挙王政でポーランドが弱体化", "1772・93・95年 ロシア・プロイセン・オーストリアによるポーランド分割→ポーランド消滅", "1807年 ワルシャワ大公国→1815年ロシア皇帝を王とするポーランド王国、1830年・63年の蜂起は鎮圧", "1867年 オーストリア=ハンガリー帝国成立", "1918年 ポーランド・チェコスロヴァキア・ハンガリーが独立", "1939年 ドイツのポーランド侵攻で第二次世界大戦→独ソによる分割", "1956年 ポズナニ暴動・ハンガリー事件、1968年プラハの春、1980年連帯", "1989年 東欧革命→2004年ポーランド・チェコ・ハンガリーなどEU加盟"], "sync": [], "secs": [{"t": "東欧の国々のはじまり", "p": ["6世紀ごろから、東ヨーロッパには【スラヴ人】が広がりました。スラヴ人はおもに、ロシア人・ウクライナ人などの【東スラヴ人】、ポーランド人・チェック人(チェコ人)・スロヴァキア人などの【西スラヴ人】、セルビア人・クロアティア人などの【南スラヴ人】に分かれます。このうち東スラヴ人の多くとセルビア人は、ビザンツ帝国の影響で【ギリシア正教】を受け入れたのに対し、西スラヴ人やクロアティア人はローマ=カトリックを受け入れました。この宗教の違いは、文字(キリル文字とラテン文字)の違いとも重なり、現在まで東欧の文化の境目になっています。", "10世紀ごろには、西スラヴ人の【ポーランド王国】と、チェック人の【ベーメン(ボヘミア)王国】が成立しました。ベーメンは神聖ローマ帝国に組み込まれ、その王は皇帝を選ぶ選帝侯の一人となりました。", "一方、アジア系の【マジャール人】は9世紀末にパンノニア平原に移り住み、西ヨーロッパへの侵入を繰り返しましたが、955年に東フランクの【オットー1世】に【レヒフェルトの戦い】で敗れました。その後マジャール人は定住してカトリックを受け入れ、【ハンガリー王国】を建てました。こうして東欧の中央部には、カトリックを信仰する国々が並ぶことになりました。", "13世紀には、モンゴル帝国の【バトゥ】率いる遠征軍が東欧に侵入し、1241年の【ワールシュタットの戦い】でドイツ・ポーランドの諸侯の軍を破りました。モンゴル軍はハンガリーにも大きな被害を与えましたが、皇帝オゴタイの死の知らせを受けて引き返しました。"]}, {"t": "中世後期 ― ヤゲウォ朝とフス戦争", "p": ["14世紀のベーメンでは、ルクセンブルク家の【カール4世】がベーメン王と神聖ローマ皇帝を兼ね、首都プラハは帝国の文化の中心として栄えました。彼は1348年に中欧で最初の大学とされる【プラハ大学】を創設し、1356年には皇帝選挙の手続きを定めた【金印勅書】を発布しました。", "15世紀初め、プラハ大学の神学者【フス】は、イギリスの【ウィクリフ】の影響を受けて教会の腐敗を批判し、聖書を重んじる立場を説きました。フスは【コンスタンツ公会議】に呼び出されて異端とされ、1415年に火刑に処されました。これに怒ったベーメンの人々は【フス戦争】を起こし、長く皇帝や教皇の軍と戦いました。この戦いには、ドイツ人の支配に対するチェック人の民族的な反発も含まれていたとされます。", "ポーランドでは、北方のバルト海沿岸に進出した【ドイツ騎士団】の圧力が強まっていました。これに対抗するため、1386年、リトアニア大公ヤゲウォとポーランド女王が結婚し、両国が合同して【ヤゲウォ朝(ヤゲロー朝)】のリトアニア=ポーランド王国が成立しました。リトアニアはこのときカトリックを受け入れています。合同した王国は1410年の【タンネンベルクの戦い】でドイツ騎士団を破り、東欧の大国となりました。16世紀には、天文学者【コペルニクス】がこの王国で地動説を唱えています。", "一方、ハンガリーはバルカン半島から北上する【オスマン帝国】と直接向き合うことになりました。1526年、ハンガリー軍は【スレイマン1世】に【モハーチの戦い】で大敗し、国王も戦死しました。その結果、ハンガリーの大部分はオスマン帝国の支配下に入り、残りの地域の王位はハプスブルク家が受け継ぎました。ベーメン王位もハプスブルク家に移り、東欧の中央部は【ハプスブルク家】の支配する地域となっていきます。"]}, {"t": "近世 ― 選挙王政とポーランド分割", "p": ["1572年にヤゲウォ朝が断絶すると、ポーランドでは貴族(シュラフタ)が国王を選挙で選ぶ【選挙王政】がとられました。貴族の議会の力が非常に強く、国王の権限は弱いものでした。外国の王族が国王に選ばれることも多く、周辺の大国が王位選挙に介入する原因になりました。西ヨーロッパの国々が絶対王政のもとで中央集権化を進めていた時代に、ポーランドは逆に王権が弱く、まとまりを欠いた国になっていったのです。", "ベーメンでは、1618年に新教徒の貴族がハプスブルク家のカトリック強制に反発して反乱を起こし、これが【三十年戦争】のきっかけになりました。反乱は鎮圧され、ベーメンではカトリック化とドイツ化が進められました。また、1683年の【第2次ウィーン包囲】が失敗したのち、1699年の【カルロヴィッツ条約】でハンガリーの大部分がオスマン帝国からオーストリアに渡されました。", "18世紀後半になると、強大化したロシア・プロイセン・オーストリアは、弱体なポーランドの領土を少しずつ奪い取りました。これが【ポーランド分割】です。1772年の第1回分割はロシアの【エカチェリーナ2世】、プロイセンの【フリードリヒ2世】、オーストリアの【ヨーゼフ2世】(母マリア=テレジアとの共同統治)のもとで行われました。ポーランドでは改革の動きが起こり憲法も制定されましたが、1793年に第2回分割(ロシアとプロイセン)が行われました。", "これに対し、アメリカ独立戦争にも義勇兵として参加した【コシューシコ】が1794年に抵抗運動を指導しましたが、鎮圧されました。そして1795年の第3回分割で、ポーランドは地図の上から完全に消滅しました。周辺の絶対君主たちの勢力均衡のもとで、一つの国が丸ごと分け取られたのです。"]}, {"t": "19世紀 ― 民族運動の高まり", "p": ["ナポレオンはプロイセンを破ったのち、1807年の【ティルジット条約】で旧ポーランド領の一部に【ワルシャワ大公国】を建てました。しかしナポレオンの没落後、【ウィーン会議】でこの地域の大部分は【ポーランド王国】とされ、ロシア皇帝がその王を兼ねることになりました。", "ポーランドの人々は独立を求めて何度も立ち上がりました。1830年、フランスの【七月革命】の影響を受けて【ワルシャワ】で蜂起が起こりましたが、ロシア軍に鎮圧されました。このとき国外にいた作曲家【ショパン】は祖国の悲劇を知り、その思いが作品にこめられたといわれます。1863年にも【1月蜂起】が起こりましたが、やはり鎮圧され、ロシアはロシア語の強制など支配を強めました。", "1848年の【諸国民の春】では、ハンガリーで【コシュート】がオーストリアからの独立を求めて立ち上がりましたが、ロシア軍の援助を受けたオーストリアに鎮圧されました。ベーメンでもチェック人の民族運動が高まり、プラハでスラヴ民族会議が開かれました。", "その後、プロイセン=オーストリア戦争に敗れたオーストリアは、国内の最大の非ドイツ系民族であるマジャール人と妥協し、1867年に【オーストリア=ハンガリー帝国(二重帝国)】をつくりました。ハンガリーは自分の政府と議会をもつことになりましたが、チェック人など他のスラヴ系民族の不満は残りました。このころ、ベーメン出身の【スメタナ】や【ドヴォルザーク】は民族色豊かな音楽を作り、民族意識の高まりを文化の面で表しました。"]}, {"t": "20世紀前半 ― 独立と二つの世界大戦", "p": ["第一次世界大戦でドイツ・オーストリア・ロシアの3帝国が崩壊すると、東欧に新しい国々が生まれました。アメリカ大統領ウィルソンの【十四か条】が民族自決を掲げたこともあり、1918年に【ポーランド】が独立を回復し、【チェコスロヴァキア】と【ハンガリー】も独立しました。ポーランドは【ピウスツキ】の指導のもとで、ソヴィエト=ロシアとも戦って東方に領土を広げました。ハンガリーは1920年の【トリアノン条約】で領土を大きく失いました。", "しかし、新しい国々の多くは国内に少数民族を抱え、経済も不安定でした。チェコスロヴァキアの【ズデーテン地方】にはドイツ系住民が多く住んでおり、ヒトラーはその割譲を要求しました。1938年の【ミュンヘン会談】で、イギリス・フランスは宥和政策をとってこれを認め、翌1939年にはドイツがチェコスロヴァキアを解体しました。", "1939年8月にドイツとソ連が【独ソ不可侵条約】を結ぶと、同年9月にドイツはポーランドに侵攻し、イギリス・フランスがドイツに宣戦して【第二次世界大戦】が始まりました。ソ連も東からポーランドに侵入し、ポーランドは秘密議定書にもとづいて再び独ソに分割されました。ナチス=ドイツは占領地に【アウシュヴィッツ】などの強制収容所をつくり、ユダヤ人などを大量に殺害しました(ホロコースト)。", "大戦末期、東欧の大部分はソ連軍によって解放されました。戦後、ポーランドの国境は西へ大きく移され、東部の領土をソ連に譲るかわりに、ドイツとの国境はオーデル=ナイセ線とされました。"]}, {"t": "冷戦期の東欧と東欧革命", "p": ["戦後の東欧諸国では、ソ連の後押しを受けた共産党が権力を握り、【人民民主主義】の名のもとで社会主義体制がつくられました。1948年にはチェコスロヴァキアで共産党が政権を独占し(チェコスロヴァキア=クーデタ)、西側に衝撃を与えました。東欧諸国は【コメコン(経済相互援助会議)】や【ワルシャワ条約機構】を通じてソ連の強い統制を受けました。", "1956年にソ連の【フルシチョフ】が【スターリン批判】を行うと、東欧では自由を求める動きが起こりました。ポーランドでは【ポズナニ暴動】が起こり、ゴムウカが指導者となって事態を収拾しました。ハンガリーでは【ナジ=イムレ】の政府がワルシャワ条約機構からの脱退を表明しましたが、ソ連軍が介入して鎮圧しました(【ハンガリー事件】)。1968年にはチェコスロヴァキアで【ドプチェク】が改革を進め「人間の顔をした社会主義」をめざしましたが(【プラハの春】)、ソ連などワルシャワ条約機構軍が軍事介入してこれを押しつぶしました。", "1980年、ポーランドでは【ワレサ】を指導者とする自主管理労組【連帯】が結成され、共産党の一党支配に挑みました。1985年にソ連で【ゴルバチョフ】が改革を始め、東欧への干渉をやめる姿勢を示すと、1989年に東欧諸国の体制は次々に崩れました(【東欧革命】)。ポーランドでは自由選挙で連帯が圧勝し、ハンガリーはオーストリアとの国境を開放しました。この動きは【ベルリンの壁】の崩壊につながり、チェコスロヴァキアでも【ビロード革命】で【ハヴェル】が大統領となりました。ルーマニアではチャウシェスク政権が倒され、指導者は処刑されました。", "その後、チェコスロヴァキアは1993年に【チェコ】と【スロヴァキア】に平和的に分離しました。ポーランド・チェコ・ハンガリーは1999年にNATOに加盟し、2004年には東欧の多くの国々とともに【EU】に加盟しました。大国にはさまれ何度も国を失ってきたポーランドの歴史は、現在の東欧の国々がロシアに対して強い警戒心をもつ背景にもなっています。"]}], "points": ["西スラヴ人(ポーランド・チェック)とマジャール人(ハンガリー)はカトリック、東スラヴ人・セルビア人はギリシア正教", "レヒフェルトの戦い(955年)とハンガリー王国の成立", "カール4世:プラハ大学(1348年)・金印勅書(1356年)、フスの処刑(1415年)とフス戦争", "ヤゲウォ朝(1386年)とタンネンベルクの戦い(1410年)、モハーチの戦い(1526年)", "ポーランド分割:1772年(露・普・墺)、1793年(露・普)、1795年(露・普・墺)とコシューシコ", "ワルシャワ大公国(1807年)→ウィーン会議でロシア皇帝が王を兼ねるポーランド王国", "ミュンヘン会談(1938年)・独ソ不可侵条約・ポーランド侵攻(1939年)", "ポズナニ暴動・ハンガリー事件(1956年)、プラハの春(1968年)、連帯(1980年)、東欧革命(1989年)"], "check": [["955年にマジャール人がオットー1世に敗れた戦いは何か", "レヒフェルトの戦い"], ["1241年にモンゴル軍がドイツ・ポーランド軍を破った戦いは何か", "ワールシュタットの戦い"], ["コンスタンツ公会議で異端とされ処刑されたベーメンの神学者は誰か", "フス"], ["1386年に成立したリトアニア=ポーランド王国の王朝は何か", "ヤゲウォ朝(ヤゲロー朝)"], ["ポーランド分割に抵抗した指導者は誰か", "コシューシコ"], ["1807年にナポレオンが旧ポーランド領に建てた国は何か", "ワルシャワ大公国"], ["1848年にハンガリーの独立運動を指導したのは誰か", "コシュート"], ["1938年にズデーテン地方のドイツ割譲を認めた会談は何か", "ミュンヘン会談"], ["1968年のチェコスロヴァキアの民主化運動は何とよばれるか", "プラハの春"], ["1980年にポーランドで結成された自主管理労組は何か", "連帯"]], "related": ["y_10", "y_13", "y_14", "y_15", "y_16", "y_18", "y_19", "y_20a", "y_20b", "t_de", "t_ru", "t_nord", "t_bal", "t_tr", "t_mn"], "n": 4283, "videos": [{"title": "【世界史】 冷戦の終結３ ソ連崩壊と東欧の民主化 （１８分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=zqqgpO3Gx0o", "note": "ソ連崩壊と東欧の民主化を学べ、ポーランドなど東欧史の現代部分を補えます。"}]}, "t_bal": {"title": "バルカン半島史", "span": "6世紀〜現在", "year": 1878, "lead": "バルカン半島は、南スラヴ人・ギリシア人・アルバニア人など多くの民族と、正教・カトリック・イスラームの宗教が入りまじる地域です。ビザンツ帝国とオスマン帝国に長く支配されたのち、19世紀に民族ごとの独立が進みましたが、列強の介入によって「ヨーロッパの火薬庫」となりました。20世紀末にもユーゴスラヴィアの解体にともなう内戦が起こっています。", "flow": ["6〜7世紀 南スラヴ人がバルカン半島へ移動、7世紀にブルガリア帝国が成立", "9世紀 ビザンツ帝国の布教でブルガリア・セルビアがギリシア正教を受容、キリル文字が広まる", "1389年 コソヴォの戦いでオスマン帝国がセルビアなどを破る→1396年ニコポリスの戦い", "1453年 コンスタンティノープル陥落→バルカン全域がオスマン帝国の支配下に(ミッレト制・デヴシルメ)", "1821年 ギリシア独立戦争→1830年ロンドン会議で独立承認", "1853〜56年 クリミア戦争", "1877〜78年 ロシア=トルコ戦争→サン=ステファノ条約→ベルリン会議でセルビア・モンテネグロ・ルーマニア独立", "1908年 オーストリアがボスニア・ヘルツェゴヴィナを併合、ブルガリア独立", "1912〜13年 第1次・第2次バルカン戦争→1914年サライェヴォ事件で第一次世界大戦", "1918年 セルブ=クロアート=スロヴェーン王国(のちユーゴスラヴィア)成立", "1948年 ユーゴスラヴィアがコミンフォルムから除名→独自の社会主義と非同盟外交", "1991年〜 ユーゴスラヴィア解体と内戦→1995年デイトン合意、1999年NATOのコソヴォ空爆"], "sync": [], "secs": [{"t": "南スラヴ人の移動とビザンツ世界", "p": ["バルカン半島は、古代には【ギリシア】の都市国家が栄え、のちに【ローマ帝国】の領土となりました。ローマ帝国が東西に分かれると、バルカン半島は東ローマ帝国、すなわち【ビザンツ帝国】の中心地域となりました。", "6世紀から7世紀にかけて、北方から【スラヴ人】がバルカン半島に移り住みました。彼らは【南スラヴ人】とよばれ、のちの【セルビア人】【クロアティア人】【スロヴェニア人】などになります。また、7世紀にはトルコ系の【ブルガール人】が進出して【ブルガリア帝国(第1次ブルガリア帝国)】を建てましたが、彼らはやがて多数派のスラヴ人に同化していきました。", "ビザンツ帝国は、これらの人々にキリスト教を広めて自国の文化圏に取り込もうとしました。9世紀には、ギリシア人の宣教師【キュリロス】とメトディオスの兄弟がスラヴ人への布教のための文字を考案し、それをもとにつくられた【キリル文字】がブルガリアやセルビア、のちのロシアに広まりました。ブルガリアとセルビアは【ギリシア正教】を受け入れ、ビザンツ文化の影響を強く受けました。これに対し、西側のクロアティア人とスロヴェニア人はローマ=カトリックを受け入れ、ラテン文字を使いました。同じ南スラヴ人の中にも、宗教と文字の境界線が引かれたのです。", "ブルガリアはビザンツ帝国と激しく争い、11世紀初めには皇帝【バシレイオス2世】によって征服されましたが、12世紀末に再び独立しました。セルビアは14世紀に【ステファン=ドゥシャン】のもとで最盛期を迎え、バルカン半島の大国となりました。しかし、その直後に東から新たな勢力が迫ってきます。"]}, {"t": "オスマン帝国の支配", "p": ["14世紀、小アジアに興った【オスマン帝国】はバルカン半島に渡り、【アドリアノープル(エディルネ)】を都としてヨーロッパへの進出を本格化させました。1389年の【コソヴォの戦い】で、オスマン軍はセルビアを中心とするバルカン諸国の連合軍を破りました。この敗北はセルビア人の民族的な記憶として長く語り継がれ、コソヴォはセルビア人にとって特別な土地とされています。", "1396年にはハンガリー王を中心とする西欧の十字軍が【ニコポリスの戦い】で【バヤジット1世】に大敗し、1453年には【メフメト2世】がコンスタンティノープルを攻略してビザンツ帝国を滅ぼしました。こうしてバルカン半島のほぼ全域が、15世紀のうちにオスマン帝国の支配下に入りました。", "オスマン帝国は、異教徒に対して比較的寛容な支配を行いました。キリスト教徒やユダヤ教徒は、宗教ごとの共同体である【ミッレト】をつくり、税を納めれば信仰や生活習慣を守ることが認められました。その一方で、キリスト教徒の少年を集めてイスラームに改宗させ、官僚や常備歩兵軍団【イェニチェリ】として育てる【デヴシルメ】という制度も行われました。", "長いオスマン支配のあいだに、【ボスニア】や【アルバニア】では多くの住民がイスラームに改宗しました。そのため、バルカン半島には正教徒・カトリック教徒・ムスリムが混住するようになりました。この複雑な宗教と民族の分布が、のちの時代に大きな問題を引き起こすことになります。"]}, {"t": "19世紀 ― 民族の独立と東方問題", "p": ["18世紀以降、オスマン帝国が弱体化すると、フランス革命が広めたナショナリズムの影響もあって、バルカンの諸民族は独立を求めるようになりました。セルビアでは19世紀初めに反乱が起こり、自治を獲得しました。1821年には【ギリシア独立戦争】が始まり、イギリスの詩人【バイロン】も義勇兵として参加しました。ギリシアは古代文明の故郷として西欧の人々の共感を集め、イギリス・フランス・ロシアが介入して1827年の【ナヴァリノの海戦】でオスマン・エジプト艦隊を破りました。1830年の【ロンドン会議】で、ギリシアの独立が国際的に承認されました。", "オスマン帝国の弱体化にともなって生じた国際問題を【東方問題】といいます。その中心にあったのは、黒海から地中海へ出るルートを求めて【南下政策】をとるロシアと、それを阻もうとするイギリス・オーストリアの対立でした。ロシアは同じスラヴ系・正教徒のバルカンの民族を支援し、【パン=スラヴ主義】を唱えて影響力を広げようとしました。1853年に始まる【クリミア戦争】では、ロシアはオスマン帝国を支援するイギリス・フランスに敗れ、南下は一時阻止されました。", "1875年、ボスニア・ヘルツェゴヴィナで農民反乱が起こり、ブルガリアでも反乱が鎮圧されると、ロシアはスラヴ人の保護を口実に1877年【ロシア=トルコ(露土)戦争】を起こし、勝利しました。翌年の【サン=ステファノ条約】で、ロシアの影響下にある大ブルガリアの成立が決まりましたが、ロシアの進出を恐れたイギリスとオーストリアが強く反対しました。", "そこでドイツの【ビスマルク】が「誠実な仲買人」として1878年に【ベルリン会議】を開きました。その結果、【セルビア・モンテネグロ・ルーマニア】の独立が承認された一方、ブルガリアは領土を縮小されてオスマン帝国内の自治国とされました。【オーストリア】はボスニア・ヘルツェゴヴィナの行政権を得て、【イギリス】はキプロス島を手に入れました。ロシアの南下はふたたび阻まれ、ロシアはこの後、関心をアジアへ向けていきます。"]}, {"t": "ヨーロッパの火薬庫", "p": ["20世紀初め、バルカン半島では、ロシアを後ろ盾とする【パン=スラヴ主義】と、ドイツ・オーストリアの【パン=ゲルマン主義】が激しく対立しました。1908年、オスマン帝国で【青年トルコ革命】が起こると、その混乱に乗じて【オーストリア】はボスニア・ヘルツェゴヴィナを正式に併合し、【ブルガリア】は完全独立を宣言しました。ボスニアには多くのセルビア人が住んでいたため、セルビアはオーストリアに強い敵意を抱きました。", "1912年、ロシアの支援のもとで、セルビア・ブルガリア・モンテネグロ・ギリシアが【バルカン同盟】を結び、オスマン帝国と戦って勝利しました(【第1次バルカン戦争】)。ところが、獲得した領土の分配をめぐって同盟国どうしが対立し、1913年にはブルガリアが他の国々と戦って敗れました(【第2次バルカン戦争】)。敗れたブルガリアはドイツ・オーストリア側に近づき、バルカンの対立は列強どうしの対立と結びついていきました。こうしてバルカン半島は【「ヨーロッパの火薬庫」】とよばれるようになります。", "1914年6月、ボスニアの州都【サライェヴォ】で、オーストリアの帝位継承者夫妻がセルビア人の青年に暗殺されました(【サライェヴォ事件】)。オーストリアがセルビアに宣戦すると、ロシア・ドイツ・フランス・イギリスが次々と参戦し、【第一次世界大戦】に発展しました。", "大戦後、1918年に南スラヴ人の統一国家として【セルブ=クロアート=スロヴェーン王国】が成立し、1929年に【ユーゴスラヴィア】(「南スラヴ人の国」の意味)と改称しました。しかし、国の実権はセルビア人が握ったため、クロアティア人などとの対立が続きました。敗戦国ブルガリアは1919年の【ヌイイ条約】で領土を失いました。また、ギリシアはトルコとの戦争に敗れ、1923年の【ローザンヌ条約】ののち、両国の間で大規模な住民交換が行われました。"]}, {"t": "第二次世界大戦と冷戦", "p": ["第二次世界大戦では、ユーゴスラヴィアとギリシアは1941年にドイツなどの枢軸国に占領されました。ユーゴスラヴィアでは、共産党の【ティトー】が率いるパルチザンが抵抗運動を展開し、ほぼ自力で国土を解放しました。この経験が、戦後のユーゴスラヴィアがソ連から自立する土台になりました。", "戦後、ユーゴスラヴィアは社会主義国となりましたが、ソ連の指導に従わなかったため、1948年に【コミンフォルム】から除名されました。その後ティトーは、労働者の自主管理にもとづく独自の社会主義を進め、外交では東西どちらの陣営にも属さない【非同盟】の立場をとりました。1961年には首都ベオグラードで【第1回非同盟諸国首脳会議】が開かれています。", "一方、ブルガリアとルーマニアはソ連の影響下で社会主義国となり、アルバニアも独自の閉鎖的な社会主義を進めました。ギリシアでは共産勢力と政府軍の内戦が起こり、アメリカは1947年の【トルーマン=ドクトリン】でギリシアとトルコへの援助を表明し、共産主義の拡大を防ごうとしました。これは【封じ込め政策】の始まりとされます。ギリシアとトルコはその後NATOに加盟し、ギリシアは1981年にECに加盟しました。"]}, {"t": "ユーゴスラヴィアの解体と現代", "p": ["1980年にティトーが死去し、さらに1989年の東欧革命で社会主義体制が揺らぐと、ユーゴスラヴィアをまとめていた力は弱まりました。各共和国では民族主義が高まり、1991年に【スロヴェニア】と【クロアティア】が独立を宣言しました。これをきっかけに【ユーゴスラヴィア内戦】が始まりました。", "とくに激しかったのが、セルビア人・クロアティア人・ムスリム(ボシュニャク人)が混住する【ボスニア・ヘルツェゴヴィナ】の内戦(1992〜95年)でした。ここでは、特定の民族を追い出したり殺害したりする【民族浄化】が行われ、多くの犠牲者と難民が出ました。NATOの空爆などを経て、1995年の【デイトン合意】で停戦が成立しました。", "さらに、セルビア内のアルバニア系住民が多数を占める【コソヴォ】で独立を求める紛争が起こると、1999年に【NATO】が国連安保理の決議なしにセルビア(ユーゴスラヴィア連邦)を空爆しました。コソヴォは2008年に独立を宣言しましたが、セルビアやロシアはこれを認めていません。", "21世紀に入ると、スロヴェニアが2004年、ブルガリアとルーマニアが2007年、クロアティアが2013年にEUに加盟しました。かつて大帝国の支配と列強の介入に翻弄されたバルカン半島は、ヨーロッパ統合の中で安定の道を探っています。宗教や言語が入りまじる地域で、一つの民族が一つの国家をつくろうとする考え方がどのような困難を生むのか、バルカン半島の歴史はそれをよく示しています。"]}], "points": ["南スラヴ人の宗教の違い:セルビア人(正教・キリル文字)とクロアティア人・スロヴェニア人(カトリック・ラテン文字)", "コソヴォの戦い(1389年)、ニコポリスの戦い(1396年)、コンスタンティノープル陥落(1453年)", "オスマン支配のミッレト制とデヴシルメ、ボスニア・アルバニアのイスラーム化", "ギリシア独立戦争(1821年〜):バイロン、ナヴァリノの海戦、ロンドン会議(1830年)", "露土戦争(1877年)→サン=ステファノ条約→ベルリン会議(1878年)の決定内容", "1908年のボスニア・ヘルツェゴヴィナ併合、バルカン戦争、サライェヴォ事件(1914年)", "ティトーとコミンフォルム除名(1948年)、非同盟諸国首脳会議(1961年、ベオグラード)", "ユーゴスラヴィア内戦:ボスニア内戦とデイトン合意(1995年)、コソヴォ紛争とNATO空爆(1999年)"], "check": [["ビザンツ帝国の布教によって南スラヴ人やロシアに広まった文字は何か", "キリル文字"], ["1389年にオスマン帝国がセルビアなどを破った戦いは何か", "コソヴォの戦い"], ["キリスト教徒の少年を徴集してイェニチェリなどに育てた制度は何か", "デヴシルメ"], ["ギリシア独立戦争に参加したイギリスの詩人は誰か", "バイロン"], ["露土戦争後の1878年に大ブルガリアの成立を定めた条約は何か", "サン=ステファノ条約"], ["ベルリン会議で独立が認められた3国はどこか", "セルビア・モンテネグロ・ルーマニア"], ["1908年にオーストリアが併合した地域はどこか", "ボスニア・ヘルツェゴヴィナ"], ["1912年にセルビア・ブルガリア・モンテネグロ・ギリシアが結んだ同盟は何か", "バルカン同盟"], ["パルチザンを率いて戦後ユーゴスラヴィアの指導者となったのは誰か", "ティトー"], ["1995年にボスニア内戦を停戦させた合意は何か", "デイトン合意"]], "related": ["y_6", "y_9", "y_14", "y_15", "y_19", "y_20a", "y_20b", "y_21", "t_gr", "t_byz", "t_tr", "t_ru", "t_pl", "t_de"], "n": 4076}, "t_ru": {"title": "ロシア史", "span": "9世紀〜現在", "year": 1917, "lead": "ロシアは9世紀にノルマン人が建てた国家に始まり、ビザンツ帝国からギリシア正教を受け入れ、モンゴルの支配を経てモスクワ大公国のもとで統一されました。ロマノフ朝のもとでシベリアからバルト海・黒海まで広がる大帝国となり、1917年の革命で世界初の社会主義国家ソ連が誕生しました。ソ連はアメリカと冷戦を戦った超大国でしたが、1991年に解体し、現在のロシア連邦となりました。", "flow": ["862年 リューリクがノヴゴロド国を建てる→キエフ公国へ、10世紀末ウラディミル1世がギリシア正教を受容", "1240年 バトゥがキエフを攻略→キプチャク=ハン国の支配(タタールのくびき)", "1480年 イヴァン3世がモンゴルから自立→イヴァン4世(雷帝)がツァーリとして専制", "1613年 ミハイル=ロマノフが即位しロマノフ朝", "1689年 ネルチンスク条約、1700〜21年北方戦争でピョートル1世がバルト海へ進出", "1762年〜 エカチェリーナ2世の啓蒙専制→プガチョフの乱、ポーランド分割、クリミア併合", "1812年 ナポレオンのロシア遠征失敗→1825年デカブリストの乱", "1853〜56年 クリミア戦争に敗北→1861年農奴解放令", "1877年 露土戦争→ベルリン会議で南下阻止→東アジアへ進出し1904〜05年日露戦争、第1次ロシア革命", "1917年 二月革命・十月革命→1922年ソヴィエト社会主義共和国連邦成立", "1928年〜 スターリンの五か年計画→1941年独ソ戦、1945年戦勝国に", "1985年 ゴルバチョフのペレストロイカ→1991年ソ連解体、CIS成立"], "sync": [], "secs": [{"t": "ロシアのはじまり ― ノヴゴロドとキエフ", "p": ["東ヨーロッパの森林と草原には、古くから【東スラヴ人】が住んでいました。9世紀、スウェーデン系の【ノルマン人】(ルーシとよばれた)が川を伝ってこの地に進出し、862年に首長【リューリク】が【ノヴゴロド国】を建てたとされます。その後、一族はドニエプル川中流に南下して【キエフ公国】をつくりました。支配者のノルマン人はやがてスラヴ人に同化し、ルーシの名がロシアの語源となりました。", "キエフ公国は、バルト海と黒海を結ぶ川の交易路をおさえ、ビザンツ帝国との交易で栄えました。10世紀末、大公【ウラディミル1世】はビザンツ皇帝の妹と結婚し、【ギリシア正教】を国の宗教として受け入れました。これにより、キリル文字や教会建築、皇帝が教会を支配する考え方など、ビザンツ文化がロシアに深く根づきました。ロシアが西ヨーロッパのカトリック世界とは異なる文化の道を歩むことになった、大きな出発点です。", "しかし、キエフ公国は12世紀ごろから諸公の分裂で衰え、13世紀には東方から来た【モンゴル】の大軍にのみこまれることになります。"]}, {"t": "モンゴル支配とモスクワ大公国", "p": ["1236年に始まる【バトゥ】の西征で、1240年にキエフは陥落し、ロシアの諸公国はモンゴルの支配下に入りました。バトゥは南ロシアの草原に【キプチャク=ハン国】を建て、ロシアの諸公に貢納を義務づけて間接的に支配しました。このおよそ240年にわたる支配は、ロシアでは【タタールのくびき】とよばれます。同じころ、ノヴゴロドの公【アレクサンドル=ネフスキー】は西から攻めてきたスウェーデンやドイツ騎士団を撃退し、ロシアの英雄とされました。", "モンゴル支配の時代に力をのばしたのが【モスクワ大公国】です。モスクワの大公はハンに代わって諸公から貢納を取り立てる役目を果たしながら、しだいに周辺を併合していきました。15世紀、大公【イヴァン3世】はノヴゴロドなどを併合して北東ロシアを統一し、1480年にはキプチャク=ハン国の支配から完全に自立しました。彼はビザンツ帝国最後の皇帝の姪と結婚し、ビザンツ皇帝の後継者として【ツァーリ】(皇帝)の称号を用いはじめました。1453年にビザンツ帝国が滅びたあと、モスクワは「第3のローマ」として正教世界の中心を自任するようになります。", "16世紀の【イヴァン4世】(雷帝)は、正式にツァーリとして戴冠し、大貴族をおさえて専制政治を強めました。また、カザン=ハン国などを征服してヴォルガ川流域に進出し、コサックの首領【イェルマーク】の遠征をきっかけにシベリアへの進出が始まりました。その一方で、農民が領主のもとを離れることを制限する政策がとられ、【農奴制】が強化されていきました。"]}, {"t": "ロマノフ朝とロシア帝国の拡大", "p": ["イヴァン4世の死後、ロシアは王朝の断絶と外国の干渉による混乱の時代を迎えましたが、1613年に全国会議で【ミハイル=ロマノフ】がツァーリに選ばれ、【ロマノフ朝】が始まりました。この王朝は1917年まで続きます。17世紀後半には農奴制の強化に反発して【ステンカ=ラージンの乱】が起こりましたが、鎮圧されました。", "17世紀末に即位した【ピョートル1世(大帝)】は、みずから使節団にまぎれて西欧を視察し、造船や軍事の技術を学んで、ロシアの【西欧化】を強力に進めました。東方では清の【康熙帝】と1689年に【ネルチンスク条約】を結んで国境を定めました。西方では、バルト海への出口を求めてスウェーデンの【カール12世】と【北方戦争】(1700〜21年)を戦い、勝利してバルト海の覇権を握りました。新しい首都【ペテルブルク】は「西欧への窓」として建設されたものです。1727年には清と【キャフタ条約】を結び、モンゴル方面の国境を定めました。", "18世紀後半の女帝【エカチェリーナ2世】は、ヴォルテールら啓蒙思想家と交流し、【啓蒙専制君主】としてふるまいました。しかし、1773年から起こった農民反乱【プガチョフの乱】を鎮圧すると、むしろ貴族と結んで農奴制を強化しました。対外的には、オスマン帝国と戦って黒海に進出し、1783年に【クリミア半島】を併合しました。またプロイセン・オーストリアとともに3回の【ポーランド分割】に加わりました。東方では、1792年に【ラクスマン】を根室に派遣し、日本に通商を求めています。"]}, {"t": "19世紀 ― 南下政策と改革の挫折", "p": ["ナポレオンの時代、ロシアは一時1807年の【ティルジット条約】でフランスと和解しましたが、大陸封鎖令に従わずイギリスとの穀物貿易を続けたため、1812年にナポレオンの【ロシア遠征】を受けました。ロシア軍はモスクワを焼き払って退き、冬の到来とともにフランス軍は壊滅しました。これがナポレオン没落のきっかけとなります。【ウィーン会議】後、皇帝【アレクサンドル1世】は【神聖同盟】を提唱し、ロシアは「ヨーロッパの憲兵」として各地の自由主義運動を抑える役割を果たしました。", "しかし、西欧の自由主義思想に触れた青年将校たちは、1825年に憲法の制定と農奴制の廃止を求めて【デカブリストの乱】を起こしました。新皇帝【ニコライ1世】はこれを鎮圧し、1830年のポーランドの蜂起や1848年のハンガリーの独立運動も武力で抑えました。", "ロシアは黒海から地中海へ出る道を求めて【南下政策】をとり、オスマン帝国に圧力をかけました。1853年に始まった【クリミア戦争】では、オスマン帝国を支援するイギリス・フランスと戦い、【セヴァストーポリ】要塞の攻防戦の末に敗れました。1856年の【パリ条約】で黒海の中立化が定められ、南下は阻まれました。", "この敗北は、ロシアの後進性を誰の目にも明らかにしました。皇帝【アレクサンドル2世】は改革にのりだし、1861年に【農奴解放令】を出しました。農民は人格的な自由を得ましたが、土地を得るには高い買い戻し金が必要で、多くは【ミール】(農村共同体)に縛られたままでした。1860年代には知識人の【ナロードニキ】が「ヴ=ナロード(人民の中へ)」を唱えて農民の啓蒙を試みましたが、農民の理解は得られず、一部はテロリズムに走り、1881年に皇帝は暗殺されました。", "南下政策はその後も続きました。1877年の【ロシア=トルコ(露土)戦争】に勝利して【サン=ステファノ条約】を結びましたが、1878年の【ベルリン会議】で成果の多くを失いました。そこでロシアは中央アジアと東アジアへの進出を強めます。清とは1858年の【アイグン条約】、1860年の【北京条約】で黒竜江以北と【沿海州】を獲得し、【ウラジヴォストーク】を建設しました。1867年にはアラスカをアメリカに売却しています。1891年にはフランス資本の導入によって【シベリア鉄道】の建設が始まり、同じころ【露仏同盟】が成立しました。"]}, {"t": "日露戦争とロシア革命", "p": ["ロシアは日清戦争後の【三国干渉】で日本に遼東半島を返還させ、その後中国東北地方(満洲)への進出を強めたため、日本との対立が深まりました。1904年に始まった【日露戦争】で苦戦が続くなか、1905年1月、首都ペテルブルクで請願に向かった民衆に軍隊が発砲する【血の日曜日事件】が起こり、【第1次ロシア革命】が始まりました。皇帝【ニコライ2世】は【十月宣言】を出して国会(【ドゥーマ】)の開設を約束し、首相の【ストルイピン】はミールを解体して自作農を育てる改革を進めましたが、専制の本質は変わりませんでした。日露戦争後、ロシアは1907年に【英露協商】を結び、【三国協商】の一角を占めました。", "第一次世界大戦では、ロシアは1914年の【タンネンベルクの戦い】でドイツ軍に大敗するなど苦戦を重ね、国内では食料や燃料が不足しました。1917年3月(ロシア暦2月)、首都で労働者と兵士が蜂起して【ソヴィエト】(評議会)がつくられ、ニコライ2世は退位してロマノフ朝は滅びました(【二月革命(三月革命)】)。その後成立した臨時政府は戦争を続けたため、民衆の不満はおさまりませんでした。", "亡命先から帰国した【ボリシェヴィキ】の指導者【レーニン】は、【四月テーゼ】で「すべての権力をソヴィエトへ」と訴えました。1917年11月(ロシア暦10月)、レーニンと【トロツキー】の率いるボリシェヴィキは武装蜂起して【ケレンスキー】の臨時政府を倒しました(【十月革命(十一月革命)】)。新政府は【平和に関する布告】で無併合・無償金・民族自決による即時講和を呼びかけ、【土地に関する布告】で地主の土地を没収しました。1918年には【ブレスト=リトフスク条約】でドイツと単独講和を結びました。", "革命に対し、国内では反革命勢力との内戦が起こり、イギリス・フランス・アメリカ・日本などは【対ソ干渉戦争】を行いました(日本などの【シベリア出兵】)。ソヴィエト政権は穀物の強制徴発などの【戦時共産主義】で乗り切り、1919年には世界革命をめざす【コミンテルン】を結成しました。内戦後、疲弊した経済を立て直すために1921年に【新経済政策(ネップ)】を採用して一部で私的な営業を認め、1922年に【ソヴィエト社会主義共和国連邦(ソ連)】が成立しました。"]}, {"t": "スターリン体制と第二次世界大戦", "p": ["1924年にレーニンが死去すると、世界革命を重視するトロツキーと、ソ連一国で社会主義を建設できるとする【スターリン】が対立し、スターリンが勝利しました。スターリンは1928年から【第1次五か年計画】を始め、重工業の建設と【農業の集団化】(【コルホーズ】・【ソフホーズ】)を強行しました。世界恐慌の影響を受けずに工業生産をのばした一方、集団化への抵抗や飢饉で多くの農民が犠牲になりました。さらに1930年代後半には、反対派とみなした人々を大量に処刑・追放する【大粛清】が行われ、個人崇拝にもとづく独裁体制が築かれました。", "ナチス=ドイツが台頭すると、ソ連は1934年に国際連盟に加盟しましたが、1938年の【ミュンヘン会談】でイギリス・フランスがドイツに譲歩すると両国への不信を深め、1939年に【独ソ不可侵条約】を結んで世界を驚かせました。ソ連はポーランド東部を占領し、【フィンランド】に侵攻して国際連盟から除名され、1940年にはバルト3国を併合しました。1941年4月には日本と【日ソ中立条約】を結んでいます。", "1941年6月、ドイツが条約を破ってソ連に侵攻し、【独ソ戦】が始まりました。ソ連は大きな犠牲を出しながらも、1942〜43年の【スターリングラードの戦い】でドイツ軍に勝利し、反撃に転じました。1945年2月の【ヤルタ会談】では、ドイツ降伏後の対日参戦と、その見返りとして南樺太・千島列島をソ連が得ることなどが秘密協定で約束されました。ソ連は1945年8月に日ソ中立条約を破って対日参戦しました。"]}, {"t": "冷戦の超大国からソ連解体へ", "p": ["戦後、ソ連は東欧諸国を勢力下に置き、アメリカとの【冷戦】が始まりました。1947年に【コミンフォルム】、1949年に【コメコン(経済相互援助会議)】をつくり、1948年には【ベルリン封鎖】を行いました。1949年に原子爆弾を開発し、1955年には【ワルシャワ条約機構】を結成して、アメリカ中心のNATOと対抗しました。", "1953年にスターリンが死去すると、【フルシチョフ】は1956年に【スターリン批判】を行い、西側との【平和共存】を唱えました。しかし同年の【ハンガリー事件】は武力で鎮圧しています。1957年には人工衛星【スプートニク1号】の打ち上げに成功し、1961年には【ガガーリン】が人類初の有人宇宙飛行を果たしました。1962年の【キューバ危機】では核戦争の寸前まで至りましたが、ソ連がミサイルを撤去して回避されました。一方、スターリン批判をめぐって中国との関係は悪化し、【中ソ対立】が深まりました。", "【ブレジネフ】の時代には、1968年の【プラハの春】に軍事介入し、社会主義圏全体の利益のためには一国の主権は制限されるという【制限主権論(ブレジネフ=ドクトリン)】を唱えました。1970年代には米ソの緊張緩和(デタント)が進みましたが、1979年の【アフガニスタン侵攻】で再び関係は悪化しました。この間、計画経済は行き詰まり、国民の生活は停滞しました。", "1985年に書記長となった【ゴルバチョフ】は、【ペレストロイカ】(改革)と【グラスノスチ】(情報公開)を進め、外交では【新思考外交】を掲げました。1986年の【チェルノブイリ原子力発電所事故】は情報公開の必要性を強く意識させました。1987年には【中距離核戦力(INF)全廃条約】に調印し、アフガニスタンから撤退し、1989年の【マルタ会談】で冷戦の終結を宣言しました。しかし改革は経済の混乱と民族運動の高まりを招き、1991年8月の保守派のクーデタが失敗に終わると、ロシア共和国大統領【エリツィン】が実権を握りました。同年12月、ロシアなどが【独立国家共同体(CIS)】を結成し、ソ連は解体しました。", "ソ連解体後のロシア連邦では、市場経済への急激な移行で混乱が続きました。2000年に大統領となったプーチンは、資源の輸出による経済の回復を背景に強い国家をめざし、チェチェン紛争を力でおさえました。2014年にはウクライナの【クリミア半島】を一方的に併合し、2022年にはウクライナへの全面的な侵攻を始めました。ロシアの歴史は、広大な国土の安全をどう守るかという問題と、強い権力が社会を統制する伝統のなかで動いてきたともいえます。"]}, {"t": "ロシアの文化", "p": ["19世紀のロシアでは、西欧の思想を受け入れながら、社会の矛盾を見つめる文学が花開きました。【ツルゲーネフ】は『父と子』で新しい世代の知識人を描き、【ドストエフスキー】は『罪と罰』で人間の内面を深く追究しました。【トルストイ】は『戦争と平和』でナポレオン戦争期のロシア社会を描きました。劇作家の【チェーホフ】、音楽では【チャイコフスキー】が活躍しました。", "ソ連時代には【社会主義リアリズム】が求められ、表現の自由は制限されました。【ショーロホフ】は『静かなドン』を著しました。一方、【パステルナーク】は『ドクトル=ジバゴ』が国内で発表できず、1958年のノーベル文学賞を辞退させられ、【ソルジェニーツィン】は強制収容所の実態を描いたのちに国外に追放されました。文化の歴史もまた、政治体制と深く結びついていたのです。"]}], "points": ["ノヴゴロド国(862年、リューリク)→キエフ公国→ウラディミル1世のギリシア正教受容", "タタールのくびき(キプチャク=ハン国)と、イヴァン3世の自立(1480年)・ツァーリの称号", "ピョートル1世:ネルチンスク条約(1689年)、北方戦争、ペテルブルク建設", "エカチェリーナ2世:プガチョフの乱、クリミア併合(1783年)、ポーランド分割、ラクスマン来航", "南下政策の流れ:クリミア戦争(パリ条約)→露土戦争(サン=ステファノ条約→ベルリン会議)→東アジアへ", "アレクサンドル2世の農奴解放令(1861年)とナロードニキ", "ロシア革命:血の日曜日事件(1905年)→二月革命→四月テーゼ→十月革命→ブレスト=リトフスク条約→ネップ→ソ連成立(1922年)", "冷戦期の指導者:スターリン→フルシチョフ(スターリン批判)→ブレジネフ(プラハの春)→ゴルバチョフ(ペレストロイカ)→ソ連解体(1991年)"], "check": [["862年にノヴゴロド国を建てたとされるノルマン人の首長は誰か", "リューリク"], ["ギリシア正教を受け入れたキエフ大公は誰か", "ウラディミル1世"], ["モンゴルの支配に対するロシア側のよび名は何か", "タタールのくびき"], ["1480年にモンゴル支配から自立したモスクワ大公は誰か", "イヴァン3世"], ["1689年にピョートル1世が清と結んだ条約は何か", "ネルチンスク条約"], ["エカチェリーナ2世の時代に起こった大規模な農民反乱は何か", "プガチョフの乱"], ["1825年に青年将校が起こした反乱は何か", "デカブリストの乱"], ["クリミア戦争の敗北後に1861年に出された改革令は何か", "農奴解放令"], ["十月革命後に1921年に採用された経済政策は何か", "新経済政策(ネップ)"], ["1985年にソ連の書記長となりペレストロイカを進めたのは誰か", "ゴルバチョフ"]], "related": ["y_9", "y_10", "y_13", "y_15", "y_16", "y_17", "y_18", "y_19", "y_20a", "y_20b", "y_21", "t_nord", "t_byz", "t_mn", "t_pl", "t_bal", "t_tr", "t_cn", "t_us"], "n": 5790, "videos": [{"title": "【世界史】 東欧絶対王政３ ロシア （１９分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=ElDX4LJEdjU", "note": "絶対王政期のロシアを整理できます。"}]}, "t_ori": {"title": "古代オリエント史", "span": "前3500年ごろ〜前525年", "year": -1750, "lead": "西アジアのメソポタミアとエジプトでは、大河の治水と灌漑を背景に世界で最も早い文明が生まれました。メソポタミアでは多くの民族が興亡をくりかえし、エジプトではファラオのもとで長く安定した王国が続きました。前7世紀にアッシリアが初めてオリエントを統一し、その崩壊後の4王国分立を経て、アケメネス朝ペルシアが再び全オリエントをまとめました。", "flow": ["前3500年ごろ〜 シュメール人がウル・ウルクなどの都市国家を建設、楔形文字", "前24世紀ごろ アッカド人のサルゴン1世がメソポタミアを統一", "前18世紀ごろ バビロン第1王朝のハンムラビ王がメソポタミアを統一、ハンムラビ法典", "前3000年ごろ〜 エジプトで統一王国→古王国(ピラミッド)・中王国・新王国", "前16〜前13世紀ごろ ヒッタイトが鉄器を用いて強大化、エジプト新王国とカデシュで戦う", "前14世紀ごろ アメンホテプ4世の宗教改革(アテン信仰)", "前12世紀ごろ 「海の民」の侵入→ヒッタイト滅亡、アラム人・フェニキア人・ヘブライ人が活躍", "前722年 アッシリアがイスラエル王国を滅ぼす→前7世紀前半に全オリエント統一", "前612年 アッシリア滅亡→エジプト・リディア・新バビロニア・メディアの4王国分立", "前586年 新バビロニアがユダ王国を滅ぼす(バビロン捕囚)→前538年解放", "前525年 アケメネス朝がエジプトを征服し全オリエントを再統一"], "sync": [], "secs": [{"t": "オリエントの風土と文明の誕生", "p": ["「オリエント」とは、ローマから見て「日の昇る方向(東方)」を意味する言葉で、現在の西アジアとエジプトをさします。この地域は乾燥した気候ですが、ティグリス川・ユーフラテス川や【ナイル川】のような大河の流域では、川の水を利用した【灌漑農業】によって豊かな収穫を得ることができました。ペルシア湾からメソポタミアを経て地中海東岸に至る弓形の地域は、【肥沃な三日月地帯】とよばれ、早くから麦の栽培や家畜の飼育が始まった場所の一つとされます。", "大規模な灌漑や治水には多くの人々を組織して働かせる必要があり、そのために強い権力をもつ指導者が生まれました。また、収穫や貢ぎ物を記録するために文字が発明され、季節を知るために暦や天文学が発達しました。こうして、都市・国家・文字・金属器をもつ【文明】が成立したのです。", "メソポタミアは周囲が開けた平原で、四方から異民族が侵入しやすく、多くの民族と王朝が興亡をくりかえしました。これに対してエジプトは、砂漠と海に囲まれて外敵の侵入が少なかったため、同じような体制の王国が長く続きました。この地理的な違いが、二つの文明の性格の違いを生んだのです。"]}, {"t": "メソポタミア ― 都市国家から統一国家へ", "p": ["メソポタミアとは、ギリシア語で「川のあいだの土地」という意味で、ティグリス川・ユーフラテス川の流域をさします。前3500年ごろから、民族系統のはっきりしない【シュメール人】が、【ウル】や【ウルク】などの【都市国家】を建設しました。都市の中心には守護神をまつる聖塔【ジッグラト】が建てられ、王は神の代理として神権政治を行いました。シュメール人は粘土板に刻む【楔形文字】を発明し、【六十進法】や【太陰暦】を用いました。ウルクの王を主人公とする【『ギルガメシュ叙事詩』】には、のちの旧約聖書のノアの箱舟の話に似た洪水伝説が含まれています。", "都市国家どうしの争いが続くなか、前24世紀ごろ、セム語系の【アッカド人】の王【サルゴン1世】がシュメールの都市国家を征服し、メソポタミアを初めて統一しました。", "その後、セム語系の【アムル人】が【バビロン第1王朝(古バビロニア王国)】を建て、前18世紀ごろの【ハンムラビ王】のときに全メソポタミアを統一しました。ハンムラビ王は運河を整備し、【ハンムラビ法典】を発布して国を治めました。この法典は「目には目を、歯には歯を」という【同害復讐】の原則で知られますが、刑罰は被害者と加害者の身分によって異なっていました。この法典は、それまでのシュメールの法を受け継いでまとめたものとされます。", "前17世紀ごろになると、小アジア(アナトリア)にインド=ヨーロッパ語系の【ヒッタイト】が国を建て、都【ハットゥシャ(ボアズキョイ)】を中心に強大化しました。ヒッタイトは早くから【鉄器】を使い、馬の引く戦車を用いた強い軍事力でバビロン第1王朝を滅ぼしました。その後のメソポタミアは、【カッシート】や【ミタンニ】などが分立する時代となります。ヒッタイトはシリアをめぐってエジプト新王国とも争いました。", "メソポタミアの文明は、民族や王朝が入れかわっても、その成果が次の支配者に受け継がれていった点に特徴があります。シュメール人の楔形文字は、アッカド人やバビロニア人、さらにはヒッタイトやペルシア人にまで使われました。六十進法は、現在も時間の1時間=60分や、円の角度=360度などに名残をとどめています。また、天体の動きを観察する占星術や天文学も発達し、のちのギリシアの学問に影響を与えました。"]}, {"t": "エジプト ― ナイルの賜物", "p": ["ギリシアの歴史家【ヘロドトス】は、「エジプトはナイルの賜物」と述べました。ナイル川は毎年決まった時期に増水し、上流から肥えた土を運んできたため、エジプトでは豊かな農業が営まれました。増水の時期を正確に知るために【太陽暦】がつくられ、増水のあとの土地を測り直すために【測地術】が発達しました。", "前3000年ごろ、エジプトでは統一国家が成立し、王である【ファラオ】は太陽神ラーの子(神の化身)として絶対的な権力をふるいました。【古王国】の時代には、都【メンフィス】の近くに、クフ王などの巨大な【ピラミッド】が建てられました。【中王国】の時代には都が【テーベ】に移りましたが、末期にはシリア方面から【ヒクソス】とよばれる遊牧民が侵入し、一時エジプトを支配しました。", "ヒクソスを追い出して始まった【新王国】は、シリアに遠征して領土を広げ、エジプトの最盛期を築きました。前14世紀ごろの【アメンホテプ4世】は、テーベの守護神アモン(アメン)を信仰する神官団の力をおさえるため、唯一神【アテン】の信仰を強制し、都をテル=エル=アマルナに移しました。この改革の時期には、写実的な【アマルナ美術】が生まれました。しかし改革は王の死後すぐにもとに戻されました。のちの【ラメス2世】は、シリアの【カデシュの戦い】でヒッタイトと戦い、その後和約を結んだことで知られています。", "エジプト人は、死後も霊魂が生き続けると信じ、遺体を【ミイラ】にして保存しました。死者の安らかな来世を願って、【「死者の書」】がつくられました。文字には、碑文などに刻まれた象形文字の【神聖文字(ヒエログリフ)】と、それを簡略にした民用文字などがあり、【パピルス】に書かれました。1799年にナポレオンのエジプト遠征の際に発見された【ロゼッタ=ストーン】をもとに、フランスの【シャンポリオン】が神聖文字を解読しました。", "エジプトの太陽暦は1年を365日とするもので、のちにローマの【カエサル】がこれをもとに【ユリウス暦】を定め、さらに改良されて現在の暦につながっています。また、ピラミッドの建設に見られる測量や建築の技術、医学の知識なども高い水準にあり、エジプトの文明はギリシア人に大きな刺激を与えました。ヘロドトスをはじめ多くのギリシア人がエジプトを訪れ、その古い歴史と知恵に驚いた記録を残しています。"]}, {"t": "東地中海の諸民族 ― アラム人・フェニキア人・ヘブライ人", "p": ["前12世紀ごろ、地中海東部では【「海の民」】とよばれる集団の侵入などで大きな混乱が起こり、ヒッタイトは滅亡し、エジプトも勢いを失いました。その結果、大国のはざまで、シリア・パレスチナを舞台にセム語系の民族が活躍するようになりました。また、ヒッタイトが独占していたとされる製鉄の技術がオリエント各地に広まり、【鉄器】の時代が始まりました。", "【アラム人】はダマスクスを中心に、ラクダを使った【内陸の中継貿易】で活躍しました。彼らの言語である【アラム語】は国際的な商業語となり、のちにはアッシリアやアケメネス朝でも広く用いられました。【アラム文字】は、のちにヘブライ文字・アラビア文字・ソグド文字などの多くの文字のもとになりました。", "【フェニキア人】は、【シドン】や【ティルス】を拠点として【地中海貿易】で活躍し、北アフリカに【カルタゴ】などの植民市を建てました。彼らは楔形文字にかわる表音文字を用い、この文字がギリシア人に伝わって【アルファベット】の起源となりました。", "【ヘブライ人】は遊牧生活ののちパレスチナに定住しました。一部はエジプトに移り住みましたが、そこで苦しい生活を強いられ、指導者【モーセ】に率いられてエジプトを脱出したと伝えられます(【出エジプト】)。前10世紀ごろ、【ダヴィデ】と【ソロモン】の王のもとで王国は繁栄しましたが、ソロモン王の死後、北の【イスラエル王国】と南の【ユダ王国】に分裂しました。イスラエル王国は前722年に【アッシリア】に滅ぼされ、ユダ王国は前586年に新バビロニアの【ネブカドネザル2世】に滅ぼされて、住民の多くがバビロンに連れ去られました(【バビロン捕囚】)。", "この苦難のなかで、ヘブライ人は唯一神【ヤハウェ】への信仰を深め、自分たちは神に選ばれた民であるとする【選民思想】や、救世主(【メシア】)の到来を待つ信仰をはぐくみました。前538年、アケメネス朝の【キュロス2世】によって解放されて帰国すると、イェルサレムに神殿を再建し、【ユダヤ教】を確立しました。その聖典は、のちにキリスト教の『旧約聖書』となりました。唯一神信仰は、キリスト教やイスラームに受け継がれる重要な源流です。"]}, {"t": "アッシリアの統一と4王国の分立", "p": ["メソポタミア北部の【アッシリア】は、もともとは商業で栄えた国でしたが、鉄製の武器と戦車・騎兵を備えた強い軍隊をつくり、前7世紀前半にはメソポタミアからエジプトまでを征服して、【初めて全オリエントを統一】しました。都【ニネヴェ】に住んだ王は、全国を州に分けて総督を置き、【駅伝制】を整えて支配しました。前7世紀の【アッシュルバニパル】王は、ニネヴェに大図書館を建てたことでも知られています。", "しかし、アッシリアは服属した民族に重い貢納を課し、反抗する民族を強制移住させるなど、厳しい【強圧的な支配】を行ったため、各地で反乱が相次ぎました。その結果、前612年にニネヴェが陥落し、アッシリアは滅亡しました。", "アッシリアが滅んだあと、オリエントは4つの王国に分かれました(【4王国分立】)。すなわち、【エジプト】、小アジアの【リディア】、メソポタミアの【新バビロニア(カルデア)】、イラン高原の【メディア】です。リディアは、世界で最初に【金属貨幣】をつくった国として知られています。新バビロニアは【ネブカドネザル2世】のもとで栄え、都バビロンには壮麗なイシュタル門が建てられました。", "この分立の時代は長くは続きませんでした。イラン高原に興ったペルシア人の【アケメネス朝】は、前550年にキュロス2世がメディアから自立して国を建て、リディア、新バビロニアを次々と征服しました。そして前525年、【カンビュセス2世】がエジプトを征服して、再び全オリエントが統一されました。アッシリアの強圧的な支配が失敗した教訓から、アケメネス朝は服属した民族の宗教や慣習を尊重する寛容な支配を行います(続きは「イラン史」で扱います)。"]}], "points": ["シュメール人:ウル・ウルク、ジッグラト、楔形文字、六十進法、太陰暦、ギルガメシュ叙事詩", "アッカド人のサルゴン1世がメソポタミアを初統一、アムル人のバビロン第1王朝とハンムラビ法典(同害復讐・身分で刑罰が異なる)", "ヒッタイトの鉄器と戦車、ハットゥシャ、カデシュの戦い", "エジプト:古王国(メンフィス・ピラミッド)、中王国(テーベ・ヒクソス)、新王国(アメンホテプ4世・アマルナ美術・ラメス2世)", "神聖文字・パピルス・死者の書・太陽暦、ロゼッタ=ストーンとシャンポリオン", "アラム人(内陸中継貿易・アラム文字)、フェニキア人(地中海貿易・カルタゴ・アルファベットの起源)、ヘブライ人(ユダヤ教)", "アッシリアの全オリエント統一→前612年滅亡→4王国分立(エジプト・リディア・新バビロニア・メディア)", "バビロン捕囚(前586年)とキュロス2世による解放(前538年)"], "check": [["シュメール人が都市の中心に建てた聖塔は何か", "ジッグラト"], ["前24世紀ごろメソポタミアを初めて統一したアッカド人の王は誰か", "サルゴン1世"], ["「目には目を、歯には歯を」の原則で知られる法典を発布した王は誰か", "ハンムラビ王"], ["小アジアで早くから鉄器を使用した民族は何か", "ヒッタイト"], ["唯一神アテンの信仰を強制したエジプト新王国の王は誰か", "アメンホテプ4世"], ["神聖文字を解読したフランスの学者は誰か", "シャンポリオン"], ["内陸の中継貿易で活躍し、その文字が多くの文字のもとになった民族は何か", "アラム人"], ["フェニキア人が北アフリカに建てた植民市は何か", "カルタゴ"], ["前586年にユダ王国を滅ぼした新バビロニアの王は誰か", "ネブカドネザル2世"], ["世界で最初に金属貨幣をつくったとされる国は何か", "リディア"]], "related": ["y_bc30", "y_bc10", "y_bc6", "t_ir", "t_ar", "t_ps", "t_gr", "t_tr", "t_af"], "n": 4014, "videos": [{"title": "【世界史】 古代オリエント１ メソポタミア （１８分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=DZaSr9KVCR8", "note": "古代オリエント史の最初の単元としてメソポタミアの歴史を映像で復習できます。"}]}, "t_ir": {"title": "イラン史", "span": "前550年〜現在", "year": -500, "lead": "イラン高原のペルシア人は、アケメネス朝のもとで初めて世界帝国を築き、パルティア・ササン朝と続く王朝のもとで東西交易と独自の文化を発展させました。7世紀にイスラーム化したのちも、ペルシア語とペルシア文化はイスラーム世界の重要な柱であり続け、16世紀のサファヴィー朝でシーア派の国となりました。近代には列強の圧力に苦しみ、1979年のイラン革命でイスラーム共和国となりました。", "flow": ["前550年 キュロス2世がアケメネス朝を建国→前525年全オリエント統一", "前500年 イオニアの反乱→ペルシア戦争(マラトン・サラミス)で敗北", "前330年 アレクサンドロス大王によりアケメネス朝滅亡→セレウコス朝", "前3世紀半ば パルティア(アルサケス朝)が自立→東西交易で繁栄", "224年 アルダシール1世がササン朝を建国→ゾロアスター教を国教に", "260年 シャープール1世がローマ皇帝ウァレリアヌスを捕虜に、6世紀ホスロー1世が最盛期", "642年 ニハーヴァンドの戦いでアラブ軍に敗北→651年ササン朝滅亡、イスラーム化", "10〜11世紀 サーマーン朝などでペルシア語文化が復興、1258年イル=ハン国成立", "1501年 イスマーイール1世がサファヴィー朝を建国、十二イマーム派を国教に→アッバース1世がイスファハーンに遷都", "1828年 カージャール朝がトルコマンチャーイ条約→1891年タバコ=ボイコット運動、1905年立憲革命", "1925年 レザー=ハーンがパフレヴィー朝→1951年モサッデグの石油国有化", "1979年 イラン革命(ホメイニ)→1980年イラン=イラク戦争"], "sync": [], "secs": [{"t": "アケメネス朝 ― 最初の世界帝国", "p": ["イラン高原には、インド=ヨーロッパ語系の人々が住んでいました。その一派であるペルシア人は、はじめメディアに服属していましたが、前550年に【キュロス2世】が自立して【アケメネス朝】を建てました。キュロス2世はメディア・リディア・新バビロニアを次々と征服し、前538年には新バビロニアに捕らわれていたヘブライ人を解放しました(バビロン捕囚の終わり)。続く【カンビュセス2世】が前525年にエジプトを征服し、アッシリア以来の全オリエントの再統一が実現しました。", "最盛期を築いたのが【ダレイオス1世】です。彼は東はインダス川流域から西はエーゲ海北岸・エジプトまでの広大な領土を、20あまりの州に分けて【サトラップ】(知事)を置き、さらに【「王の目」「王の耳」】とよばれる監察官を派遣してサトラップを監視しました。都【スサ】から小アジアのサルデスまで【「王の道」】という国道を整備し、【駅伝制】を設けて命令や情報を速く伝えました。また、統一的な金貨・銀貨を発行し、フェニキア人やアラム人の商業活動を保護しました。新しい都【ペルセポリス】には壮大な宮殿が築かれました。", "アケメネス朝の支配の特徴は、征服した民族の宗教や慣習を認める【寛容な政策】をとったことでした。これは、強圧的な支配で反乱を招いたアッシリアの失敗に学んだものと考えられています。公用語としては【アラム語】が広く使われ、楔形文字をもとにした【ペルシア文字】もつくられました。ダレイオス1世の業績を3種類の言語で刻んだ【ベヒストゥーン碑文】は、のちに楔形文字の解読の手がかりとなりました。", "宗教では、【ゾロアスター教】が信仰されました。この宗教は、世界を光明(善)の神【アフラ=マズダ】と暗黒(悪)の神アーリマンの戦いととらえる【善悪二元論】を説き、最後には善が勝って【最後の審判】が行われると教えました。火を神聖なものとして崇めたため、拝火教ともよばれます。この終末観や天使・悪魔の考え方は、ユダヤ教やキリスト教にも影響を与えたとされます。", "前500年、ペルシアの支配に対して小アジアのギリシア人植民市が【イオニアの反乱】を起こし、これを支援したアテネとの間に【ペルシア戦争】が始まりました。ペルシア軍は前490年の【マラトンの戦い】、前480年の【サラミスの海戦】、前479年の【プラタイアの戦い】で敗れ、ギリシア征服は失敗しました。その後、アケメネス朝は内紛で弱まり、前330年、マケドニアの【アレクサンドロス大王】に滅ぼされました(最後の王は【ダレイオス3世】)。"]}, {"t": "パルティアとササン朝", "p": ["アレクサンドロス大王の死後、イランは【セレウコス朝シリア】の支配下に入りました。前3世紀半ば、カスピ海の東南でイラン系の遊牧民の族長【アルサケス】が自立し、【パルティア(アルサケス朝)】を建てました。パルティアは中国では【安息】とよばれ、都【クテシフォン】を中心に、ローマと中国を結ぶ【東西交易(シルクロード)】の中継で栄えました。西方のローマとはたびたび戦い、前53年の【カルラエの戦い】ではローマのクラッススの軍を破りました。はじめはギリシア文化(ヘレニズム文化)の影響が強かったのですが、しだいにイランの伝統文化が復活していきました。", "224年、ペルシア人の【アルダシール1世】がパルティアを倒し、【ササン朝】を建てました。ササン朝はアケメネス朝の後継者を自任し、【ゾロアスター教】を【国教】とし、その教典『【アヴェスター】』を編纂しました。2代目の【シャープール1世】は、西では260年にローマ軍を破って皇帝【ウァレリアヌス】を捕虜とし、東ではインドの【クシャーナ朝】を攻撃して領土を広げました。", "3世紀には【マニ】が、ゾロアスター教・キリスト教・仏教を融合した【マニ教】を開きました。マニ教はササン朝では異端として迫害されましたが、西は北アフリカ、東は中央アジアや中国まで広まりました。また、ビザンツ帝国で異端とされた【ネストリウス派】キリスト教はササン朝で保護され、のちに中国に伝わって景教とよばれました。", "6世紀の【ホスロー1世】の時代に、ササン朝は最盛期を迎えました。彼は北方の遊牧国家【突厥】と結んで中央アジアの【エフタル】を滅ぼし、西ではビザンツ皇帝【ユスティニアヌス】と戦って有利な和約を結びました。ササン朝の美術工芸品はシルクロードを通じて東アジアにも伝わり、日本の【正倉院】に伝わる【漆胡瓶】や、法隆寺の【獅子狩文錦】にはササン朝様式の影響が見られます。", "しかし、ビザンツ帝国との長い戦争で国力は消耗していきました。そこへアラビア半島で興ったイスラーム勢力が進出し、642年の【ニハーヴァンドの戦い】でササン朝軍はアラブ軍に大敗しました。651年、ササン朝は滅亡します。"]}, {"t": "イスラーム化とペルシア文化の復興", "p": ["ササン朝の滅亡後、イランはイスラーム帝国の一部となり、住民の多くはしだいにイスラームに改宗しました。しかし、アラブ人が特権をもつ【ウマイヤ朝】のもとで、イラン人などの非アラブ人の改宗者(【マワーリー】)は差別を受けていました。こうした不満を背景に、イラン東部の【ホラーサーン地方】から起こった運動によって、750年にウマイヤ朝は倒れ、【アッバース朝】が成立しました。アッバース朝では、民族の違いをこえてムスリムが平等に扱われるようになり、ササン朝の行政制度やペルシア人の官僚が重く用いられました。", "9世紀以降、アッバース朝の力が弱まると、イランには地方政権が次々と生まれました。中央アジアの【サーマーン朝】はイラン系の王朝で、ペルシア語による文学を保護し、詩人【フィルドゥシー】はイランの神話・英雄伝説をまとめた叙事詩『【シャー=ナーメ(王の書)】』を著しました。このころからペルシア語はアラビア文字で書かれるようになり、アラビア語に次ぐイスラーム世界の重要な言語となりました。946年には、シーア派のイラン系軍事政権【ブワイフ朝】がバグダードに入り、カリフから大アミールの称号を得て実権を握りました。", "11世紀には、トルコ系の【セルジューク朝】がイランを支配し、1055年にバグダードに入城しました。この時代、医学者・哲学者の【イブン=シーナー】や、詩人で天文学者の【ウマル=ハイヤーム】(『ルバイヤート』)が活躍しました。支配者がトルコ人に代わっても、行政や文化の担い手はペルシア人であり、ペルシア文化はイスラーム世界の東半分に広がっていきました。", "13世紀にはモンゴルが侵入し、【フレグ】が1258年にバグダードを攻略してアッバース朝を滅ぼし、イランを中心に【イル=ハン国】を建てました。7代目の【ガザン=ハン】はイスラームを国教とし、宰相【ラシード=アッディーン】はペルシア語で歴史書『【集史】』を著しました。その後、14世紀後半には【ティムール】がイランを征服しています。"]}, {"t": "サファヴィー朝 ― シーア派国家の成立", "p": ["16世紀初め、神秘主義教団である【サファヴィー教団】の指導者【イスマーイール1世】は、トルコ系遊牧民の騎馬軍団【キジルバシュ】を率いてイランを統一し、1501年に【サファヴィー朝】を建てました。彼はイラン古来の王の称号である【シャー】を用い、シーア派の一派である【十二イマーム派】を国教としました。これが、スンナ派が多数を占める周辺のイスラーム世界の中で、イランがシーア派の国となる出発点です。", "サファヴィー朝はスンナ派のオスマン帝国と激しく対立し、1514年の【チャルディランの戦い】では、鉄砲を備えたオスマン帝国の【セリム1世】の軍に大敗しました。この経験から、のちのサファヴィー朝は軍事改革を進めることになります。", "最盛期の王【アッバース1世】は、王に忠実な奴隷軍人を中心とする軍隊を整え、オスマン帝国から領土を奪い返しました。1622年には、イギリスの協力を得て、ペルシア湾の入口にある【ホルムズ島】からポルトガル人を追放しました。新しい首都【イスファハーン】には、壮大なモスクや広場が建設され、【「イスファハーンは世界の半分」】といわれるほどの繁栄を見せました。絹織物や陶器などの手工業も盛んで、ヨーロッパとの交易も活発に行われました。", "しかし、アッバース1世の死後、サファヴィー朝はしだいに弱まり、1722年に【アフガン人】に首都イスファハーンを占領されて事実上崩壊しました。"]}, {"t": "近代 ― カージャール朝と列強の圧力", "p": ["18世紀末、トルコ系の【カージャール朝】がイランを統一し、テヘランを都としました。19世紀に入ると、カージャール朝は南下するロシアと、インドを守ろうとするイギリスの両方から圧力を受けました。ロシアとの戦争に敗れて1828年に結んだ【トルコマンチャーイ条約】では、アルメニアなどの領土を割譲したうえ、ロシアに【治外法権】を認め、【関税自主権】を失いました。これはイランが半植民地化していく出発点となりました。", "列強の進出と社会の不安のなかで、19世紀半ばには、救世主の再来を説く【バーブ教】の信徒が蜂起しましたが(バーブ教徒の乱)、政府に鎮圧されました。1890年、国王がイギリスの業者にタバコの独占利権を与えると、イスラーム法学者(ウラマー)と商人を中心に、全国的な【タバコ=ボイコット運動】が起こり、その結果、利権は撤回されました。この運動は、パン=イスラーム主義を説いた【アフガーニー】の影響を受けたとされます。", "日露戦争で立憲国家の日本が専制国家ロシアに勝利したことにも刺激され、1905年に【イラン立憲革命】が起こりました。翌年には国民議会が開かれ憲法も制定されましたが、1907年の【英露協商】でイランは北部をロシア、南東部をイギリスの勢力範囲とされ、両国の干渉によって革命は挫折しました。"]}, {"t": "パフレヴィー朝からイラン=イスラーム共和国へ", "p": ["第一次世界大戦後、軍人の【レザー=ハーン】が実権を握り、1925年に【パフレヴィー朝】を開きました。彼はトルコのムスタファ=ケマルにならって、近代的な軍隊や法律を整え、西欧化と近代化を進めました。1935年には国名を正式に【イラン】と改めています。", "第二次世界大戦後、イランの石油はイギリス系の会社が支配していました。1951年、首相【モサッデグ】は【石油国有化】を断行しましたが、イギリスの反発を受け、1953年にアメリカとイギリスの支援を受けた国王派のクーデタで失脚しました。その後、国王【パフレヴィー2世】はアメリカと結んで独裁を強め、1955年には【バグダード条約機構】に加わりました。1960年代からは【白色革命】とよばれる上からの近代化(土地改革や女性参政権など)を進めましたが、貧富の差の拡大や宗教勢力の反発を招きました。", "1979年、シーア派の宗教指導者【ホメイニ】を中心とする【イラン革命(イスラーム革命)】が起こり、国王は亡命して王政は倒れました。イスラーム法学者が国の最高指導者となる【イラン=イスラーム共和国】が成立し、反米の姿勢をとりました。革命の混乱で石油の生産が落ち込み、【第2次石油危機】が起こりました。また同年には、テヘランのアメリカ大使館占拠事件が起こり、アメリカとの関係は決定的に悪化しました。", "1980年、隣国イラクの【サダム=フセイン】は革命の波及を恐れ、国境問題を口実にイランに侵攻しました(【イラン=イラク戦争】)。戦争は1988年まで続き、両国に大きな犠牲を出しました。その後もイランは、核開発問題などをめぐって欧米諸国と対立を続けています。古代から続くペルシア人の誇りと、シーア派イスラームという二つの要素が、現代イランの国家のあり方を形づくっているといえるでしょう。"]}], "points": ["アケメネス朝の統治:サトラップ、王の目・王の耳、王の道、駅伝制、寛容政策、ペルセポリス", "ゾロアスター教の善悪二元論と最後の審判、ササン朝で国教化し『アヴェスター』を編纂", "パルティア(安息)の東西交易とカルラエの戦い(前53年)", "ササン朝:アルダシール1世(224年)、シャープール1世がウァレリアヌスを捕虜(260年)、ホスロー1世が突厥と結びエフタルを滅ぼす", "ニハーヴァンドの戦い(642年)→ササン朝滅亡(651年)", "フィルドゥシー『シャー=ナーメ』とペルシア語文化の復興、ブワイフ朝(946年)、イル=ハン国(1258年)", "サファヴィー朝:イスマーイール1世・十二イマーム派・シャー、チャルディランの戦い(1514年)、アッバース1世とイスファハーン", "トルコマンチャーイ条約(1828年)→タバコ=ボイコット運動→立憲革命→英露協商、モサッデグ、イラン革命(1979年)"], "check": [["アケメネス朝で各州に置かれた知事を何というか", "サトラップ"], ["スサとサルデスを結んだアケメネス朝の国道を何というか", "王の道"], ["アケメネス朝の最盛期を築いた王は誰か", "ダレイオス1世"], ["中国で安息とよばれたイランの王朝は何か", "パルティア"], ["224年にササン朝を建てたのは誰か", "アルダシール1世"], ["642年にササン朝がアラブ軍に大敗した戦いは何か", "ニハーヴァンドの戦い"], ["『シャー=ナーメ』を著したペルシアの詩人は誰か", "フィルドゥシー"], ["サファヴィー朝が国教としたシーア派の一派は何か", "十二イマーム派"], ["「世界の半分」とよばれたサファヴィー朝の首都はどこか", "イスファハーン"], ["1951年にイランの石油国有化を断行した首相は誰か", "モサッデグ"]], "related": ["y_bc6", "y_bc4", "y_bc2", "y_3", "y_6", "y_7", "y_10", "y_13", "y_16", "y_19", "y_20b", "t_ori", "t_gr", "t_ro", "t_byz", "t_ar", "t_tr", "t_mn", "t_in"], "n": 4686, "videos": [{"title": "【世界史】 古代オリエント６ 古代イラン （１９分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=xElyOE-mbmo", "note": "古代イランの諸王朝の流れをまとめて復習できます。"}]}, "t_tr": {"title": "トルコ・オスマン帝国史", "span": "6世紀〜現在", "year": 1453, "lead": "モンゴル高原に起こったトルコ系の人々は、西へ移動しながらイスラームを受け入れ、セルジューク朝のもとで小アジア(アナトリア)に定着しました。14世紀に興ったオスマン帝国は、ビザンツ帝国を滅ぼして三大陸にまたがる大帝国となりましたが、17世紀末から後退し、19世紀には「東方問題」の舞台となりました。第一次世界大戦後、ムスタファ=ケマルのもとで近代的なトルコ共和国が生まれました。", "flow": ["552年 モンゴル高原に突厥が建国→744年ウイグル", "10世紀 カラハン朝がトルコ系最初のイスラーム王朝に、マムルークとしてイスラーム世界へ", "1055年 セルジューク朝のトゥグリル=ベクがバグダード入城→スルタンの称号", "1071年 マンジケルトの戦いでビザンツ軍を破る→小アジアのトルコ化、十字軍のきっかけ", "1299年 オスマン帝国成立→1389年コソヴォの戦い、1396年ニコポリスの戦い", "1402年 アンカラの戦いでティムールに敗北→1453年メフメト2世がコンスタンティノープル攻略", "1517年 セリム1世がマムルーク朝を滅ぼす→メッカ・メディナの保護者に", "1526年 スレイマン1世がモハーチの戦いに勝利→1529年第1次ウィーン包囲、1538年プレヴェザの海戦", "1683年 第2次ウィーン包囲失敗→1699年カルロヴィッツ条約でハンガリーを失う", "1839年 タンジマート開始→1876年ミドハト憲法→1878年アブデュルハミト2世が停止", "1908年 青年トルコ革命→第一次世界大戦で敗北、1920年セーヴル条約", "1923年 ローザンヌ条約・トルコ共和国成立(ムスタファ=ケマル)→1924年カリフ制廃止"], "sync": [], "secs": [{"t": "トルコ系民族の西への移動", "p": ["トルコ系の人々は、もともとモンゴル高原から中央アジアにかけての草原で遊牧生活を送っていました。6世紀半ば、彼らは【突厥】を建て、モンゴル高原から中央アジアにまたがる大遊牧国家をつくりました。突厥はササン朝と結んで中央アジアのエフタルを滅ぼしたことで知られ、独自の【突厥文字】を用いました。突厥はやがて東西に分裂し、8世紀半ばにはトルコ系の【ウイグル】がモンゴル高原の支配者となりました。", "840年、ウイグルが【キルギス】に敗れて崩壊すると、多くのトルコ系の人々が西へ移動し、中央アジア(のちに【トルキスタン】とよばれる)に定着しました。ここで彼らはイスラーム世界と接し、10世紀には【カラハン朝】がトルコ系最初のイスラーム王朝となりました。", "一方、イスラーム世界では、騎馬と弓に優れたトルコ人が【マムルーク】(奴隷軍人)として重用されるようになりました。アッバース朝のカリフや各地の王朝はトルコ人の軍人を親衛隊とし、やがてマムルーク出身者が自ら王朝を開くこともありました。アフガニスタンの【ガズナ朝】や、のちにエジプトの【マムルーク朝】もそのような例です。こうしてトルコ人は、イスラーム世界の軍事を担う中心的な存在になっていきました。"]}, {"t": "セルジューク朝と小アジアのトルコ化", "p": ["11世紀、トルコ系の【セルジューク朝】が中央アジアから西アジアへ進出しました。指導者【トゥグリル=ベク】は、1055年にバグダードに入城して、シーア派のブワイフ朝を追い出しました。アッバース朝のカリフは彼に【スルタン】(支配者)の称号を与えました。こうして、カリフは宗教的な権威として残り、スルタンが政治・軍事の実権を握るという分担が生まれました。スンナ派の守り手となったセルジューク朝では、宰相【ニザーム=アルムルク】が各地に【ニザーミーヤ学院】を建て、スンナ派の学問を振興しました。", "1071年、セルジューク朝は【マンジケルト(マラーズギルド)の戦い】でビザンツ帝国軍を破り、皇帝を捕虜にしました。これにより、トルコ人が大挙して【小アジア(アナトリア)】に移り住むようになり、この地域のトルコ化とイスラーム化が進みました。小アジアには一族が【ルーム=セルジューク朝】を建てました。追いつめられたビザンツ皇帝はローマ教皇に救援を求め、これが1096年に始まる【十字軍】のきっかけとなりました。", "13世紀にモンゴルが西アジアに進出すると、ルーム=セルジューク朝はその支配下に入り、小アジアには多くのトルコ系の小さな君侯国が分立しました。その中から、のちの大帝国が生まれることになります。"]}, {"t": "オスマン帝国の興隆", "p": ["13世紀末、小アジア北西部のビザンツ帝国との境界地帯で、【オスマン】に率いられたトルコ系の集団が力をつけ、1299年ごろ【オスマン帝国】が成立したとされます。オスマン帝国は異教徒との戦いを掲げて戦士を集め、ビザンツ帝国の領土を奪いながら成長しました。14世紀にはバルカン半島に渡り、【アドリアノープル(エディルネ)】を首都としました。", "1389年の【コソヴォの戦い】でセルビアなどの連合軍を破り、さらに1396年には【バヤジット1世】が【ニコポリスの戦い】で、ハンガリー王の率いるヨーロッパの十字軍を打ち破りました。ところが、1402年の【アンカラの戦い】で、中央アジアから攻めてきた【ティムール】に大敗し、バヤジット1世は捕虜となりました。オスマン帝国は一時崩壊の危機に陥りましたが、ティムールが東へ引き返したため、やがて国力を回復しました。", "1453年、【メフメト2世】は大砲を用いた攻撃で【コンスタンティノープル】を攻略し、1000年以上続いたビザンツ帝国を滅ぼしました。この都は【イスタンブル】とよばれるようになってオスマン帝国の新しい首都となり、ハギア=ソフィア聖堂はモスクに改められました。メフメト2世はトプカプ宮殿を建設し、さらにバルカン半島や黒海沿岸の支配を固めました。", "16世紀初め、【セリム1世】は東方のシーア派国家サファヴィー朝を1514年の【チャルディランの戦い】で破り、1517年にはエジプトの【マムルーク朝】を滅ぼしました。これによりオスマン帝国は、イスラームの聖地【メッカ・メディナ】の保護者となり、イスラーム世界の中心的な国家となりました。のちに、オスマン帝国のスルタンがカリフの地位も兼ねるとする【スルタン=カリフ制】の考え方が唱えられましたが、これは後世に強調された主張とされます。"]}, {"t": "スレイマン1世の時代と帝国のしくみ", "p": ["オスマン帝国の最盛期を築いたのが、16世紀の【スレイマン1世】です。1526年の【モハーチの戦い】でハンガリー軍を破ってハンガリーの大部分を支配し、1529年には神聖ローマ皇帝カール5世の拠点である【ウィーン】を包囲しました(【第1次ウィーン包囲】)。ウィーンは攻略できませんでしたが、ヨーロッパに大きな衝撃を与えました。また、1538年の【プレヴェザの海戦】でスペイン・ヴェネツィア・ローマ教皇の連合艦隊を破り、地中海の制海権を握りました。", "スレイマン1世は、共通の敵であるハプスブルク家に対抗するため、フランス王【フランソワ1世】と協力関係を結びました。オスマン帝国はフランス人などの外国商人に、帝国内での居住・通商の自由や治外法権などを認めました。この特権は【カピチュレーション】とよばれ、もとは強い立場の帝国が恩恵として与えたものでしたが、のちに帝国が弱体化すると、ヨーロッパ諸国の進出を許す不平等な特権に変わっていきました。", "オスマン帝国の強さを支えたのは、独特の統治のしくみでした。スルタンのもとで【大宰相】が行政を統括し、イスラーム法(シャリーア)に加えてスルタンが定める法【カーヌーン】によって国が治められました。軍事面では、騎士に土地からの徴税権を与えて軍役を課す【ティマール制】がとられました。また、バルカン半島のキリスト教徒の少年を集めてイスラームに改宗させ、教育する【デヴシルメ】によって、官僚やスルタン直属の常備歩兵軍団【イェニチェリ】が育てられました。イェニチェリは鉄砲を装備した精鋭部隊でした。", "帝国内の非ムスリムは、宗教ごとの共同体【ミッレト】をつくり、税を納めれば信仰や自治を認められました。ギリシア正教徒・アルメニア教会の信徒・ユダヤ教徒などがそれぞれのミッレトをもち、多様な民族と宗教が共存する帝国が成り立っていました。文化面では、建築家【ミマール=シナン】がイスタンブルにスレイマン=モスクを建てるなど、壮麗なイスラーム建築が生まれました。"]}, {"t": "帝国の後退と東方問題", "p": ["1571年の【レパントの海戦】で、オスマン海軍はスペインなどの連合艦隊に敗れましたが、すぐに艦隊を再建し、地中海での優位はしばらく保たれました。しかし、17世紀になると、ティマール制がくずれて徴税請負制が広がり、イェニチェリも特権化して規律がゆるむなど、帝国の体制は変化していきました。", "1683年、オスマン軍は再びウィーンを包囲しましたが(【第2次ウィーン包囲】)、失敗に終わりました。その後の戦争に敗れ、1699年の【カルロヴィッツ条約】でハンガリーなどをオーストリアに割譲しました。これはオスマン帝国が初めて大規模に領土を失った条約であり、ヨーロッパとの力関係が逆転したことを示しています。18世紀前半には、西欧文化を取り入れた華やかな【チューリップ時代】が訪れましたが、ロシアとの戦争に敗れて黒海北岸を失い、1783年にはロシアが【クリミア半島】を併合しました。", "19世紀になると、オスマン帝国の衰退にともなって、列強の利害が複雑にからみあう【東方問題】が起こりました。1821年に始まった【ギリシア独立戦争】では、イギリス・フランス・ロシアが介入してギリシアの独立が実現しました。エジプトでは総督【ムハンマド=アリー】が近代化を進めて自立し、シリアの領有を求めて2度にわたる【エジプト=トルコ戦争】を起こしました。また、ロシアは【南下政策】をとり、1853年の【クリミア戦争】、1877年の【ロシア=トルコ(露土)戦争】と、オスマン帝国と戦いを重ねました。1878年の【ベルリン会議】では、セルビア・モンテネグロ・ルーマニアの独立が承認され、オスマン帝国はバルカン半島の領土の多くを失いました。"]}, {"t": "近代化の試み ― タンジマートから青年トルコ革命へ", "p": ["危機に直面したオスマン帝国は、近代化によって立て直しをはかりました。1826年にはすでに特権化したイェニチェリが廃止されていました。1839年、スルタン【アブデュルメジト1世】は【ギュルハネ勅令】を出し、【タンジマート】(恩恵改革)を始めました。これは、宗教の違いをこえて臣民の生命・財産の安全と法の前の平等を保障し、西欧にならった行政・司法・軍事・教育の制度を整えようとするものでした。しかし、改革の費用は外国からの借款に頼り、ヨーロッパ製品の流入で国内の産業も打撃を受け、帝国は財政的に破綻していきました。", "1876年、宰相【ミドハト=パシャ】の起草によって、アジアで最初の本格的な憲法とされる【ミドハト憲法】が発布され、議会が開かれました。しかし、スルタン【アブデュルハミト2世】は、1877年に始まった露土戦争を口実に、1878年に議会を閉鎖して憲法を停止し、専制政治を行いました。彼は【パン=イスラーム主義】を利用して、帝国内のムスリムの団結をはかろうとしました。", "専制に反対する知識人や青年将校は【「青年トルコ人」】とよばれる運動を起こし、1908年に【青年トルコ革命】を起こして憲法を復活させました。しかしその混乱に乗じて、オーストリアはボスニア・ヘルツェゴヴィナを併合し、ブルガリアは独立を宣言しました。その後もイタリアとの戦争(イタリア=トルコ戦争)でリビアを失い、【バルカン戦争】でヨーロッパ側の領土の大半を失いました。青年トルコ政権はしだいにトルコ民族主義を強め、ドイツに接近していきました。"]}, {"t": "第一次世界大戦とトルコ共和国", "p": ["第一次世界大戦で、オスマン帝国はドイツ・オーストリアの同盟国側について参戦しました。イギリスはオスマン帝国の内部からの崩壊をねらって、1915年の【フセイン・マクマホン協定】でアラブ人に独立を約束しながら、1916年の【サイクス・ピコ協定】でフランス・ロシアとオスマン帝国領の分割を取り決めました。この矛盾した約束が、のちのパレスチナ問題など中東の紛争の原因となりました。", "敗戦国となったオスマン帝国は、1920年に【セーヴル条約】を結ばされ、領土の大部分を失い、小アジアの一部もギリシアなどに占領されることになりました。これに対して軍人の【ムスタファ=ケマル】は、アンカラで【トルコ大国民議会】を開いて抵抗運動を指導し、侵入してきたギリシア軍を撃退しました。1922年には【スルタン制】を廃止してオスマン帝国を滅ぼし、1923年には連合国と【ローザンヌ条約】を結んで、新しい国境を認めさせるとともに、治外法権の撤廃と関税自主権の回復を実現しました。", "1923年、【トルコ共和国】が成立し、ムスタファ=ケマルが初代大統領となり、首都は【アンカラ】に置かれました。翌1924年には【カリフ制】を廃止し、政治と宗教を分ける【政教分離】を進めました。さらに、一夫多妻制の廃止、女性の参政権の実現、太陽暦の採用、そして1928年にはアラビア文字にかわって【ローマ字(ラテン文字)】を用いる【文字改革】を行うなど、急速な西欧化・近代化を進めました。のちに彼は議会から【アタテュルク】(トルコの父)の姓を贈られました。", "第二次世界大戦ではトルコはほぼ中立を保ちましたが、戦後はソ連の圧力に対抗するため、1947年の【トルーマン=ドクトリン】でアメリカの援助を受け、1952年に【NATO】に加盟しました。1955年にはイラク・イラン・パキスタン・イギリスとともに【バグダード条約機構(中東条約機構)】を結成しました。その後もトルコは、ヨーロッパとアジアの境に位置する国として、キプロス問題やクルド人問題、EU加盟交渉など、さまざまな課題に向き合っています。"]}], "points": ["突厥→ウイグル→西方移動、カラハン朝(トルコ系最初のイスラーム王朝)、マムルーク", "セルジューク朝:トゥグリル=ベクのバグダード入城(1055年)とスルタンの称号、マンジケルトの戦い(1071年)と十字軍", "オスマン帝国の拡大:コソヴォ(1389年)→ニコポリス(1396年)→アンカラの戦いで敗北(1402年)→コンスタンティノープル攻略(1453年)", "セリム1世:チャルディランの戦い(1514年)、マムルーク朝征服(1517年)", "スレイマン1世:モハーチ(1526年)、第1次ウィーン包囲(1529年)、プレヴェザの海戦(1538年)、カピチュレーション", "統治制度:ティマール制・デヴシルメ・イェニチェリ・ミッレト・カーヌーン", "第2次ウィーン包囲(1683年)→カルロヴィッツ条約(1699年)が後退の転機", "タンジマート(1839年)→ミドハト憲法(1876年)→アブデュルハミト2世の停止→青年トルコ革命(1908年)→セーヴル条約→ローザンヌ条約・トルコ共和国(1923年)"], "check": [["6世紀半ばにモンゴル高原に建てられたトルコ系の遊牧国家は何か", "突厥"], ["トルコ系最初のイスラーム王朝は何か", "カラハン朝"], ["1055年にバグダードに入城しスルタンの称号を得たのは誰か", "トゥグリル=ベク"], ["1402年にバヤジット1世がティムールに敗れた戦いは何か", "アンカラの戦い"], ["1453年にコンスタンティノープルを攻略したスルタンは誰か", "メフメト2世"], ["1526年にスレイマン1世がハンガリー軍を破った戦いは何か", "モハーチの戦い"], ["オスマン帝国が外国商人に認めた居住・通商の特権を何というか", "カピチュレーション"], ["キリスト教徒の少年を徴集して官僚や軍人に育てた制度は何か", "デヴシルメ"], ["1699年にオスマン帝国がハンガリーを失った条約は何か", "カルロヴィッツ条約"], ["1876年に発布されたアジア最初の本格的な憲法は何か", "ミドハト憲法"]], "related": ["y_6", "y_11", "y_14", "y_15", "y_16", "y_17", "y_19", "y_20a", "y_20b", "t_mn", "t_byz", "t_bal", "t_ir", "t_ar", "t_ru", "t_pl", "t_ps"], "n": 4873, "videos": [{"title": "【世界史】 イスラームの繁栄２ オスマン帝国 （１９分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=2LQfBM7xxQ0", "note": "オスマン帝国の歴史を学べ、2026年度第5問で問われたオスマン帝国の税制の背景理解に役立ちます。"}]}, "t_ar": {"title": "アラブ・エジプト史", "span": "前3000年ごろ〜現在", "year": 1956, "lead": "ナイル川が育てた古代エジプト文明は、のちにギリシア・ローマ・ビザンツの支配を受け、7世紀のアラブ人の征服によってアラビア語とイスラームの世界に組み込まれました。カイロはファーティマ朝・アイユーブ朝・マムルーク朝のもとでイスラーム世界の中心都市となり、近代にはムハンマド=アリーの改革、イギリスの支配、ナセルのアラブ民族主義を経て、中東政治の要の国として現代に至ります。", "flow": ["前3000年ごろ 上下エジプト統一→ファラオによる神権政治(古王国・中王国・新王国)", "前525年 アケメネス朝が征服→前332年アレクサンドロス大王、プトレマイオス朝へ", "前30年 プトレマイオス朝滅亡→ローマ、のちビザンツ帝国の属州(キリスト教化)", "7世紀 ムハンマドがイスラーム教を創始→正統カリフ時代にアラブ人がシリア・エジプトを征服", "661年 ウマイヤ朝(アラブ帝国)→750年アッバース朝(イスラーム帝国)", "909年 ファーティマ朝成立→969年カイロ建設、アズハル学院", "1169年 サラーフ=アッディーンがアイユーブ朝→1187年イェルサレム奪回", "1250年 マムルーク朝→1260年モンゴル撃退、1517年オスマン帝国に征服される", "1798年 ナポレオンのエジプト遠征→ムハンマド=アリーの近代化・自立", "1869年 スエズ運河開通→財政破綻、1881年ウラービー運動→1882年イギリスの事実上の保護下", "1922年 エジプト王国が形式的に独立→1952年エジプト革命", "1956年 ナセルのスエズ運河国有化→中東戦争、1978年キャンプ=デーヴィッド合意"], "sync": [], "secs": [{"t": "古代 ― ナイルの賜物としてのエジプト文明", "p": ["エジプトは国土の大部分が砂漠ですが、南から北へ流れる【ナイル川】が毎年定期的に増水し、上流から肥えた土を運んできました。人々はこの増水を利用して農耕を営み、早くから豊かな社会をつくりました。ギリシアの歴史家【ヘロドトス】が「エジプトはナイルの賜物」と記したのはこのためです。増水の時期を正確に知る必要から【太陽暦】が、氾濫後に土地を測り直す必要から【測地術】や【十進法】が発達しました。太陽暦はのちにローマに伝わり、カエサルの【ユリウス暦】のもとになります。", "はじめナイル流域には【ノモス】とよばれる小国家が分立していましたが、前3000年ごろ統一王国が成立しました。伝承では【メネス】が上下エジプトを統一したとされます。王は【ファラオ】とよばれ、太陽神【ラー】の子として神のように崇められました。こうした神権政治のもとで、【古王国】時代(都【メンフィス】)には巨大な【ピラミッド】が築かれました。ピラミッドを建てるには大量の労働力と食料を組織する必要があり、それだけ王の権力が強かったことを示しています。", "その後、中王国時代には都が上エジプトの【テーベ】に移りましたが、末期にはアジア系の【ヒクソス】が侵入し、馬と戦車をもたらしました。これを追放して成立した【新王国】は、戦車を使った軍事力でシリア方面に進出し、【トトメス3世】のときに最大版図を築きました。シリアをめぐっては小アジアの【ヒッタイト】と争い、【ラメス2世】の時代に【カデシュの戦い】が起こりました。新王国では一時、【アメンホテプ4世】が唯一神【アトン】の信仰を強制し、テル=エル=アマルナに都を移しましたが、彼の死後に旧来の信仰に戻りました。", "古代エジプト人は霊魂の不滅と復活を信じ、遺体を【ミイラ】にして保存し、死後の審判について記した【死者の書】を墓に納めました。冥界の王【オシリス】が死者を審判すると考えられていたのです。文字は碑文などに使う【神聖文字(ヒエログリフ)】と、それを簡略化した【民用文字(デモティック)】などがあり、草からつくった【パピルス】に書かれました。19世紀に【ロゼッタ=ストーン】をもとに【シャンポリオン】が神聖文字を解読し、古代エジプトの研究が大きく進みました。"]}, {"t": "外国支配の時代 ― ペルシア・ギリシア・ローマ", "p": ["前7世紀前半、エジプトは一時【アッシリア】に征服されました。アッシリア滅亡後はエジプト・新バビロニア・リディア・メディアの4王国が分立しましたが、前525年にはアケメネス朝の【カンビュセス2世】がエジプトを征服し、オリエントは再び統一されました。これ以後、エジプトは長く外国勢力の支配を受けることになります。", "前332年に【アレクサンドロス大王】がエジプトを征服し、都市【アレクサンドリア】を建設しました。大王の死後は部下が建てた【プトレマイオス朝】がエジプトを支配し、アレクサンドリアには王立研究所【ムセイオン】が置かれて、ヘレニズム時代の学問の中心となりました。しかしローマの東方進出の中で、前31年の【アクティウムの海戦】でクレオパトラがオクタウィアヌスに敗れ、前30年にプトレマイオス朝は滅亡しました。", "ローマ時代のエジプトは、首都ローマの人々を養う穀倉として重視されました。この間にキリスト教が広まり、アレクサンドリアは神学の中心地の一つとなります。ローマ帝国の東西分裂後はビザンツ帝国の領土となりましたが、エジプトのキリスト教徒の多くは、キリストの神性を重視する【単性論】をとるコプト教会に属し、コンスタンティノープルの教会と対立していました。この宗教的な不満が、のちにアラブ人の征服が比較的すみやかに進んだ一因とされます。"]}, {"t": "アラブ人の征服とイスラーム化", "p": ["7世紀初め、アラビア半島のメッカで【ムハンマド】が唯一神アッラーの教えを説き、【イスラーム教】が生まれました。622年の【ヒジュラ(聖遷)】でメディナに移ったムハンマドは信徒の共同体【ウンマ】をつくり、630年にメッカを征服してアラビア半島の大部分を統合しました。", "ムハンマドの死後、信徒の選挙で選ばれた【正統カリフ】のもとで、アラブ人は大規模な征服活動(ジハード)を行いました。第2代カリフ【ウマル】の時代に、ビザンツ帝国からシリアとエジプトを奪い、ササン朝を【ニハーヴァンドの戦い】で破りました。アラブ人は征服地に【ミスル】とよばれる軍営都市を建設し、エジプトでは【フスタート】がつくられました。これがのちのカイロの母体です。征服地の住民は、改宗しなくても【ジズヤ(人頭税)】と【ハラージュ(地租)】を払えば信仰を認められたため、急激な改宗は起こりませんでしたが、長い時間をかけてアラビア語とイスラームがエジプトに浸透していきました。", "661年に成立した【ウマイヤ朝】は都を【ダマスクス】に置き、アラブ人が特権を持つ国家だったため【アラブ帝国】とよばれます。異民族の改宗者【マワーリー】は、改宗してもジズヤを課されるなど差別され、不満を強めました。この不満を背景に750年に成立した【アッバース朝】は、ムスリムであれば民族を問わずジズヤを免除したため【イスラーム帝国】とよばれます。このようにして、エジプトを含む地域は「アラブ人が支配する地域」から「アラビア語を話すムスリムの世界」へと変わっていきました。現在「アラブ」とよばれる地域が北アフリカからイラクまで広がるのは、この時代の征服と同化の結果です。"]}, {"t": "カイロの繁栄 ― ファーティマ朝・アイユーブ朝・マムルーク朝", "p": ["10世紀になるとアッバース朝の支配力が弱まり、各地に独立王朝が生まれました。909年に北アフリカのチュニジアで建国したシーア派(イスマーイール派)の【ファーティマ朝】は、自らカリフを名のってアッバース朝の権威を否定し、969年にエジプトを征服して新都【カイロ】を建設しました。カイロには学府【アズハル学院】が創建され、エジプトはイスラーム世界の学問と商業の中心地として栄えはじめます。これ以後、カイロはバグダードと並ぶ、さらにのちにはそれを上回る大都市となっていきました。", "12世紀、十字軍の時代にエジプトの実権を握ったのがクルド人の武将【サラーフ=アッディーン(サラディン)】です。彼はファーティマ朝を廃して1169年に【アイユーブ朝】を開き、エジプトをスンナ派に戻しました。そして1187年に十字軍から【イェルサレム】を奪回し、これに対抗して起こされた【第3回十字軍】(イギリスのリチャード1世らが参加)とも戦い抜きました。", "アイユーブ朝はトルコ人などの奴隷軍人【マムルーク】を軍の中核としていましたが、1250年にはそのマムルークが実権を奪って【マムルーク朝】を建てました。1258年にモンゴル軍がバグダードを攻略してアッバース朝を滅ぼすと、マムルーク朝の軍人【バイバルス】は1260年の【アイン=ジャールートの戦い】でモンゴル軍を破り、エジプト・シリアをモンゴルの侵攻から守りました。さらにマムルーク朝はアッバース家のカリフをカイロに擁立し、メッカ・メディナの保護者となったことで、イスラーム世界の中心としての権威を高めました。", "マムルーク朝時代のカイロは、紅海とインド洋を結ぶ香辛料交易で繁栄しました。この交易を担ったのが【カーリミー商人】です。西アフリカのマリ王国の王【マンサ=ムーサ】がメッカ巡礼の途中で大量の金を持ち込み、カイロの金相場を下落させたという話は、この時代のカイロがアフリカとアジアを結ぶ交易の結節点だったことを示しています。歴史家【イブン=ハルドゥーン】もこの時代にカイロで活躍しました。しかし15世紀末にポルトガルがインド航路を開くと香辛料交易の利益は減り、1517年、マムルーク朝はオスマン帝国の【セリム1世】に滅ぼされました。"]}, {"t": "オスマン帝国の支配と近代化の試み", "p": ["オスマン帝国の支配下でも、エジプトではマムルーク出身の有力者が実権を保ち続けました。この状況を大きく変えたのが、1798年の【ナポレオンのエジプト遠征】です。ナポレオンはイギリスとインドの連絡を断つことをねらってエジプトに上陸しました。遠征自体は失敗に終わりましたが、同行した学者たちの調査で【ロゼッタ=ストーン】が発見されるなど、ヨーロッパの東洋研究が進むきっかけとなりました。一方、エジプトの人々にとっては、ヨーロッパの軍事力の強さを思い知らされる体験でした。", "この混乱の中で、オスマン帝国から派遣された軍人【ムハンマド=アリー】がエジプト総督となり、マムルーク勢力を一掃して権力を握りました。彼は西欧式の軍隊を創設し、綿花などの専売制、工場の建設、留学生の派遣など、上からの近代化を進めました。その力を背景に、シリアの領有を求めてオスマン帝国と2度にわたる【エジプト=トルコ戦争】を戦い、エジプト総督の地位の世襲を認めさせて事実上自立しました。ただし、エジプトが強くなりすぎることを警戒したイギリスなど列強の干渉によって、シリアの獲得はかないませんでした。", "その後、フランス人【レセップス】の指導で【スエズ運河】が建設され、1869年に開通しました。運河は地中海と紅海を結ぶ世界交通の要となりましたが、建設費や近代化事業の負担でエジプトは多額の外債を抱え、財政が破綻しました。1875年、イギリス首相【ディズレーリ】はエジプトが手放したスエズ運河会社の株を買収し、運河の支配権を握りました。英仏はエジプトの財政を管理するようになり、エジプトは列強に従属していきます。"]}, {"t": "イギリスの支配と民族運動", "p": ["外国の干渉に反発し、1881年には軍人【ウラービー】が「エジプト人のためのエジプト」をスローガンに【ウラービー運動】を起こしました。これは立憲制の実現と外国支配からの脱却をめざす民族運動でしたが、イギリスは1882年に軍事介入してこれを鎮圧し、エジプトを事実上の保護下に置きました。イギリスにとってエジプトは、スエズ運河を通るインドへの道を守るうえで欠かせない場所であり、のちにカイロ・ケープタウン・カルカッタを結ぶ【3C政策】の拠点となりました。", "第一次世界大戦が始まると、オスマン帝国がドイツ側で参戦したため、イギリスは1914年にエジプトを正式に保護国としました。同時にイギリスは、アラブ人の協力を得るため1915年の【フセイン・マクマホン協定】で戦後のアラブ人の独立を約束しました。しかし一方で、英仏露が旧オスマン領を分け合う【サイクス・ピコ協定】、ユダヤ人に民族的郷土の建設を認める【バルフォア宣言】も結んでおり、この矛盾した外交がのちのパレスチナ問題の原因となります。戦後、シリア・レバノンはフランス、イラク・トランスヨルダン・パレスチナはイギリスの【委任統治領】とされ、アラブ人の独立の期待は裏切られました。", "大戦後、エジプトでは【ワフド党】を中心に独立運動が高まり、1919年には大規模な反英運動が起こりました。その結果、1922年にエジプトは【エジプト王国】として形式的に独立しましたが、スエズ運河地帯の駐兵権などはイギリスが保持し続け、真の独立とはいえない状態が続きました。1945年には、アラブ諸国の協力をめざして【アラブ連盟】が結成されています。"]}, {"t": "ナセルとアラブ民族主義", "p": ["1948年にイスラエルが建国されると、アラブ諸国はこれを認めず【第1次中東戦争(パレスチナ戦争)】が起こりましたが、アラブ側は敗れました。この敗北で王政への不満が高まり、1952年に【ナギブ】や【ナセル】ら【自由将校団】が【エジプト革命】を起こして王政を倒し、翌年共和政となりました。", "大統領となったナセルは、【アスワン=ハイダム】建設の資金を得るため1956年に【スエズ運河の国有化】を宣言しました。これに反発したイギリス・フランス・イスラエルがエジプトに出兵し、【第2次中東戦争(スエズ戦争)】が起こりました。しかし、アメリカとソ連がともに英仏の行動を非難し、国連も停戦を求めたため、3国は撤退に追い込まれました。軍事的には劣勢だったエジプトが政治的には勝利したことで、ナセルはアラブ民族主義の英雄となり、1958年にはシリアと合同して【アラブ連合共和国】を結成しました(1961年にシリアが離脱)。ナセルは【非同盟】の立場をとり、インドのネルーらとともに第三世界のリーダーとして活躍しました。", "ところが1967年の【第3次中東戦争(6日戦争)】でエジプトは大敗し、シナイ半島をイスラエルに占領されました。ナセルの死後に大統領となった【サダト】は、1973年の【第4次中東戦争】で緒戦に善戦し、アラブ産油国はイスラエル寄りの国に石油輸出を制限する【石油戦略】をとって【第1次石油危機】を引き起こしました。その後サダトはアメリカに接近し、1978年の【キャンプ=デーヴィッド合意】、翌年の【エジプト=イスラエル平和条約】でイスラエルと和解し、1982年までにシナイ半島を取り戻しました。しかしこの単独和平はアラブ諸国の反発を招き、サダトは1981年に暗殺されました。"]}, {"t": "現代のアラブ世界", "p": ["サダトの後を継いだ【ムバラク】は親米路線と長期政権を続けました。一方、アラブ世界全体では、イランの【イラン=イスラーム革命】(1979年)の影響も受けてイスラーム復興の動きが強まり、世俗的な民族主義に代わってイスラームを政治の基礎に置こうとする勢力が力を伸ばしました。1990年にはイラクの【フセイン】政権がクウェートに侵攻し、翌年アメリカ中心の多国籍軍との間で【湾岸戦争】が起こりました。さらに2003年には【イラク戦争】でフセイン政権が倒されています。", "2010年末にチュニジアで始まった民主化要求運動は【アラブの春】とよばれて各地に広がり、エジプトでも2011年にムバラク政権が崩壊しました。しかしその後の政治は安定せず、シリアでは内戦が長期化するなど、アラブ世界は今も大きな課題を抱えています。古代文明、イスラームの中心、ヨーロッパの帝国主義、民族主義と冷戦、そして宗教と民主化という、それぞれの時代の世界の大きな動きが、エジプトとアラブ世界には重なって現れているのです。"]}], "points": ["古王国(メンフィス・ピラミッド)→中王国→新王国(テーベ・ヒクソス追放・アメンホテプ4世のアトン信仰)の区別", "プトレマイオス朝の都アレクサンドリアとムセイオン、前30年の滅亡", "ファーティマ朝(シーア派・カイロ建設・アズハル学院)→アイユーブ朝(サラディン・イェルサレム奪回)→マムルーク朝(バイバルス・アイン=ジャールート)", "ムハンマド=アリーの近代化とエジプト=トルコ戦争、列強の干渉", "スエズ運河(1869年開通・レセップス)→ディズレーリの株買収(1875年)→ウラービー運動(1881年)→イギリスの占領", "フセイン・マクマホン協定・サイクス・ピコ協定・バルフォア宣言の矛盾", "ナセルのスエズ運河国有化(1956年)と第2次中東戦争、サダトのキャンプ=デーヴィッド合意(1978年)"], "check": [["エジプト新王国でアトン一神教を強制した王は?", "アメンホテプ4世"], ["プトレマイオス朝を滅ぼしたローマの勝利となった前31年の海戦は?", "アクティウムの海戦"], ["969年にファーティマ朝が建設した都は?", "カイロ"], ["1187年にイェルサレムを奪回したアイユーブ朝の建国者は?", "サラーフ=アッディーン(サラディン)"], ["1260年にモンゴル軍を破ったマムルーク朝の軍人は?", "バイバルス"], ["1517年にマムルーク朝を滅ぼしたオスマン帝国のスルタンは?", "セリム1世"], ["エジプトで近代化を進め、オスマン帝国から事実上自立した総督は?", "ムハンマド=アリー"], ["1881年に「エジプト人のためのエジプト」を掲げて起こった運動は?", "ウラービー運動"], ["1956年にスエズ運河の国有化を宣言した大統領は?", "ナセル"], ["1978年にエジプトとイスラエルが和平に合意した合意は?", "キャンプ=デーヴィッド合意"]], "related": ["t_ori", "t_ps", "t_tr", "t_ir", "t_af", "t_uk", "t_fr", "t_byz", "y_7", "y_12", "y_13", "y_19", "y_20b"], "n": 5662, "videos": [{"title": "【世界史】 イスラーム世界１ ムハンマド時代 （１８分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=_2Yx0ZG9xfU", "note": "ムハンマドの時代を扱い、アラブ・イスラーム史の出発点を押さえられます。"}]}, "t_ps": {"title": "イスラエル・パレスチナ史", "span": "前1500年ごろ〜現在", "year": 1948, "lead": "地中海東岸のパレスチナは、ユダヤ教・キリスト教・イスラームという三つの一神教の聖地イェルサレムをかかえ、古代から多くの帝国が争奪した土地です。古代ヘブライ人の王国が滅んだのち、ユダヤ人は各地に離散しましたが、19世紀末のシオニズムとイギリスの矛盾した外交を経て1948年にイスラエルが建国され、追われたパレスチナ人との対立は中東戦争と和平の試みを繰り返しながら現在まで続いています。", "flow": ["前13世紀ごろ モーセに率いられたヘブライ人の出エジプト(伝承)→パレスチナに定住", "前10世紀 ダヴィデ・ソロモン王の繁栄→死後イスラエル王国とユダ王国に分裂", "前722年 アッシリアがイスラエル王国を滅ぼす", "前586年 新バビロニアがユダ王国を滅ぼす→バビロン捕囚→ユダヤ教の成立", "前538年 アケメネス朝が解放→帰国して神殿再建", "1世紀 ローマ支配下でイエスが活動→キリスト教成立、66年ユダヤ戦争→ユダヤ人の離散(ディアスポラ)", "638年ごろ アラブ=イスラーム軍がイェルサレムを支配→岩のドーム", "1099年 第1回十字軍がイェルサレム王国→1187年サラディンが奪回", "1516〜17年 オスマン帝国の支配", "1897年 第1回シオニスト会議→1917年バルフォア宣言、イギリスの委任統治", "1948年 イスラエル建国→第1次中東戦争、パレスチナ難民", "1993年 オスロ合意(パレスチナ暫定自治協定)→その後も対立が続く"], "sync": [], "secs": [{"t": "古代 ― ヘブライ人の王国と一神教", "p": ["パレスチナは、メソポタミアからシリアにかけての【肥沃な三日月地帯】の西の端にあたり、エジプトとメソポタミアという二大文明を結ぶ通り道でした。そのため古くから多くの民族が行き交い、強国の争奪の対象となってきました。「パレスチナ」という地名は、前12世紀ごろ地中海沿岸に住み着いた「海の民」系の【ペリシテ人】に由来するといわれます。", "この地に定住し、唯一神【ヤハウェ】を信仰したのが、セム語系の【ヘブライ人】です。伝承では、一部のヘブライ人はエジプトで苦役を課されましたが、指導者【モーセ】に率いられて脱出しました。これを【出エジプト】といい、このとき神から【十戒】を授かったとされます。ヘブライ人は前11世紀末ごろ王国をつくり、【ダヴィデ王】とその子【ソロモン王】の時代に最盛期を迎え、イェルサレムには壮大な神殿が建てられました。", "しかしソロモン王の死後、王国は北の【イスラエル王国】と南の【ユダ王国】に分裂しました。イスラエル王国は前722年に【アッシリア】に滅ぼされ、ユダ王国も前586年に【新バビロニア】の【ネブカドネザル2世】に滅ぼされて、住民の多くが都バビロンに連れ去られました。これを【バビロン捕囚】といいます。", "国を失い異国に連れ去られた苦しみの中で、人々は自分たちだけが神に選ばれた民であり、やがて救世主【メシア】が現れて救われるという信仰を強めました。こうして唯一神ヤハウェへの信仰は、選民思想・メシア信仰を特色とする【ユダヤ教】としてまとまっていきます。前538年、新バビロニアを滅ぼしたアケメネス朝の【キュロス2世】によって解放された人々はイェルサレムに戻って神殿を再建しました。この信仰を受け継ぐ人々が、以後【ユダヤ人】とよばれるようになります。ユダヤ教の聖典は、のちにキリスト教の『旧約聖書』となりました。"]}, {"t": "ローマ支配とキリスト教の誕生、ユダヤ人の離散", "p": ["その後パレスチナはアレクサンドロス大王の帝国、セレウコス朝などの支配を経て、前1世紀にはローマの支配下に入りました。ローマの支配とユダヤ教の祭司たちの形式的な律法主義に人々が苦しむ中で、【イエス】が神の愛と隣人愛を説きました。イエスはローマへの反逆者として十字架にかけられましたが、弟子たちはイエスの復活を信じ、彼こそがメシア(ギリシア語でキリスト)であると説きました。こうして生まれた【キリスト教】は、【ペテロ】や【パウロ】の伝道によってユダヤ人以外にも広まり、ローマ帝国の世界宗教となっていきます。", "一方、ユダヤ人はローマへの反乱を起こしました。66年に始まる【ユダヤ戦争】は鎮圧され、70年にイェルサレムの神殿は破壊されました。2世紀前半の反乱も鎮められると、ユダヤ人はイェルサレムへの立ち入りを禁じられ、地中海世界の各地に散らばって暮らすことになりました。これを【ディアスポラ(離散)】といいます。ユダヤ人は国家を持たないまま、ユダヤ教の信仰と律法を支えに共同体を守り続けました。このことが、のちのヨーロッパでの差別と迫害、そして近代のシオニズムの背景となります。"]}, {"t": "イスラームの聖地と十字軍", "p": ["ローマ帝国のキリスト教化ののち、パレスチナはビザンツ帝国の支配を受けましたが、7世紀には正統カリフ時代のアラブ=イスラーム軍がシリア・パレスチナを征服しました。イェルサレムはムハンマドが昇天したと伝えられる場所として、メッカ・メディナに次ぐイスラームの聖地とされ、ウマイヤ朝の時代に【岩のドーム】が建てられました。こうしてイェルサレムは、ユダヤ教・キリスト教・イスラームの三つの宗教の聖地となったのです。以後、パレスチナの住民の多くはアラビア語を話すムスリムとなっていきましたが、キリスト教徒やユダヤ教徒も共存していました。", "11世紀、トルコ系の【セルジューク朝】がイェルサレムを支配し、ビザンツ帝国を圧迫すると、ビザンツ皇帝は教皇に救援を求めました。教皇【ウルバヌス2世】は1095年の【クレルモン宗教会議】で聖地回復を呼びかけ、【第1回十字軍】は1099年にイェルサレムを占領して【イェルサレム王国】を建てました。しかし1187年、アイユーブ朝の【サラーフ=アッディーン(サラディン)】がイェルサレムを奪回し、その後の十字軍も聖地を長く確保することはできませんでした。13世紀末には、マムルーク朝が十字軍の最後の拠点アッコンを攻略しています。", "16世紀初め、オスマン帝国の【セリム1世】がマムルーク朝を滅ぼすと、パレスチナはオスマン帝国の支配下に入り、以後約400年間その統治が続きました。", "オスマン帝国のもとでは、【ミッレト】とよばれる宗教共同体ごとに一定の自治が認められ、ムスリム・キリスト教徒・ユダヤ教徒がそれぞれの法と慣習に従って暮らしていました。帝国が衰えた19世紀には、聖地の管理権をめぐってフランスやロシアが干渉し、これが【クリミア戦争】の一因となりました。また、ヨーロッパ列強がオスマン帝国内のキリスト教徒の保護を口実に進出するようになり、パレスチナは再び列強の関心を集める土地となっていきました。"]}, {"t": "シオニズムとイギリスの三枚舌外交", "p": ["19世紀のヨーロッパでは、国民国家の形成とともにユダヤ人を異分子とみなす【反ユダヤ主義】が強まりました。ロシアでは【ポグロム】とよばれるユダヤ人への集団的な迫害が起こり、フランスではユダヤ系軍人がスパイの疑いをかけられた【ドレフュス事件】が社会を揺るがしました。この事件に衝撃を受けたジャーナリスト【ヘルツル】は、ユダヤ人が自らの国家を持つべきだと主張し、1897年に【第1回シオニスト会議】を開きました。古代の故地パレスチナ(シオンの丘)にユダヤ人国家を建設しようとするこの運動を【シオニズム】といいます。", "第一次世界大戦が始まると、オスマン帝国と戦うイギリスは、さまざまな勢力の協力を得るために互いに矛盾する約束を結びました。1915年の【フセイン・マクマホン協定】ではアラブ人に独立を約束し、1916年の【サイクス・ピコ協定】では英仏露で旧オスマン領の分割を取り決め、1917年の【バルフォア宣言】ではユダヤ人にパレスチナでの「民族的郷土」の建設への支持を表明しました。これらはしばしば【三枚舌外交】とよばれます。", "戦後、パレスチナはイギリスの【委任統治領】となりました。バルフォア宣言を背景にユダヤ人の移住が進むと、土地を失うことを恐れるアラブ系住民(パレスチナ人)との衝突が繰り返されました。1930年代にナチス=ドイツがユダヤ人迫害を強めると移民はさらに増え、対立は激化しました。第二次世界大戦中のナチスによるユダヤ人の大量虐殺【ホロコースト】は、ユダヤ人国家の建設を求める国際世論を強めることになりました。"]}, {"t": "イスラエル建国と中東戦争", "p": ["第二次世界大戦後、イギリスはパレスチナ問題を国連にゆだね、1947年に国連総会は【パレスチナ分割案】を採択しました。この案はユダヤ人に有利な内容だったため、アラブ側は反発しました。1948年、イギリスの委任統治が終わると同時にユダヤ人は【イスラエル】の建国を宣言し、これを認めないエジプトなどのアラブ諸国との間で【第1次中東戦争(パレスチナ戦争)】が起こりました。アメリカなどの支援を受けたイスラエルが勝利して領土を広げた結果、多数のパレスチナ人が故郷を追われて【パレスチナ難民】となりました。ここに、現在まで続く【パレスチナ問題】が本格的に始まります。", "1956年には、エジプトのナセルによるスエズ運河国有化に対して、イギリス・フランスとともにイスラエルがエジプトに出兵しました(【第2次中東戦争】)。1964年にはパレスチナ人の組織【パレスチナ解放機構(PLO)】が結成され、のちに【アラファト】が議長となって武装闘争を進めました。1967年の【第3次中東戦争(6日戦争)】でイスラエルは圧勝し、エジプトの【シナイ半島】、シリアの【ゴラン高原】、ヨルダン川西岸と【ガザ地区】、東イェルサレムを占領しました。これによりさらに多くのパレスチナ人が占領下に置かれることになります。", "1973年の【第4次中東戦争】では、エジプト・シリアが緒戦で善戦し、アラブ産油国の石油戦略によって【第1次石油危機】が起こりました。中東の対立が世界経済を揺るがすことが明らかになったのです。その後エジプトのサダトはイスラエルとの和解に転じ、1978年の【キャンプ=デーヴィッド合意】を経てシナイ半島はエジプトに返還されました。しかしパレスチナ人の問題は解決されず、イスラエルは占領地にユダヤ人の【入植地】を建設していきました。", "第1次中東戦争の結果、パレスチナのうちヨルダン川西岸はヨルダンが、ガザ地区はエジプトが管理することになり、パレスチナ人自身の国家はつくられませんでした。周辺のアラブ諸国に逃れた難民は難民キャンプでの生活を強いられ、その子や孫の世代まで故郷に帰れない状態が続いています。難民の帰還をどう扱うかは、今も和平交渉の最大の争点の一つです。"]}, {"t": "和平の模索と現在", "p": ["1987年、占領地のパレスチナ人は【インティファーダ】とよばれる民衆蜂起を始めました。冷戦の終結で国際情勢が変わる中、1993年にイスラエルの【ラビン】首相とPLOのアラファト議長は、ノルウェーの仲介で【パレスチナ暫定自治協定(オスロ合意)】に調印しました。イスラエルとPLOは互いの存在を認め合い、ガザ地区とヨルダン川西岸の一部でパレスチナ人の暫定自治が始まりました。", "しかし1995年にラビン首相がユダヤ人の過激派に暗殺され、イェルサレムの帰属、難民の帰還、入植地の扱いといった難題をめぐって交渉は行き詰まりました。2000年代には再び衝突が激化し、イスラエルは西岸に【分離壁】を建設しました。ガザ地区ではイスラーム主義組織【ハマス】が実権を握り、イスラエルとの間で武力衝突が繰り返されています。", "このように、イスラエル・パレスチナ問題は、古代以来の宗教的な聖地の問題に、近代ヨーロッパの反ユダヤ主義、イギリスの帝国主義外交、冷戦期の大国の思惑が重なって生まれたものです。一つの土地に二つの民族がそれぞれの国家を求めるという構図は、今も解決の道筋が見えないまま続いています。"]}], "points": ["ヘブライ人の王国分裂:北のイスラエル王国(前722年アッシリアが滅ぼす)と南のユダ王国(前586年新バビロニアが滅ぼす)", "バビロン捕囚→選民思想・メシア信仰をもつユダヤ教の成立、キュロス2世による解放", "ディアスポラ(離散)とヨーロッパの反ユダヤ主義、ドレフュス事件とヘルツルのシオニズム", "フセイン・マクマホン協定(1915年)・サイクス・ピコ協定(1916年)・バルフォア宣言(1917年)の矛盾", "1947年国連のパレスチナ分割案→1948年イスラエル建国→第1次中東戦争とパレスチナ難民", "第3次中東戦争(1967年)で占領された地域:シナイ半島・ゴラン高原・ヨルダン川西岸・ガザ地区", "PLO(1964年結成・アラファト)とオスロ合意(1993年)"], "check": [["ヘブライ人を率いてエジプトを脱出したとされる指導者は?", "モーセ"], ["前586年にユダ王国を滅ぼした国は?", "新バビロニア"], ["バビロン捕囚からユダヤ人を解放したアケメネス朝の王は?", "キュロス2世"], ["ローマ支配期にユダヤ人が各地に離散したことを何という?", "ディアスポラ"], ["ウマイヤ朝時代にイェルサレムに建てられた聖堂は?", "岩のドーム"], ["1897年に第1回シオニスト会議を開いた人物は?", "ヘルツル"], ["1917年、イギリスがユダヤ人の民族的郷土建設を支持した宣言は?", "バルフォア宣言"], ["1964年に結成されたパレスチナ人の組織は?", "パレスチナ解放機構(PLO)"], ["1987年に始まった占領地のパレスチナ人の民衆蜂起は?", "インティファーダ"], ["1993年にイスラエルとPLOが結んだ協定は?", "パレスチナ暫定自治協定(オスロ合意)"]], "related": ["t_ori", "t_ar", "t_ro", "t_tr", "t_uk", "y_bc10", "y_bc6", "y_1", "y_11", "y_12", "y_20a", "y_20b", "y_21"], "n": 4114, "videos": [{"title": "【世界史】 現在の世界２ パレスチナ問題の行方 （１１分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=M0df9JzEB5E", "note": "パレスチナ問題のその後の展開を確認できます。"}]}, "t_af": {"title": "アフリカ史", "span": "前1000年ごろ〜現在", "year": 1960, "lead": "サハラ以南のアフリカには、ナイル上流のクシュ王国やエチオピアのアクスム王国、金と塩の交易で栄えた西アフリカの諸王国、インド洋交易で栄えた東アフリカのスワヒリ都市など、独自の国家と文明が展開しました。しかし大西洋奴隷貿易と19世紀末の列強による分割で大陸のほとんどが植民地となり、1960年の「アフリカの年」を頂点に独立を達成したのちも、植民地時代の国境や経済構造が残した課題と向き合い続けています。", "flow": ["前10世紀ごろ ナイル上流にクシュ王国→前8世紀にエジプトを支配、のちメロエに遷都(製鉄)", "紀元前後〜 エチオピアにアクスム王国→4世紀にキリスト教を受容", "8世紀ごろ〜 西アフリカでガーナ王国が金と塩の交易で繁栄→11世紀ムラービト朝の攻撃で衰退", "13〜14世紀 マリ王国(マンサ=ムーサ)、15〜16世紀ソンガイ王国→トンブクトゥの繁栄", "10世紀ごろ〜 東アフリカ沿岸でスワヒリ文化、内陸にジンバブエの石造遺跡", "15世紀末 ポルトガルが喜望峰に到達→16〜19世紀大西洋奴隷貿易(三角貿易)", "1652年 オランダがケープ植民地→1815年イギリス領に", "1884〜85年 ベルリン会議→アフリカ分割(イギリスの縦断政策、フランスの横断政策)", "1898年 ファショダ事件、1899年南アフリカ戦争、エチオピアとリベリアのみ独立維持", "1957年 ガーナ独立→1960年「アフリカの年」、1963年アフリカ統一機構(OAU)", "1994年 南アフリカでアパルトヘイト撤廃後マンデラが大統領に→2002年アフリカ連合(AU)"], "sync": [], "secs": [{"t": "古代 ― ナイル上流とエチオピアの王国", "p": ["アフリカは人類誕生の地とされ、古代からナイル川下流のエジプト文明が栄えたことはよく知られています(エジプトについては「アラブ・エジプト史」を参照)。サハラ砂漠より南の地域にも、早くから独自の国家が生まれていました。", "エジプトの南、ナイル川上流のヌビア地方には、黒人系の【クシュ王国】が成立しました。クシュ王国はエジプト文化の影響を強く受け、前8世紀には一時エジプトを征服して王朝を開きました。その後アッシリアに追われて南方に退き、都を【メロエ】に移しました。メロエは鉄鉱石と燃料の木材に恵まれ、【製鉄】が盛んになったことで知られ、独自の【メロエ文字】もつくられました。", "紀元前後ごろには、エチオピア高原に【アクスム王国】が成立しました。アクスム王国は紅海交易で栄え、4世紀にはキリスト教を受け入れて、メロエを攻撃したとされます。エチオピアのキリスト教は、のちにイスラーム勢力に囲まれながらも独自の教会として受け継がれ、エチオピアが近代まで独立を保つ精神的な支えの一つとなりました。", "また、西アフリカから中部・南部にかけては、【バントゥー語系】の人々が鉄器と農耕を携えて長い時間をかけて移動・拡散していったと考えられています。こうしてアフリカ各地に多様な社会が形づくられていきました。"]}, {"t": "西アフリカの王国 ― 金と塩の交易とイスラーム", "p": ["西アフリカのニジェール川流域は金を豊富に産しました。一方、サハラ砂漠では岩塩がとれ、北アフリカのムスリム商人はラクダの隊商を組んでサハラを越え、塩や北方の産物を運んで金と交換しました。この【サハラ縦断交易(金と塩の交易)】で栄えたのが【ガーナ王国】です。ガーナ王国は8世紀ごろには繁栄していたとされますが、11世紀後半に北アフリカのベルベル人の王朝【ムラービト朝】の攻撃を受けて衰退したとされ、これをきっかけに西アフリカのイスラーム化が進みました。", "13世紀に成立した【マリ王国】は、ガーナに代わって金の交易を支配しました。14世紀前半の王【マンサ=ムーサ】はイスラームを篤く信仰し、メッカ巡礼の途中、カイロで大量の金を使ったため金の相場が下がったと伝えられます。この話は、マリ王国の豊かさがイスラーム世界に広く知られていたことを示しています。ニジェール川中流の交易都市【トンブクトゥ】はモスクや学問の施設を備え、イスラームの学術都市として栄えました。14世紀には旅行家【イブン=バットゥータ】もマリを訪れています。", "15世紀後半から16世紀にかけては【ソンガイ王国】が最盛期を迎え、トンブクトゥを支配しました。しかし16世紀末にモロッコの攻撃を受けて衰退しました。西アフリカの王国が栄えたのは、金という世界的な商品と、それを地中海世界と結ぶムスリム商人のネットワークがあったからでした。このネットワークを通じて、イスラームの信仰やアラビア文字も西アフリカに広まりました。"]}, {"t": "東アフリカ・南部アフリカとインド洋交易", "p": ["東アフリカの沿岸部では、季節風(【モンスーン】)を利用したインド洋交易が早くから行われていました。10世紀ごろからはムスリム商人が多く訪れ、【モガディシュ】【マリンディ】【モンバサ】【キルワ】などの港市が栄えました。これらの都市では、現地の【バントゥー語】にアラビア語の影響が加わって【スワヒリ語】が生まれ、イスラームを受け入れた独自の【スワヒリ文化】が形成されました。15世紀初めには明の【鄭和】の艦隊がマリンディまで来航し、15世紀末にはポルトガルの【ヴァスコ=ダ=ガマ】がマリンディでインド洋の水先案内人を得てインドに向かいました。", "南部アフリカの内陸では、ザンベジ川の南に【モノモタパ王国】が栄え、金などを沿岸の港市に送ってインド洋交易と結びついていました。この地域に残る巨大な石造建築の遺跡【大ジンバブエ遺跡】は、こうした交易で栄えた社会の繁栄を物語っています。のちに独立したジンバブエの国名は、この遺跡に由来しています。"]}, {"t": "大西洋奴隷貿易の時代", "p": ["15世紀、ポルトガルは【エンリケ航海王子】のもとでアフリカ西岸の探検を進め、1488年には【バルトロメウ=ディアス】が南端の【喜望峰】に到達しました。こうしてヨーロッパ人がアフリカ沿岸に拠点を築くようになると、アフリカの歴史は大きく変わります。", "16世紀以降、アメリカ大陸ではスペインやポルトガルの支配によって先住民の人口が激減し、さらに17世紀以降はカリブ海やブラジル、北アメリカ南部で【サトウキビ】や【綿花】などの【プランテーション】が拡大しました。その労働力として、アフリカから大量の黒人が奴隷として運ばれました。ヨーロッパから武器や綿織物などをアフリカに運び、アフリカで奴隷を手に入れてアメリカへ運び、アメリカの砂糖などをヨーロッパに持ち帰る【三角貿易】が、イギリスなどに莫大な利益をもたらしました。", "アフリカ西岸には、奴隷を供給することで武器を手に入れて勢力を伸ばした【ダホメ王国】などの国もありましたが、全体としては、働き盛りの多くの人々が失われ、地域間の戦争も激化して、アフリカの社会と経済は深い傷を負いました。この時期のヨーロッパの繁栄と資本の蓄積は、アフリカの犠牲の上に成り立っていた面があるのです。19世紀に入るとイギリスなどで奴隷貿易・奴隷制の廃止が進みましたが、それはアフリカがヨーロッパの支配から解放されることを意味しませんでした。", "南端では、1652年にオランダが【ケープ植民地】を建設し、オランダ系移民(【ブール人】、アフリカーナー)が入植しました。ケープ植民地は【ウィーン議定書】で1815年にイギリス領となり、イギリスの支配を嫌ったブール人は北方に移動して【トランスヴァール共和国】と【オレンジ自由国】を建てました。"]}, {"t": "列強によるアフリカ分割", "p": ["19世紀半ばまで、ヨーロッパ人にとってアフリカ内陸部はよく知られていませんでした。イギリスの宣教師【リヴィングストン】はアフリカ横断を探検し、彼を捜索した【スタンリー】はコンゴ地域を探検しました。スタンリーの探検をもとにベルギー国王レオポルド2世がコンゴに進出しようとしたことなどから、列強の対立が強まりました。そこでドイツのビスマルクは1884〜85年に【ベルリン会議(ベルリン=コンゴ会議)】を開き、コンゴを国王の私有地【コンゴ自由国】とすることを認めるとともに、先に実効支配した国が領有できるという原則を確認しました。これをきっかけに、列強は先を争ってアフリカの分割に乗り出しました。", "イギリスは、1882年にエジプトを事実上保護下に置き、北のカイロと南のケープタウンを結ぶ【アフリカ縦断政策】を進めました。ケープ植民地首相の【セシル=ローズ】はその推進者で、植民相【ジョゼフ=チェンバレン】のもとで1899年に金やダイヤモンドを産するブール人の国々を征服しようとして【南アフリカ戦争(ブール戦争)】を起こしました。イギリスは苦戦の末に勝利し、1910年に自治領【南アフリカ連邦】を成立させました。", "一方フランスは、アルジェリア(1830年に出兵)からサハラ砂漠を経て東のジブチ・マダガスカルにつなげる【アフリカ横断政策】を進めました。両国の政策は1898年にスーダンの【ファショダ事件】で衝突しかけましたが、フランスが譲歩し、これを機に両国は接近して1904年の【英仏協商】に至ります。ドイツはカメルーンや東アフリカなどを得て、モロッコをめぐってフランスと対立しました(【モロッコ事件】)。イタリアはエチオピアに進出しましたが、1896年の【アドワの戦い】で敗れ、のちにリビアを獲得しました。", "こうして20世紀初めまでに、アフリカで独立を保ったのは【エチオピア】と【リベリア】だけとなりました。分割は現地の民族や文化の分布を無視して、緯線・経線などを使った直線的な国境で行われたため、のちの独立国家にも民族対立などの問題を残すことになりました。各地では、ドイツ領東アフリカの【マジ=マジ反乱】のような抵抗運動も起こりましたが、近代兵器を持つ列強に鎮圧されました。"]}, {"t": "独立への道 ― 「アフリカの年」", "p": ["第一次世界大戦後、アフリカ出身者やアメリカの黒人知識人たちによって、アフリカの解放と黒人の連帯をめざす【パン=アフリカ主義】の運動が広がりました。1935年にはイタリアのムッソリーニがエチオピアに侵攻し、翌年併合しましたが、国際連盟はこれを止められませんでした。", "第二次世界大戦で宗主国のイギリス・フランスが疲弊し、アジア諸国の独立が相次ぐと、アフリカでも独立の動きが本格化しました。北アフリカでは1950年代にリビア・モロッコ・チュニジアなどが独立し、1957年には【エンクルマ(ンクルマ)】の指導で【ガーナ】が、サハラ以南で黒人を主体とする国として初めて自力で独立を達成しました。1960年には一挙に17か国が独立し、この年は【アフリカの年】とよばれます。1963年にはアフリカ諸国の連帯をめざして【アフリカ統一機構(OAU)】が結成されました。", "一方、多くのフランス人入植者がいた【アルジェリア】では、1954年から激しい独立戦争が続き、フランス本国の政治も揺るがして第五共和政の成立につながりました。アルジェリアは1962年に独立を達成しました。ベルギー領【コンゴ】では1960年の独立直後に内乱(【コンゴ動乱】)が起こり、豊富な鉱物資源をめぐって旧宗主国や大国が介入しました。ポルトガル領のアンゴラやモザンビークの独立は1970年代までずれこみました。"]}, {"t": "独立後の課題と現代のアフリカ", "p": ["独立後のアフリカ諸国は多くの困難を抱えました。植民地時代に引かれた国境の中にはさまざまな民族が含まれていたため、民族対立や内戦が起こりやすく、ナイジェリアの【ビアフラ戦争】や、1994年の【ルワンダ内戦】での大量虐殺のような悲劇も起こりました。また、植民地時代につくられた特定の農産物や鉱産物の輸出に頼る【モノカルチャー経済】が続き、先進国との経済格差(【南北問題】)や累積債務に苦しむ国も少なくありません。冷戦期には米ソが各地の政権や反政府勢力を支援したことも、紛争を長引かせました。", "南アフリカでは、白人政権が少数の白人の支配を守るため、住む場所や結婚、教育などあらゆる面で人種を分ける【アパルトヘイト(人種隔離政策)】を行いました。これに対して黒人の【アフリカ民族会議(ANC)】が抵抗を続け、国際社会も経済制裁で圧力をかけました。1991年にアパルトヘイト関連法が撤廃され、1994年には全人種が参加した選挙で、長く投獄されていた【マンデラ】が黒人初の大統領となりました。", "2002年にはOAUが発展して【アフリカ連合(AU)】が発足し、地域の紛争解決や経済統合に取り組んでいます。21世紀のアフリカは人口が急増し、資源開発をめぐって中国などの進出も目立っています。古代から交易を通じて世界とつながってきたアフリカは、奴隷貿易と植民地支配という苦難を経て、今は自らの手で発展の道を切り開こうとしているのです。"]}], "points": ["クシュ王国(メロエで製鉄・メロエ文字)とアクスム王国(4世紀キリスト教受容)", "西アフリカの王国の順序:ガーナ王国→マリ王国(マンサ=ムーサ)→ソンガイ王国、交易都市トンブクトゥ", "金と塩のサハラ縦断交易とムラービト朝による西アフリカのイスラーム化", "東アフリカのスワヒリ語・スワヒリ文化と港市マリンディ、モノモタパ王国と大ジンバブエ遺跡", "大西洋三角貿易と奴隷貿易がアフリカに与えた影響", "ベルリン会議(1884〜85年)→イギリスの縦断政策とフランスの横断政策→ファショダ事件(1898年)", "独立を保った国:エチオピア(アドワの戦い1896年)とリベリア", "ガーナ独立(1957年・エンクルマ)、アフリカの年(1960年)、OAU(1963年)、マンデラ大統領(1994年)"], "check": [["メロエに都を移し、製鉄で栄えたナイル上流の王国は?", "クシュ王国"], ["4世紀にキリスト教を受け入れたエチオピアの王国は?", "アクスム王国"], ["メッカ巡礼で大量の金を用いたマリ王国の王は?", "マンサ=ムーサ"], ["マリ王国・ソンガイ王国のもとで学術都市として栄えたニジェール川中流の都市は?", "トンブクトゥ"], ["バントゥー語にアラビア語の影響が加わって成立した言語は?", "スワヒリ語"], ["1884〜85年にアフリカ分割の原則を話し合った会議は?", "ベルリン会議(ベルリン=コンゴ会議)"], ["1898年にイギリスとフランスがスーダンで衝突しかけた事件は?", "ファショダ事件"], ["1896年にエチオピアがイタリアを破った戦いは?", "アドワの戦い"], ["1957年にガーナを独立に導いた指導者は?", "エンクルマ(ンクルマ)"], ["南アフリカで行われた人種隔離政策は?", "アパルトヘイト"]], "related": ["t_ar", "t_uk", "t_fr", "t_es", "t_la", "t_us", "y_14", "y_16", "y_19", "y_20b", "y_21"], "n": 4426, "videos": [{"title": "【世界史】 列強の世界分割１ アフリカ分割開始 （１７分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=bX0ux4gTk4M", "note": "列強のアフリカ分割の始まりを学べ、2026年度第2問Ｃ（植民地化と法）の背景知識になります。"}]}, "t_in": {"title": "インド史", "span": "前2600年ごろ〜現在", "year": 1947, "lead": "インダス文明に始まるインドの歴史は、アーリヤ人の進入とヴァルナ制の成立、仏教・ジャイナ教の誕生、マウリヤ朝・グプタ朝による統一を経て、ヒンドゥー教を中心とする社会を形づくりました。中世以降はイスラーム勢力が北インドを支配し、ムガル帝国のもとでインド=イスラーム文化が花開きましたが、18世紀からイギリスの植民地支配が進み、ガンディーらの民族運動を経て1947年にインドとパキスタンに分かれて独立しました。", "flow": ["前2600年ごろ インダス文明(モエンジョ=ダーロ・ハラッパー)", "前1500年ごろ アーリヤ人が進入→前1000年ごろガンジス川流域へ、ヴァルナ制・バラモン教", "前6世紀ごろ 都市国家の発展→仏教(ガウタマ=シッダールタ)・ジャイナ教(ヴァルダマーナ)の成立", "前4世紀末 マウリヤ朝がインド初の統一→アショーカ王のダルマの政治", "1世紀ごろ クシャーナ朝(カニシカ王)→大乗仏教・ガンダーラ美術", "320年ごろ グプタ朝→ヒンドゥー教の確立、サンスクリット文学", "7世紀前半 ハルシャ王のヴァルダナ朝→玄奘が訪れる", "1206年 奴隷王朝→デリー=スルタン朝、イスラーム化の進展", "1526年 バーブルがムガル帝国を建国→アクバルの融和政策、アウラングゼーブの厳格化", "1757年 プラッシーの戦い→イギリス東インド会社の支配拡大", "1857年 インド大反乱→1858年ムガル帝国滅亡・東インド会社解散、1877年インド帝国", "1885年 インド国民会議→ガンディーの非暴力・不服従→1947年インド・パキスタン分離独立"], "sync": [], "secs": [{"t": "インダス文明とアーリヤ人", "p": ["前2600年ごろ、インダス川流域に【インダス文明】が栄えました。代表的な都市遺跡であるシンド地方の【モエンジョ=ダーロ】やパンジャーブ地方の【ハラッパー】は、焼きれんがでつくられた計画的な都市で、排水路や【大沐浴場】をもっていました。印章に刻まれた【インダス文字】は現在も解読されていません。インダス文明は前1800年ごろまでに衰退しましたが、その原因ははっきりしていません。", "前1500年ごろ、中央アジアからインド=ヨーロッパ語系の【アーリヤ人】がカイバル峠をこえて西北インドの【パンジャーブ地方】に進入しました。彼らは自然神を崇拝し、神々への賛歌を集めた最古の聖典【リグ=ヴェーダ】をつくりました。前1000年ごろからアーリヤ人は鉄器を使って東方の【ガンジス川流域】に進出し、農耕社会を築きました。", "この過程で、司祭の【バラモン】、王侯・武士の【クシャトリヤ】、農民・牧畜民(のち主に商人)の【ヴァイシャ】、隷属民の【シュードラ】の4つの身分からなる【ヴァルナ制】が形づくられました。のちに世襲の職業や婚姻の範囲を共有する集団【ジャーティ】が多数生まれ、ヴァルナと結びついて、現在【カースト制度】とよばれる身分制度となりました。ヴェーダを聖典とし、バラモンが祭式を独占する宗教を【バラモン教】といいます。"]}, {"t": "新しい宗教の誕生とマウリヤ朝の統一", "p": ["前6世紀ごろ、ガンジス川流域では商工業が発展して都市国家が成長し、【マガダ国】や【コーサラ国】などが有力となりました。経済力をつけたクシャトリヤやヴァイシャは、祭式を独占するバラモンの権威に不満をもつようになります。こうした中で、バラモン教の祭式主義を批判し、内面の思索を重んじる【ウパニシャッド哲学】が生まれ、宇宙の根本原理ブラフマンと個人の本体アートマンが一つであると悟る【梵我一如】が説かれました。", "さらに、ヴァルナの区別を否定する新しい宗教が生まれました。シャカ族の王子【ガウタマ=シッダールタ(ブッダ)】は、人生の苦しみからの解脱を求めて修行し、悟りを開いて【仏教】を説きました。正しい実践である【八正道】によって苦しみから解放されると説く教えは、身分にかかわらず救いを求める人々、特にクシャトリヤや商人に支持されました。同じころ【ヴァルダマーナ】は、厳しい苦行と【不殺生】を説いて【ジャイナ教】を開き、特にヴァイシャ(商人)に信者を得ました。", "前4世紀、【アレクサンドロス大王】が西北インドまで遠征すると、その混乱の中で【チャンドラグプタ】が【マウリヤ朝】を開き、都【パータリプトラ】を中心にインド最初の統一王朝を築きました。第3代の【アショーカ王】は、東インドの【カリンガ征服】で多くの犠牲を出したことを悔いて仏教に帰依し、倫理的な規範である【ダルマ(法)】による政治をめざしました。その方針は各地の【磨崖碑・石柱碑】に刻まれ、【第3回仏典結集】が行われたとされ、【スリランカ(セイロン島)】にも仏教が伝えられました。しかしアショーカ王の死後、帝国は急速に衰えました。"]}, {"t": "クシャーナ朝・グプタ朝 ― 仏教美術からヒンドゥー教へ", "p": ["1世紀ごろ、中央アジアから西北インドにかけてイラン系の【クシャーナ朝】が成立しました。都は【プルシャプラ】で、2世紀の【カニシカ王】の時代に最盛期を迎え、仏教を保護しました。この時代には、自分の解脱だけでなく広く人々の救済をめざす【大乗仏教】が盛んになり、【ナーガールジュナ(竜樹)】が「空」の思想で教理を体系化しました。また、ヘレニズム文化の影響を受けた【ガンダーラ美術】が栄え、初めて【仏像】がつくられました。大乗仏教は中央アジアから中国・朝鮮・日本へと伝わり、一方スリランカや東南アジアには個人の解脱を重んじる【上座部仏教】が広まりました。南インドでは【サータヴァーハナ朝】が季節風を利用したローマとの交易で栄え、【ローマ金貨】が多く出土しています。", "4世紀前半、【チャンドラグプタ1世】が北インドに【グプタ朝】を開き、【チャンドラグプタ2世】のときに最盛期を迎えました。この時代、バラモン教が民間信仰を吸収して、破壊と創造の神【シヴァ】や世界を維持する神【ヴィシュヌ】などを信仰する【ヒンドゥー教】が確立しました。ヴァルナごとの義務を定めた【マヌ法典】がまとめられ、二大叙事詩『【マハーバーラタ】』『【ラーマーヤナ】』が完成し、宮廷では【サンスクリット語】が公用語となって詩人【カーリダーサ】が戯曲『【シャクンタラー】』を書きました。【ゼロの概念】を含む数字表記や十進法もこの時代に発達し、のちにイスラーム世界を経てヨーロッパに伝わりました。仏教も保護され、【アジャンター石窟寺院】には純インド的な【グプタ様式】の壁画が残り、学問の中心【ナーランダー僧院】が創建されました。中国からは東晋の僧【法顕】が訪れています。", "5世紀後半から中央アジアの遊牧民【エフタル】の侵入を受けてグプタ朝は衰え、7世紀前半には【ハルシャ=ヴァルダナ】が北インドを統一しました。このとき唐の【玄奘】がナーランダー僧院で学び、『【大唐西域記】』を著しました。ハルシャ王の死後、北インドでは【ラージプート】とよばれるヒンドゥー諸勢力が分立し、仏教はヒンドゥー教におされて衰えていきました。神への絶対的な帰依を説く【バクティ運動】が広まったことも、ヒンドゥー教が民衆に浸透する力となりました。南インドでは、タミル系の【チョーラ朝】が海上交易で栄え、東南アジアにまで遠征しました。"]}, {"t": "イスラーム勢力の進出とデリー=スルタン朝", "p": ["10世紀末からは、アフガニスタンのトルコ系イスラーム王朝【ガズナ朝】が北インドへの侵入を繰り返し、12世紀末には【ゴール朝】が進出しました。ゴール朝のマムルーク(奴隷軍人)出身の武将【アイバク】は、1206年にデリーで独立して【奴隷王朝】を開きました。これ以後、デリーを都とした5つのイスラーム王朝(奴隷王朝・【ハルジー朝】・【トゥグルク朝】・サイイド朝・【ロディー朝】)を【デリー=スルタン朝】とよびます。デリーには高い塔【クトゥブ=ミナール】が建てられました。", "イスラーム教は支配者の強制というよりも、神との一体感を重んじる【スーフィズム(イスラーム神秘主義)】の聖者たちの活動を通じて、民衆の間にも広まりました。特にカーストの差別に苦しむ人々の中には、神の前の平等を説くイスラームに改宗する者もいました。一方、南インドでは14世紀にヒンドゥー教の【ヴィジャヤナガル王国】が成立し、イスラーム勢力と争いました。15世紀には【カビール】が偶像崇拝やカーストを否定して神の前の平等を説き、16世紀初めには【ナーナク】がヒンドゥー教とイスラーム教の融合をめざして【シク教】を開きました。"]}, {"t": "ムガル帝国 ― インド=イスラーム文化の花", "p": ["1526年、ティムールの子孫【バーブル】は【パーニーパットの戦い】でロディー朝を破り、【ムガル帝国】を建てました。帝国の基礎を固めたのは第3代【アクバル】です。アクバルは、官僚に位階を与えて騎兵数と給与を定める【マンサブダール制】を整え、都を【アグラ】に置きました。さらに、多数派のヒンドゥー教徒との融和をはかって非ムスリムへの【ジズヤ(人頭税)】を廃止し、ヒンドゥー教徒のラージプートの王女と結婚するなどして、広大な帝国を安定させました。", "この時代、インドの伝統とイスラーム文化が融合した【インド=イスラーム文化】が栄えました。宮廷の公用語は【ペルシア語】で、ペルシア語とインドの地方語がまざって【ウルドゥー語】が成立しました。イランの細密画の影響を受けた【ムガル絵画】が発達し、第5代【シャー=ジャハーン】は亡き妃のために壮麗な墓廟【タージ=マハル】をアグラに建て、デリーには【赤い城】を築きました。", "しかし第6代【アウラングゼーブ】は、帝国の最大領土を築いた一方で、厳格なスンナ派の立場からジズヤを復活させ、ヒンドゥー教徒を圧迫しました。これに反発して、デカン高原西部では【シヴァージー】がヒンドゥー国家の【マラーター王国】を建て、パンジャーブでは【シク教徒】が反乱を起こしました。アウラングゼーブの死後、帝国は急速に分裂し、地方の勢力が自立していきました。この分裂が、ヨーロッパ勢力の進出を許す条件となったのです。"]}, {"t": "イギリスの植民地支配", "p": ["17世紀、イギリス東インド会社は【マドラス】【ボンベイ】【カルカッタ】を拠点に、フランス東インド会社は【ポンディシェリ】などを拠点にインド貿易を進めました。18世紀半ば、両国は七年戦争と連動してインドで争い、1757年の【プラッシーの戦い】でイギリス東インド会社の【クライヴ】がベンガル太守とフランスの連合軍を破りました。これでインドでのイギリスの優位が決まり、会社はベンガルなどの徴税権を得て、単なる貿易会社から領土を支配する統治機関へと変わっていきました。その後、南インドの【マイソール戦争】、西インドの【マラーター戦争】、西北部の【シク戦争】に勝利して、19世紀半ばまでにインド全土を支配下に置きました。", "イギリスの支配はインド社会を大きく変えました。土地の所有者を確定して地税を徴収する制度が導入され、農民は重い税に苦しみました。また、イギリスの産業革命で生まれた安価な機械製綿布が流入して、インドの伝統的な綿織物業は打撃を受け、インドは綿花などの原料供給地、イギリス製品の市場へと変えられていきました。", "こうした不満が爆発したのが、1857年の【インド大反乱(シパーヒーの反乱)】です。東インド会社のインド人傭兵【シパーヒー】の反乱をきっかけに、旧支配層から農民まで広い層が加わりました。イギリスはこれを鎮圧し、1858年に名目だけ残っていた【ムガル帝国】を滅ぼし、東インド会社を解散してインドを本国政府の直接統治としました。1877年には【ヴィクトリア女王】がインド皇帝を兼ねる【インド帝国】が成立しました。"]}, {"t": "民族運動と独立、現代のインド", "p": ["イギリスは1885年、インド人エリートの意見を聞く場として【インド国民会議】を設けましたが、やがてこれが民族運動の中心となりました。1905年、イギリスがヒンドゥー教徒とムスリムを分断するねらいで【ベンガル分割令】を出すと、国民会議は【ティラク】らの指導で1906年の【カルカッタ大会】において【英貨排斥・スワデーシ(国産品愛用)・スワラージ(自治)・民族教育】の4綱領を掲げました。一方、イギリスはムスリムの【全インド=ムスリム連盟】の結成を支援し、宗教による分断をはかりました。", "第一次世界大戦中、イギリスは戦争協力の見返りに戦後の自治を約束しましたが、1919年に令状なしの逮捕を認める【ローラット法】を制定し、抗議集会に発砲する【アムリットサール事件】も起こりました。こうした中で【ガンディー】が指導した【非暴力・不服従運動(サティヤーグラハ)】は、民衆を広く巻き込む運動となりました。1929年、国民会議派は【ネルー】らの主導で【ラホール大会】を開き【プールナ=スワラージ(完全独立)】を目標に掲げ、翌年ガンディーはイギリスの塩の専売に抗議して【塩の行進】を行いました。1935年の【インド統治法】で各州の自治が認められましたが、完全独立は実現しませんでした。", "第二次世界大戦後、イギリスはインドの独立を認めましたが、ムスリム連盟の【ジンナー】はムスリム国家の分離を主張し、1947年、ヒンドゥー教徒が多数の【インド】とムスリムが多数の【パキスタン】に分かれて独立しました。分離の過程で大規模な宗教暴動と住民の移動が起こり、統一インドを願ったガンディーも1948年にヒンドゥー教徒の急進派に暗殺されました。両国は【カシミール】の帰属をめぐって対立を続け、1971年には東パキスタンが【バングラデシュ】として独立しました。", "独立後のインドは初代首相ネルーのもとで議会制民主主義を維持し、冷戦期には【非同盟】外交を進め、1954年には中国の周恩来と【平和五原則】を発表しました。1990年代からは経済の自由化を進めて急成長をとげ、現在では世界最大級の人口を抱える大国として国際社会で存在感を増しています。"]}], "points": ["インダス文明の遺跡(モエンジョ=ダーロ・ハラッパー)とインダス文字(未解読)", "ヴァルナ制の4身分とジャーティ、カースト制度の関係", "仏教(ガウタマ=シッダールタ)はクシャトリヤ・商人に、ジャイナ教(ヴァルダマーナ)はヴァイシャに支持された", "マウリヤ朝(アショーカ王・ダルマの政治・第3回仏典結集)とクシャーナ朝(カニシカ王・大乗仏教・ガンダーラ美術)", "グプタ朝:ヒンドゥー教確立・マヌ法典・サンスクリット文学・アジャンター石窟・法顕", "デリー=スルタン朝の5王朝の順序と、奴隷王朝の建国者アイバク", "ムガル帝国:アクバルのジズヤ廃止と融和、アウラングゼーブのジズヤ復活と帝国の分裂", "プラッシーの戦い(1757年)→インド大反乱(1857年)→インド帝国(1877年)→国民会議カルカッタ大会4綱領(1906年)→分離独立(1947年)"], "check": [["インダス文明の遺跡でシンド地方にある都市は?", "モエンジョ=ダーロ"], ["アーリヤ人の神々への賛歌を集めた最古のヴェーダは?", "リグ=ヴェーダ"], ["カリンガ征服を悔いて仏教に帰依したマウリヤ朝の王は?", "アショーカ王"], ["クシャーナ朝で仏教を保護した最盛期の王は?", "カニシカ王"], ["グプタ朝期に成立した、ヴァルナごとの義務を定めた法典は?", "マヌ法典"], ["1206年にデリーで奴隷王朝を建てた人物は?", "アイバク"], ["非ムスリムへのジズヤを廃止したムガル皇帝は?", "アクバル"], ["1757年にイギリス東インド会社がベンガル太守とフランスを破った戦いは?", "プラッシーの戦い"], ["1930年にガンディーがイギリスの専売に抗議して行った行進は?", "塩の行進"], ["パキスタンの分離独立を主張した全インド=ムスリム連盟の指導者は?", "ジンナー"]], "related": ["t_ir", "t_mn", "t_uk", "t_fr", "t_th", "t_id", "t_mm", "t_cn", "y_bc6", "y_bc4", "y_4", "y_7", "y_13", "y_16", "y_18", "y_19", "y_20a", "y_20b"], "n": 4878, "videos": [{"title": "【世界史】 イスラームの繁栄３ ムガル帝国 （１６分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=hq_6H5dhr6g", "note": "ムガル帝国の歴史を学べ、2026年度第4問Ｂ（ムガル帝国の政治や文化）の背景知識になります。"}]}, "t_th": {"title": "タイ史", "span": "7世紀ごろ〜現在", "year": 1782, "lead": "タイ人は中国南部から南下し、13世紀にスコータイ朝を建てて上座部仏教の国づくりを始めました。アユタヤ朝は東西交易の中継地として栄え、ビルマに滅ぼされたのちはラタナコーシン朝(チャクリ朝)が現在まで続いています。19世紀には巧みな外交と近代化によって東南アジアで唯一独立を守り、20世紀には立憲革命を経て、軍と王室が大きな役割を果たす独自の近代国家を歩みました。", "flow": ["7世紀ごろ〜 チャオプラヤ川流域にモン人のドヴァーラヴァティー王国", "11〜13世紀 カンボジアのアンコール朝がタイの一部を支配", "13世紀 タイ人がスコータイ朝を建てる→ラームカムヘーン王がタイ文字、上座部仏教を受容", "1351年 アユタヤ朝成立→スコータイを併合、アンコール朝を攻撃", "16〜17世紀 アユタヤが国際交易都市として繁栄→日本町、山田長政", "1767年 ビルマのコンバウン朝がアユタヤを滅ぼす→タークシンがトンブリー朝", "1782年 ラーマ1世がラタナコーシン朝(チャクリ朝)を開きバンコクを都に", "1855年 イギリスとボーリング条約→不平等条約のもと開国、米の輸出", "19世紀後半 ラーマ5世(チュラロンコン)の近代化→英仏の緩衝地帯として独立維持", "1932年 立憲革命→立憲君主制、1939年国名をシャムからタイへ", "1941年 日本と同盟→戦後は反共の立場でアメリカと結ぶ、1967年ASEAN結成"], "sync": [], "secs": [{"t": "タイ人の登場以前とスコータイ朝", "p": ["現在のタイの中心を流れる【チャオプラヤ川】の流域には、もともとモン人が住み、7世紀ごろから【ドヴァーラヴァティー王国】とよばれる仏教国が栄えていたとされます。その後、11〜13世紀にはカンボジアの【アンコール朝(クメール人)】が勢力を伸ばし、タイ東部・中部の一部を支配しました。タイ各地に残るクメール様式の寺院は、この時代の名残です。", "一方、【タイ人】はもともと中国の南部から雲南方面にかけて住んでいたと考えられ、長い時間をかけてインドシナ半島へと南下してきました。13世紀、アンコール朝の勢力が弱まるとタイ人はその支配から自立し、チャオプラヤ川の上流域に【スコータイ朝】を建てました。これがタイ人最初の王朝とされます。", "スコータイ朝の最盛期の王が13世紀後半の【ラームカムヘーン】です。彼はクメール文字などをもとに【タイ文字】をつくったとされ、王の事績を刻んだ碑文が残っています。また、スリランカから【上座部仏教】を取り入れて保護しました。これ以後、上座部仏教はタイの人々の信仰と生活の中心となり、男子が一時出家する習慣など、現在のタイ社会にも受け継がれています。同じころ、ビルマ(ミャンマー)のパガン朝やカンボジアも上座部仏教を受け入れており、インドシナ半島の大陸部は上座部仏教圏としてまとまっていきました。", "タイ人が南下して勢力を広げた背景には、13世紀のモンゴルの動きもありました。モンゴル(元)は雲南の【大理】を征服し、さらにビルマのパガン朝やベトナムにも遠征軍を送りました。こうした遠征によってインドシナ半島の既存の大国が動揺したことが、タイ人の諸勢力が台頭する条件の一つとなったと考えられています。北部には【チェンマイ】を中心とするランナー王国も成立し、のちにアユタヤやビルマと争いながら独自の文化を育てました。"]}, {"t": "アユタヤ朝 ― 交易国家の繁栄", "p": ["1351年、チャオプラヤ川の下流域に【アユタヤ朝】が成立しました。アユタヤは川と海の交通の要所にあり、内陸の米や森林産物を集めて海外に輸出するのに適した場所でした。アユタヤ朝はやがてスコータイ朝を併合し、さらに東のアンコール朝を攻撃してその都を攻略し、カンボジアの衰退を決定的にしました。", "アユタヤ朝は【明】に朝貢して交易を行い、15世紀以降は中国、インド、イスラーム世界、のちにはヨーロッパを結ぶ中継交易の拠点として繁栄しました。王は交易を独占する仕組みをもち、その利益が王権を支えました。16世紀にはポルトガル人が来航し、17世紀にはオランダやイギリス、フランスも商館を置きました。日本との間では【朱印船貿易】が盛んで、アユタヤには【日本町】がつくられ、【山田長政】のように王室に仕えて活躍した日本人もいました。", "一方、アユタヤ朝は西のビルマとたびたび戦いました。16世紀後半にはビルマの【タウングー朝】に一時都を占領されて従属しましたが、まもなく独立を回復しました。しかし18世紀半ば、ビルマに新たに成立した【コンバウン朝】が攻め込み、1767年にアユタヤは陥落して、約400年続いたアユタヤ朝は滅びました。", "アユタヤ朝の政治は、王を頂点とする身分秩序の上に成り立っていました。王はヒンドゥー教の神の化身とされるなど、カンボジアの王権の考え方も取り入れ、王を神聖な存在とする儀礼が整えられました。また、人々の身分や地位を数値で表す【サクディナー制】とよばれる制度が整えられたとされます。こうした仕組みのもとで、王は人々を労役や兵役に動員し、交易の利益とあわせて強い王権を維持しました。17世紀後半には、ギリシア人の側近を通じてフランスのルイ14世と使節を交換するなど、ヨーロッパとの外交も活発でしたが、外国勢力の影響が強まることへの反発から、のちに対外関係は一時縮小しました。"]}, {"t": "ラタナコーシン朝(チャクリ朝)の成立", "p": ["アユタヤ陥落後の混乱の中で、中国系の父をもつ武将【タークシン】がビルマ軍を追い払い、チャオプラヤ川下流の【トンブリー】を都として王位につきました(トンブリー朝)。しかしタークシンの晩年に政治が混乱すると、将軍【チャクリ】が実権を握り、1782年に【ラーマ1世】として即位して【ラタナコーシン朝(チャクリ朝)】を開きました。都は対岸の【バンコク】に移され、この王朝は現在まで続いています。", "ラタナコーシン朝の初期は、ビルマの侵攻を退けながら、ラオスやカンボジアの一部に影響力を広げ、インドシナ半島の大国となりました。また、中国の清との朝貢貿易や、中国人商人による交易が盛んになり、多くの【華人(中国系移民)】がタイに移り住みました。華人は商業や米の流通で大きな役割を果たし、現在のタイ社会でも重要な位置を占めています。", "ラタナコーシン朝の王たちは、ビルマに破壊されたアユタヤの栄光を受け継ぐことを国づくりの目標とし、バンコクに王宮や寺院を建て、仏教の経典を整理し、法典を編纂しました。都の名前にも、アユタヤの伝統を引き継ぐ意識が表れています。こうしてバンコクは政治・宗教・商業の中心として発展し、19世紀には東南アジア有数の港市となりました。"]}, {"t": "列強の進出と独立の維持", "p": ["19世紀、東南アジアは次々と欧米の植民地となりました。西のビルマはイギリスとの3度の戦争の末に1886年までにイギリス領インドに併合され、東のベトナム・カンボジア・ラオスはフランスの支配下に入りました。マレー半島もイギリスの勢力下に置かれ、タイは東西から英仏に挟まれる形になりました。", "こうした中で、【ラーマ4世(モンクット)】は、欧米の力を正しく認識し、西洋の学問を学んで開国に踏み切りました。1855年にはイギリスと【ボーリング条約】を結び、治外法権を認め、関税自主権を失うなど不平等な条件で自由貿易を受け入れました。これ以降、タイはチャオプラヤ川デルタで生産される米を大量に輸出するようになり、世界経済に組み込まれていきました。", "続く【ラーマ5世(チュラロンコン)】は、【チャクリ改革】とよばれる近代化を進めました。奴隷制を段階的に廃止し、中央集権的な官僚制度と省庁を整え、地方の有力者の支配を改めて全国を国王の直接統治のもとに置きました。鉄道や郵便を整備し、近代的な学校教育や軍隊もつくりました。これは、同じころの日本の明治維新とも比べられる上からの近代化でした。", "外交面では、英仏の対立を利用しながら、カンボジアの一部やラオスの一部をフランスに、マレー半島北部の一部をイギリスに譲るなど、領土の一部を手放す代わりに本土の独立を守りました。1896年には英仏が、タイを両国の勢力圏の間の【緩衝地帯】とすることに合意しています。こうしてタイは、19世紀の東南アジアで唯一独立を維持した国となりました。独立を守れた理由として、英仏が直接衝突を避けたかったという国際情勢と、国王による近代化の努力の両方が挙げられます。"]}, {"t": "立憲革命と戦争の時代", "p": ["20世紀に入ると、ヨーロッパに留学した官僚や軍人の間で、国王が全権を握る絶対王政への批判が高まりました。世界恐慌で財政が悪化する中、1932年、文官の【プリーディー】や軍人の【ピブーン】らの人民党が無血のクーデタを起こし、国王に憲法を受け入れさせました。これを【立憲革命】といい、タイは絶対王政から【立憲君主制】に移行しました。", "その後実権を握ったピブーンは、タイ民族主義を強く打ち出し、1939年に国名を【シャム】から【タイ】に改めました。第二次世界大戦が始まると、1941年に日本軍の進駐を認めて日本と同盟を結び、英米に宣戦しました。一方で、プリーディーらは国内外で抗日の【自由タイ】運動を組織して連合国と連絡をとりました。このため、戦後タイは敗戦国としての厳しい扱いを免れることができました。", "立憲革命は、国王の権力を憲法と議会で制限したという点で大きな転換でしたが、民衆が下から起こした革命ではなく、少数のエリート官僚・軍人によるものでした。そのため、その後の政治でも軍の発言力が強く残り、議会政治はなかなか定着しませんでした。このことが、戦後まで続くクーデタの繰り返しにつながっていきます。"]}, {"t": "戦後から現代へ", "p": ["第二次世界大戦後、隣国のベトナムなどで共産主義勢力が力を伸ばすと、タイは反共の立場からアメリカと強く結びつきました。1954年に結成された反共軍事同盟【東南アジア条約機構(SEATO)】には本部がバンコクに置かれ、ベトナム戦争ではアメリカ軍に基地を提供しました。1967年には、インドネシア・マレーシア・フィリピン・シンガポールとともに【東南アジア諸国連合(ASEAN)】を結成しました。", "戦後のタイ政治では、軍がクーデタによってたびたび政権を握り、これに対して学生や市民が民主化を求める運動を起こす、ということが繰り返されてきました。その中で国王は国民統合の象徴として大きな権威を保ち、政治の危機に調停者の役割を果たすこともありました。経済面では、1980年代後半から外国資本を受け入れて工業化が進み、自動車や電機の生産拠点として急成長しましたが、1997年にはタイの通貨バーツの暴落をきっかけに【アジア通貨危機】が起こり、東アジア・東南アジア全体に打撃を与えました。", "冷戦の終結後、ASEANにはベトナム・ラオス・ミャンマー・カンボジアも加わり、かつて対立していたインドシナ半島の国々が一つの地域協力の枠組みに入りました。タイは地理的にこれらの国々の中心にあり、道路や経済回廊の整備を通じて周辺国との結びつきを強めています。かつての交易国家アユタヤのように、地域を結ぶ結節点としての役割を再び担っているともいえます。一方で、国内では都市と農村の格差や、王室と政治の関係をめぐる対立がたびたび表面化しています。", "タイの歴史を通して見ると、インドから伝わった仏教文化、中国との交易と華人の役割、そして欧米列強との巧みな外交が、この国の特色を形づくってきたことがわかります。植民地にならなかったことは、現在のタイ人の誇りであると同時に、王室と国家を重んじる政治文化の背景ともなっています。"]}], "points": ["スコータイ朝(13世紀・タイ人最初の王朝)とラームカムヘーン王のタイ文字、上座部仏教の受容", "アユタヤ朝(1351年成立):アンコール朝を攻撃、中継交易で繁栄、日本町と山田長政", "1767年ビルマのコンバウン朝がアユタヤを滅ぼす→1782年ラタナコーシン朝(チャクリ朝)・都バンコク", "ボーリング条約(1855年)による開国と米の輸出", "ラーマ5世(チュラロンコン)の近代化と英仏の緩衝地帯としての独立維持", "1932年立憲革命で立憲君主制、1939年国名をタイに", "ASEAN原加盟国(1967年)、1997年アジア通貨危機の発端"], "check": [["13世紀に成立したタイ人最初の王朝は?", "スコータイ朝"], ["タイ文字をつくったとされるスコータイ朝の王は?", "ラームカムヘーン"], ["1351年に成立し、1767年にビルマに滅ぼされたタイの王朝は?", "アユタヤ朝"], ["アユタヤ朝を滅ぼしたビルマの王朝は?", "コンバウン朝"], ["1782年に成立し、現在まで続くタイの王朝は?", "ラタナコーシン朝(チャクリ朝)"], ["1855年にタイがイギリスと結んだ不平等条約は?", "ボーリング条約"], ["19世紀後半に近代化を進めたタイの国王は?", "ラーマ5世(チュラロンコン)"], ["19世紀に東南アジアで独立を維持した国は?", "タイ(シャム)"], ["1932年にタイで絶対王政を終わらせた事件は?", "立憲革命"], ["1939年に国名をシャムからタイに改めた指導者は?", "ピブーン"]], "related": ["t_mm", "t_vn", "t_id", "t_in", "t_cn", "t_uk", "t_fr", "y_13", "y_14", "y_17", "y_18", "y_19", "y_20a", "y_20b"], "n": 4061, "videos": [{"title": "【世界史】 東南アジア史１ 半島大陸部の国々 （１４分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=fhW28OZwilA", "note": "東南アジアの半島・大陸部の国々の歴史をまとめて確認できます。"}]}, "t_vn": {"title": "ベトナム史", "span": "前4世紀ごろ〜現在", "year": 1975, "lead": "ベトナム北部は約1000年にわたって中国王朝の支配を受け、漢字・儒教・科挙など中国文化を深く取り入れながらも、10世紀に独立してからは李朝・陳朝・黎朝のもとで中国やモンゴルの侵攻を何度も退けました。19世紀の阮朝のときフランスの植民地となりましたが、ホー=チ=ミンらの独立運動、インドシナ戦争、ベトナム戦争という長い戦いを経て1976年に南北統一を実現し、現在はドイモイ(刷新)政策のもとで経済成長を続けています。", "flow": ["前4世紀ごろ 北部でドンソン文化(銅鼓)", "前111年 前漢の武帝が南越を滅ぼす→北部は中国王朝の支配下に", "40年 徴姉妹の反乱→後漢の馬援が鎮圧", "2世紀末 中部にチャム人のチャンパーが成立", "7世紀 唐が安南都護府を置く", "10世紀 中国から独立→1009年李朝(大越国)", "13世紀 陳朝が元軍の侵入を撃退→字喃(チュノム)", "1428年 黎利が明の支配を脱し黎朝→チャンパーを圧迫", "18世紀後半 西山(タイソン)の乱→1802年阮福暎が阮朝", "1858年〜 フランスの侵略→清仏戦争(1884〜85年)→1887年フランス領インドシナ連邦", "1945年 ホー=チ=ミンがベトナム民主共和国の独立宣言→インドシナ戦争、1954年ジュネーヴ休戦協定", "1965年 アメリカの北爆と本格介入→1973年和平協定→1975年サイゴン陥落、1976年統一、1986年ドイモイ"], "sync": [], "secs": [{"t": "古代 ― ドンソン文化と中国の支配", "p": ["ベトナムは南北に細長い国で、北部の【紅河(ホン川)】デルタと南部の【メコン川】デルタという二つの大きな稲作地帯をもっています。歴史の中心となったのは北部の紅河流域で、前4世紀ごろには青銅器・鉄器文化の【ドンソン文化】が栄えました。祭りの道具とされる大型の青銅の太鼓【銅鼓】が特徴で、東南アジアの広い範囲に伝わりました。", "前3世紀末、秦の滅亡の混乱の中で、中国南部からベトナム北部にかけて【南越】が建てられましたが、前111年、前漢の【武帝】がこれを滅ぼして郡を置きました。これ以後、ベトナム北部は約1000年にわたって中国王朝の支配を受けることになります。この間に、漢字、儒教、仏教、中国式の制度などがもたらされ、ベトナムは東アジアの中国文化圏に組み込まれていきました。この点で、インド文化の影響を強く受けた他の東南アジアの国々とは異なる特色をもっています。", "しかし人々は支配に従うばかりではありませんでした。40年には、後漢の支配に反発した【徴姉妹(チュン姉妹)】が反乱を起こしました。反乱は後漢の将軍馬援に鎮圧されましたが、姉妹は現在もベトナムの民族的英雄とされています。7世紀には唐が現在のハノイに【安南都護府】を置いて統治しました。のちにフランスがこの地域を「アンナン」とよんだのは、この名に由来します。", "一方、ベトナム中部では、2世紀末にチャム人が【チャンパー】を建てました。チャンパーはインド文化の影響を受けたヒンドゥー教の国で、海上交易で栄え、中国では林邑・占城などとよばれました。南部のメコン川下流域には【扶南】があり、のちにカンボジアの勢力圏となりました。現在のベトナムの領域は、北部の国家がこれらの地域へ南へと拡大していった結果できあがったものです。"]}, {"t": "独立と大越国 ― 李朝・陳朝", "p": ["10世紀、唐が滅亡して中国が五代十国の分裂状態になると、ベトナム北部の勢力は自立を強め、938年に南漢の軍を破ってついに中国からの独立を果たしました。いくつかの短い王朝を経て、1009年に【李朝】が成立しました。李朝は都を【昇竜(タンロン、現在のハノイ)】に定め、国号を【大越(ダイベト)】としました。李朝は中国にならって官僚制を整え、科挙を実施し、仏教を保護しました。また、宋の侵攻を退けて独立を守りました。", "13世紀前半に成立した【陳朝】は、ユーラシアを席巻したモンゴル帝国(元)の侵入を3度にわたって撃退しました。特に将軍【陳興道(チャン=フン=ダオ)】は、ゲリラ戦術と紅河の地形を生かした戦いで元軍を打ち破ったことで知られます。陳朝の時代には、ベトナム語を書き表すために漢字をもとにした文字【字喃(チュノム)】がつくられ、民族意識が高まりました。ただし公式の文書には引き続き漢文が使われました。中国の文化を受け入れながらも中国に支配されないという、ベトナムの独立の伝統がこの時代に固まったといえます。", "李朝・陳朝の時代のベトナムは、対外的には中国の皇帝に朝貢して形式上は臣下の礼をとりつつ、国内では自らの君主を皇帝と称しました。中国と正面から対立せずに独立を保つという、この二面的な外交は、その後のベトナムの王朝にも受け継がれていきます。一方で、南方のチャンパーとはたびたび戦い、少しずつ南へ領土を広げていきました。"]}, {"t": "黎朝・西山の乱・阮朝", "p": ["15世紀初め、明の【永楽帝】は陳朝の混乱に乗じてベトナムに出兵し、一時ベトナムを直接支配しました。これに対して【黎利(レ=ロイ)】が抵抗運動を指導して明軍を退け、1428年に【黎朝】を開きました。黎朝は明の制度にならって中央集権体制を整え、儒学(朱子学)を重んじて科挙官僚による統治を進めました。15世紀後半には南方のチャンパーを攻撃して大きな打撃を与え、ベトナム人の南進が進みました。", "16世紀以降、黎朝の皇帝は名目的な存在となり、北部の【鄭氏】と中部の【阮氏】という二つの有力な一族が実権を争って、国は事実上分裂しました。阮氏はさらに南へ進出し、17世紀以降メコン川デルタにまで支配を広げました。この時代、中部の港町【ホイアン】には日本町がつくられ、朱印船が来航しました。", "18世紀後半、重い税と政治の混乱に苦しむ農民を背景に【西山(タイソン)の乱】が起こりました。西山の阮氏三兄弟は南の阮氏と北の鄭氏を倒し、侵攻してきた清軍も破って、黎朝を滅ぼしました。しかし南の阮氏の生き残りである【阮福暎(グエン=フック=アイン)】は、フランス人宣教師【ピニョー】を通じてフランス人の援助を受け、タイなどの支援も得て西山政権を倒し、1802年に【阮朝】を開きました。都は中部の【フエ(ユエ)】に置かれ、国号は清から認められた【越南(ベトナム)】となりました。こうして初めて、北部から南部のメコンデルタまでを含む現在のベトナムの領域が一つの王朝のもとに統一されました。阮朝は清に朝貢し、清の制度にならった政治を行いました。"]}, {"t": "フランスの植民地支配", "p": ["阮朝の成立をフランスが助けたことは、のちにフランスが介入する口実ともなりました。阮朝がキリスト教を禁止し、宣教師を迫害すると、フランスの【ナポレオン3世】はスペインとともに1858年に出兵しました。1862年の条約でフランスは南部の一部を獲得し、その後南部全体を【コーチシナ】植民地としました。1863年にはカンボジアも保護国としています。", "フランスはさらに北部への進出をはかり、これに対して阮朝は清に助けを求めました。北部では、太平天国の残党の流れをくむとされる【劉永福】の【黒旗軍】がフランス軍に抵抗しました。1883年と1884年の【ユエ条約】でベトナムはフランスの保護国となり、ベトナムに対する宗主権を主張する清とフランスの間で【清仏戦争】(1884〜85年)が起こりました。1885年の【天津条約】で清はベトナムに対するフランスの保護権を認め、宗主権を放棄しました。", "1887年、フランスはベトナムとカンボジアを合わせて【フランス領インドシナ連邦】を成立させ、1899年にはラオスも加えました。フランスは米やゴムなどの輸出を進め、メコンデルタでは大土地所有が広がって、多くの農民が小作人として苦しい生活を強いられました。また、塩・アルコール・アヘンの専売などで住民に重い負担を課しました。", "こうした植民地支配のもとで、フランス式の教育を受けた新しい知識人層も生まれました。また、ベトナム語をローマ字で書き表す【クオック=グー】が普及し、漢字や字喃に代わって広く使われるようになりました。新しい知識人たちは、やがて植民地支配そのものを批判し、民族の独立を求める運動の担い手となっていきます。"]}, {"t": "民族運動とホー=チ=ミン", "p": ["20世紀初め、日露戦争での日本の勝利に刺激されて、【ファン=ボイ=チャウ】は【維新会】を結成し、青年を日本に留学させる【ドンズー(東遊)運動】を進めました。しかし日本政府がフランスとの協約を結んで留学生を国外に退去させたため、運動は挫折しました。その後ファン=ボイ=チャウは辛亥革命の影響を受けて中国に拠点を移し、【ベトナム光復会】を組織しました。", "第一次世界大戦後、民族運動の中心となったのが【ホー=チ=ミン】です。ホー=チ=ミンはフランスで社会主義に触れ、1930年に【インドシナ共産党】を結成しました。第二次世界大戦中に日本軍がフランス領インドシナに進駐すると、1941年に【ベトナム独立同盟(ベトミン)】を組織して抗日・反仏の闘争を進めました。", "1945年、日本の降伏直後にベトミンは全国で権力を握り(八月革命)、ホー=チ=ミンは【ベトナム民主共和国】の独立を宣言しました。阮朝最後の皇帝は退位し、阮朝はここに終わりました。"]}, {"t": "インドシナ戦争とベトナム戦争", "p": ["しかしフランスは独立を認めず、1946年に【インドシナ戦争】が始まりました。フランスは1949年に阮朝最後の皇帝バオ=ダイを元首として【ベトナム国】を建てて対抗しました。冷戦の中で、ベトナム民主共和国は中国やソ連の支援を、フランスはアメリカの援助を受け、戦争は国際的な対立の場となりました。1954年、ベトナム軍は【ディエンビエンフーの戦い】でフランス軍に決定的な勝利をおさめ、同年の【ジュネーヴ休戦協定】で北緯17度線を暫定的な軍事境界線とし、2年後に統一選挙を行うことが決まりました。", "しかしアメリカは協定に調印せず、共産主義の拡大を防ぐため、南部に1955年【ゴ=ディン=ジエム】を大統領とする【ベトナム共和国】を樹立させて支援しました。統一選挙は行われず、ベトナムは南北に分断されました。南ベトナム政府の独裁に反対して、1960年に【南ベトナム解放民族戦線】が結成され、北ベトナムの支援を受けてゲリラ戦を展開しました。", "1964年の【トンキン湾事件】を口実に、アメリカの【ジョンソン】政権は1965年から北ベトナムへの爆撃(【北爆】)を始め、大量の地上軍を派遣して【ベトナム戦争】に本格的に介入しました。しかし、ジャングルでのゲリラ戦に苦しみ、戦争は泥沼化しました。戦争の悲惨さが報道されると、アメリカ国内や世界各地で反戦運動が高まり、アメリカの財政も悪化しました。1973年の【ベトナム(パリ)和平協定】でアメリカ軍は撤退し、1975年に北ベトナム軍と解放戦線が南の首都【サイゴン】を攻略して戦争は終わりました。1976年、南北が統一されて【ベトナム社会主義共和国】が成立し、サイゴンはホー=チ=ミン市と改称されました。"]}, {"t": "統一後のベトナム", "p": ["統一後、ベトナムは社会主義化を急ぎましたが、経済は停滞し、多くの人々が小舟で国外に逃れました(ボート=ピープル)。1978年には、ポル=ポト政権下のカンボジアに侵攻して親ベトナム政権を樹立し、これに反発した中国との間で1979年に【中越戦争】が起こりました。ソ連と結ぶベトナムと、アメリカに接近した中国の対立は、社会主義国どうしの対立としても注目されました。", "1986年、ベトナムは【ドイモイ(刷新)】政策を打ち出し、共産党の一党支配を維持しながら市場経済を導入し、外国資本を受け入れました。1989年にカンボジアから撤退し、1995年にはアメリカと国交を正常化し、同年【ASEAN】に加盟しました。その後ベトナムは工業化と輸出によって高い経済成長を続けています。千年にわたる中国の支配、フランスの植民地支配、そしてアメリカとの戦争という外国勢力との長い戦いの歴史は、ベトナムの人々の強い民族意識の源となっています。"]}], "points": ["ドンソン文化(銅鼓)、前111年前漢武帝の南越征服→約1000年の中国支配", "徴姉妹の反乱(40年)と唐の安南都護府", "李朝(1009年・大越国・ハノイ)→陳朝(元軍撃退・字喃)→黎朝(1428年・黎利・明から独立)", "西山(タイソン)の乱→阮福暎が仏人宣教師ピニョーの援助で阮朝(1802年・都フエ・国号越南)", "清仏戦争(1884〜85年)と天津条約→フランス領インドシナ連邦(1887年)", "ファン=ボイ=チャウのドンズー(東遊)運動とその挫折", "ホー=チ=ミン:インドシナ共産党(1930年)→ベトミン(1941年)→独立宣言(1945年)", "ディエンビエンフー・ジュネーヴ休戦協定(1954年)→北爆(1965年)→和平協定(1973年)→統一(1976年)→ドイモイ(1986年)"], "check": [["前4世紀ごろベトナム北部で栄えた、銅鼓で知られる文化は?", "ドンソン文化"], ["1世紀に後漢の支配に反抗して反乱を起こした姉妹は?", "徴姉妹"], ["11世紀初めに成立し、大越国と称したベトナムの王朝は?", "李朝"], ["陳朝の時代に漢字をもとにつくられた文字は?", "字喃(チュノム)"], ["明軍を退けて黎朝を建てた人物は?", "黎利"], ["1802年に阮朝を建てた人物は?", "阮福暎"], ["日本への留学を進めるドンズー運動を指導した人物は?", "ファン=ボイ=チャウ"], ["1954年、インドシナ戦争の帰趨を決した戦いは?", "ディエンビエンフーの戦い"], ["1960年に南ベトナム政府に対抗して結成された組織は?", "南ベトナム解放民族戦線"], ["1986年からベトナムで進められた市場経済導入の政策は?", "ドイモイ(刷新)"]], "related": ["t_cn", "t_mm", "t_th", "t_fr", "t_us", "t_mn", "y_bc2", "y_1", "y_10", "y_13", "y_15", "y_19", "y_20a", "y_20b"], "n": 4227, "videos": [{"title": "【世界史】 アジアの紛争１ ベトナム戦争 （１６分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=azrUX0Gargw", "note": "ベトナム戦争を扱い、ベトナム史の現代部分を補えます。"}]}, "t_mm": {"title": "ミャンマー・カンボジア史", "span": "1世紀ごろ〜現在", "year": 1113, "lead": "インドシナ半島の西のミャンマー(ビルマ)と南のカンボジアは、どちらもインド文化の影響を受けて国家を形成し、のちに上座部仏教の国となりました。カンボジアでは扶南・真臘を経てアンコール朝が巨大な寺院都市を築き、ミャンマーではパガン朝・タウングー朝・コンバウン朝が興亡しました。近代にはミャンマーがイギリス、カンボジアがフランスの植民地となり、独立後はミャンマーの軍政、カンボジアの内戦とポル=ポト政権という苦難の歴史を歩みました。", "flow": ["1世紀末 メコン川下流に扶南(外港オケオ)→インド・中国を結ぶ交易", "6世紀 クメール人の真臘(カンボジア)が扶南を滅ぼす", "9世紀初め アンコール朝成立→12世紀前半スールヤヴァルマン2世がアンコール=ワット", "12世紀末 ジャヤヴァルマン7世がアンコール=トム→その後衰退、15世紀にアユタヤ朝の攻撃", "1044年 ビルマ人のパガン朝(ビルマ最初の統一王朝)→上座部仏教", "13世紀後半 元(モンゴル)の侵攻でパガン朝衰退", "16世紀 タウングー朝がビルマを統一→アユタヤを一時従属", "18世紀半ば コンバウン朝→1767年アユタヤを滅ぼす", "1824〜86年 3次のビルマ戦争→イギリス領インドに併合", "1863年 カンボジアがフランスの保護国→1887年フランス領インドシナ連邦", "1948年 ビルマ独立(アウン=サンの暗殺後)、1953年カンボジア独立(シハヌーク)", "1975年 ポル=ポトの民主カンプチア→1979年ベトナム軍侵攻、1991年和平協定"], "sync": [], "secs": [{"t": "インド化する東南アジアと扶南・真臘", "p": ["紀元前後から、季節風を利用したインドと中国を結ぶ海の交易が盛んになると、その中継地となった東南アジアの沿岸部には港市国家が生まれました。インドから商人やバラモンが訪れ、ヒンドゥー教や仏教、サンスクリット語、インド式の王権の考え方が伝わりました。こうして東南アジア各地がインド文化を取り入れていった動きを、【インド化】とよぶことがあります。", "1世紀末、メコン川下流域に成立した【扶南】は、東南アジア最古級の国の一つとされます。扶南の外港とされる【オケオ】の遺跡からは、ローマ金貨やインドの神像、中国の鏡などが見つかっており、扶南がローマ・インド・中国を結ぶ交易で栄えたことを示しています。", "6世紀になると、メコン川中流域でクメール人が建てた【真臘(カンボジア)】が扶南を滅ぼしました。扶南が海の交易国家だったのに対し、真臘は内陸の農業を基盤とする国でした。真臘はその後南北に分裂しましたが、やがて再統一され、アンコール朝へとつながっていきます。", "インド化といっても、東南アジアの人々がインドの文化をそのまま受け入れたわけではありません。各地の支配者は、自らの権威を高めるのに役立つ要素を選んで取り入れ、在来の精霊信仰や祖先崇拝と組み合わせて独自の文化をつくりあげました。カンボジアやビルマに見られる壮大な宗教建築も、インドの様式をもとにしながら、それぞれの土地で独自の発展をとげたものです。また、中国の歴史書にも扶南や真臘の記録が残されており、これらの国々が中国の王朝に使節を送っていたことがわかります。"]}, {"t": "アンコール朝の栄華と衰退", "p": ["9世紀初め、ジャヤヴァルマン2世がカンボジアを統一し、【アンコール朝】を開きました。王は自らを神と一体の存在とする【神王】の思想を掲げ、ヒンドゥー教の儀式によって権威を高めました。アンコール地方には巨大な貯水池と水路が整備され、それを利用した稲作が王国の繁栄を支えたと考えられています。", "アンコール朝は12世紀に最盛期を迎えました。12世紀前半の王【スールヤヴァルマン2世】は、ヒンドゥー教のヴィシュヌ神をまつる巨大な寺院【アンコール=ワット】を造営しました。壁面には『ラーマーヤナ』『マハーバーラタ』の物語などが細かく彫刻されています。アンコール=ワットは造営当初【ヒンドゥー教】の寺院として建てられましたが、のちに仏教寺院として使われるようになりました。", "12世紀末にはチャンパーの侵攻で都が一時占領されましたが、【ジャヤヴァルマン7世】がこれを撃退し、都城【アンコール=トム】を造営しました。ジャヤヴァルマン7世は大乗仏教を篤く信仰し、中心寺院バイヨンには観音菩薩とされる巨大な顔の塔が並んでいます。この王のもとでアンコール朝の支配はインドシナ半島の広い範囲に及びました。", "しかし13世紀以降、アンコール朝はしだいに衰えました。大規模な建設事業の負担に加え、民衆の間に上座部仏教が広まって神王の権威が弱まったことや、西方のタイ人の台頭が原因と考えられています。14世紀半ばに成立したタイの【アユタヤ朝】の攻撃を受け、15世紀には都はアンコールから南のプノンペン方面に移されました。その後のカンボジアは、西のタイと東のベトナムという二つの強国に挟まれて圧迫される時代が長く続きました。"]}, {"t": "ビルマの王朝 ― パガン朝からコンバウン朝へ", "p": ["ミャンマー(ビルマ)のエーヤワディー(イラワディ)川流域には、古くは【ピュー人】や南部の【モン人】が国をつくり、仏教を受け入れていました。9世紀ごろ、北方からビルマ人が進出し、1044年に【パガン朝】を開きました。これがビルマ最初の統一王朝とされます。パガン朝はモン人から【上座部仏教】を取り入れ、都パガンには数多くの仏塔(パゴダ)や寺院が建てられました。上座部仏教はこれ以後、ビルマの人々の信仰の中心となります。", "13世紀後半、雲南を征服した【元(モンゴル)】がビルマに侵攻し、パガン朝は衰退しました。その後ビルマは分裂状態となりましたが、16世紀に【タウングー朝】が再統一し、タイのアユタヤを一時従属させるほどの勢力を誇りました。", "18世紀半ばには【アラウンパヤー】が【コンバウン朝】を開き、ビルマを再統一しました。コンバウン朝は勢力を拡大し、1767年にはタイのアユタヤを攻略してアユタヤ朝を滅ぼしました。さらに清軍の侵攻を退け、西方ではアッサームなどインド東北部へも進出しましたが、これがインドを支配していたイギリスとの衝突を招くことになります。", "ビルマの王朝の歴史を通して見ると、北の中国(雲南)、西のインド、東のタイという周辺勢力との関係が、つねに大きな影響を与えてきたことがわかります。パガン朝はモンゴルの侵攻で衰え、タウングー朝とコンバウン朝はタイとの戦争をくり返し、そしてコンバウン朝の西方進出は、インドを支配するイギリスとの衝突を引き起こしました。また、多数派のビルマ人のほかにモン人やシャン人、カレン人など多くの民族が暮らしていたことも、のちの民族問題の背景となります。"]}, {"t": "植民地化 ― ビルマはイギリスへ、カンボジアはフランスへ", "p": ["コンバウン朝とイギリスの対立は、1824年に始まる【ビルマ戦争(イギリス=ビルマ戦争)】に発展しました。イギリスは3次にわたる戦争でビルマの領土を段階的に奪い、1885年の第3次戦争でコンバウン朝を滅ぼして、翌1886年にビルマを【イギリス領インド】に併合しました。イギリスはビルマを米やチーク材、石油の供給地として開発し、インドから多くの労働者や金融業者が移り住みました。そのため、ビルマ人の間にはイギリスだけでなくインド系住民に対する反感も生まれました。", "カンボジアでは、タイとベトナムの圧迫に苦しむ王が、フランスの保護を受け入れる道を選びました。1863年、カンボジアはフランスの【保護国】となり、1887年にはベトナムとともに【フランス領インドシナ連邦】に組み込まれました。フランスは王政を残しつつ実権を握り、ゴムのプランテーションなどの開発を進めました。また、19世紀後半にフランス人がアンコール=ワットを広く紹介したことで、アンコール遺跡は世界に知られるようになりました。", "イギリスがビルマをインドの一州として統治したことは、ビルマの人々の誇りを深く傷つけました。ビルマがインドから分離されて独自の植民地となるのは1937年のことです。一方、フランス領インドシナのもとでのカンボジアでは、行政の多くをベトナム人の官吏が担ったため、カンボジア人とベトナム人の間にも複雑な感情が生まれました。植民地時代に形づくられたこうした民族間の関係は、独立後の政治にも影を落としました。"]}, {"t": "ビルマ(ミャンマー)の独立と軍政", "p": ["20世紀に入るとビルマでも民族運動が高まり、1930年代には「われらビルマ人」を意味する【タキン党】が結成され、若き指導者【アウン=サン】らが独立運動を進めました。第二次世界大戦が始まると、アウン=サンらは日本軍の支援を受けてビルマ独立義勇軍を組織し、日本軍とともにイギリス軍を駆逐しました。1943年には日本の占領下で形式的な独立が認められましたが、実権は日本軍にありました。そこでアウン=サンは【反ファシスト人民自由連盟】を組織して抗日に転じ、戦後はイギリスとの交渉で独立を勝ち取りました。アウン=サン自身は独立直前の1947年に暗殺されましたが、1948年に【ビルマ連邦】がイギリス連邦を離脱して完全独立を達成しました。", "独立後のビルマでは、多数派のビルマ人と少数民族の対立や共産党の武装闘争が続きました。1962年、【ネ=ウィン】が軍事クーデタで権力を握り、独自の社会主義(ビルマ式社会主義)を掲げて鎖国に近い政策をとりましたが、経済は停滞しました。1988年には大規模な民主化運動が起こり、アウン=サンの娘【アウン=サン=スー=チー】がその指導者となりましたが、軍が再びクーデタで実権を握り、1989年に国名をミャンマーと改めました。1990年の選挙ではスー=チーの国民民主連盟が大勝しましたが、軍は政権を譲らず、スー=チーは長く自宅軟禁に置かれました。", "2010年代に入ると民政移管が進み、スー=チーの政党が政権を担いましたが、2021年に軍が再びクーデタを起こし、混乱が続いています。また、イスラーム教徒の少数民族ロヒンギャへの迫害も国際的な問題となっています。"]}, {"t": "カンボジアの独立・内戦・ポル=ポト政権", "p": ["カンボジアは、国王【シハヌーク】の外交努力によって1953年にフランスから独立しました。シハヌークはインドシナ戦争後の冷戦の中で中立政策をとりましたが、隣国ベトナムでの戦争が激しくなると、カンボジア領内を北ベトナムの補給路が通るなど、戦争に巻き込まれていきました。1970年、親米派の【ロン=ノル】がクーデタでシハヌークを追放し、カンボジアは内戦状態に陥りました。", "1975年、共産主義勢力の【赤色クメール(クメール=ルージュ)】が首都プノンペンを制圧し、【ポル=ポト】を指導者とする【民主カンプチア】を樹立しました。ポル=ポト政権は、都市の住民を農村に強制移住させ、貨幣や市場、学校を廃止する極端な共産主義政策を行い、知識人などを大量に虐殺しました。強制労働や飢餓、虐殺によって多数の国民が命を落としたとされます。", "1978年末、ポル=ポト政権と対立していたベトナムがカンボジアに侵攻し、1979年に親ベトナムの【ヘン=サムリン】政権を樹立しました。ポル=ポト派などは各地で抵抗を続け、内戦は長期化しました。また、ポル=ポト政権を支援していた中国はこれに反発し、【中越戦争】が起こりました。冷戦の終結とともに和平の動きが進み、1989年にベトナム軍が撤退、1991年に【カンボジア和平協定(パリ協定)】が結ばれました。その後、【国連カンボジア暫定統治機構(UNTAC)】のもとで1993年に総選挙が行われ、シハヌークを国王とする立憲君主制のカンボジア王国が成立しました。日本の自衛隊がPKOとして初めて海外に派遣されたのも、このカンボジアでした。", "その後、ミャンマーは1997年、カンボジアは1999年に【ASEAN】に加盟し、東南アジアの地域協力の中で発展をめざしています。アンコール遺跡は世界遺産となり、カンボジアの国旗にも描かれて、民族の誇りの象徴となっています。"]}], "points": ["扶南(1世紀末・外港オケオ・ローマ金貨)→真臘(6世紀・クメール人)→アンコール朝(9世紀)の流れ", "アンコール=ワット(12世紀前半・スールヤヴァルマン2世・当初ヒンドゥー教寺院)とアンコール=トム(12世紀末・ジャヤヴァルマン7世・大乗仏教)", "ビルマの王朝の順序:パガン朝(1044年・最初の統一王朝・上座部仏教)→タウングー朝→コンバウン朝", "パガン朝は元(モンゴル)の侵攻で衰退、コンバウン朝は1767年にアユタヤ朝を滅ぼす", "3次のビルマ戦争→1886年イギリス領インドに併合", "カンボジアは1863年フランスの保護国→1887年フランス領インドシナ連邦", "アウン=サン(独立運動)とアウン=サン=スー=チー(民主化運動)の区別", "ポル=ポトの民主カンプチア(1975年)→ベトナム軍侵攻(1979年)→カンボジア和平協定(1991年)→UNTAC"], "check": [["1世紀末にメコン川下流域に成立した国は?", "扶南"], ["扶南の外港とされ、ローマ金貨が出土した遺跡は?", "オケオ"], ["6世紀にクメール人が建て、扶南を滅ぼした国は?", "真臘(カンボジア)"], ["アンコール=ワットを造営した12世紀前半の王は?", "スールヤヴァルマン2世"], ["アンコール=トムを造営した王は?", "ジャヤヴァルマン7世"], ["11世紀に成立したビルマ最初の統一王朝は?", "パガン朝"], ["18世紀半ばに成立し、イギリスに滅ぼされたビルマの王朝は?", "コンバウン朝"], ["ビルマ独立運動を指導し、1947年に暗殺された人物は?", "アウン=サン"], ["1953年にカンボジアをフランスから独立に導いた国王は?", "シハヌーク"], ["カンボジアで大量虐殺を行った民主カンプチア政権の指導者は?", "ポル=ポト"]], "related": ["t_th", "t_vn", "t_in", "t_id", "t_uk", "t_fr", "t_cn", "t_mn", "y_1", "y_6", "y_11", "y_12", "y_13", "y_19", "y_20b"], "n": 4140}, "t_id": {"title": "インドネシア・マレーシア史", "span": "7世紀ごろ〜現在", "year": 1511, "lead": "マラッカ海峡をはさむ島々と半島は、インド洋と南シナ海を結ぶ海の道の要所として、シュリーヴィジャヤやマジャパヒト、マラッカ王国などの港市国家・王国が栄え、仏教・ヒンドゥー教ののちイスラームが広まりました。16世紀以降はポルトガル・オランダ・イギリスが香辛料と交易を求めて進出し、インドネシアはオランダ、マレー半島はイギリスの植民地となりました。第二次世界大戦後に独立した両国は、ASEANの中心国として発展しています。", "flow": ["7世紀 スマトラ島パレンバン中心にシュリーヴィジャヤ→義浄が訪れる", "8〜9世紀 ジャワ島中部にシャイレンドラ朝→ボロブドゥール、ヒンドゥー教のプランバナン", "1293年 元軍を退けジャワ東部にマジャパヒト王国", "13世紀末〜 サムドラ=パサイなどイスラーム化の進展", "14世紀末 マラッカ王国成立→15世紀鄭和の遠征を機に発展、国王がイスラームに改宗", "1511年 ポルトガルがマラッカを占領→アチェ王国・マタラム王国などイスラーム国家", "1619年 オランダがバタヴィアを建設→1623年アンボイナ事件でイギリスを排除", "1824年 英蘭協定→マラッカ海峡を境に勢力分け、1826年イギリスの海峡植民地", "1830年 オランダがジャワで強制栽培制度", "1911〜12年ごろ イスラーム同盟(サレカット=イスラーム)→1927年スカルノがインドネシア国民党", "1945年 スカルノがインドネシア独立宣言→1949年オランダが承認", "1957年 マラヤ連邦独立→1963年マレーシア、1965年シンガポール分離、九・三〇事件、1967年ASEAN"], "sync": [], "secs": [{"t": "海の道と仏教・ヒンドゥー教の王国", "p": ["インドネシアとマレーシアの歴史を理解するうえで最も大切なのは、両国のあいだにある【マラッカ海峡】の位置です。この海峡はインド洋と南シナ海を結ぶ最短の航路で、季節風(【モンスーン】)を利用する船は、風向きが変わるまで港で待つ必要がありました。そのため海峡の周辺には、船が立ち寄って水や食料を補給し、商品を取引する【港市】が栄え、港市を支配する国家が生まれました。", "7世紀には、スマトラ島の【パレンバン】を中心に【シュリーヴィジャヤ】が成立しました。シュリーヴィジャヤはマラッカ海峡の交易を支配して栄え、大乗仏教が盛んでした。7世紀後半にはインドへ向かう唐の僧【義浄】がここに滞在し、『【南海寄帰内法伝】』を著してその様子を伝えています。中国の記録では、のちにこの地域の国は三仏斉とよばれました。", "一方、肥沃な火山灰土に恵まれたジャワ島では、稲作を基盤とする王国が栄えました。8〜9世紀にジャワ島中部で栄えた【シャイレンドラ朝】は大乗仏教を信仰し、巨大な石造の仏教遺跡【ボロブドゥール】を造営しました。ほぼ同じころ、ジャワ島中部ではヒンドゥー教の寺院群【プランバナン】も建てられています。このように、この地域の国々はインドから仏教やヒンドゥー教を取り入れて王の権威を高めました。11世紀には南インドの【チョーラ朝】がシュリーヴィジャヤに遠征したことも知られ、インド洋をはさんだ結びつきの強さがうかがえます。", "13世紀後半、元の【フビライ】はジャワにも遠征軍を送りましたが、この混乱の中で1293年、ジャワ島東部に【マジャパヒト王国】が成立し、元軍を退けました。マジャパヒト王国はヒンドゥー教の王国で、14世紀には周辺の島々に影響力を広げ、インドネシアの歴史上最大級の勢力を誇りました。"]}, {"t": "イスラームの広まりとマラッカ王国", "p": ["13世紀末ごろから、ムスリム商人の活動を通じて、この地域にイスラームが広まりはじめました。スマトラ島北部には、東南アジア最初期のイスラーム国家の一つ【サムドラ=パサイ】が成立しました。イスラームは、商人たちのネットワークや、神との一体感を重んじる神秘主義者(スーフィー)の布教を通じて、港市から内陸へと少しずつ浸透していきました。", "14世紀末、マレー半島南西部に【マラッカ王国】が成立しました。マラッカ王国は、15世紀初めに明の【鄭和】の艦隊が拠点として利用したことをきっかけに、明の後ろ盾を得て発展しました。やがて国王がイスラームに改宗すると、ムスリム商人が多く集まるようになり、マラッカは東南アジア最大の交易都市となりました。マラッカの繁栄は、海峡の周辺地域のイスラーム化をさらに進め、マレー語が交易の共通語として広く使われるようになりました。こうして、現在のインドネシア・マレーシアがイスラーム教徒の多い国となる基礎が築かれたのです。", "イスラームが港市の支配者に受け入れられたのには理由がありました。ムスリム商人とのつながりを深めることで交易の利益を得やすくなり、また、イスラームの教えにもとづく法や文字(アラビア文字)を取り入れることで、国の仕組みを整えることができたからです。一方、ジャワ島の内陸部やバリ島などでは、ヒンドゥー教や在来の信仰が長く残り、イスラームもそれらと混じり合いながら受け入れられました。特にバリ島では、現在もヒンドゥー教の文化が色濃く残っています。"]}, {"t": "ヨーロッパ勢力の進出 ― 香辛料をめぐる争い", "p": ["ヨーロッパの人々がこの地域に強くひかれたのは、【モルッカ諸島(マルク諸島)】で産する【丁子(クローヴ)】や【ナツメグ】などの香辛料のためでした。モルッカ諸島は「香料諸島」とよばれ、香辛料はヨーロッパで高値で取引されていました。", "インド航路を開いたポルトガルは、1511年に【マラッカ】を占領し、香辛料交易の独占をはかりました。しかしムスリム商人たちはポルトガルを避けて別の港に移ったため、スマトラ島北端の【アチェ王国】や、ジャワ島の【バンテン王国】などのイスラーム国家が交易で栄えました。16世紀末にはジャワ島中・東部に【マタラム王国】が成立しました。", "17世紀に入ると、【オランダ東インド会社】が進出し、1619年にジャワ島に【バタヴィア(現在のジャカルタ)】を建設してアジア貿易の拠点としました。1623年にはモルッカ諸島の【アンボイナ事件】でイギリス商館員を殺害してイギリス勢力を排除し、香辛料交易の独占を確立しました。敗れたイギリスはインド経営に重点を移していきます。1641年にはオランダがポルトガルからマラッカも奪いました。その後オランダは、香辛料交易の利益が減ると、ジャワ島の内陸支配に乗り出し、マタラム王国の内紛に介入して領土を広げていきました。"]}, {"t": "オランダ領東インドとイギリス領マラヤ", "p": ["18世紀末、オランダ東インド会社は経営難から解散し、その領土はオランダ政府の直接統治に移されました。ナポレオン戦争中には一時イギリスがジャワを占領しましたが、戦後オランダに返還されました。1824年の【英蘭協定】で、両国はマラッカ海峡を境に勢力圏を分け、海峡の北のマレー半島はイギリス、南のスマトラ島などはオランダの勢力圏とされました。現在のマレーシアとインドネシアの国境の基本は、このとき決まったといえます。", "イギリスは、1819年に【ラッフルズ】がマレー半島南端に【シンガポール】を建設し、1826年には【ペナン】・【マラッカ】・シンガポールを合わせて【海峡植民地】としました。その後イギリスはマレー半島の諸王国(スルタン国)を次々と保護下に置き、1895年に【マレー連合州】を結成しました。マレー半島では【錫】の採掘と【ゴム】のプランテーションが発達し、鉱山には中国人(華僑)、ゴム園には南インドのタミル人が多数労働者として移り住みました。その結果、マレー人・中国系・インド系が共存する【複合社会】が形成され、これが独立後の民族問題の背景となりました。", "オランダは、ジャワ戦争などで財政が悪化すると、1830年から【強制栽培制度】を導入しました。これは、ジャワの農民にコーヒー・サトウキビ・藍などの輸出用作物を指定して栽培させ、政府が安い価格で買い上げる制度です。オランダ本国は莫大な利益を得ましたが、食料用の稲作が圧迫されたジャワでは飢饉が起こるなど、農民は大きな苦しみを強いられました。この制度は批判を受けて19世紀後半に廃止されていきました。オランダはその後スマトラのアチェ王国を長い戦争の末に征服するなど、20世紀初めまでに現在のインドネシアのほぼ全域を【オランダ領東インド】として支配下に置きました。", "こうしてインドネシアとマラヤは、それぞれ異なる宗主国のもとで、別々の植民地として歩むことになりました。同じマレー系の言葉や文化、イスラームの信仰を共有しながらも、二つの国が別の国家として独立したのは、この植民地時代の線引きの結果なのです。"]}, {"t": "民族運動と独立", "p": ["20世紀初め、オランダは現地住民の福祉や教育に配慮する「倫理政策」をとり、その中で教育を受けた知識人層が生まれました。1908年には知識人による【ブディ=ウトモ】が結成され、1911〜12年ごろにはムスリム商人を中心に【イスラーム同盟(サレカット=イスラーム)】が結成されて、大衆的な民族運動に発展しました。1920年には【インドネシア共産党】も結成されています。1927年には【スカルノ】が【インドネシア国民党】を結成し、インドネシアの独立を掲げました。1928年には青年たちが「一つの祖国・一つの民族・一つの言語」を誓い、マレー語をもとにした【インドネシア語】を民族の言語としました。広大な島々に住む多様な人々を一つの民族としてまとめる意識が、この時期に生まれたのです。", "第二次世界大戦中、日本軍はオランダ領東インドとマラヤを占領しました。日本は石油やゴムなどの資源の獲得をめざし、住民を労働力として動員しました。一方で、独立運動の指導者を利用したため、スカルノらは日本の占領下で独立の準備を進めました。", "1945年8月、日本の降伏直後にスカルノは【インドネシア共和国】の独立を宣言し、初代大統領となりました。しかし植民地の回復をめざすオランダとの間で独立戦争が起こり、国際世論の圧力もあって、1949年にオランダは【ハーグ協定】でインドネシアの独立を承認しました。"]}, {"t": "独立後の歩みとASEAN", "p": ["独立後のスカルノは、1955年にバンドンで【アジア・アフリカ会議(バンドン会議)】を開き、【平和十原則】を採択して、第三世界の連帯と非同盟を世界に訴えました。国内では、民族主義・宗教・共産主義の勢力のバランスの上に立つ【指導される民主主義】を唱え、共産党とも結んで強い権力をふるいました。", "1965年、軍の一部によるクーデタ未遂事件である【九・三〇事件】が起こると、陸軍の【スハルト】がこれを鎮圧し、共産党の仕業として共産党員とされた人々を大規模に弾圧しました。この事件をきっかけにスカルノは失脚し、スハルトが1968年に大統領に就任しました。スハルトは反共・親米の立場をとり、軍の力を背景に開発を優先する【開発独裁】を進めて経済を成長させましたが、1997年の【アジア通貨危機】で経済が混乱すると民主化を求める運動が高まり、1998年に退陣しました。その後インドネシアは民主化を進め、2002年には住民投票を経て【東ティモール】が独立しました。", "マレー半島では、1957年に【マラヤ連邦】がイギリスから独立し、1963年にはシンガポール、ボルネオ島北部のサバ・サラワクと合わせて【マレーシア】が成立しました。しかし、マレー人を優遇する政府と、中国系住民が多いシンガポールとの対立から、1965年にシンガポールは分離独立しました。マレーシアでは1969年に民族間の暴動が起こったのち、マレー系住民を経済・教育面で優遇する【ブミプトラ政策】がとられました。1980年代には【マハティール】首相が日本や韓国に学ぶ【ルック=イースト政策】を掲げて工業化を進めました。", "1967年、インドネシア・マレーシア・シンガポール・タイ・フィリピンの5か国は【東南アジア諸国連合(ASEAN)】を結成しました。結成当初は反共の色彩が強い組織でしたが、冷戦後はベトナムなどインドシナ諸国も加わり、東南アジア全体の経済協力と地域の安定をめざす組織へと発展しています。古くから海の道の十字路として世界と結びついてきたこの地域は、今も世界の物流の要として重要な位置を占めています。"]}], "points": ["マラッカ海峡と季節風(モンスーン)が港市国家を生んだこと", "シュリーヴィジャヤ(7世紀・パレンバン・義浄)とシャイレンドラ朝(ボロブドゥール・大乗仏教)、プランバナン(ヒンドゥー教)", "マジャパヒト王国(1293年・元軍を退ける・ヒンドゥー教)", "マラッカ王国:鄭和の遠征を機に発展→国王がイスラームに改宗→1511年ポルトガルが占領", "オランダのバタヴィア建設(1619年)とアンボイナ事件(1623年)", "イギリスのシンガポール建設(1819年・ラッフルズ)と海峡植民地(1826年)、オランダの強制栽培制度(1830年)", "イスラーム同盟→インドネシア国民党(1927年・スカルノ)→独立宣言(1945年)", "九・三〇事件(1965年)とスハルトの開発独裁、マレーシア成立(1963年)とシンガポール分離(1965年)、ASEAN(1967年)"], "check": [["7世紀にパレンバンを中心に栄えた港市国家は?", "シュリーヴィジャヤ"], ["シャイレンドラ朝がジャワ島中部に造営した仏教遺跡は?", "ボロブドゥール"], ["1293年に元軍を退けてジャワ島東部に成立した王国は?", "マジャパヒト王国"], ["鄭和の遠征を機に発展し、国王がイスラームに改宗したマレー半島の港市国家は?", "マラッカ王国"], ["1511年にマラッカを占領した国は?", "ポルトガル"], ["1619年にオランダがジャワ島に建設した拠点は?", "バタヴィア"], ["1819年にシンガポールを建設したイギリス人は?", "ラッフルズ"], ["オランダがジャワで輸出用作物を栽培させた制度は?", "強制栽培制度"], ["1927年にインドネシア国民党を結成した人物は?", "スカルノ"], ["1965年にスカルノ失脚のきっかけとなった事件は?", "九・三〇事件"]], "related": ["t_ph", "t_th", "t_mm", "t_vn", "t_in", "t_nl", "t_uk", "t_es", "t_cn", "y_7", "y_8", "y_13", "y_15", "y_16", "y_17", "y_19", "y_20b"], "n": 4236}, "t_ph": {"title": "フィリピン史", "span": "10世紀ごろ〜現在", "year": 1898, "lead": "多くの島からなるフィリピンは、統一国家ができる前に16世紀にスペインの植民地となり、マニラを拠点とするアジアとアメリカ大陸を結ぶ交易の中継地になりました。19世紀末の独立運動はアメリカの支配に置き換えられ、日本の占領を経て1946年に独立しました。独立後はマルコスの長期独裁と、それを倒した民主化運動が大きな転機です。", "flow": ["10世紀ごろ〜 島々に小さな首長国、中国・東南アジアとの交易", "14〜16世紀 南部のミンダナオ島・スールー諸島にイスラーム教が広がる", "1521年 マゼランの船団が到達→マゼランは現地で戦死", "1571年 スペインのレガスピがマニラを建設→フィリピン統治の中心に", "16世紀後半〜 ガレオン貿易→メキシコ銀と中国の絹・陶磁器をマニラで交換", "1880年代〜 ホセ=リサールの民族運動→1896年処刑", "1896年 フィリピン革命→アギナルドが指導", "1898年 米西戦争→アメリカがフィリピンを獲得、1899年からフィリピン=アメリカ戦争", "1934年 独立法で10年後の独立を約束→1935年独立準備政府", "1942年 日本軍が占領→1945年アメリカが奪回", "1946年 フィリピン共和国独立", "1965年〜 マルコス政権→1986年の民衆の運動で退陣、コラソン=アキノ大統領"], "sync": [], "secs": [{"t": "スペイン到来以前の島々", "p": ["フィリピンは7000を超える島々からなる国で、ルソン島・ビサヤ諸島・ミンダナオ島が主な地域です。山がちで島が分かれているため、スペインが来るまで島全体をまとめる統一王朝は生まれませんでした。人々は【バランガイ】とよばれる村落共同体をつくり、首長のもとで暮らしていたとされます。この点は、早くから王朝が成立したタイやベトナム、ジャワとは大きく異なる特徴です。", "それでも島々は孤立していたわけではありません。10世紀ごろからは中国の商人が来航し、陶磁器や絹織物が持ちこまれました。フィリピン各地の遺跡から中国陶磁が多く見つかるのはそのためです。また、14〜16世紀にはマラッカ王国などを通じて【イスラーム教】が南部に伝わり、ミンダナオ島やスールー諸島にはイスラームの首長国(スルタン国)が成立しました。東南アジアの島々にイスラームが広がった大きな流れの東の端が、フィリピン南部だったのです。のちにスペインは北部・中部をカトリック化しますが、南部のイスラーム勢力は最後まで抵抗を続けました。現在も続くミンダナオ島のイスラーム系住民の自治問題は、この時代にさかのぼる歴史をもっています。"]}, {"t": "スペインの植民地化とガレオン貿易", "p": ["大航海時代、スペインは西回りでアジアをめざしました。1521年、スペイン王の支援を受けた【マゼラン】の船団がフィリピンに到達しましたが、マゼラン自身は現地の首長ラプラプとの戦いで戦死しました。残った船員が航海を続け、初の世界周航が達成されます。国名の「フィリピン」は、のちのスペイン王フェリペ2世にちなんで名づけられたものです。", "本格的な植民地化は、メキシコから派遣された【レガスピ】によって進められました。1571年、レガスピはルソン島に【マニラ】を建設し、ここをフィリピン統治の中心としました。スペインは島々の住民をカトリックに改宗させ、修道会が教会や学校をつくり、土地と人々の支配に大きな力をもちました。こうしてフィリピンは、現在まで東南アジアで珍しいキリスト教徒が多数を占める国となりました。", "マニラが重要だったのは、【ガレオン貿易(アカプルコ貿易)】の拠点になったからです。スペインはメキシコのアカプルコとマニラを大型帆船で結び、アメリカ大陸で産出した大量の【銀(メキシコ銀)】をマニラに運びました。マニラには福建などから中国商人が集まり、銀と引きかえに中国の絹織物や陶磁器を売りました。これらの品はアカプルコを経てスペイン本国やヨーロッパへ送られます。つまりマニラは、アメリカ大陸の銀がアジアに流れこむ入口となったのです。この銀は明の財政にも取りこまれ、銀で税を納める【一条鞭法】が広まる背景の一つにもなりました。マニラには日本人町もつくられ、16世紀末〜17世紀初めには朱印船貿易の行き先にもなりました。", "一方で、スペインの支配は先住民の負担と反発を生みました。中国人商人も経済的に重要でしたが、数が増えると警戒され、たびたび迫害を受けました。フィリピンの社会は、スペイン人の役人や修道士、中国系の商人、スペイン人と現地人の混血などが入りまじる重層的な構造になっていきます。", "さらにスペインは、南部のイスラーム勢力を完全には征服できませんでした。スペイン人は彼らを、イベリア半島のイスラーム教徒をよんだ呼び名にちなんで「モロ」とよび、数百年にわたって戦いをくり返しました。レコンキスタを戦い抜いたスペインにとって、アジアでも再びイスラーム勢力と向き合うことになったのです。"]}, {"t": "19世紀の変化とフィリピン革命", "p": ["19世紀になると、フィリピンは世界経済に深く組みこまれていきました。ガレオン貿易は1815年に終わり、かわって1830年代以降マニラが外国貿易に開放されると、【サトウキビ】や【マニラ麻】、タバコなど輸出用の商品作物の栽培が広がりました。この経済の変化によって、土地を持ち教育を受けた現地生まれの富裕層が育ちます。彼らの中からスペインに留学する若者が現れ、ヨーロッパの自由主義思想にふれて、スペインの支配や修道会の特権を批判するようになりました。", "その代表が【ホセ=リサール】です。リサールは医師で作家でもあり、小説『ノリ=メ=タンヘレ(われにふれるな)』で修道会の横暴と植民地社会の矛盾を描きました。彼は暴力ではなく、スペイン本国と同じ権利を求める改革(プロパガンダ運動)を訴え、1892年にはフィリピン民族同盟を結成します。しかしスペイン当局はリサールを危険視して流刑にしました。", "同じころ、より急進的な秘密結社【カティプーナン】がボニファシオによって結成され、武力による独立をめざしました。1896年にカティプーナンが蜂起して【フィリピン革命】が始まると、スペインは直接関与していなかったリサールまで処刑しました。リサールの死はかえって人々の怒りを高め、彼は国民的英雄となりました。革命の主導権はやがて【アギナルド】に移り、アギナルドは一時スペインと和解して国外に出ましたが、のちの米西戦争をきっかけに再び立ち上がることになります。"]}, {"t": "アメリカの統治", "p": ["1898年、キューバの独立問題をきっかけに【アメリカ=スペイン戦争(米西戦争)】が起こりました。アメリカ艦隊はマニラ湾でスペイン艦隊を破り、アメリカの支援を期待したアギナルドは帰国して独立を宣言し、1899年にはフィリピン共和国(マロロス共和国)を樹立しました。ところが、戦争を終わらせた1898年のパリ条約で、スペインはフィリピンを【グアム・プエルトリコ】とともにアメリカに譲りました。アメリカは独立を認めず、フィリピンを領有したのです。", "このため1899年から【フィリピン=アメリカ戦争】が始まりました。アメリカ軍は大軍を送りこんでゲリラ戦を鎮圧し、1901年にアギナルドを捕らえました。この戦争では多くのフィリピン人が犠牲になり、アメリカ国内でも植民地をもつことへの反対論(反帝国主義)が起こりました。アメリカにとってフィリピン領有は、19世紀末に西部の【フロンティア】が消滅したあと、太平洋とアジアの市場へ進出する足がかりでした。同じころアメリカはハワイも併合し、中国については【門戸開放宣言】を出しています。", "アメリカの統治は、スペイン時代と異なり、英語による公教育の普及や、選挙による議会の設置など、段階的な自治の拡大を特徴としました。ただし地主層の力はそのまま残り、経済はアメリカへの砂糖などの輸出に依存する形になりました。1930年代、世界恐慌の中でアメリカ国内ではフィリピン産の砂糖と競合する農業団体などが独立を後押しし、1934年に10年後の独立を約束する法律(タイディングズ=マクダフィー法)が成立しました。翌1935年には【独立準備政府(コモンウェルス)】が発足し、ケソンが大統領となりました。"]}, {"t": "日本の占領と独立", "p": ["独立準備が進む中、1941年に太平洋戦争が始まると、日本軍はフィリピンに上陸し、1942年にはアメリカ軍を追い出して占領しました。日本は1943年にフィリピンを「独立」させてラウレルを大統領とする政権をつくりましたが、実際には日本の戦争に協力させるためのものでした。フィリピンでは抗日ゲリラの活動が続き、共産党系の【フクバラハップ(フク団)】も日本軍と戦いました。1944〜45年にアメリカ軍が反攻し、マニラは激しい市街戦で大きな被害を受けました。", "戦後、約束どおり1946年に【フィリピン共和国】が独立しました。ただし独立後もアメリカとの結びつきは強く、アメリカの軍事基地が残され、経済面でもアメリカに有利な取り決めが結ばれました。冷戦の中でフィリピンはアメリカ側に立ち、1951年に米比相互防衛条約を結び、1954年には【東南アジア条約機構(SEATO)】に加盟しました。国内では土地改革を求めるフク団の反乱が続きましたが、マグサイサイ政権のもとで鎮圧されました。1967年には、タイ・マレーシア・シンガポール・インドネシアとともに【ASEAN(東南アジア諸国連合)】の原加盟国となっています。", "日本との関係では、戦争で受けた大きな被害のため戦後の対日感情はきびしく、1956年に賠償協定が結ばれてようやく国交が正常化しました。賠償は日本の工業製品や役務の提供という形で行われ、これがのちの日本企業の東南アジア進出の足がかりにもなりました。このような賠償と経済協力の組み合わせは、ビルマやインドネシアなどとの関係でも見られた戦後日本の対東南アジア外交の型です。フィリピンの歴史を学ぶときは、スペイン・アメリカ・日本という三つの外国支配が、それぞれ宗教・言語と教育・戦争の記憶という異なる形で現在の社会に跡を残していることを意識するとよいでしょう。"]}, {"t": "マルコス独裁と民主化", "p": ["1965年に大統領となった【マルコス】は、1972年に戒厳令を出して議会を停止し、長期の独裁体制を築きました。共産ゲリラやイスラーム系勢力の活動を理由に治安を強化し、アメリカも反共の立場からこれを支えました。マルコス政権は外資を導入して経済開発を進める【開発独裁】の一つとされますが、大統領の一族や側近による利権の独占と汚職が深刻になりました。", "1983年、亡命先から帰国した野党指導者ベニグノ=アキノがマニラ空港で暗殺されると、国民の不満は一気に高まりました。1986年の大統領選挙で不正が明らかになると、軍の一部も離反し、首都の大通りに数十万人の市民が集まって政権に退陣を求めました。マルコスは国外に逃れ、ベニグノの妻【コラソン=アキノ】が大統領に就任しました。この政変は、流血を避けて市民の力で独裁を倒したことから【ピープルパワー(エドサ革命)】とよばれ、同じ1980年代後半の韓国や台湾の民主化とならぶアジアの民主化の象徴となりました。", "民主化後、1991年のピナトゥボ山の噴火も重なってアメリカ軍の基地は1992年までに返還されました。その後も貧富の格差、ミンダナオの自治問題、南シナ海をめぐる中国との対立など課題は多くありますが、海外で働く人々の送金や英語力を生かしたサービス産業によって、人口の多い若い国として成長を続けています。"]}], "points": ["1571年レガスピがマニラを建設→スペインのフィリピン統治の中心", "ガレオン貿易(アカプルコ貿易):メキシコ銀と中国の絹・陶磁器をマニラで交換→明の銀経済", "南部ミンダナオ島のイスラーム化と、北部・中部のカトリック化の対比", "ホセ=リサール(『ノリ=メ=タンヘレ』、1896年処刑)とカティプーナン、アギナルドのフィリピン革命", "1898年米西戦争→フィリピン・グアム・プエルトリコがアメリカ領、フィリピン=アメリカ戦争", "1934年独立法→1935年独立準備政府→1946年独立", "マルコスの開発独裁と1986年のピープルパワー(コラソン=アキノ大統領)", "ASEAN原加盟国(1967年)、SEATO加盟"], "check": [["16世紀後半にスペインが建設し、フィリピン統治の中心とした都市は?", "マニラ"], ["マニラとメキシコのアカプルコを結んだスペインの貿易は?", "ガレオン貿易(アカプルコ貿易)"], ["1521年にフィリピンに到達し、現地で戦死した航海者は?", "マゼラン"], ["『ノリ=メ=タンヘレ』を書き、1896年に処刑されたフィリピンの民族運動家は?", "ホセ=リサール"], ["フィリピン革命を指導し、1899年に共和国の大統領となった人物は?", "アギナルド"], ["米西戦争の結果、アメリカが獲得した領土は?", "フィリピン・グアム・プエルトリコ"], ["1972年に戒厳令を出し長期独裁を行ったフィリピン大統領は?", "マルコス"], ["1986年のピープルパワーで大統領に就任した人物は?", "コラソン=アキノ"]], "related": ["t_es", "t_us", "t_la", "t_id", "t_th", "t_cn", "y_16", "y_17", "y_19", "y_20a", "y_20b"], "n": 4093}, "t_cn": {"title": "中国史", "span": "前5000年ごろ〜現在", "year": -221, "lead": "黄河・長江流域の農耕文化から殷・周が生まれ、秦の始皇帝が初めて中国を統一してから、漢・唐・宋・元・明・清と王朝が交代しながら皇帝による中央集権の国家が続きました。北方の遊牧民との対立と融合、科挙と儒学による官僚制、銀を中心とする経済の発展がこの長い歴史を貫く軸です。19世紀には欧米と日本の圧力で半植民地化し、辛亥革命・国共の対立を経て1949年に中華人民共和国が成立しました。", "flow": ["前5000年ごろ〜 黄河流域に仰韶文化・竜山文化、長江流域に河姆渡遺跡", "前16世紀ごろ 殷→神権政治と甲骨文字、前11世紀ごろ周が封建制、前770年周の東遷→春秋・戦国時代", "前221年 秦の始皇帝が統一→郡県制、焚書・坑儒", "前202年 劉邦が漢を建国→武帝のとき儒学の官学化、匈奴と対決", "220年〜 魏晋南北朝の分裂→五胡の華北進出、北魏の均田制→589年隋が統一", "618年 唐→律令体制と国際文化、755年安史の乱→780年両税法", "960年 宋→文治主義と科挙の完成、遼・西夏・金の圧迫、1127年靖康の変で南宋へ", "1271年 フビライが国号を元に→1279年南宋を滅ぼす、1368年朱元璋が明を建国→鄭和の遠征・一条鞭法", "1644年 清が北京に入る→康熙・雍正・乾隆の最盛期、地丁銀制", "1840年 アヘン戦争→南京条約、太平天国・洋務運動・日清戦争・義和団", "1911年 辛亥革命→1912年中華民国、1919年五・四運動", "1949年 中華人民共和国成立→大躍進・文化大革命、1978年から改革・開放"], "sync": [], "secs": [{"t": "文明のはじまりと殷・周", "p": ["中国の文明は、黄河と長江という二つの大河の流域で育ちました。黄河中流域では彩文土器(彩陶)を特徴とする【仰韶文化】、その後に黒陶を特徴とする【竜山文化】が栄え、アワやキビの畑作が行われました。長江下流域の【河姆渡遺跡】からは稲作の跡が見つかっており、中国文明は黄河だけでなく複数の地域で同時に育ったと考えられています。", "やがて黄河流域に、現在確認できる最古の王朝【殷】が成立しました。殷の王は占いによって神の意思を問い、その結果にもとづいて政治を行う【神権政治】を行いました。占いの内容を亀の甲や牛の骨に刻んだのが甲骨文字で、漢字の起源です。都の跡【殷墟】からは、精巧な【青銅器】が多数出土しています。", "前11世紀ごろ、殷を倒した【周】は都を【鎬京】におき、一族や功臣に土地を与えて諸侯とし、代わりに軍役や貢納を求める【封建制】をしきました。この秩序は血縁にもとづく【宗法】によって支えられていました。また周は、天命を受けた有徳者が天子として治め、徳を失えば天命が改まるという【易姓革命】の考えで王朝交代を正当化しました。これは以後の中国王朝の交代を説明する思想として長く使われます。"]}, {"t": "春秋・戦国から秦・漢の統一へ", "p": ["前770年、周は異民族の侵入を受けて都を東の【洛邑】に移しました。これ以後を【春秋時代】とよびます。周王の権威は残っており、有力諸侯は【覇者】として周王を立てつつ他の諸侯をまとめる【尊王攘夷】を掲げました。斉の【桓公】がその代表です。しかし前5世紀に入る【戦国時代】には、諸侯が周王を無視して王を名乗り、【戦国の七雄】が争いました。", "戦乱の時代は社会を大きく変えました。【鉄製農具と牛耕】が広まって農業生産が上がり、【刀銭】や【布銭】などの青銅貨幣が流通しました。各国は強い国をつくるため有能な人材を求め、【諸子百家】とよばれる思想家が活躍します。【孔子】は仁と礼による徳治を説いて儒家を開き、【孟子】は性善説と王道政治、【荀子】は性悪説を唱えました。【老子】・【荘子】の道家、兼愛を説く【墨子】、法による統治を説く【韓非】の法家などが現れました。", "戦国の諸国のうち、法家の【商鞅】の改革で強国となった秦は、前221年、【始皇帝】のもとで中国を初めて統一しました。始皇帝は全国を郡と県に分けて中央から官吏を派遣する【郡県制】を全国に施行し、度量衡・貨幣(【半両銭】)・文字を統一しました。思想統制として【焚書・坑儒】を行い、北方の【匈奴】に対しては長城を修築しました。しかし急激な改革と土木工事への動員は民衆を苦しめ、始皇帝の死後に【陳勝・呉広の乱】が起こり、秦はわずか15年ほどで滅びます。", "秦のあとを継いだのが、【項羽】を破った【劉邦(高祖)】の【漢】です。漢は都を【長安】におき、郡県制と封建制を併用する【郡国制】で始めましたが、【呉楚七国の乱】を鎮圧したのちは実質的に中央集権化しました。前2世紀後半の【武帝】の時代が最盛期で、【張騫】を西域に派遣し、匈奴を攻撃し、朝鮮に【楽浪郡】などを置きました。内政では【董仲舒】の献策によって儒学を官学とし、【五経博士】を置いて、儒学が国家の正統思想となる基礎ができました。遠征の費用をまかなうため塩・鉄の専売や【均輸法】・【平準法】も行いました。一時、外戚の【王莽】が新を建てますが、【赤眉の乱】で倒れ、【劉秀(光武帝)】が漢を復興して都を【洛陽】におきました(後漢)。後漢は西域に【班超】を派遣するなど勢力を保ちましたが、宦官と官僚の対立(【党錮の禁】)のなかで、184年に【黄巾の乱】が起こり、衰退していきます。"]}, {"t": "魏晋南北朝:分裂の中の融合", "p": ["後漢が衰えると、群雄が争い、【赤壁の戦い】を経て魏・【蜀】・【呉】の三国が並び立ちました。魏は官吏登用法として【九品中正】を始めましたが、これは結果として有力な家柄の者ばかりが高官につく【門閥貴族】の社会を生みました。魏をついだ晋(西晋)は一時中国を統一しましたが、【八王の乱】で混乱し、そのすきに【五胡】とよばれる北方・西方の諸民族が華北に入り、【永嘉の乱】で西晋は滅びました。", "以後、華北では五胡の政権が興亡する【五胡十六国】の時代となり、江南では【司馬睿】が【建康】に東晋を建てました。華北の混乱から逃れた漢人が多く南に移り、江南の開発が進みます。華北を統一したのは鮮卑の【北魏】で、【孝文帝】は都を洛陽に移し、漢人の服装や言語を取り入れる【漢化政策】を進めました。北魏が始めた【均田制】(土地を国家が民に分け与える制度)と【三長制】は、のちの隋・唐の土地制度の原型となります。この時代には仏教が広まり、【雲崗石窟寺院】・【竜門石窟寺院】が造られました。", "江南の東晋とそれに続く宋・斉・梁・陳を【南朝】といい、建康を都とした呉から陳までの六つの王朝を【六朝】とよびます。南朝では貴族文化が栄え、書の【王羲之】、画の【顧愷之】、詩の【陶淵明(陶潜)】が活躍し、梁の昭明太子は詩文集『【文選】』を編みました。分裂の時代は、北方民族と漢人が混じり合い、新しい制度と文化が生まれる準備期間でもあったのです。"]}, {"t": "隋・唐:律令国家と東アジア世界", "p": ["589年、北周から出た【楊堅(文帝)】の隋が南朝の陳を滅ぼし、約300年ぶりに中国を統一しました。文帝は門閥貴族の力をおさえるため、学科試験で官吏を選ぶ【科挙】を始めました。次の【煬帝】は華北と江南を結ぶ大運河を完成させ、経済の中心となりつつあった江南の物資を北へ運べるようにしました。しかし3度にわたる【高句麗】遠征の失敗と重い負担で反乱が起こり、隋は短期間で滅びました。", "618年に【李淵(高祖)】が建てた【唐】は、2代【太宗(李世民)】の時代に体制を固めました。中央には【中書省】・【門下省】・【尚書省】の三省と六部を置き、刑法の【律】、行政法の令、施行細則の【式】などからなる律令を整えました。土地は【均田制】で農民に分け、【租調庸制】で税を取り、【府兵制】で兵を集めるという、土地・税・兵役が一体となった仕組みです。周辺民族には【都護府】を置いて現地の首長に統治をまかせる【羈縻政策】をとりました。", "唐の都長安は国際都市となり、シルクロードを通じてソグド商人や西方の宗教(【景教】・【祆教】・マニ教)が入りました。日本も遣唐使を送って律令や都城(【平城京】)を学び、【新羅】・【渤海】なども唐の制度を取り入れました。唐を中心に、漢字・儒学・仏教・律令を共有する東アジア文化圏が形づくられたのです。文化では【李白】・【杜甫】・【白居易】の詩、【顔真卿】の書が名高く、【唐三彩】も作られました。", "唐は【則天武后(武則天)】の時代を経て、玄宗の【開元の治】で最盛期を迎えます。しかし人口増加などで均田制が崩れ、府兵制から【募兵制】に変わり、辺境には大きな兵力をもつ【節度使】が置かれました。751年の【タラス河畔の戦い】ではアッバース朝に敗れています。755年、節度使の【安禄山】らが起こした【安史の乱】は、唐を大きく揺るがしました。乱は【ウイグル】の援軍も得て鎮圧されましたが、各地の節度使が自立し、財政再建のため780年に土地の所有額に応じて夏・秋の2回課税する【両税法】が採用されました。これは均田制の放棄を意味します。9世紀後半の【黄巣の乱】で唐は事実上崩壊し、907年に節度使の【朱全忠】が唐を滅ぼしました。"]}, {"t": "宋と北方民族:経済の発展と文治主義", "p": ["唐の滅亡後、華北では五つの王朝が交代し、各地に十あまりの国が分立する【五代十国】の時代となりました。この間、北方の【遼(契丹)】は後晋から【燕雲十六州】を得ています。960年、【趙匡胤(太祖)】は宋(北宋)を建て、都を【開封】におきました。太祖は武人の節度使が国を乱した反省から、文官を重んじる【文治主義】をとり、科挙の最終試験として皇帝自らが行う【殿試】を設けました。科挙官僚の多くは、新興の地主層である【形勢戸】の出身でした。", "しかし文治主義は軍事力の弱さにもつながりました。宋は遼と1004年に【澶淵の盟】を結んで毎年銀や絹を贈り、西方の【西夏】とも【慶暦の和約】で同様の関係を結びました。財政難を立て直すため、神宗のもとで【王安石】が【青苗法】・【市易法】・【募役法】・【保甲法】などの新法を行いましたが、大地主や大商人の利益をおさえる改革だったため、【司馬光】らの旧法党が反対し、党争が続きました。やがて女真の【金】が遼を滅ぼし、1126〜27年の【靖康の変】で開封を攻め落とし、【徽宗】らを連れ去りました。皇族の【高宗】は江南に逃れて【臨安(杭州)】を都に南宋を建て、【淮河】を国境として金と和議を結びました。和平派の【秦檜】と抗戦派の【岳飛】の対立はこのときのものです。", "北方民族の国家は、遊牧民と農耕民を別々の制度で治める工夫をしました。遼は【二重統治体制】をとり、金は【猛安・謀克】という軍事・行政組織を用いました。また【契丹文字】・【西夏文字】・【女真文字】など独自の文字もつくっています。", "宋代は経済が大きく発展した時代です。江南の開発が進み、ベトナム原産の【占城稲】の導入もあって「【蘇湖】熟すれば天下足る」といわれました。商業が盛んになって【草市・鎮】とよばれる市場町が生まれ、商人の同業組合【行】、手工業者の【作】が組織されました。紙幣の【交子】(北宋)・【会子】(南宋)も使われ、【景徳鎮】の陶磁器は海外へ輸出されました。文化面では、【周敦頤】に始まり南宋の【朱熹(朱子)】が大成した【朱子学】(宋学)が生まれ、【大義名分論】などを通じて東アジアに大きな影響を与えました。"]}, {"t": "元と明:モンゴルの統一と漢人王朝の復活", "p": ["13世紀、【チンギス=ハン】が統一したモンゴルは急速に領土を広げ、1234年に金を滅ぼしました。孫の【フビライ=ハン】は大都(現在の北京)に都を移し、1271年に国号を【元】と定め、1279年に南宋を滅ぼして中国全土を支配しました。元はモンゴル人を頂点に、中央アジア・西アジア出身の【色目人】を財務などに登用し、旧金領の【漢人】、旧南宋の【南人】を下に置きました。科挙は一時停止され、漢人の知識人は官界から遠ざけられたため、【元曲】などの庶民文化に才能を注ぎました。駅伝制の【ジャムチ(站赤)】によってユーラシアの交通が結ばれ、【マルコ=ポーロ】らが来訪しました。一方、紙幣【交鈔】の乱発で経済が混乱し、1351年に【紅巾の乱】が起こります。", "紅巾の乱の中から出た【朱元璋(洪武帝)】は、1368年に【南京】で明を建て、元を北に追いました。洪武帝は宰相の職(中書省)を廃止して皇帝に権力を集中させ、村落を【里甲制】で組織し、租税台帳の【賦役黄冊】と土地台帳の【魚鱗図冊】をつくり、民衆教化のため【六諭】を定めました。対外的には民間の海上貿易を禁じる【海禁】をとり、朝貢貿易のみを認めました。", "洪武帝の死後、【靖難の役】で帝位を奪った【永楽帝】は都を【北京】に移し、モンゴル高原に遠征し、【鄭和】に大艦隊を率いさせて南海諸国から東アフリカまで遠征させ、朝貢を促しました。しかし15世紀半ばには【土木の変】で皇帝がオイラトの【エセン】に捕らえられ、その後は長城を修築して守りを固めます。16世紀には北のモンゴル(【アルタン=ハン】)と南の倭寇に苦しむ【北虜南倭】に直面し、さらに【豊臣秀吉】の朝鮮出兵に援軍を送って財政が悪化しました。", "この時代、日本銀やアメリカ大陸の銀が大量に流入し、税や労役をまとめて銀で納める【一条鞭法】が普及しました。【張居正】の財政再建も一時的で、宦官と官僚の対立(【東林派】)が続く中、1644年、【李自成】の反乱軍が北京を落として明は滅びました。明代には【陽明学】を唱えた【王守仁(王陽明)】、『【本草綱目】』『【天工開物】』などの実学書、『【三国志演義】』『【水滸伝】』『【西遊記】』などの小説が生まれ、【マテオ=リッチ】らイエズス会士が西洋の学問を伝えました。"]}, {"t": "清:最後の王朝の繁栄と動揺", "p": ["中国東北部では、女真の【ヌルハチ】が【八旗】を組織して後金を建て、子の【ホンタイジ】が国号を清と改めました。明が李自成に倒されると、清は明の将軍【呉三桂】の手引きで北京に入り、中国支配を始めます。4代【康熙帝】は【三藩の乱】を鎮め、台湾の【鄭成功】一族を降伏させ、ロシアと1689年に【ネルチンスク条約】を結んで国境を定めました。続く【雍正帝】は【軍機処】を設け、ロシアと【キャフタ条約】を結びました。【乾隆帝】の時代にはジュンガルを滅ぼして【新疆】とし、清は最大の領域を実現しました。モンゴル・チベット・新疆は【藩部】として【理藩院】が管轄しました。", "清は少数の満洲人が多数の漢人を治めるため、要職に満洲人と漢人を同数ずつ置く【満漢併用制】をとる一方、【辮髪】を強制し、【文字の獄】で反清的な言論を弾圧しました。また『【康熙字典】』『【四庫全書】』などの大編纂事業で知識人を取りこみました。税制では、人頭税を土地税に組みこむ【地丁銀制】が実施されました。サツマイモやトウモロコシなど新大陸の作物の普及もあって、18世紀に人口は急増しますが、それは土地不足と社会不安も生みました。18世紀末の【白蓮教徒の乱】は、その表れです。"]}, {"t": "近代・現代:半植民地化から中華人民共和国へ", "p": ["清は欧米との貿易を【広州】一港に限り、特許商人の【公行】に独占させていました。茶の輸入で銀が流出していたイギリスは、インド産アヘンを中国に密輸する三角貿易で対抗しました。アヘンの害と銀の流出に苦しんだ清が取り締まりを強めると、1840年に【アヘン戦争】が起こり、敗れた清は1842年の【南京条約】で香港を割譲し、5港を開港しました。続く不平等条約で、清は関税自主権を失い、領事裁判権を認めます。アロー戦争後の北京条約ではさらに権益を奪われました。", "国内では、洪秀全が率いる【太平天国の乱】(1851〜64年)が南京を占領して清を揺るがしました。これを鎮圧した曽国藩・李鴻章ら漢人官僚は、西洋の技術を取り入れる【洋務運動】を進めましたが、「中体西用」の考えのもと政治体制は変えませんでした。その限界は日清戦争(1894〜95年)の敗北で明らかになり、列強は中国分割を進めます。変法運動は戊戌の政変でつぶれ、義和団事件のあと清はようやく改革に乗り出しましたが、1911年の【辛亥革命】で倒れ、1912年に【孫文】を臨時大総統とする中華民国が成立しました。", "しかし中華民国は袁世凱の独裁と軍閥の割拠で混乱しました。日本の【二十一か条の要求】への反発から、1919年に【五・四運動】が起こり、民族運動が広がります。雑誌『【新青年】』による新文化運動では【胡適】や【魯迅】が活躍しました。1921年に【中国共産党】が結成され、国民党と【第1次国共合作】を結びますが、北伐の途中で蔣介石が【上海クーデタ】で共産党を弾圧しました。日本の【満州事変】、【盧溝橋事件】による日中戦争が始まると、【西安事件】をきっかけに第2次国共合作が成立し、抗日戦争を戦いました。", "日本の敗戦後、国共内戦に勝利した共産党は、1949年に【毛沢東】を主席、【周恩来】を首相とする【中華人民共和国】を建国し、国民党は【台湾】に逃れました。新中国は1950年に【中ソ友好同盟相互援助条約】を結んでソ連側に立ち、朝鮮戦争に義勇軍を送りました。1958年からの【大躍進】は急激な集団化で大量の餓死者を出して失敗し、1966年からの【プロレタリア文化大革命】では毛沢東が権力を取り戻すために紅衛兵を動員し、社会と文化が大きく破壊されました。この間、中ソ対立が深まり、1969年には【珍宝島(ダマンスキー島)】で武力衝突が起こり、中国はアメリカに接近しました。", "毛沢東の死後、実権を握った鄧小平は1978年から【改革・開放政策】に転じ、人民公社を解体し、経済特区を設けて外国資本を導入しました。経済は急成長しましたが、政治の民主化は認められず、1989年の【天安門事件(第2次)】では民主化を求める学生・市民が武力で鎮圧されました。1997年に【香港】、1999年に【マカオ】が返還され、「一国二制度」が適用されました。台湾では【李登輝】のもとで民主化が進み、中国との関係は現在も東アジアの重要な課題となっています。"]}], "points": ["殷の神権政治と甲骨文字、周の封建制・宗法、易姓革命(禅譲・放伐)", "秦の始皇帝(前221年統一):郡県制、度量衡・貨幣・文字の統一、焚書・坑儒", "漢の郡国制、武帝の儒学官学化・匈奴攻撃・塩鉄専売", "土地・税・兵制の変化:均田制・租調庸制・府兵制→両税法(780年)・募兵制", "宋の文治主義と殿試、澶淵の盟、王安石の新法、靖康の変と南宋", "元の色目人・漢人・南人の区分とジャムチ、明の海禁・鄭和・一条鞭法", "清の満漢併用制・辮髪・文字の獄、ネルチンスク条約、地丁銀制", "アヘン戦争→南京条約、洋務運動の限界、辛亥革命、五・四運動、改革・開放"], "check": [["前221年に中国を統一し、郡県制を全国に施行した皇帝は?", "始皇帝"], ["漢の武帝に儒学の官学化を献策した学者は?", "董仲舒"], ["北魏で始まり、隋・唐に受け継がれた土地制度は?", "均田制"], ["780年に唐で採用された、土地所有額に応じて年2回課税する税法は?", "両税法"], ["1004年に宋と遼が結んだ和議は?", "澶淵の盟"], ["北宋の神宗のもとで新法を行った宰相は?", "王安石"], ["明の永楽帝の命で南海遠征を行った宦官は?", "鄭和"], ["税と労役を銀でまとめて納める明代の税制は?", "一条鞭法"], ["1689年に清とロシアが結んだ国境条約は?", "ネルチンスク条約"], ["1978年から鄧小平が進めた経済政策は?", "改革・開放政策"]], "related": ["t_kr", "t_mn", "t_vn", "t_uk", "t_ru", "y_bc4", "y_bc2", "y_7", "y_8", "y_11", "y_13", "y_15", "y_18", "y_19", "y_20a", "y_20b"], "n": 6560}, "t_kr": {"title": "朝鮮史", "span": "前2世紀〜現在", "year": 1392, "lead": "朝鮮半島は中国と日本のあいだにあり、漢の楽浪郡、三国時代を経て新羅・高麗・朝鮮(李氏朝鮮)と統一王朝が続きました。中国王朝の冊封を受けながら独自の文化(高麗青磁・ハングル)を育て、北方民族やモンゴル、日本の侵攻にさらされました。近代には日本の植民地となり、解放後は冷戦のなかで南北に分断され、朝鮮戦争を経て現在に至ります。", "flow": ["前108年 漢の武帝が衛氏朝鮮を滅ぼし楽浪郡など4郡を置く", "4世紀 高句麗が楽浪郡を滅ぼす→高句麗・百済・新羅の三国時代", "663年 白村江の戦い→唐・新羅が百済・倭の連合軍を破る", "676年 新羅が半島の大部分を統一→骨品制、仏国寺", "918年 王建が高麗を建国→936年半島統一、科挙・高麗青磁", "13世紀 モンゴルの侵攻→高麗は服属、元寇に動員される", "1392年 李成桂が朝鮮(李氏朝鮮)を建国→朱子学と両班", "1446年 世宗が訓民正音(ハングル)を公布", "1592年・1597年 豊臣秀吉の出兵(壬辰・丁酉倭乱)→李舜臣の水軍が抵抗", "1876年 日朝修好条規で開国→甲午農民戦争・日清戦争", "1910年 韓国併合→1919年三・一独立運動", "1948年 大韓民国・朝鮮民主主義人民共和国の成立→1950年朝鮮戦争"], "sync": [], "secs": [{"t": "古代:楽浪郡と三国の時代", "p": ["朝鮮半島北部には、前2世紀に衛氏朝鮮とよばれる国がありました。前108年、漢の【武帝】はこれを滅ぼし、現在の平壌付近に【楽浪郡】など4つの郡を置いて直接支配しました。楽浪郡は中国の文化や技術が朝鮮半島や日本列島に伝わる窓口となり、倭の諸国も楽浪郡を通じて漢に使いを送ったとされます。", "中国東北部から起こった【高句麗】は、中国が分裂した混乱に乗じて勢力を広げ、313年に楽浪郡を滅ぼしました。半島南部では、西に【百済】、東に【新羅】が成立し、南端には小国の連合である加耶(加羅)がありました。こうして4世紀から7世紀にかけて、三国が争う【三国時代】が続きます。三国はいずれも中国の南北朝に使いを送って仏教や儒学を取り入れ、百済は日本(倭)と結んで仏教などを伝えました。", "高句麗は5世紀に都を平壌に移して最盛期を迎え、のちに中国を統一した隋の煬帝による3度の遠征をしりぞけました。この遠征の失敗は隋が滅びる原因の一つになっています。半島の歴史は、このように中国の王朝交代と深く結びついているのです。"]}, {"t": "新羅の統一と高麗", "p": ["7世紀、唐が成立すると、新羅は唐と同盟して勢力の拡大をはかりました。唐・新羅連合軍は660年に百済を滅ぼし、百済の復興を助けようとした倭の軍を663年の【白村江の戦い】で破りました。668年には高句麗も滅びます。その後、新羅は半島を直接支配しようとした唐の勢力を追い出し、676年に大同江以南の半島を統一しました。この敗北をきっかけに、日本は唐・新羅の侵攻に備えて防衛を固め、律令国家づくりを急ぐことになります。", "統一後の新羅は唐の冊封を受け、律令や仏教文化を取り入れました。都の金城(慶州)には【仏国寺】が建てられ、仏教文化が栄えました。一方で、社会は血統によって身分や就ける官職を厳しく定める【骨品制】に支えられていました。なお、高句麗の滅亡後、その遺民と靺鞨人は中国東北部に【渤海】を建て、唐の制度を取り入れて「海東の盛国」とよばれ、日本とも盛んに交流しました。", "9世紀になると新羅では王位争いと地方豪族の自立が進み、混乱の中から918年に【王建】が【高麗】を建国しました。高麗は936年に半島を再統一し、都を開城におきました。高麗は中国にならって【科挙】を取り入れ、文官・武官からなる両班の官僚制をつくりました。文化では、美しい青緑色の【高麗青磁】や、仏教の経典を集大成した【高麗版大蔵経】が知られます。また、世界最古級の金属活字による印刷も行われたとされます。", "高麗は北方の契丹(遼)や女真(金)の圧迫を受け、12世紀には武臣が実権を握る武臣政権の時代に入りました。13世紀にはモンゴルが侵入し、高麗は都を江華島に移して約30年間抵抗しましたが、最終的に服属しました。元の支配下で高麗は日本遠征(【元寇(文永の役・弘安の役)】)のための船と兵を負担させられ、大きな犠牲を払いました。抵抗を続けた三別抄の反乱もこの時期のできごとです。"]}, {"t": "朝鮮王朝(李氏朝鮮)の成立と文化", "p": ["14世紀後半、元が衰えて明が興ると、高麗の内部では親元派と親明派が対立しました。倭寇の撃退で名を上げた武将【李成桂】は実権を握り、1392年に高麗を倒して【朝鮮(李氏朝鮮)】を建国しました。都は漢城(現在のソウル)におかれ、明の冊封を受けて朝貢を行いました。", "朝鮮王朝は高麗時代に保護された仏教をおさえ、【朱子学】を国家の正統な学問としました。政治と社会の中心となったのは、科挙に合格して官僚となる【両班】とよばれる支配階層です。両班は土地を所有し、儒教の礼にもとづく家族制度や祖先祭祀を重んじました。朝鮮の朱子学は中国以上に厳格だったとされ、のちに江戸時代の日本の朱子学にも影響を与えました。", "15世紀前半の第4代国王【世宗】は、朝鮮王朝の最盛期をきずいた王です。世宗は、漢字を学べない民衆でも自分たちの言葉を書き表せるように、1446年に表音文字の【訓民正音(ハングル)】を公布しました。また金属活字による印刷や天文観測器・雨量計の製作など、学問と技術の振興にも努めました。ただし公文書や両班の学問では漢文が使われ続け、ハングルが広く公的に使われるのは近代以降のことです。"]}, {"t": "倭乱・胡乱と近世の朝鮮", "p": ["16世紀末、日本を統一した【豊臣秀吉】は明の征服をめざして朝鮮に大軍を送りました。1592年の壬辰倭乱(文禄の役)と1597年の丁酉倭乱(慶長の役)です。日本軍は一時半島の大部分を制圧しましたが、【李舜臣】が率いる水軍が【亀甲船】を用いて日本の水軍を破り、補給を断ちました。各地で義兵も抵抗し、明が援軍を送ったこともあって、秀吉の死を機に日本軍は撤退しました。朝鮮は国土が荒廃し、明も出兵の負担で財政が悪化して、女真の自立を許す一因となりました。", "17世紀前半、女真の後金(清)が朝鮮に侵入し、朝鮮は清に服属させられました(丁卯・丙子胡乱)。朝鮮は清の冊封を受けましたが、知識人のあいだでは、明こそ正統な中華であり、自分たちこそがその文化を受けつぐ「小中華」だという意識が強まりました。一方、日本とは江戸幕府のもとで国交が回復し、対馬藩の宗氏を通じた貿易と、将軍の代替わりなどに派遣された【朝鮮通信使】による交流が続きました。", "18世紀には英祖・正祖のもとで政治が安定し、清の進んだ学問を学ぼうとする実学(北学)も起こりました。しかし19世紀に入ると、王の外戚が権力を握る勢道政治のもとで政治は腐敗し、農民の反乱が相次ぎました。またカトリック(西学)が広がると、儒教の祖先祭祀と対立するとして厳しく弾圧されました。これに対抗して、崔済愚は儒教・仏教・道教をまじえた【東学】を開きました。"]}, {"t": "開国と日本による植民地化", "p": ["19世紀後半、国王高宗の父【大院君】は鎖国と攘夷を進め、フランスやアメリカの艦隊を退けました。しかし1875年の江華島事件をきっかけに、日本は1876年に【日朝修好条規(江華島条約)】を朝鮮に結ばせ、開国させました。この条約は朝鮮を自主の国とうたい、清との宗属関係を否定しようとするもので、日本の領事裁判権を認める不平等条約でした。", "開国後の朝鮮では、清との関係を重んじる勢力と、日本にならって近代化を進めようとする金玉均らの開化派が対立しました。開化派は1884年に甲申政変を起こしましたが、清軍の介入で失敗します。1894年、東学の信徒を中心とする農民が【甲午農民戦争(東学の乱)】を起こすと、清と日本が出兵し、これが【日清戦争】につながりました。敗れた清は1895年の下関条約で朝鮮の独立を認め、朝鮮に対する宗主権を失いました。", "その後、朝鮮は1897年に国号を【大韓帝国】と改めましたが、朝鮮をめぐる日本とロシアの対立は【日露戦争】に発展しました。勝利した日本は1905年の第2次日韓協約で韓国の外交権を奪って保護国とし、統監府を置いて伊藤博文が初代統監となりました。韓国皇帝はハーグ密使事件で国際社会に訴えようとしましたが失敗し、各地で義兵闘争が起こりました。1909年に伊藤博文が【安重根】に暗殺されると、日本は1910年に【韓国併合】を行い、朝鮮総督府を置いて植民地支配を始めました。", "日本は土地調査事業を行って多くの土地を接収し、言論や集会を厳しく制限しました。第一次世界大戦後、ウィルソンの民族自決の考えにはげまされ、1919年3月1日、ソウルで独立宣言が読み上げられ、【三・一独立運動】が全国に広がりました。日本は武力で鎮圧しましたが、その後は「文化政治」に転換し、上海では大韓民国臨時政府がつくられました。1930年代後半、日中戦争が始まると、日本は創氏改名や日本語の強制などの皇民化政策を進め、戦時中には多くの朝鮮人が労働力や兵力として動員されました。"]}, {"t": "解放と南北分断・朝鮮戦争", "p": ["1945年8月、日本の敗戦によって朝鮮は植民地支配から解放されました。しかし北緯38度線を境に、北はソ連、南はアメリカが占領し、冷戦の対立の中で統一政府づくりは進みませんでした。1948年、南に【李承晩】を大統領とする【大韓民国】、北に【金日成】を首相とする【朝鮮民主主義人民共和国】が成立し、分断が固定されました。", "1950年、北朝鮮軍が南に侵攻して【朝鮮戦争】が始まりました。国連の安全保障理事会はソ連が欠席する中で北朝鮮を侵略者とし、アメリカ軍を中心とする国連軍が派遣されました。国連軍が中国国境近くまで進むと、中国が人民義勇軍を送りこみ、戦線は38度線付近で膠着しました。1953年に休戦協定が結ばれましたが、平和条約は結ばれず、現在も法的には休戦状態が続いています。戦争は半島に大きな被害を与える一方、日本には特需による経済回復をもたらし、アメリカは日本の再軍備と西側陣営への組み入れを急ぎました。"]}, {"t": "現代の韓国と北朝鮮", "p": ["韓国では、李承晩政権が1960年の学生運動で倒れたのち、1961年に軍人の【朴正熙】がクーデタで実権を握りました。朴正熙は1965年に【日韓基本条約】を結んで日本と国交を正常化し、日本からの経済協力やベトナム戦争への派兵で得た資金を使って工業化を進め、「漢江の奇跡」とよばれる高度成長を実現しました。これは政治的自由を制限しながら経済開発を進める【開発独裁】の典型とされます。朴正熙が1979年に暗殺されたあとも軍人政権が続き、1980年の光州事件では民主化運動が武力で弾圧されました。しかし1987年の大規模な民主化運動の結果、大統領の直接選挙制が実現し、民主化が進みました。", "1990年代以降、冷戦の終結とともに韓国はソ連・中国と国交を結び、1991年には南北朝鮮が国連に同時加盟しました。2000年には金大中大統領と金正日総書記による初の南北首脳会談が行われました。韓国は1996年にOECDに加盟し、先進国の一員となっています。", "一方、北朝鮮は金日成のもとで主体(チュチェ)思想を掲げる独自の社会主義体制を築き、その後は金正日・金正恩と世襲による権力継承が続いています。冷戦終結後、ソ連という後ろ盾を失った北朝鮮は経済難に陥り、核兵器やミサイルの開発を進めて国際社会と対立してきました。日本人拉致問題も未解決の課題です。朝鮮半島の分断は、冷戦が終わったあとも続くその遺産として、東アジアの国際関係に大きな影響を与え続けています。"]}], "points": ["漢の武帝の楽浪郡設置(前108年)→高句麗が4世紀に滅ぼす", "高句麗・百済・新羅の三国時代、白村江の戦い(663年)と新羅の統一(676年)、骨品制", "高麗(918年建国・王建):科挙、高麗青磁、高麗版大蔵経、モンゴル服属と元寇への動員", "朝鮮(李氏朝鮮)(1392年・李成桂):朱子学と両班、世宗の訓民正音(ハングル)", "壬辰・丁酉倭乱と李舜臣、朝鮮通信使", "日朝修好条規(1876年)→甲午農民戦争→日清戦争→韓国併合(1910年)→三・一独立運動(1919年)", "南北分断(1948年)と朝鮮戦争(1950〜53年)", "朴正熙の開発独裁と日韓基本条約(1965年)、1987年の民主化"], "check": [["前108年に漢の武帝が朝鮮半島に置いた郡の代表は?", "楽浪郡"], ["663年に唐・新羅連合軍が倭・百済の軍を破った戦いは?", "白村江の戦い"], ["新羅の血統にもとづく身分制度は?", "骨品制"], ["918年に高麗を建てた人物は?", "王建"], ["1392年に朝鮮(李氏朝鮮)を建国した人物は?", "李成桂"], ["朝鮮の世宗が1446年に公布した表音文字は?", "訓民正音(ハングル)"], ["豊臣秀吉の朝鮮出兵の際、水軍を率いて日本軍を破った武将は?", "李舜臣"], ["1919年に朝鮮で起こった日本からの独立を求める運動は?", "三・一独立運動"], ["1965年に日本と韓国が国交を正常化した条約は?", "日韓基本条約"]], "related": ["t_cn", "t_mn", "t_ru", "t_us", "y_bc2", "y_7", "y_10", "y_14", "y_15", "y_16", "y_19", "y_20a", "y_20b"], "n": 4144, "videos": [{"title": "【世界史】 中国周辺史３ 朝鮮半島の分裂 （１９分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=BRhpBVlQdvE", "note": "中国周辺史の一つとして朝鮮半島の歴史を整理できます。"}]}, "t_mn": {"title": "モンゴル・内陸アジア史", "span": "前7世紀ごろ〜現在", "year": 1206, "lead": "モンゴル高原・中央アジアの草原とオアシスでは、騎馬遊牧民の国家とオアシスの都市が結びつき、東西交易を担いました。匈奴・鮮卑・突厥・ウイグルと遊牧国家が交代し、10世紀以降はトルコ人のイスラーム化が進みました。13世紀のモンゴル帝国はユーラシアの大部分を統合し、その後もティムール朝やオイラト・ジュンガルが活躍しましたが、近世にはロシアと清に分割されました。", "flow": ["前7世紀ごろ 南ロシアの草原にスキタイ→騎馬遊牧文化が東へ広がる", "前3世紀末 冒頓単于のもとで匈奴が強大化→前200年白登山の戦いで漢を破る", "4〜6世紀 鮮卑が華北に北魏を建てる、モンゴル高原に柔然、中央アジアにエフタル", "552年 突厥が柔然から自立→6世紀後半に東西に分裂", "744年 ウイグルが突厥にかわる→安史の乱で唐を援助、840年キルギスに敗れ西へ移動", "10世紀 カラハン朝がイスラーム化→トルキスタンのトルコ化・イスラーム化", "1206年 チンギス=ハンがクリルタイで即位→モンゴル帝国", "13世紀後半 4ハン国と元に分かれる→ジャムチで東西交流", "1370年 ティムールがサマルカンドを都に帝国→1402年アンカラの戦い", "15〜16世紀 オイラトのエセン(土木の変)、タタールのアルタン=ハン", "17〜18世紀 ジュンガルが清に滅ぼされ新疆に、ロシアと清が内陸アジアを分割", "1924年 モンゴル人民共和国成立→1992年モンゴル国"], "sync": [], "secs": [{"t": "草原とオアシス:内陸アジアの舞台", "p": ["ユーラシア大陸の内陸部には、東はモンゴル高原から西は黒海北岸まで、広大な草原(ステップ)が帯のように続いています。降水量が少なく農耕に向かないこの地域では、羊や馬などの家畜を連れて季節ごとに移動する【遊牧】が生活の基本でした。遊牧民は馬に乗って弓を射る優れた騎馬戦士であり、強い指導者が現れると部族を束ねて大きな国家をつくりました。", "草原の南側には砂漠が広がり、そのなかに点在する水場には【オアシス】都市が栄えました。オアシスの住民は農業を営むとともに、隊商による交易を行いました。中国と西アジア・地中海を結ぶ【オアシスの道(絹の道)】と、草原を通る【草原の道】は、内陸アジアを東西に貫く大動脈です。とくにサマルカンドなどを拠点とした【ソグド人】は、絹の道の交易を担う商業民として活躍しました。", "遊牧国家とオアシス都市は、互いに支え合う関係にありました。遊牧国家は交易路を保護してオアシスから税を取り、オアシスの商人は遊牧国家の軍事力のもとで安全に商売をしました。そして遊牧国家は、中国などの農耕国家から絹や穀物を得るため、交易を求めたり、略奪や攻撃を行ったりしました。内陸アジアの歴史は、この遊牧・オアシス・農耕の三つの世界の関係として理解するとわかりやすくなります。"]}, {"t": "スキタイと匈奴:最初の遊牧国家", "p": ["最初の騎馬遊牧民として知られるのが、前7世紀ごろから南ロシアの草原で活躍した【スキタイ】です。スキタイは独特の動物文様をもつ金属器(スキタイ文化)を残し、その騎馬の技術や文化は草原を通じて東へ伝わりました。", "前3世紀、モンゴル高原では【匈奴】が勢力を強めました。中国の秦の始皇帝は匈奴に対抗して長城を修築しています。前3世紀末に即位した【冒頓単于】は高原の諸部族を統一し、西の月氏を追い払い、前200年の【白登山の戦い】では漢の高祖劉邦を包囲して破りました。その後、漢は匈奴に絹や食料を贈り、皇族の娘を嫁がせる和親策をとらざるを得ませんでした。", "しかし前2世紀後半、漢の【武帝】は方針を転換し、匈奴を挟み撃ちにするため【張騫】を西方の【大月氏】に派遣し、大軍を送って匈奴を攻撃しました。匈奴は打撃を受けてやがて東西に分裂し、1世紀には南北に分かれて【南匈奴】は後漢に服属しました。張騫の派遣は同盟には失敗しましたが、西域の情報をもたらし、オアシスの道の交易が盛んになるきっかけとなりました。"]}, {"t": "鮮卑・柔然・突厥・ウイグル", "p": ["匈奴が衰えたあと、モンゴル高原では【鮮卑】が台頭しました。4世紀に中国が分裂すると、鮮卑など五胡とよばれる諸民族が華北に進出し、鮮卑の拓跋氏は【北魏】を建てて華北を統一しました。遊牧民が農耕地帯に国家を建て、漢人と融合していったこの流れは、隋・唐の成立にもつながります。高原では鮮卑のあとに【柔然】が勢力をもち、中央アジアでは【エフタル】がササン朝やグプタ朝を圧迫しました。", "6世紀半ば、柔然に服属していたトルコ系の【突厥】が自立し、柔然を滅ぼしてモンゴル高原から中央アジアにまたがる大国家をつくりました。突厥はササン朝と結んでエフタルを滅ぼし、絹の道の交易を押さえて繁栄しました。突厥は遊牧民として初めて自らの文字(【突厥文字】)を用いたことでも知られます。しかし内紛から6世紀後半に【東突厥と西突厥に分裂】し、東突厥は7世紀に唐の太宗に服属しました。", "8世紀半ば、突厥にかわってモンゴル高原を支配したのが、同じトルコ系の【ウイグル】です。ウイグルは唐で【安史の乱】が起こると援軍を送り、その見返りとして唐から大量の絹を得る絹馬交易を行いました。ウイグルにはソグド商人が深く関わり、マニ教が信仰され、ソグド文字をもとに【ウイグル文字】がつくられました。この文字はのちにモンゴル文字、さらに満洲文字のもとになります。840年、ウイグルはトルコ系の【キルギス】に敗れて高原を離れ、一部は天山山脈方面のオアシスに移住しました。"]}, {"t": "トルキスタンの成立とイスラーム化", "p": ["ウイグルの移動をきっかけに、中央アジアのオアシス地帯にはトルコ系の人々が住みつき、もとはイラン系住民が多かったこの地域の言語がしだいにトルコ化していきました。こうして、この地域は「トルコ人の土地」を意味する【トルキスタン】とよばれるようになります。", "一方、西からはイスラーム勢力が中央アジアに進出していました。751年の【タラス河畔の戦い】でアッバース朝が唐を破り、以後、西トルキスタンではイスラーム化が進みます。イラン系のサーマーン朝はトルコ人を奴隷軍人(マムルーク)として用い、そのトルコ人がイスラームに改宗していきました。10世紀には、トルコ系として最初にイスラームを受け入れた王朝とされる【カラハン朝】が成立し、サーマーン朝を滅ぼしました。", "やがてトルコ系の人々は西アジアに進出し、セルジューク朝を建ててアッバース朝のカリフからスルタンの称号を得るなど、イスラーム世界の主役の一人となっていきます。東方では、契丹(遼)の一族が12世紀に中央アジアに逃れて【西遼(カラキタイ)】を建てました。内陸アジアは、中国とイスラーム世界の勢力がぶつかり合い、混じり合う場所だったのです。"]}, {"t": "モンゴル帝国:ユーラシアの統合", "p": ["12世紀末、モンゴル高原の諸部族を統一したテムジンは、1206年に有力者の会議【クリルタイ】で推されて【チンギス=ハン】となりました。チンギス=ハンは遊牧民を千人隊に編成して強力な軍を組織し、西夏を攻め、中央アジアの【ホラズム=シャー朝】を倒しました。", "後を継いだ【オゴタイ(オゴデイ)】は1234年に金を滅ぼし、都【カラコルム】を建設しました。バトゥの遠征軍は南ロシアから東ヨーロッパに進み、1241年の【ワールシュタットの戦い】でドイツ・ポーランドの諸侯軍を破りました。その後、フラグはアッバース朝を滅ぼしてイランに【イル=ハン国】を建て、南ロシアには【キプチャク=ハン国】、中央アジアには【チャガタイ=ハン国】が成立します。【フビライ=ハン】は大都を都に【元】を建てて南宋を滅ぼし、モンゴル帝国は元を宗主とするゆるやかな連合となりました。", "モンゴル帝国の意義は、ユーラシアの東西を一つの政治秩序のもとに置き、交通と交易を活発にしたことです。駅伝制の【ジャムチ(站赤)】が整備され、陸と海の交易路が結ばれました。【プラノ=カルピニ】や【ルブルック】がローマ教皇やフランス王の使節としてカラコルムを訪れ、【マルコ=ポーロ】は元に仕えたとされます。モンゴルは支配地の宗教に寛容で、元では【チベット仏教】が保護され、フビライの師パクパがつくった【パスパ文字】が公用文字とされました。行政面では、征服地に【ダルガチ】とよばれる監督官を置いて統治しました。", "しかし14世紀になると、天災・疫病(黒死病)の流行や内紛によって各ハン国は動揺し、元は【紅巾の乱】の中で1368年に明に追われてモンゴル高原へ退きました(北元)。イル=ハン国も分裂し、ユーラシアの統合の時代は終わりを迎えます。"]}, {"t": "ティムール朝と北方の遊牧勢力", "p": ["14世紀後半、チャガタイ=ハン国の分裂の中から【ティムール】が台頭し、1370年に【サマルカンド】を都とする帝国を建てました。ティムールはモンゴル帝国の再興をめざし、イラン・イラクに遠征し、1402年の【アンカラの戦い】でオスマン帝国を破ってスルタンを捕らえました。その後、明への遠征の途中で亡くなります。ティムール朝ではイラン=イスラーム文化とトルコ文化が融合し、サマルカンドは壮麗な建築で飾られ、君主【ウルグ=ベク】は天文台をつくりました。文学では【チャガタイ=トルコ語】が発達しました。16世紀初め、ティムール朝はトルコ系の【ウズベク】に滅ぼされ、その王族のバーブルはインドに移ってムガル帝国を建てました。", "モンゴル高原では、元の北走後、西の【オイラト】と東のタタール(韃靼)が対立しました。15世紀半ば、オイラトの【エセン】は明に侵入し、1449年の【土木の変】で明の正統帝を捕らえました。16世紀には、タタールの【アルタン=ハン】が明を圧迫し、北京を包囲したこともあります。アルタン=ハンは【チベット仏教】に帰依してダライ=ラマの称号を贈り、以後モンゴルではチベット仏教が深く信仰されるようになりました。チベット仏教では15世紀に【ツォンカパ】が改革を行い、黄帽派(ゲルク派)が勢力をもっていました。"]}, {"t": "清・ロシアによる分割と近現代", "p": ["17世紀、東モンゴルの【チャハル】が清のホンタイジに服属し、内モンゴルは清の支配下に入りました。西方ではオイラトの一派【ジュンガル】が強大となり、外モンゴルやチベット、東トルキスタンに勢力を伸ばして清と激しく争いました。清は康熙帝・雍正帝・乾隆帝の3代にわたる戦いの末、18世紀半ばにジュンガルを滅ぼし、東トルキスタンを【新疆】(新しい領土)として支配しました。モンゴル・チベット・新疆は藩部として【理藩院】が管轄し、清は現地の有力者による支配をある程度認めました。", "同じころ、西からはロシアがシベリアに進出し、清とのあいだで【ネルチンスク条約】(1689年)と【キャフタ条約】(1727年)を結んで国境を定めました。19世紀後半には、ロシアは西トルキスタンのウズベク人の3ハン国(ブハラ・ヒヴァ・コーカンド)を征服・保護国化し、清とはイリ地方をめぐって争いました。こうして、かつて遊牧国家が東西に覇を競った内陸アジアは、ロシアと清という二つの帝国に分割されたのです。また、イギリスとロシアは中央アジアやアフガニスタンをめぐって対立しました(グレート=ゲーム)。", "20世紀に入り、1911年の辛亥革命を機に外モンゴルは独立を宣言し、ソ連の支援を受けて1924年に【モンゴル人民共和国】が成立しました。これはソ連に次ぐ世界で2番目の社会主義国とされます。内モンゴルは中国にとどまり、現在は内モンゴル自治区となっています。冷戦終結後、モンゴルは社会主義を放棄して1992年に国名をモンゴル国と改めました。西トルキスタンはソ連の構成共和国となり、1991年のソ連解体でウズベキスタンやカザフスタンなどとして独立しました。中国の新疆ウイグル自治区やチベット自治区では、民族や宗教をめぐる問題が現在も続いています。"]}], "points": ["遊牧・オアシス・農耕の三つの世界の関係、オアシスの道(絹の道)と草原の道、ソグド人", "匈奴の冒頓単于と白登山の戦い(前200年)、漢の武帝と張騫の大月氏派遣", "突厥(突厥文字、東西分裂)→ウイグル(安史の乱で唐を援助、ウイグル文字)→840年キルギスに敗れる", "トルキスタンの成立とカラハン朝のイスラーム化、タラス河畔の戦い", "チンギス=ハン(1206年即位)、オゴタイ、ワールシュタットの戦い、4ハン国と元、ジャムチ", "ティムール(サマルカンド、1402年アンカラの戦い)、ウルグ=ベク", "オイラトのエセン(土木の変)、アルタン=ハンとチベット仏教、ジュンガルの滅亡と新疆", "ネルチンスク条約・キャフタ条約、1924年モンゴル人民共和国"], "check": [["前200年、白登山の戦いで漢の高祖を破った匈奴の君主は?", "冒頓単于"], ["匈奴挟撃のため漢の武帝が大月氏に派遣した人物は?", "張騫"], ["遊牧民として初めて独自の文字をもったとされるトルコ系の国家は?", "突厥"], ["安史の乱で唐を援助したトルコ系遊牧国家は?", "ウイグル"], ["トルコ系最初のイスラーム王朝とされる王朝は?", "カラハン朝"], ["モンゴルで君主の選出などを行った有力者の会議は?", "クリルタイ"], ["1241年にモンゴル軍がドイツ・ポーランド連合軍を破った戦いは?", "ワールシュタットの戦い"], ["1402年にオスマン帝国を破ったティムールの戦いは?", "アンカラの戦い"], ["清が18世紀半ばに滅ぼしたオイラト系の遊牧国家は?", "ジュンガル"]], "related": ["t_cn", "t_ru", "t_ir", "t_tr", "t_in", "t_kr", "y_bc2", "y_6", "y_8", "y_10", "y_13", "y_14", "y_15", "y_18"], "n": 4114, "videos": [{"title": "【世界史】 中国周辺史１ モンゴル・内陸アジア （１９分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=g30r8OQ-qdU", "note": "遊牧国家の興亡を通史でまとめられ、国別ページの復習に向いています。"}]}, "t_us": {"title": "アメリカ合衆国史", "span": "1607年〜現在", "year": 1776, "lead": "イギリスの13植民地は本国の課税に反発して1776年に独立を宣言し、憲法にもとづく共和国をつくりました。19世紀には西へ領土を広げ、奴隷制をめぐる南北戦争を経て工業国に成長し、世紀末には海外へ進出します。二度の世界大戦で国際的地位を高め、戦後はソ連と冷戦を戦う超大国となり、国内では公民権運動などを通じて自由と平等の意味が問い直されてきました。", "flow": ["1607年 ヴァージニアにジェームズタウン建設→1620年ピルグリム=ファーザーズ", "1763年 フレンチ=インディアン戦争の終結→本国が課税強化(1765年印紙法)", "1773年 ボストン茶会事件→1775年レキシントン・コンコードの戦いで独立戦争", "1776年 独立宣言→1783年パリ条約で独立承認", "1787年 合衆国憲法制定→1789年ワシントンが初代大統領", "1803年 ルイジアナ購入→1823年モンロー教書、1848年カリフォルニア獲得", "1861年 南北戦争→1863年奴隷解放宣言、1865年北部の勝利", "1869年 大陸横断鉄道→1890年フロンティア消滅、1898年米西戦争", "1917年 第一次世界大戦に参戦→1920年代の繁栄、1929年世界恐慌", "1933年 ニューディール→1941年第二次世界大戦に参戦", "1947年 トルーマン=ドクトリン→冷戦、1962年キューバ危機、ベトナム戦争", "1964年 公民権法→1991年冷戦終結後の唯一の超大国、2001年同時多発テロ事件"], "sync": [], "secs": [{"t": "植民地の形成と独立革命", "p": ["17世紀初め、イギリスは北アメリカ東岸に植民を始めました。1607年に建設されたヴァージニアのジェームズタウンが最初の恒久的植民地で、1620年には信仰の自由を求めるピューリタンの一団(【ピルグリム=ファーザーズ】)がメイフラワー号で到着し、ニューイングランドの植民地の基礎をつくりました。18世紀前半までに東岸には【13植民地】が成立します。北部では自営農民や商工業が、南部では黒人奴隷を使ってタバコなどを栽培する【プランテーション】が発達しました。各植民地には植民地議会があり、自治の伝統が育っていました。", "転機は【フレンチ=インディアン戦争】でした。この戦争でイギリスはフランスに勝ち、1763年のパリ条約で北アメリカのフランス領を得ましたが、戦費で財政が苦しくなりました。そこでイギリスは植民地への課税を強め、1765年に【印紙法】を定めます。植民地側は、本国議会に代表を送っていないのに課税されるのはおかしいとして「【代表なくして課税なし】」と反対し、印紙法は撤回されました。その後、茶の販売独占をめぐる1773年の【ボストン茶会事件】をきっかけに対立が深まり、1775年の【レキシントン・コンコードの戦い】で独立戦争が始まりました。", "植民地側は【ワシントン】を総司令官に選び、1776年、【トマス=ジェファソン】らが起草した【アメリカ独立宣言】を発表しました。宣言は、人は生まれながらに平等で、生命・自由・幸福追求の権利をもち、政府がこれを侵すなら人民は政府を変える権利があるとし、ロックの思想の影響を強く受けています。独立を訴えたペインの『【コモン=センス】』も世論を動かしました。1777年の【サラトガの戦い】の勝利をきっかけにフランスが参戦し、【ラ=ファイエット】ら義勇兵も加わりました。1781年の【ヨークタウンの戦い】で勝敗は決し、1783年の【パリ条約(1783年)】でイギリスは独立を認め、ミシシッピ川以東の領土を譲りました。"]}, {"t": "合衆国憲法と領土の拡大", "p": ["独立当初の合衆国は、各州の力が強く中央政府が弱い連合体でした。これを改めるため、1787年に【アメリカ合衆国憲法】が制定されました。憲法は、中央政府に強い権限を与える一方で州の自治も認める連邦主義、行政・立法・司法の三権分立、人民主権を柱とする世界初の近代的な成文憲法の一つです。議会は各州2名の【上院】と人口比例の下院からなります。1789年にワシントンが初代大統領に就任しました。アメリカ独立革命は、フランス革命やラテンアメリカの独立にも大きな影響を与えました。", "19世紀前半、合衆国は西へと領土を広げました。1803年、ジェファソン大統領はフランスのナポレオンから【ルイジアナ】を買収し、国土を倍増させました。イギリスとの【アメリカ=イギリス(米英)戦争】(1812〜14年)は、国内の工業が自立するきっかけとなります。1823年、大統領モンローは【モンロー教書(宣言)】を発表し、ヨーロッパとアメリカ大陸の相互不干渉を唱え、ラテンアメリカの独立にヨーロッパが介入することに反対しました。", "1829年に大統領となった【ジャクソン】は西部の農民などに支持され、白人男性の普通選挙の広がりなど民主主義を進めました(ジャクソニアン=デモクラシー)。しかしその一方で、1830年の【先住民強制移住法】によって先住民をミシシッピ川以西へ追いやり、多くの犠牲を出しました。1840年代には、領土拡大は神に与えられた使命だとする「【明白な天命(マニフェスト=デスティニー)】」の考えが唱えられ、テキサスの併合、オレゴンの獲得、アメリカ=メキシコ戦争による【カリフォルニア】などの獲得(1848年)が続きました。同じ年、カリフォルニアで金鉱が見つかると【ゴールドラッシュ】が起こり、西部への人口移動が一気に進みました。"]}, {"t": "南北戦争と再建", "p": ["領土が広がるにつれて、新しい州で奴隷制を認めるかどうかが国を二分する問題になりました。北部は工業化が進み、保護関税と奴隷制の拡大反対を主張しました。南部は綿花のプランテーションで黒人奴隷に依存し、綿花をイギリスへ輸出していたため、自由貿易と奴隷制の維持を望みました。ストウの『【アンクル=トムの小屋】』は奴隷制の非人道性を訴え、北部の世論に大きな影響を与えました。1854年の【カンザス・ネブラスカ法】は、新しい州の奴隷制の可否を住民が決めるとしたため対立が激化し、奴隷制拡大に反対する【共和党】が結成されました。", "1860年、共和党の【リンカン】が大統領に当選すると、南部諸州は合衆国を離脱して【アメリカ連合国】をつくり、1861年に【南北戦争】が始まりました。リンカンは1862年に【ホームステッド法】で西部の農民の支持を集め、1863年に奴隷解放宣言を出して内外の世論を味方につけました。同年の【ゲティスバーグの戦い】で北軍が勝利し、リンカンはその地で「【人民の、人民による、人民のための政治】」という演説を行いました。1865年に北部の勝利で戦争は終わり、奴隷制は憲法修正によって廃止されました。", "しかし、戦後の再建は不十分なものでした。解放された黒人の多くは土地を得られず、地主から土地を借りて収穫の一部を納める【シェアクロッパー】(分益小作人)となり、貧困から抜け出せませんでした。南部では州法によって黒人の投票権が奪われ、公共施設での人種隔離が進められました。この差別は20世紀の公民権運動まで続くことになります。"]}, {"t": "工業大国と海外進出", "p": ["南北戦争後、合衆国は急速に工業化しました。1869年に【大陸横断鉄道】が完成し、国内市場が一つに結ばれました。【エディソン】の電灯や【ベル】の電話など新しい技術が生まれ、石油・鉄鋼などの分野では巨大企業が成長しました。工業の担い手として、南欧や東欧、アジアから多くの移民がやってきます。1890年には国勢調査で【フロンティア】の消滅が発表され、国内の開拓が一段落したことを示しました。", "国内の拡大が終わると、合衆国の関心は海外に向かいました。1867年にロシアから【アラスカ】を買収していた合衆国は、1898年に【ハワイ】を併合し、同年の【アメリカ=スペイン(米西)戦争】に勝って【フィリピン・グアム・プエルトリコ】を獲得し、キューバを保護国としました。中国については、1899年に国務長官ジョン=ヘイが【門戸開放宣言】を出し、列強の中国分割に遅れて参加した立場から、門戸開放・機会均等を求めました。ラテンアメリカに対しては【パン=アメリカ会議】を開いて影響力を強め、セオドア=ローズヴェルトは武力を背景とする「棍棒外交」でパナマ運河の建設を進めました。"]}, {"t": "二つの世界大戦と世界恐慌", "p": ["第一次世界大戦に対し、合衆国は当初中立を守りましたが、ドイツの無制限潜水艦作戦をきっかけに1917年に参戦しました。大統領【ウィルソン】は十四か条の平和原則を発表し、国際連盟の設立を提唱しましたが、上院の反対で合衆国自身は連盟に加盟しませんでした。それでも合衆国は大戦を通じて債務国から債権国に転じ、ヨーロッパに代わる世界経済の中心となります。ドイツの賠償問題では【ドーズ案】・【ヤング案】を通じて資金を貸し付け、ヨーロッパの復興を支えました。", "1920年代の合衆国は「永遠の繁栄」とよばれる好景気に沸き、自動車や家電が普及し、【ラジオ放送】・【ハリウッド】映画・【ジャズ】などの大衆文化が広がりました。一方で【禁酒法】が施行され、【移民法(1924年移民法)】で東欧・南欧からの移民が制限され、アジアからの移民は事実上禁止されました。イタリア系移民が冤罪で処刑されたとされる【サッコ・ヴァンゼッティ事件】も、移民への偏見を示しています。", "1929年、ニューヨークの株価暴落から【世界恐慌】が始まりました。生産過剰と農業不況が背景にあり、恐慌は世界中に広がりました。1933年に大統領となったフランクリン=ローズヴェルトは【ニューディール】を実施し、【農業調整法(AAA)】で農産物の生産を調整し、【全国産業復興法(NIRA)】で産業を統制し、【テネシー川流域開発公社(TVA)】による公共事業で雇用を生み出しました。【ワグナー法】では労働者の団結権・団体交渉権を認めています。これは政府が経済に積極的に介入する大きな転換でした。外交ではラテンアメリカへの干渉を控える【善隣外交】をとりました。", "第二次世界大戦が始まると、合衆国は【武器貸与法】でイギリスなどを支援し、1941年に日本の真珠湾攻撃を受けて参戦しました。原子爆弾を開発する【マンハッタン計画】を進め、1945年に広島・長崎に原爆を投下しました。"]}, {"t": "冷戦期の超大国", "p": ["戦後、合衆国はソ連と対立する【冷戦】の中心となりました。1947年、大統領【トルーマン】は共産主義の拡大を封じこめる【トルーマン=ドクトリン】を発表し、ヨーロッパの経済復興を援助する【マーシャル=プラン】を打ち出しました。1949年にはNATOを結成します。国内ではマッカーシー上院議員を中心に共産主義者を排除する【赤狩り(マッカーシズム)】が吹き荒れました。", "【アイゼンハワー】政権のあと、1961年に大統領となった【ケネディ】は、【キューバ革命】で社会主義化したキューバにソ連がミサイル基地を建設したことに対し、1962年に海上封鎖を行いました。この【キューバ危機】は核戦争寸前までいきましたが、ソ連がミサイルを撤去して回避され、その後米ソは対話を進めるようになります。", "国内では、黒人差別の撤廃を求める公民権運動が高まりました。【キング牧師】は非暴力による運動を指導し、1963年のワシントン大行進で「私には夢がある」と演説しました。ケネディ暗殺後の【ジョンソン】政権のもとで1964年に【公民権法】が成立し、法律上の人種差別は撤廃されました。しかしジョンソンは【トンキン湾事件】を口実にベトナムへの本格介入(北爆)を始め、戦争の泥沼化は国内に大規模な反戦運動を生みました。", "【ニクソン】大統領は1972年に中国を訪問して【中華人民共和国】との関係改善を進め、1973年にベトナムから撤兵しました。また1971年にドルと金の交換を停止し(ドル=ショック)、戦後の国際通貨体制は転換します。しかしニクソンは【ウォーターゲート事件】で1974年に辞任に追いこまれました。1980年代の【レーガン】政権は「強いアメリカ」を掲げてソ連に対抗しつつ、減税と規制緩和を進めましたが、財政と貿易の「双子の赤字」が膨らみました。"]}, {"t": "冷戦後のアメリカ", "p": ["1989年のマルタ会談で冷戦の終結が宣言され、1991年にソ連が解体すると、合衆国は唯一の超大国となりました。同年の湾岸戦争では多国籍軍を率いてイラクをクウェートから撤退させました。1990年代には【インターネット】などの情報技術産業が成長し、経済のグローバル化を主導しました。", "2001年の【同時多発テロ事件】は、合衆国の安全保障観を大きく変えました。合衆国はテロとの戦いを掲げてアフガニスタンを攻撃し、2003年には大量破壊兵器の保有を理由にイラク戦争を起こしましたが、兵器は見つからず、国際的な批判を受けました。2008年には、住宅ローン問題をきっかけとする金融危機(リーマン=ショック)が世界経済を揺るがしました。同年、初の黒人大統領としてオバマが当選しています。現在の合衆国は、中国の台頭への対応や、移民・格差をめぐる国内の分断といった課題を抱えています。建国以来の「自由と平等」の理念を、誰にどこまで認めるのかという問いは、合衆国の歴史全体を貫くテーマだといえるでしょう。"]}], "points": ["印紙法(1765年)と「代表なくして課税なし」→ボストン茶会事件→独立戦争", "独立宣言(1776年・ジェファソン、ロックの影響)、サラトガの戦いとフランス参戦、パリ条約(1783年)", "合衆国憲法(1787年):連邦主義・三権分立・人民主権", "ルイジアナ買収、モンロー教書(1823年)、先住民強制移住法、明白な天命とカリフォルニア獲得", "南北戦争の背景(北部の保護貿易・奴隷制反対と南部の自由貿易・奴隷制)、ホームステッド法、奴隷解放宣言", "フロンティアの消滅(1890年)→米西戦争(1898年)・門戸開放宣言", "世界恐慌とニューディール(AAA・NIRA・TVA・ワグナー法)", "トルーマン=ドクトリン・マーシャル=プラン、キューバ危機、公民権法(1964年)、ベトナム戦争"], "check": [["1765年にイギリスが植民地に課し、強い反発を受けた法律は?", "印紙法"], ["アメリカ独立宣言を起草した中心人物は?", "トマス=ジェファソン"], ["独立戦争中、フランス参戦のきっかけとなった1777年の戦いは?", "サラトガの戦い"], ["1823年にヨーロッパとアメリカ大陸の相互不干渉を唱えた宣言は?", "モンロー教書(宣言)"], ["1854年に成立し、共和党結成のきっかけとなった法律は?", "カンザス・ネブラスカ法"], ["1862年に公有地を西部の農民に無償で与えた法律は?", "ホームステッド法"], ["1899年に中国の門戸開放・機会均等を唱えた宣言は?", "門戸開放宣言"], ["フランクリン=ローズヴェルトが世界恐慌対策として行った政策は?", "ニューディール"], ["1947年に共産主義の封じこめを表明した宣言は?", "トルーマン=ドクトリン"], ["1964年に成立し、法律上の人種差別を撤廃した法律は?", "公民権法"]], "related": ["t_uk", "t_fr", "t_la", "t_oc", "t_ph", "t_ru", "t_vn", "y_17", "y_18", "y_19", "y_20a", "y_20b", "y_21"], "n": 4712, "videos": [{"title": "【世界史】 アメリカ独立革命２ アメリカ独立戦争 （１６分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=XLACsd-LBXE", "note": "アメリカ独立戦争を扱い、アメリカ合衆国史の出発点を押さえられます。"}]}, "t_la": {"title": "ラテンアメリカ史", "span": "前1200年ごろ〜現在", "year": 1810, "lead": "中南米ではトウモロコシやジャガイモの農耕にもとづいて、マヤ・アステカ・インカなどの独自の文明が栄えました。16世紀にスペインとポルトガルに征服されると、銀や砂糖を生む植民地社会がつくられ、先住民・黒人奴隷・白人の混じる複雑な社会が生まれます。19世紀前半に多くの国が独立しましたが、経済的な従属と大土地所有が残り、20世紀にはアメリカ合衆国の影響、革命と軍事政権、民主化を経験しました。", "flow": ["前1200年ごろ メキシコ湾岸にオルメカ文明", "4〜9世紀ごろ ユカタン半島などでマヤ文明が最盛期→ピラミッド状神殿、二十進法", "14〜16世紀 メキシコ高原にアステカ王国(都テノチティトラン)、アンデスにインカ帝国(都クスコ)", "1492年 コロンブスがカリブ海に到達→1494年トルデシリャス条約", "1521年 コルテスがアステカ王国を征服、1533年ピサロがインカ帝国を征服", "16世紀 エンコミエンダ制、ポトシ銀山→銀がヨーロッパ・アジアへ", "1804年 ハイチがフランスから独立→最初の黒人共和国", "1810〜20年代 シモン=ボリバル・サン=マルティンの独立運動→多くの国が独立、1822年ブラジル独立", "1861〜67年 ナポレオン3世のメキシコ出兵→失敗", "1910年 メキシコ革命→1917年憲法", "1959年 キューバ革命→1962年キューバ危機", "1970〜80年代 軍事政権と累積債務→1980年代以降民主化"], "sync": [], "secs": [{"t": "アメリカ大陸の古代文明", "p": ["アメリカ大陸の人々の祖先は、氷河時代にユーラシアからベーリング海峡付近を渡ってきたと考えられています。彼らはやがて中米やアンデスで農耕を始め、【トウモロコシ】・ジャガイモ・トマト・カボチャなど、のちに世界中に広がる作物を育てました。アメリカ大陸の文明には、鉄器や車輪の実用化、牛や馬などの大型家畜が見られないという特徴があり、ユーラシアとは別の道筋で発展したことがわかります。", "メキシコ湾岸では前1200年ごろに【オルメカ文明】が生まれ、巨石人頭像を残しました。ユカタン半島からグアテマラにかけては【マヤ文明】が栄え、4〜9世紀ごろに最盛期を迎えました。マヤの人々はピラミッド状の神殿を築き、独自の【マヤ文字】、ゼロの概念を用いた【二十進法】、精密な暦をもっていました。メキシコ高原では大都市テオティワカンが栄えたのち、14世紀に【アステカ人】が湖上の都【テノチティトラン】(現在のメキシコシティ)を建設し、周辺を支配する【アステカ王国】をつくりました。", "南アメリカのアンデス地方では、15世紀に【インカ帝国】が成立し、都【クスコ】を中心に現在のエクアドルからチリに及ぶ広大な領域を支配しました。インカは文字をもたず、縄の結び目で数量を記録する【キープ(結縄)】を用い、帝国内に道路網を整えていました。山上の都市マチュ=ピチュは、その高い石造技術を今に伝えています。"]}, {"t": "スペイン・ポルトガルによる征服", "p": ["1492年、スペイン女王イサベルの支援を受けた【コロンブス】がカリブ海の島に到達しました。彼はそこをアジアの一部と考えていましたが、のちにアメリゴ=ヴェスプッチの探検によって新大陸であることが知られ、その名から「アメリカ」とよばれるようになります。1494年、スペインとポルトガルは【トルデシリャス条約】を結んで、大西洋上の境界線より西をスペイン、東をポルトガルの勢力範囲と定めました。このため、南アメリカの東端にあたるブラジルはポルトガル領となり、それ以外の多くの地域はスペイン領となりました。", "スペインの征服者(コンキスタドール)は、わずかな兵で大帝国を滅ぼしました。1521年、【コルテス】はアステカ王国を征服し、1533年には【ピサロ】がインカ帝国を滅ぼしました。少数の兵で勝てた理由として、鉄製の武器・銃・馬の優位、アステカに支配されていた周辺の先住民の協力、そしてヨーロッパから持ちこまれた【天然痘】などの伝染病の大流行が挙げられます。免疫をもたない先住民は伝染病で激減しました。", "スペインは征服地で【エンコミエンダ制】を実施しました。これは、先住民の保護とキリスト教化を条件に、植民者に先住民の統治と労働力の利用を委ねる制度です。しかし実際には先住民は鉱山や農園で酷使され、人口はさらに減少しました。ドミニコ会修道士【ラス=カサス】は先住民への虐待を告発し、スペイン王に保護を訴えました。先住民の人口減少を補うため、アフリカから多数の黒人奴隷が連れてこられ、大西洋をまたぐ【奴隷貿易】が拡大していきます。"]}, {"t": "植民地社会と世界経済", "p": ["スペイン領アメリカの富の中心は銀でした。1545年に発見されたボリビアの【ポトシ銀山】やメキシコの銀山から大量の銀が産出され、スペインに運ばれました。この大量の銀の流入はヨーロッパで物価の急上昇(【価格革命】)を引き起こし、固定地代で暮らす領主層を没落させるなど、ヨーロッパの社会を変えました。また銀の一部は【ガレオン貿易】でアカプルコからマニラへ運ばれ、中国の絹や陶磁器と交換されました。アメリカ大陸の銀は、ヨーロッパとアジアを結ぶ世界経済の血液となったのです。", "17世紀以降、エンコミエンダ制にかわって、大土地所有者が先住民や混血の人々を債務などでしばって働かせる【アシエンダ制】が広がりました。ブラジルやカリブ海の島々では、黒人奴隷を使ったサトウキビの【プランテーション】が発達し、砂糖がヨーロッパに輸出されました。こうしてラテンアメリカは、ヨーロッパに鉱産物や農産物を供給する役割を担わされ、この経済構造は独立後も長く続くことになります。", "植民地の社会は、人種と出生地による階層で成り立っていました。最上層は本国生まれの白人(ペニンスラール)で、植民地の高官を独占しました。その下に植民地生まれの白人である【クリオーリョ】がおり、彼らは大地主や商人として富を持ちながら、政治的には本国生まれの白人に差別されていました。さらに白人と先住民の混血である【メスティーソ】、白人と黒人の混血であるムラート、先住民、黒人奴隷が続きます。この不満をもつクリオーリョこそが、のちの独立運動の中心となりました。"]}, {"t": "独立の時代", "p": ["ラテンアメリカの独立の背景には、アメリカ独立革命とフランス革命の影響がありました。最初に独立を果たしたのは、カリブ海のフランス領サン=ドマング、現在の【ハイチ】です。ここでは砂糖プランテーションの黒人奴隷が反乱を起こし、【トゥサン=ルヴェルチュール】が指導しました。トゥサンはナポレオンの軍に捕らえられましたが、運動は続き、1804年にハイチは世界初の黒人共和国として独立しました。", "スペイン領では、ナポレオンがスペインを占領して本国が混乱したことが独立の直接のきっかけとなりました。1810年ごろから各地でクリオーリョが自治や独立を求めて立ち上がります。南米北部では【シモン=ボリバル】が指導して、ベネズエラ・コロンビアなどを独立させ、南部では【サン=マルティン】がアルゼンチン・チリ・ペルーの独立を指導しました。メキシコでは神父イダルゴの蜂起をきっかけに独立運動が広がり、1821年に独立を果たしました。", "ポルトガル領の【ブラジル】は、ナポレオンの侵攻を逃れてポルトガル王室がリオデジャネイロに移っていたこともあり、1822年に王子が皇帝となって帝国として独立するという、比較的平和な形をとりました。独立運動に対しては、ウィーン体制下のヨーロッパ諸国が干渉しようとしましたが、イギリスは新しい市場を求めて独立を支持し、アメリカ合衆国は1823年の【モンロー教書(宣言)】でヨーロッパの介入に反対しました。こうして1820年代までにラテンアメリカの大部分が独立しました。", "しかし、独立は社会の大きな変化をもたらしませんでした。権力を握ったのはクリオーリョの大地主層で、先住民や混血の人々の地位は改善されず、大土地所有制も残りました。ボリバルは南米の大きな連合をめざしましたが実現せず、各地では【カウディーリョ】とよばれる軍事的な実力者が政権を争い、政治は不安定になりました。経済面でも、イギリスなどに一次産品を輸出し工業製品を輸入する従属的な構造が続きました。"]}, {"t": "19世紀後半〜20世紀前半:外国の介入と革命", "p": ["メキシコは独立後、アメリカ=メキシコ戦争(1846〜48年)に敗れて【カリフォルニア】などの広大な領土を失いました。その後、先住民出身のフアレス大統領が自由主義改革を進めると、フランスの【ナポレオン3世】は1861年から【メキシコ出兵】を行い、オーストリア皇族のマクシミリアンを皇帝に立てましたが、メキシコ人の抵抗とアメリカの反発で失敗しました。19世紀末からは独裁者ディアスが外国資本を導入して近代化を進めましたが、土地は少数の大地主と外国企業に集中しました。", "これに対し、1910年に【メキシコ革命】が起こりました。マデロがディアス独裁の打倒を呼びかけ、農民指導者サパタらが土地の分配を求めて戦いました。革命は長い内戦となりましたが、1917年には土地改革や地下資源の国有を定めた憲法が制定され、1930年代には石油の国有化も行われました。メキシコ革命は、ラテンアメリカで初めて社会の根本的な改革をめざした革命として重要です。", "一方、19世紀末から合衆国の影響力が強まりました。合衆国は【パン=アメリカ会議】を開き、1898年の米西戦争でキューバを事実上の保護国としました。20世紀初めにはパナマを独立させて運河地帯を手に入れ、カリブ海諸国にたびたび軍事介入しました(棍棒外交)。1930年代、世界恐慌でラテンアメリカの一次産品の輸出が激減すると、フランクリン=ローズヴェルトは干渉を控える【善隣外交】に転じました。この時期、各国では輸入に頼っていた工業製品を国内で生産する工業化が進み、アルゼンチンの【ペロン】のように労働者の支持を集めて民族主義的な政策をとる指導者も現れました。"]}, {"t": "冷戦期と現代のラテンアメリカ", "p": ["第二次世界大戦後、合衆国は1948年に米州機構(OAS)を結成し、ラテンアメリカを反共の陣営にまとめようとしました。しかし貧富の格差や外国資本への反発は強く、1959年にはキューバで【カストロ】らがアメリカ寄りのバティスタ政権を倒す【キューバ革命】を起こしました。キューバは土地改革やアメリカ企業の国有化を進め、合衆国と対立してソ連に接近し、社会主義を宣言しました。1962年にはソ連のミサイル基地建設をめぐって【キューバ危機】が起こり、世界は核戦争の瀬戸際に立たされました。", "キューバ革命の影響を恐れた合衆国は、各地の反共的な軍部を支援しました。チリでは1970年に選挙で社会主義の【アジェンデ】政権が成立しましたが、1973年に軍のクーデタで倒され、ピノチェトの軍事政権が長く続きました。アルゼンチンやブラジルでも軍事政権が成立し、反対派が弾圧されました。軍事政権の多くは外国からの借り入れで開発を進めましたが、1980年代には【累積債務問題】が深刻化し、経済危機に陥りました。", "こうした危機の中で、1980年代には軍事政権が次々と倒れ、民政に移行していきました。アルゼンチンではフォークランド(マルビナス)戦争でイギリスに敗れたことが軍政崩壊のきっかけとなっています。1990年代以降は、経済の自由化と地域統合(メルコスール(南米南部共同市場)など)が進みました。現在のラテンアメリカは、ブラジルやメキシコのような新興の経済大国を生みつつも、植民地時代以来の大土地所有や貧富の格差、先住民の権利といった課題に向き合い続けています。"]}], "points": ["マヤ文明(マヤ文字・二十進法)、アステカ王国(テノチティトラン)、インカ帝国(クスコ・キープ)、鉄器・車輪・大型家畜がない", "コルテスのアステカ征服(1521年)、ピサロのインカ征服(1533年)、伝染病による先住民の激減", "エンコミエンダ制とラス=カサス→アシエンダ制、黒人奴隷とプランテーション", "ポトシ銀山の銀→価格革命とガレオン貿易による世界経済の形成", "クリオーリョ・メスティーソなどの植民地社会の階層", "ハイチ独立(1804年・トゥサン=ルヴェルチュール)、シモン=ボリバルとサン=マルティン、ブラジルの帝国としての独立", "モンロー教書とイギリスの独立支持、独立後の大土地所有と経済的従属", "メキシコ革命(1910年)、キューバ革命(1959年)とキューバ危機、チリのアジェンデ政権と軍事クーデタ"], "check": [["マヤ文明で用いられた、ゼロの概念をもつ記数法は?", "二十進法"], ["アステカ王国の都は?", "テノチティトラン"], ["文字をもたなかったインカ帝国で、数量の記録に用いられたものは?", "キープ(結縄)"], ["インカ帝国を滅ぼした人物は?", "ピサロ"], ["先住民の保護とキリスト教化を条件に植民者に統治を委ねた制度は?", "エンコミエンダ制"], ["16世紀にスペインが開発したボリビアの銀山は?", "ポトシ銀山"], ["ラテンアメリカ生まれの白人を何とよぶか?", "クリオーリョ"], ["1804年に独立した世界初の黒人共和国は?", "ハイチ"], ["アルゼンチン・チリ・ペルーの独立を指導した人物は?", "サン=マルティン"], ["1959年にカストロらがバティスタ政権を倒した革命は?", "キューバ革命"]], "related": ["t_es", "t_us", "t_fr", "t_uk", "t_ph", "t_af", "y_15", "y_16", "y_17", "y_19", "y_20a", "y_20b"], "n": 4072, "videos": [{"title": "【世界史】 列強の世界分割６ ラテンアメリカ （１３分）", "channel": "映像授業 Try IT（トライイット）", "url": "https://www.youtube.com/watch?v=0J52gb7Jh70", "note": "列強の世界分割の中のラテンアメリカを学べ、2026年度第4問Ｃで問われたアメリカ合衆国のカリブ海政策の理解に役立ちます。"}]}, "t_oc": {"title": "カナダ・オセアニア史", "span": "17世紀〜現在", "year": 1867, "lead": "カナダとオーストラリア・ニュージーランドは、先住民の土地にイギリスが植民地をつくり、19世紀後半から自治領として自治を広げ、20世紀に事実上独立した国々です。フランスとの争いや流刑植民地、ゴールドラッシュなど成り立ちはさまざまですが、いずれもイギリス帝国からイギリス連邦へという流れの中で国家となりました。太平洋の島々は19世紀末までに列強に分割され、戦後に独立が進みました。", "flow": ["1608年 フランスがケベックを建設→北アメリカにヌーヴェル=フランス", "1713年 ユトレヒト条約→イギリスがニューファンドランドなどを獲得", "1763年 パリ条約→イギリスがカナダを獲得", "1770年 クックがオーストラリア東岸を探検→1788年流刑植民地シドニー建設", "1840年 ワイタンギ条約→ニュージーランドがイギリス植民地に、マオリ戦争", "1851年 オーストラリアでゴールドラッシュ→移民急増、のち白豪主義", "1867年 カナダ連邦成立→最初の自治領", "1901年 オーストラリア連邦成立、1907年ニュージーランドが自治領に", "19世紀末 太平洋の島々が列強に分割→1898年ハワイがアメリカに併合", "1931年 ウェストミンスター憲章→自治領が本国と対等な主権国家に", "1970年代 オーストラリアが白豪主義を放棄→多文化主義へ", "1989年 APEC発足→アジア太平洋との結びつきを強める"], "sync": [], "secs": [{"t": "先住民の世界と植民の始まり", "p": ["ヨーロッパ人が来る前、北アメリカの北部には狩猟や漁労で暮らす先住民(イヌイットなど)が住み、オーストラリアには数万年前から【アボリジニー】が、ニュージーランドには【マオリ】が暮らしていました。太平洋の島々には、カヌーで広大な海を渡ったポリネシア・ミクロネシア・メラネシアの人々が住んでいました。", "北アメリカ北部に最初に本格的な植民地を築いたのはフランスです。1608年、シャンプランが【ケベック】を建設し、セントローレンス川流域を中心に【ヌーヴェル=フランス】が広がりました。フランス人の植民者は少なかったものの、先住民と結んでビーバーなどの【毛皮交易】を進め、ミシシッピ川流域の【ルイジアナ】まで勢力を伸ばしました。一方、イギリスはハドソン湾会社を通じて北部で毛皮交易を行い、大西洋岸には13植民地を築いていました。", "オセアニアがヨーロッパに知られるのは、北アメリカより遅れてのことです。17世紀にはオランダ東インド会社の船がオーストラリアの西岸や北岸に到達し、オランダ人タスマンがタスマニアやニュージーランドを訪れましたが、乾燥した土地に交易の利益が見こめなかったため、オランダは植民を行いませんでした。本格的な探検は18世紀後半、イギリスの【クック】による3回の太平洋航海によって進められ、太平洋の地理がヨーロッパに詳しく知られるようになりました。このように、カナダとオセアニアの歴史は、いずれもヨーロッパの海外進出と英仏の覇権争いの流れの中で始まったのです。"]}, {"t": "英仏の植民地戦争とカナダの成立", "p": ["17世紀末から18世紀にかけて、イギリスとフランスはヨーロッパでの戦争と連動して北アメリカでも戦いました。スペイン継承戦争の講和である1713年の【ユトレヒト条約】で、イギリスはフランスから【ニューファンドランド】・アカディア・ハドソン湾地方を得ました。さらに、七年戦争と並行して戦われた【フレンチ=インディアン戦争】でイギリスが勝利し、1763年の【パリ条約】でカナダとミシシッピ川以東のルイジアナを獲得しました。こうして北アメリカのフランス植民地はほぼ失われました。", "イギリスはフランス系住民の多いケベックを治めるため、1774年のケベック法でカトリックの信仰とフランス系の民法を認めました。アメリカ独立戦争の際には、独立に反対してイギリスに忠誠を守った人々(国王派、ロイヤリスト)が多くカナダへ移住し、英語系住民が増えました。この結果、カナダは英語系とフランス語系の二つの集団をかかえる国となり、この二重性は現在のカナダにも受けつがれています。", "19世紀前半には自治を求める反乱も起こり、イギリスは植民地に議会にもとづく責任政府を認めるようになりました。南のアメリカ合衆国が南北戦争を経て強大化すると、その圧力に対抗するためにも植民地の統合が求められ、1867年、カナダ連邦が成立しました。カナダはイギリス帝国の中で内政の自治を認められた最初の【自治領】となります。その後、大陸横断鉄道の建設によって西部への開拓が進み、領土は太平洋岸まで広がりました。"]}, {"t": "オーストラリア・ニュージーランドの植民", "p": ["オーストラリアは17世紀にオランダ人に知られていましたが、本格的な植民は18世紀後半からです。1770年、イギリスの【クック】が東岸を探検してイギリス領を宣言しました。アメリカ独立によって13植民地に囚人を送れなくなったイギリスは、オーストラリアを新たな【流刑植民地】とし、1788年に囚人を乗せた船団が到着して、現在のシドニーに植民地が建設されました。その後、自由移民も増え、19世紀前半には【牧羊】が発展して、羊毛がイギリスの毛織物工業の原料として輸出されました。", "1851年に金鉱が発見されて【ゴールドラッシュ】が起こると、世界中から移民が押し寄せ、人口が急増しました。その中には中国人の労働者も多く含まれていましたが、白人労働者との対立が起こり、アジア系移民を制限する動きが強まります。1901年、6つの植民地が統合されて【オーストラリア連邦】が成立し、自治領となりました。連邦政府は有色人種の移民を制限する【白豪主義】を国の方針としました。一方で、オーストラリアは世界でも早い時期に女性参政権を認めるなど、民主的な制度づくりも進めました。", "白人の植民と開拓の陰で、先住民アボリジニーは土地を奪われ、伝染病や迫害によって人口が激減しました。20世紀に入ってからも、先住民の子どもを家族から引き離す同化政策が長く続けられ、その反省は現代オーストラリアの大きな課題となっています。", "ニュージーランドでは、1840年にイギリスが先住民マオリの首長たちと【ワイタンギ条約】を結び、植民地としました。しかし条約の内容の解釈をめぐって対立が起こり、土地を奪われることに抵抗したマオリと植民者・イギリス軍の間で【マオリ戦争】が続きました。ニュージーランドは牧羊や酪農の輸出で発展し、1893年には世界で初めて国政レベルで女性参政権を認めました。1907年にはニュージーランドも自治領となりました。"]}, {"t": "太平洋の島々と列強の分割", "p": ["18世紀後半のクックの航海以降、太平洋の島々にはヨーロッパの捕鯨船・商人・宣教師が訪れるようになりました。19世紀後半、帝国主義の時代になると、列強は資源や中継基地を求めて島々を次々と分割しました。イギリスはフィジーなどを、フランスはタヒチやニューカレドニアを、ドイツはマーシャル諸島やカロリン諸島などのミクロネシアとニューギニアの一部を領有しました。", "ハワイでは、18世紀末にカメハメハ1世が島々を統一してハワイ王国を建てました。19世紀には砂糖プランテーションが広がり、アメリカ系の白人がその経営を握り、日本や中国から多くの労働者が移住しました。1893年、アメリカ系住民がリリウオカラニ女王を退位させて王政を倒し、1898年に【ハワイ】はアメリカ合衆国に併合されました。同じ年の米西戦争でアメリカはグアムも獲得しています。", "第一次世界大戦後、ドイツ領だった赤道以北の南洋諸島は日本の【委任統治領】となり、赤道以南はオーストラリアやニュージーランドの委任統治領となりました。第二次世界大戦では太平洋の島々が日米の激戦地となりました。戦後は旧日本委任統治領がアメリカの信託統治となり、1960年代以降、フィジーやサモアなど多くの島々が独立しました。一方、フランス領ポリネシアやアメリカの太平洋の島々では核実験が行われ、住民が被害を受けたことも忘れてはなりません。"]}, {"t": "イギリス連邦の中での自立と世界大戦", "p": ["カナダ・オーストラリア・ニュージーランドは、自治領としてイギリス本国と強く結びついていました。第一次世界大戦では本国とともに参戦し、多くの兵士を送りました。オーストラリア・ニュージーランド軍団(ANZAC)がオスマン帝国のガリポリで多くの犠牲を出した戦いは、両国の国民意識を形づくるできごととして記憶されています。大戦への貢献によって自治領の発言力は高まり、それぞれ単独で国際連盟に加盟しました。", "こうした流れを受けて、1926年のイギリス帝国会議で本国と自治領が対等であることが確認され、1931年の【ウェストミンスター憲章】で法的に定められました。これにより自治領は本国と対等な主権国家となり、王冠への共通の忠誠で結ばれる【イギリス連邦(コモンウェルス)】が成立しました。世界恐慌の際には、イギリスは1932年のオタワ連邦会議で連邦内の関税を優遇する【スターリング=ブロック】を形成し、自治領との経済的な結びつきを強めました。", "第二次世界大戦では、カナダ・オーストラリア・ニュージーランドは再び連合国として参戦しました。とくにオーストラリアは日本軍の南進によって本土が空襲を受けるなど直接の脅威にさらされました。シンガポールの陥落によってイギリスが守ってくれないことが明らかになると、オーストラリアとニュージーランドは安全保障の面でアメリカを頼るようになり、戦後の1951年には【ANZUS(太平洋安全保障条約)】をアメリカと結びました。"]}, {"t": "戦後の歩み:多文化主義とアジア太平洋", "p": ["戦後、カナダはNATOの原加盟国となり、アメリカとともに西側陣営の一員として冷戦を戦いつつ、国連の平和維持活動にも積極的に取り組みました。国内では、1960年代にケベック州でフランス語系住民の自治と独立を求める運動が高まり、カナダは英語とフランス語の二言語を公用語とし、1970年代には【多文化主義】を国の政策として掲げました。1982年には、憲法の改正権がイギリスから移され、法的にも完全な独立を達成しました。ケベックの独立をめぐっては住民投票が行われましたが、いずれも否決されています。", "オーストラリアは戦後、労働力不足を補うためヨーロッパからの移民を大量に受け入れ、やがてアジアとの経済関係が強まると、1970年代に【白豪主義】を放棄して多文化主義に転換しました。現在ではアジア系の住民も多く暮らしています。先住民アボリジニーについても、1960年代以降に市民権の承認や土地の権利の回復が進められ、21世紀には政府が過去の同化政策について公式に謝罪しました。ニュージーランドでも、ワイタンギ条約にもとづくマオリの権利の回復が進められ、マオリ語は公用語の一つとなっています。", "経済面では、イギリスが1973年にECに加盟したことで、オーストラリアやニュージーランドは伝統的な輸出市場を失い、日本・中国などアジアとの結びつきを強めていきました。1989年には、オーストラリアの提唱により【APEC(アジア太平洋経済協力)】が発足しました。カナダはアメリカ・メキシコとともに【NAFTA(北米自由貿易協定)】(1994年発効)を結んで北米の経済統合を進めました。いずれの国も、イギリス帝国の一部という出発点から、多様な人々が共に暮らす国家として、アジア太平洋や北米の地域の中に自らを位置づけ直してきたといえます。"]}], "points": ["ヌーヴェル=フランス(ケベック建設1608年)と毛皮交易", "ユトレヒト条約(1713年)・パリ条約(1763年)でイギリスが北アメリカのフランス領を獲得", "1867年カナダ連邦→最初の自治領、英語系とフランス語系の二重構造", "オーストラリア:クックの探検、流刑植民地(1788年)、牧羊、ゴールドラッシュ、1901年連邦成立と白豪主義", "ニュージーランド:ワイタンギ条約(1840年)とマオリ戦争、1893年女性参政権", "太平洋の分割とハワイ併合(1898年)、旧ドイツ領南洋諸島の日本の委任統治", "ウェストミンスター憲章(1931年)とイギリス連邦、スターリング=ブロック", "白豪主義の放棄と多文化主義、APEC(1989年)、NAFTA"], "check": [["1608年にフランスが北アメリカに建設した植民地の拠点は?", "ケベック"], ["1763年のパリ条約でカナダを獲得した国は?", "イギリス"], ["1867年に成立し、イギリス帝国最初の自治領となった国は?", "カナダ連邦"], ["オーストラリアの先住民を何とよぶか?", "アボリジニー"], ["1840年にイギリスとマオリの首長が結んだ条約は?", "ワイタンギ条約"], ["1901年成立のオーストラリア連邦が掲げた有色人種の移民制限政策は?", "白豪主義"], ["1931年に自治領を本国と対等な主権国家とした法律は?", "ウェストミンスター憲章"], ["1898年にアメリカ合衆国に併合された太平洋の王国は?", "ハワイ"], ["1989年にオーストラリアの提唱で発足したアジア太平洋の経済協力の枠組みは?", "APEC(アジア太平洋経済協力)"]], "related": ["t_uk", "t_fr", "t_us", "t_id", "t_ph", "y_17", "y_18", "y_19", "y_20a", "y_20b"], "n": 4003}});
